-- ----------------------------
-- Table structure for sanpham
-- ----------------------------
DROP TABLE IF EXISTS `sanpham`;
CREATE TABLE `sanpham` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `TenSanPham` varchar(150) NOT NULL,
  `MoTa` text,
  `NoiDung` text,
  `GiaSanPham` float DEFAULT NULL,
  `GiaKhuyenMai` float DEFAULT NULL,
  `SoLuong` int DEFAULT NULL,
  `DonVi` varchar(150) DEFAULT NULL,
  `AnhSanPham` varchar(255) DEFAULT NULL,
  `DanhMucId` varchar(50) DEFAULT NULL,
  `ThuongHieuId` varchar(50) DEFAULT NULL,
  `TrangThaiId` tinyint DEFAULT NULL,
  `DaBan` int DEFAULT NULL,
  `NgayTao` datetime DEFAULT NULL,
  `NgaySua` datetime DEFAULT NULL,
  `DaDuyet` tinyint DEFAULT NULL,
  `NgayDuyet` datetime DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `fk_danhmuc_id` (`DanhMucId`),
  KEY `fk_thuonghieu_id` (`ThuongHieuId`),
  KEY `fk_trangthai_id` (`TrangThaiId`),
  CONSTRAINT `fk_danhmuc_id` FOREIGN KEY (`DanhMucId`) REFERENCES `danhmuc` (`Id`),
  CONSTRAINT `fk_thuonghieu_id` FOREIGN KEY (`ThuongHieuId`) REFERENCES `thuonghieu` (`Id`),
  CONSTRAINT `fk_trangthai_id` FOREIGN KEY (`TrangThaiId`) REFERENCES `trangthai` (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb3;

-- ----------------------------
-- Records of sanpham
-- ----------------------------
BEGIN;
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (1, 'Chuột Logitech MX Master 3 (Màu xám)', '<ul>\r\n	<li>Sản phẩm: Chu&ocirc;̣t kh&ocirc;ng d&acirc;y</li>\r\n	<li>H&atilde;ng sản xuất: Logitech</li>\r\n	<li>Model: MX Master 3&nbsp;</li>\r\n	<li>Ki&ecirc;̉u k&ecirc;́t n&ocirc;́i: Kh&ocirc;ng d&acirc;y</li>\r\n	<li>Chu&acirc;̉n giao ti&ecirc;́p: USB-Wireless, Bluetooth</li>\r\n	<li>Ph&iacute;m chức năng: Standard</li>\r\n	<li>M&agrave;u: X&aacute;m</li>\r\n</ul>', '<h2>Chu&ocirc;̣t kh&ocirc;ng d&acirc;y Bluetooth, Wireless Logitech MX Master 3 (M&agrave;u x&aacute;m)</h2>\r\n\r\n<h3>Thiết kế tinh tế, tiện dụng</h3>\r\n\r\n<p><strong>MX Master 3</strong>&nbsp;l&agrave; một con chuột lớn, tiện dụng, d&agrave;nh cho người thuận tay phải.&nbsp;<strong>MX Master 3</strong>&nbsp;được trang bị b&aacute;nh xe cuộn với cơ chế điện từ ho&agrave;n to&agrave;n mới, gi&uacute;p tăng độ mượt khi cuộn tự do v&agrave; giảm tiếng ồn khi cuộn nhiều nấc thay v&igrave; cơ chế cơ học.</p>\r\n\r\n<p>N&uacute;t cuộn của&nbsp;<strong>MX Master 3</strong>&nbsp;được l&agrave;m bằng th&eacute;p kh&ocirc;ng gỉ, b&ecirc;n cạnh đ&oacute;, n&uacute;t bấm phụ v&agrave; b&aacute;nh xe cuộn ngang cũng được cải tiến bằng chất liệu th&eacute;p kh&ocirc;ng gỉ v&agrave; được thiết kế d&agrave;i hơn. C&aacute;ch bố tr&iacute;, sắp xếp vị tr&iacute; c&aacute;c n&uacute;t của&nbsp;chuột kh&ocirc;ng d&acirc;y Logitech&nbsp;v&ocirc; c&ugrave;ng tiện lợi. Chuột c&oacute; n&uacute;t nhấp chuột tr&aacute;i, chuột phải, b&aacute;nh xe điều chỉnh v&agrave; b&aacute;nh xe cuộn ngang ở ng&oacute;n tay c&aacute;i được đặt song song.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Chuột không dây Bluetooth, Wireless Logitech MX Master 3 (Màu xám)\" height=\"450\" src=\"https://phucanhcdn.com/media/lib/41440_MXMaster3GrayBVh1.jpg\" width=\"600\" /></p>\r\n\r\n<p>Hơn nữa, c&aacute;c thao t&aacute;c điều khiển tr&ecirc;n phần c&ograve;n lại của ng&oacute;n tay c&aacute;i c&oacute; một n&uacute;t ri&ecirc;ng để giữ thay v&igrave; chỉ nhấn xuống. Những thay đổi t&iacute;ch cực về thiết kế của chiếc&nbsp;<strong>MX Master 3</strong>&nbsp;kh&ocirc;ng chỉ g&oacute;p phần tăng t&iacute;nh thẩm mỹ cho sản phẩm m&agrave; c&ograve;n g&oacute;p phần khiến cho việc sử dụng cũng như lướt web trở l&ecirc;n thoải m&aacute;i v&agrave; mượt m&agrave; hơn.</p>\r\n\r\n<h3>Hoạt động tốt tr&ecirc;n nhiều bề mặt</h3>\r\n\r\n<p>Với cảm biến l&ecirc;n tới 4000 DPI th&igrave;&nbsp;<strong>MX Master 3</strong>&nbsp;c&oacute; thể c&oacute; thể hoạt động tốt ở những bề mặt kh&oacute; nhằn, ch&iacute;nh v&igrave; vậy n&oacute; nhanh hơn, ch&iacute;nh x&aacute;c hơn nhiều lần với so với những con chuột b&igrave;nh thường.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Chuột không dây Bluetooth, Wireless Logitech MX Master 3 (Màu xám)\" src=\"https://phucanhcdn.com/media/lib/41440_MXMaster3GrayBVh2.jpg\" width=\"600\" /></p>\r\n\r\n<h3>Thời lượng pin lớn, sạc nhanh</h3>\r\n\r\n<p><strong>MX Master 3</strong>&nbsp;cung cấp cho ch&uacute;ng ta một thời lượng Pin v&ocirc; c&ugrave;ng ấn tượng, l&ecirc;n đến 70 ng&agrave;y cho một lần sạc đầy.&nbsp;<strong>MX Master 3</strong>&nbsp;sẽ được sạc đầy trong v&ograve;ng 3 giờ, nhưng bạn c&oacute; thể sạc nhanh 1 ph&uacute;t cho 3 giờ sử dụng.</p>\r\n\r\n<p>Với một lượng pin khổng lồ như vậy, bạn c&oacute; thể tha hồ sử dụng&nbsp;chuột kh&ocirc;ng d&acirc;y&nbsp;n&agrave;y m&agrave; kh&ocirc;ng cần phải lo rằng thi thoảng bạn c&oacute; thể sẽ qu&ecirc;n kh&ocirc;ng sạc pin khi sử dụng.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Chuột không dây Bluetooth, Wireless Logitech MX Master 3 (Màu xám)\" src=\"https://phucanhcdn.com/media/lib/41440_MXMaster3GrayBVh4.jpg\" width=\"600\" /></p>\r\n\r\n<h3>Kết nối c&ugrave;ng l&uacute;c nhiều thiết bị</h3>\r\n\r\n<p>Ở mặt trước của chuột c&oacute; cổng USB-C v&agrave; ở ph&iacute;a dưới c&oacute; một n&uacute;t để chuyển đổi giữa ba đầu v&agrave;o kh&aacute;c nhau. Với Bluetooth v&agrave; Wireless được trang bị, bạn c&oacute; thể kết nối&nbsp;<strong>MX Master 3</strong>&nbsp;với cả ba thiết bị c&ugrave;ng một l&uacute;c, sau đ&oacute; bạn c&oacute; thể ngay lập tức chuyển đổi giữa ch&uacute;ng nhờ phần mềm từ Logitech.</p>\r\n\r\n<p>Đ&acirc;y l&agrave; một t&iacute;nh năng v&ocirc; c&ugrave;ng hữu &iacute;ch nếu như bạn c&oacute; m&aacute;y t&iacute;nh để b&agrave;n, latop v&agrave; một thiết bị di động b&ecirc;n cạnh trong khi bạn đang l&agrave;m việc.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Chuột không dây Bluetooth, Wireless Logitech MX Master 3 (Màu xám)\" src=\"https://phucanhcdn.com/media/lib/41440_MXMaster3GrayBVh3.jpg\" width=\"600\" /></p>', 2000000, NULL, 10, 'Bộ sản phẩm', 'Logitech Master 3 Wireless (Mid Grey).jpg', 'MOUSE', 'LOGITECH', 1, NULL, '2021-07-02 11:03:40', '2021-07-24 16:35:04', 1, '2021-07-14 18:02:17');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (2, 'MacBook Pro 13\" 2020 Touch Bar M1 256GB', '<ul>\r\n	<li>CPU: Apple M1</li>\r\n	<li>RAM: 8 GB, LPDDR4</li>\r\n	<li>M&agrave;n h&igrave;nh: 13.3&quot;, 2560 x 1600 Pixel, IPS, IPS LCD LED Backlit, True Tone</li>\r\n	<li>Đồ họa: Apple M1 GPU 8 nh&acirc;n</li>\r\n	<li>Ổ cứng: SSD 256 GB</li>\r\n	<li>Hệ điều h&agrave;nh: Mac OS</li>\r\n	<li>Trọng lượng (kg): 1.4</li>\r\n	<li>K&iacute;ch thước (mm): 304.1 x 212.4 x 15.6</li>\r\n	<li>Xuất xứ: Trung Quốc</li>\r\n	<li>Năm ra mắt: 2020</li>\r\n</ul>', '<h2 style=\"text-align:center\">Đ&aacute;nh gi&aacute; chi tiết&nbsp;MacBook Pro 13&quot; 2020 Touch Bar M1 256GB</h2>\r\n\r\n<p><strong>Tốc độ v&agrave; sức mạnh ho&agrave;n hảo trong một th&acirc;n m&aacute;y nhỏ gọn.&nbsp;<a href=\"https://fptshop.com.vn/may-tinh-xach-tay/macbook-pro-13-2020-touch-bar-m1-256gb\" title=\"MacBook Pro M1\" type=\"MacBook Pro M1\">MacBook Pro M1</a>&nbsp;13 inch 2020 Touch Bar mới với bộ vi xử l&yacute;&nbsp;<a href=\"https://fptshop.com.vn/tin-tuc/danh-gia/tat-tan-tat-ve-chip-apple-m1-bo-vi-xu-ly-dinh-cao-moi-danh-cho-mac-128095\" title=\"Apple M1\" type=\"Apple M1\">Apple M1</a>&nbsp;cho bạn hiệu suất v&agrave; thời lượng pin tuyệt vời nhất từ trước đến nay, mang đến hiệu năng chuy&ecirc;n nghiệp để ho&agrave;n th&agrave;nh những c&ocirc;ng việc chuy&ecirc;n nghiệp.</strong></p>\r\n\r\n<p style=\"text-align:center\"><strong><img alt=\"MacBook Pro 13 2020 Touch Bar M1\" src=\"https://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/QuanLNH2/macbook-pro-13-m1-1.jpg\" width=\"800\" /></strong></p>\r\n\r\n<h3><strong>Con chip nhỏ, đột ph&aacute; lớn</strong></h3>\r\n\r\n<p>Vũ kh&iacute; b&iacute; mật của MacBook Pro 13 2020 đến từ Apple M1, bộ vi xử l&yacute; đầu ti&ecirc;n được ch&iacute;nh Apple chế tạo cho m&aacute;y Mac. Với 16 tỷ b&oacute;ng b&aacute;n dẫn, Apple M1 t&iacute;ch hợp tất cả từ CPU, GPU, Neural Engine, I/O, bộ xử l&yacute; h&igrave;nh ảnh v&agrave; hơn thế nữa v&agrave;o một con chip nhỏ b&eacute;. Bạn sẽ được tận hưởng những điều đ&aacute;ng kinh ngạc chưa từng thấy ở MacBook Pro 13.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"MacBook Pro 13 2020 Touch Bar M1 vi xử lý\" src=\"https://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/QuanLNH2/macbook-pro-13-m1-16.jpg\" width=\"800\" /></p>\r\n\r\n<h3><strong>Tốc độ nhanh vượt trội</strong></h3>\r\n\r\n<p>Bộ vi xử l&yacute; M1 gi&uacute;p MacBook Pro 13 2020 nhanh v&agrave; mạnh một c&aacute;ch đ&aacute;ng kinh ngạc. Bộ vi xử l&yacute; 8 l&otilde;i mạnh mẽ c&oacute; thể giải quyết c&aacute;c t&aacute;c vụ nặng, c&aacute;c quy tr&igrave;nh phức tạp với tốc độ CPU nhanh hơn tới 2,8 lần thế hệ trước. 4 l&otilde;i hiệu năng cao của Apple M1 l&agrave; 4 l&otilde;i CPU nhanh nhất thế giới đối với d&ograve;ng chip sử dụng năng lượng thấp. Trong khi đ&oacute; 4 l&otilde;i c&ograve;n lại gi&uacute;p bạn xử l&yacute; c&aacute;c t&aacute;c vụ th&ocirc;ng thường h&agrave;ng ng&agrave;y chỉ với một phần mười năng lượng, qua đ&oacute; mang đến thời lượng pin m&agrave; ai cũng phải bất ngờ.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"tốc độ MacBook Pro 13 2020 Touch Bar M1\" src=\"https://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/QuanLNH2/macbook-pro-13-m1-5.jpg\" width=\"800\" /></p>\r\n\r\n<h3><strong>Đồ họa t&iacute;ch hợp nhanh nhất thế giới</strong></h3>\r\n\r\n<p>GPU 8 nh&acirc;n b&ecirc;n trong Apple M1 l&agrave; bộ xử l&yacute; đồ họa ti&ecirc;n tiến nhất m&agrave; Apple từng tạo ra. Bạn sẽ c&oacute; hiệu suất đồ họa nhanh gấp 5 lần thế hệ trước v&agrave; l&agrave; đồ họa t&iacute;ch hợp nhanh nhất thế giới laptop hiện nay. Bạn c&oacute; thể ph&aacute;t video 8K, xử l&yacute; c&aacute;c t&aacute;c vụ đồ họa 3D, thiết kế những bối cảnh phức tạp v&agrave; thậm ch&iacute; l&agrave; b&ugrave;ng nổ với những tựa game đồ họa m&atilde;n nh&atilde;n tr&ecirc;n chiếc MacBook Pro 13 2020 nhỏ b&eacute; nhưng đầy chuy&ecirc;n nghiệp.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"đồ họa MacBook Pro 13 2020 Touch Bar M1\" src=\"https://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/QuanLNH2/macbook-pro-13-m1-17.jpg\" width=\"800\" /></p>\r\n\r\n<h3><strong>L&agrave;m việc nhanh hơn nhờ tr&iacute; tuệ AI</strong></h3>\r\n\r\n<p>Apple M1 t&iacute;ch hợp nh&acirc;n Neural Engine 16 l&otilde;i, tối ưu hệ thống tr&iacute; tuệ nh&acirc;n tạo Machine Learning. Tốc độ xử l&yacute; sẽ nhanh hơn nhờ khả năng tự động h&oacute;a cho c&aacute;c hoạt động ph&acirc;n t&iacute;ch video, nhận dạng giọng n&oacute;i, xử l&yacute; h&igrave;nh ảnh v&agrave; hơn thế nữa. So với thế hệ trước, Machine Learning nhanh hơn tới 11 lần, để bạn ho&agrave;n th&agrave;nh c&ocirc;ng việc trong chớp mắt.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"AI MacBook Pro 13 2020 Touch Bar M1\" src=\"https://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/QuanLNH2/macbook-pro-13-m1-22.jpg\" width=\"800\" /></p>\r\n\r\n<h3><strong>L&agrave;m m&aacute;t tức th&igrave;, duy tr&igrave; hiệu năng</strong></h3>\r\n\r\n<p>MacBook Pro 13 2020 M1 trang bị quạt tản nhiệt ti&ecirc;n tiến, nhanh ch&oacute;ng l&agrave;m m&aacute;t, lưu th&ocirc;ng luồng kh&iacute; để bạn lu&ocirc;n c&oacute; được hiệu năng ổn định trong thời gian d&agrave;i. Sẵn s&agrave;ng cho những c&ocirc;ng việc cần hoạt động li&ecirc;n tục, những t&aacute;c vụ đ&ograve;i hỏi khả năng xử l&yacute; cao m&agrave; m&aacute;y vẫn hết sức mượt m&agrave;.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"làm mát MacBook Pro 13 2020 Touch Bar M1\" src=\"https://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/QuanLNH2/macbook-pro-13-m1-21.jpg\" width=\"800\" /></p>\r\n\r\n<h3><strong>Thời lượng pin kh&oacute; tin 20 tiếng</strong></h3>\r\n\r\n<p>Với bộ vi xử l&yacute; Apple M1, Apple đ&atilde; tạo ra chiếc&nbsp;<a href=\"https://fptshop.com.vn/may-tinh-xach-tay/apple-macbook\" title=\"MacBook chính hãng\" type=\"MacBook chính hãng\">MacBook</a>&nbsp;c&oacute; thời lượng pin l&acirc;u nhất từ trước đến nay. MacBook Pro 13 2020 M1 c&oacute; thể xem video li&ecirc;n tục trong 20 giờ hay duyệt web qua Wi-Fi trong 17 giờ đồng hồ. Thời lượng pin n&agrave;y l&agrave; qu&aacute; đủ để hoạt động l&agrave;m việc, giải tr&iacute; của bạn kh&ocirc;ng bao giờ bị gi&aacute;n đoạn.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"pin MacBook Pro 13 2020 Touch Bar M1\" src=\"https://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/QuanLNH2/macbook-pro-13-m1-8.jpg\" width=\"800\" /></p>\r\n\r\n<h3><strong>M&agrave;n h&igrave;nh Retina đỉnh cao</strong></h3>\r\n\r\n<p>Vẻ đẹp của m&agrave;n h&igrave;nh Retina tr&ecirc;n MacBook Pro 13 2020 M1 thật kh&oacute; c&oacute; thể để diễn tả th&agrave;nh lời. Từ văn bản sắc n&eacute;t cho đến h&igrave;nh ảnh r&otilde; r&agrave;ng, độ chi tiết ho&agrave;n hảo v&agrave; sự ch&acirc;n thực đ&aacute;ng kinh ngạc. Đ&egrave;n nền LED mang tới m&agrave;u đen s&acirc;u v&agrave; &aacute;nh s&aacute;ng trắng. Trong khi đ&oacute; c&ocirc;ng nghệ m&agrave;u P3 cho dải m&agrave;u rộng hơn tới 25% so với sRGB. Hơn nữa, MacBook Pro 13 2020 M1 c&ograve;n c&oacute; c&ocirc;ng nghệ True Tone, điều chỉnh m&agrave;u sắc theo m&ocirc;i trường v&agrave; &aacute;nh s&aacute;ng xung quanh để bạn lu&ocirc;n c&oacute; được trải nghiệm xem dễ chịu nhất.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"màn hình MacBook Pro 13 2020 Touch Bar M1\" src=\"https://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/QuanLNH2/macbook-pro-13-m1-2.jpg\" width=\"800\" /></p>\r\n\r\n<h3><strong>N&acirc;ng cao chất lượng gọi FaceTime</strong></h3>\r\n\r\n<p>Con chip M1 cũng g&oacute;p phần tăng cường chất lượng cuộc gọi FaceTime HD nhờ bộ xử l&yacute; t&iacute;n hiệu h&igrave;nh ảnh mới. Chất lượng h&igrave;nh ảnh được cải thiện r&otilde; rệt, đặc biệt l&agrave; trong c&aacute;c điều kiện &aacute;nh s&aacute;ng yếu hay ch&ecirc;nh lệch &aacute;nh s&aacute;ng mạnh. Kết hợp với 3 micro chất lượng ph&ograve;ng thu, giảm thiểu tạp &acirc;m đ&aacute;ng kể, bạn sẽ c&oacute; những cuộc gọi FaceTime HD r&otilde; r&agrave;ng v&agrave; r&otilde; n&eacute;t. Thoải m&aacute;i sắp xếp c&ocirc;ng việc v&agrave; l&agrave;m việc ở bất cứ đ&acirc;u qua c&aacute;c cuộc họp video trực tuyến chất lượng.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"FaceTime MacBook Pro 13 2020 Touch Bar M1\" src=\"https://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/QuanLNH2/macbook-pro-13-m1-3.jpg\" width=\"800\" /></p>\r\n\r\n<h3><strong>B&agrave;n ph&iacute;m Magic Keyboard, Touch Bar v&agrave; Touch ID</strong></h3>\r\n\r\n<p>Tr&ecirc;n MacBook Pro 13 2020 M1, b&agrave;n ph&iacute;m Magic Keyboard mới với cơ chế cắt k&eacute;o tinh chỉnh mang lại trải nghiệm g&otilde; ph&iacute;m nhanh, nhạy v&agrave; y&ecirc;n tĩnh. Ngo&agrave;i ra bạn c&ograve;n nhận được sự hỗ trợ của thanh cảm ứng Touch Bar, lu&ocirc;n hiểu bạn cần g&igrave; v&agrave; th&ecirc;m v&agrave;o những thao t&aacute;c l&agrave;m việc nhanh ch&oacute;ng ở đ&uacute;ng nơi bạn cần. Cuối c&ugrave;ng l&agrave; cảm biến v&acirc;n tay Touch ID, thay thế thao t&aacute;c nhập mật khẩu chỉ bằng một c&uacute; chạm. Tất cả đều hướng tới sự nhanh ch&oacute;ng, tiện lợi nhất cho bạn khi l&agrave;m việc với MacBook Pro.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"bàn phím MacBook Pro 13 2020 Touch Bar M1\" src=\"https://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/QuanLNH2/macbook-pro-13-m1-4.jpg\" width=\"800\" /></p>\r\n\r\n<h3><strong>Kết nối nhanh ch&oacute;ng</strong></h3>\r\n\r\n<p>MacBook Pro 13 2020 Touch Bar M1 t&iacute;ch hợp những kết nối nhanh h&agrave;ng đầu thế giới hiện nay, d&ugrave; l&agrave; kết nối kh&ocirc;ng d&acirc;y hay c&oacute; d&acirc;y. Thế hệ Wi-Fi 6 vừa nhanh hơn, vừa cho chất lượng s&oacute;ng khỏe hơn, kể cả khi bạn truy cập mạng ở nơi c&ocirc;ng cộng c&oacute; nhiều người d&ugrave;ng c&ugrave;ng l&uacute;c. Trong khi đ&oacute; cổng Thunderbolt 4 kh&ocirc;ng chỉ c&oacute; tốc độ cao m&agrave; c&ograve;n hết sức đa năng. Bạn c&oacute; thể d&ugrave;ng cổng kết nối n&agrave;y để sạc, xuất h&igrave;nh độ ph&acirc;n giải l&ecirc;n tới 6K, truyền dữ liệu si&ecirc;u tốc 40Gb/s v&agrave; kết nối với nhiều thiết bị ngoại vi kh&aacute;c.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"kết nối MacBook Pro 13 2020 Touch Bar M1\" src=\"https://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/QuanLNH2/macbook-pro-13-m1-20.jpg\" width=\"800\" /></p>', 34990000, NULL, 8, 'Bộ sản phẩm', 'macbook pro 13 m1.jpg', 'Mac', 'APPLE', 1, NULL, '2021-07-02 17:45:34', '2021-07-19 09:34:12', 1, '2021-07-06 14:27:13');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (3, 'Bàn phím cơ Keydous NJ68 2021', '<h3><strong>TH&Ocirc;NG TIN CHI TIẾT</strong></h3>\r\n\r\n<ul>\r\n	<li>H&atilde;ng: Keydous (tiền th&acirc;n l&agrave; Keywalker)</li>\r\n	<li>Bảo h&agrave;nh 1 năm</li>\r\n	<li>Layout: 68 ph&iacute;m</li>\r\n	<li>Kết nối: Bluetooth + d&acirc;y</li>\r\n	<li>Keycap PBT Cherry profile; kiểu in dye-sub hoặc doubleshot (tuỳ bản)</li>\r\n	<li>Switch: Kailh Box White, Red, Brown</li>\r\n	<li>Case: smoke - Plate: đồng - Led: RGB</li>\r\n	<li>Hotswap switch (3-pin, 5-pin)</li>\r\n	<li>Dung lượng pin: 3100mah</li>\r\n</ul>', '<h1>Manual / Hướng dẫn sử dụng Keydous NJ68</h1>\r\n\r\n<p>Hướng dẫn sử dụng Keydous NJ68</p>\r\n\r\n<p><strong>Phần 1: Hướng dẫn kết nối Bluetooth</strong><br />\r\n<br />\r\n1. Bật c&ocirc;ng tắc ph&iacute;a sau b&agrave;n ph&iacute;m, nhấn giữ FN + Q đến khi led n&uacute;t Q nh&aacute;y nhanh (kh&ocirc;ng phải nh&aacute;y chậm)</p>\r\n\r\n<p>2. T&igrave;m KEYDOUS trong danh s&aacute;ch thiết bị bluetooth.</p>\r\n\r\n<p>3. Kết nối v&agrave; sử dụng. Nhập pass 6 số tr&ecirc;n ph&iacute;m sau đ&oacute; nhấn ENTER (nếu c&oacute;)</p>\r\n\r\n<p>4. NJ68 c&oacute; thể kết nối tối đa 3 thiết bị tương ứng với c&aacute;c ph&iacute;m Q &ndash; W &ndash; E</p>\r\n\r\n<p>5. Nếu muốn kết nối với thiết bị mới, cần tắt Bluetooth tr&ecirc;n thiết bị đang sử dụng, sau đ&oacute; kết nối lại từ bước 1, thay bằng FN + W v&agrave; FN + E</p>\r\n\r\n<p><strong>Phần 2: Hướng dẫn sử dụng ph&iacute;m, led RGB</strong><br />\r\n<br />\r\nFN + 1 đến + : F1-F12<br />\r\nFN + \\| : C&aacute;c hiệu ứng s&aacute;ng led RGB<br />\r\nFN + Enter : C&aacute;c hiệu ứng s&aacute;ng một m&agrave;u led<br />\r\nFN + Shift phải : t&iacute;ch kiệm pin tắt to&agrave;n bộ led khi d&ugrave;ng bluetooth<br />\r\nFN + ESC : Tho&aacute;t chế độ tiết kiệm pin<br />\r\nFN + Spacebar :Dừng c&aacute;c hiệu ứng led chuyển động<br />\r\nFN + Backspace (giữ 3 gi&acirc;y): Custom led từng ph&iacute;m theo sở th&iacute;ch. Ấn backspace 1 lần nữa để ho&agrave;n th&agrave;nh. Ấn FN + Backspace để sử dụng led t&ugrave;y chỉnh<br />\r\nFN + Tab : Chọn thời gian sleep cho led khi kh&ocirc;ng sử dụng (1 nh&aacute;y = 2p, 2 nh&aacute;y = 30p, 3 nh&aacute;y =kh&ocirc;ng tắt)</p>\r\n\r\n<p>FN + mũi t&ecirc;n l&ecirc;n xuống: Tăng giảm độ s&aacute;ng led<br />\r\nFN + mũi t&ecirc;n tr&aacute;i phải: Tăng giảm tốc độ hiệu ứng<br />\r\n&nbsp;</p>\r\n\r\n<p>Khi led n&uacute;t ~ s&aacute;ng đỏ l&agrave; pin yếu, cần sạc.<br />\r\n&nbsp;</p>\r\n\r\n<p>Reset chức năng ph&iacute;m về mặc định : Giữ ESC + CTRL tr&aacute;i + Backspace + mũi t&ecirc;n phải trong 5s bao giờ đ&egrave;n nh&aacute;y l&agrave; được<br />\r\n<br />\r\n<strong>Kh&ocirc;ng sử dụng sạc pin điện thoại để sạc ph&iacute;m, chỉ sử dụng cổng usb tr&ecirc;n m&aacute;y t&iacute;nh</strong></p>', 2550000, NULL, 9, 'Bộ sản phẩm', 'nj68_smoke.jpg', 'BPhim', 'KEYDOUS', 1, NULL, '2021-07-02 17:58:51', '2021-07-14 21:24:49', 1, '2021-07-14 21:23:22');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (4, 'MacBook Pro 16 inch 2019 – CTO', '<ul>\r\n	<li>T&igrave;nh trạng: Newseal</li>\r\n	<li>M&agrave;u: X&aacute;m (Space Gray)</li>\r\n	<li>CPU: 2.4GHz 8-core i9-9980HK (16MB cache, Turbo 5.0GHz)</li>\r\n	<li>RAM: 32GB 2666MHz DDR4 memory</li>\r\n	<li>Storage: 2TB SSD storage</li>\r\n	<li>M&agrave;n h&igrave;nh: 16-inch Retina with True Tone (3072&times;1920)</li>\r\n	<li>VGA: AMD Radeon Pro 5500M with 8GB GDDR6 memory</li>\r\n	<li>Interface: Four Thunderbolt 3 ports (USB-Type C)</li>\r\n	<li>Touch Bar &amp; Touch ID</li>\r\n	<li>Trọng lượng: 2.0Kg</li>\r\n</ul>', '<h3>MacBook Pro 16 inch 2019 New -&nbsp;CTO -&nbsp;(Space Gray / i9 2.4Ghz / 32GB / 1TB)</h3>\r\n\r\n<p>CTO - MacBook Pro 16 inch 2019 New - (Space Gray/i9 2.4Ghz/32GB/1TB/8GB)&nbsp; ho&agrave;n to&agrave;n mới vừa được Apple cho ra mắt. Theo như giới thiệu, CTO - MacBook Pro 16 inch 2019 New- (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) được cho sẽ trở th&agrave;nh chiếc m&aacute;y t&iacute;nh x&aacute;ch tay tốt nhất tr&ecirc;n thế giới. Với những ưu điểm tuyệt vời cả về cấu h&igrave;nh lẫn kiểu d&aacute;ng thiết kế b&ecirc;n ngo&agrave;i, CTO -&nbsp;MacBook Pro 16 inch 2019 New -&nbsp;(Space Gray/i9 2.4Ghz/32GB/1TB/8GB) chắc chắn sẽ l&agrave; sản phẩm tuyệt vời d&agrave;nh cho bất kỳ người d&ugrave;ng n&agrave;o kể cả l&agrave; những người l&agrave;m thiết kế phim ảnh hay những nh&agrave; sản xuất ứng dụng y&ecirc;u cầu cấu h&igrave;nh cao. H&atilde;y c&ugrave;ng&nbsp;Macstores&nbsp;t&igrave;m hiểu kỹ hơn về sản phẩm n&agrave;y.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" height=\"488\" sizes=\"(max-width: 788px) 100vw, 788px\" src=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-1.jpg\" srcset=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-1.jpg 2576w, https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-1-768x475.jpg 768w\" width=\"788\" /></p>\r\n\r\n<h3>M&agrave;n h&igrave;nh Retina lơn nhất cho d&ograve;ng m&aacute;y t&iacute;nh x&aacute;ch tay</h3>\r\n\r\n<p>CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) được Apple trang bị một m&agrave;n h&igrave;nh Retina 16 inch c&oacute; gam m&agrave;u rộng P3 c&ugrave;ng độ s&aacute;ng 500 nits, mật độ điểm ảnh l&agrave; 226 ppi v&agrave; độ ph&acirc;n giải l&ecirc;n đến 3072 x 1920 pixel. Nhờ vậy m&agrave; CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) c&oacute; thể cung cấp gần 6 triệu điểm ảnh v&agrave; mang đến những trải nghiệm tuyệt vời nhất từ trước đến nay tr&ecirc;n c&aacute;c d&ograve;ng m&aacute;y t&iacute;nh x&aacute;ch tay.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" height=\"555\" sizes=\"(max-width: 812px) 100vw, 812px\" src=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-2.jpg\" srcset=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-2.jpg 1954w, https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-2-768x525.jpg 768w\" width=\"812\" /></p>\r\n\r\n<p>V&agrave; đ&acirc;y cũng l&agrave; chiếc m&aacute;y t&iacute;nh x&aacute;ch tay c&oacute; m&agrave;n h&igrave;nh Retina lớn nhất từ trước tới nay tr&ecirc;n thị trường. Mỗi một m&agrave;n h&igrave;nh đều được Apple hiệu chỉnh ri&ecirc;ng trong nh&agrave; nhằm mang đến gam m&agrave;u, điểm trắng v&agrave; dải m&agrave;u ch&iacute;nh x&aacute;c nhất trước khi được xuất xưởng.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>B&agrave;n ph&iacute;m Magic Keyboard ho&agrave;n to&agrave;n mới</h3>\r\n\r\n<p>Thay v&igrave; sử dụng b&agrave;n ph&iacute;m c&aacute;nh bướm như c&aacute;c sản phẩm Macbook Pro tiền nhiệm, CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) được trang bị bộ b&agrave;n ph&iacute;m ma thuật Magic Keyboard với cơ chế cắt k&eacute;o v&ocirc; c&ugrave;ng tinh tế. H&igrave;nh tr&igrave;nh ph&iacute;m cũng được n&acirc;ng l&ecirc;n 1mm v&agrave; th&ecirc;m lớp l&oacute;t cao su ở ph&iacute;a b&ecirc;n dưới b&agrave;n ph&iacute;m nhằm đem lại cảm gi&aacute;c thoải m&aacute;i v&agrave; y&ecirc;n tĩnh hơn cho người d&ugrave;ng khi nhấn ph&iacute;m. So với b&agrave;n ph&iacute;m c&aacute;nh bướm trước kia, độ n&ocirc;ng của Macgic tốt hơn nhiều. Đặc biệt, ph&iacute;m &ldquo;Exc&rdquo; thay v&igrave; để tr&ecirc;n thanh TouchBar cuối c&ugrave;ng n&oacute; cũng đ&atilde; được Apple t&aacute;ch ri&ecirc;ng ra th&agrave;nh một n&uacute;t vật l&yacute;.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" height=\"500\" sizes=\"(max-width: 500px) 100vw, 500px\" src=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-3.jpg\" srcset=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-3.jpg 500w, https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-3-180x180.jpg 180w, https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-3-300x300.jpg 300w\" width=\"500\" /></p>\r\n\r\n<h3>Hệ thống tản nhiệt hiệu quả hơn</h3>\r\n\r\n<p>Từ trước đến nay, d&ugrave; được nhồi nh&eacute;t những chiếc CPU, GPU khủng khiếp nhưng hệ thống tản nhiệt tr&ecirc;n Macbook Pro 15.6 inch vẫn lu&ocirc;n hoạt động tốt. V&agrave; đến CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB), kiến tr&uacute;c tản nhiệt của n&oacute; lại được Apple l&agrave;m mới th&ecirc;m lần nữa nhằm mang đến hiệu quả hoạt động tốt hơn. N&oacute; được thiết kế với 2 quạt to hơn, đường ống dẫn nhiệt cũng theo đ&oacute; to hơn nhiều so với trước. Nhờ vậy m&agrave; khả năng dẫn kh&iacute; của V cũng tăng l&ecirc;n 28%. Ch&iacute;nh điều n&agrave;y đ&atilde; gi&uacute;p cho CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) c&oacute; thể chạy tối đa c&ocirc;ng suất của m&igrave;nh tr&ocirc;ng suốt một khoảng thời gian d&agrave;i m&agrave; kh&ocirc;ng lo bị n&oacute;ng m&aacute;y.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" height=\"562\" sizes=\"(max-width: 852px) 100vw, 852px\" src=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-4.jpg\" srcset=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-4.jpg 1708w, https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-4-768x507.jpg 768w\" width=\"852\" /></p>\r\n\r\n<h3>Bộ xử l&yacute; mạnh mẽ hơn bao giờ hết</h3>\r\n\r\n<p>Với bộ vi xử l&yacute; Intel thế hệ thứ 9 v&agrave; 8 l&otilde;i ho&agrave;n to&agrave;n mới với Turbo Boost l&ecirc;n đến 5.0 GHz, CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) ch&iacute;nh l&agrave; chiếc notebook c&oacute; bộ vi xử l&yacute; mạnh mẽ nhất t&iacute;nh đến thời điểm hiện tại. Kết hợp với n&oacute; l&agrave; bộ nhớ RAM dung lượng 64GB DDR4 c&ugrave;ng tốc độ bus 2666MHz. Nhờ vậy m&agrave; hiệu năng của CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) đạt được mức cao nhất. Những c&ocirc;ng việc y&ecirc;u cầu t&aacute;c vụ đặc biệt phức tạp như render 3D, coding hay chỉnh sửa video giờ đ&acirc;y đều c&oacute; thể chạy mượt m&agrave; tr&ecirc;n CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB).</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" height=\"559\" sizes=\"(max-width: 861px) 100vw, 861px\" src=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-5.jpg\" srcset=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-5.jpg 1632w, https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-5-768x499.jpg 768w\" width=\"861\" /></p>\r\n\r\n<p>CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) khi được so s&aacute;nh với Macbook Pro l&otilde;i tứ nhanh nhất (i7-7920HQ) đ&atilde; cho ra kết quả v&ocirc; c&ugrave;ng đ&aacute;ng nể:<br />\r\n&ndash; Tốc độ xử l&yacute; nhạc của n&oacute; nhanh hơn gấp 2.1 lần trong ứng dụng Logic Pro X<br />\r\n&ndash; Tốc độ m&ocirc; phỏng động lực trong Matlab của n&oacute; cũng nhanh hơn gấp 2.1 lần<br />\r\n&ndash; Với c&aacute;c nh&agrave; ph&aacute;t triển ứng dụng tr&ecirc;n Xcode th&igrave; việc bi&ecirc;n dịch m&atilde; cũng nhanh hơn gấp 1.8 lần.<br />\r\n&ndash; X&eacute;t về tốc độ xử l&yacute; c&aacute;c tấm ảnh phức tạp trong ứng dụng Photoshop, CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) cũng nhanh hơn 1.7 lần.</p>\r\n\r\n<p>CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) sử dụng chip core i8 c&oacute; 8 nh&acirc;n c&ugrave;ng tốc độ cơ bản l&agrave; 2.3GHz, bộ nhớ đệm l&ecirc;n đến 16MB v&agrave; Turbo Boost l&ecirc;n đến 4.6GHz. CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) cũng được trang bị Ram 16GB 2666MHz DDR4.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" height=\"242\" src=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-6.jpg\" width=\"400\" /></p>\r\n\r\n<h3>Card đồ họa ti&ecirc;n tiến bậc nhất</h3>\r\n\r\n<p>Hiệu suất GPU lu&ocirc;n l&agrave; một yếu tố đ&aacute;nh gi&aacute; quan trọng với những người d&ugrave;ng l&agrave; nh&agrave; sản xuất phim, game hay x&acirc;y dựng c&aacute;c ứng dụng dựa tr&ecirc;n nền tảng AI. V&agrave; CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) chắc chắn sẽ l&agrave; một sự lựa chọn tuyệt vời với AMD Radeon Pro 5000M series mới nhất. Đ&acirc;y l&agrave; card sử dụng c&ocirc;ng nghệ &ldquo;discreet GPU&rdquo; dựa tr&ecirc;n nền tảng chip 7nm v&agrave; bộ nhớ video mới nhất GDDR6 với t&ugrave;y chọn VRAM l&ecirc;n đến 8GB. Tất cả những ưu điểm n&agrave;y cho ph&eacute;p CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) xử l&yacute; t&aacute;c vụ nặng nhanh hơn bao giờ hết.</p>\r\n\r\n<p>Ngo&agrave;i ra, CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) c&ograve;n c&oacute; cấu h&igrave;nh ti&ecirc;u chuẩn với card đồ họa Radeon Pro 5000M w/4GB GDDR6 memory. Điều n&agrave;y cho ph&eacute;p n&oacute; mang lại hiệu suất đồ họa cao hơn 2.1 lần so với cấu h&igrave;nh ti&ecirc;u chuẩn.</p>\r\n\r\n<p>Nếu bạn lựa chọn CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) với cầu h&igrave;nh cao nhất th&igrave; tương đương với n&oacute; ch&iacute;nh l&agrave; hiệu suất đồ họa cũng sẽ nhanh hơn 80%.<br />\r\nKhi so s&aacute;nh CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) với phi&ecirc;n bản Mac Pro 15 inch c&oacute; 8 nh&acirc;n với card đồ họa cao cấp nhất, kết quả m&agrave; Apple nhận được đ&oacute; l&agrave;:<br />\r\n&ndash; Hiện ứng hiển thị khi ph&acirc;n loại m&agrave;u trong chương tr&igrave;nh Davinci Resolve sẽ nhanh hơn 1.8 lần.<br />\r\n&ndash; Tốc độ chơi game v&agrave; độ mượt trong tr&ograve; chơi Fortnite l&ecirc;n đến 1.6 lần.<br />\r\n&ndash; C&aacute;c nh&agrave; ph&aacute;t triển ứng dụng cũng được trả về kết quả nhanh hơn 1.4 lần trong Unity khi sử dụng CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB)</p>\r\n\r\n<h3>Dung lượng pin khủng nhất</h3>\r\n\r\n<p>Với những hiệu năng khủng khiếp như tr&ecirc;n, Apple đ&atilde; sử dụng củ sạc USB-C với c&ocirc;ng suất 96W v&agrave; cụ pin Lithium c&oacute; dung lượng l&ecirc;n đến 100WHr để cung cấp năng lượng cho CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB). Đ&acirc;y cũng l&agrave; dung lượng lớn nhất từ trước đến nay tr&ecirc;n c&aacute;c d&ograve;ng Macbook của Apple.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" height=\"502\" sizes=\"(max-width: 811px) 100vw, 811px\" src=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-78.jpg\" srcset=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-78.jpg 2411w, https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-78-768x475.jpg 768w\" width=\"811\" /></p>\r\n\r\n<p>Với cục pin 100WHr n&agrave;y, Apple c&ocirc;ng bố CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) c&oacute; thể k&eacute;o d&agrave;i thời gian sử dụng pin l&ecirc;n đến 11 giờ đồng hồ cho c&aacute;c c&ocirc;ng việc như lướt web, ph&aacute;t lại video từ ứng dụng Apple TV.</p>\r\n\r\n<h3>SSD l&ecirc;n đến 8TB</h3>\r\n\r\n<p>Lần đầu ti&ecirc;n tr&ecirc;n thế giới, một chiếc m&aacute;y t&iacute;nh x&aacute;ch tay sở hữu SSD c&oacute; dung lượng l&ecirc;n đến 8TB. Đ&acirc;y quả thực l&agrave; một con số khủng khiếp v&agrave; n&oacute; ho&agrave;n to&agrave;n c&oacute; thể thoải m&aacute;i đ&aacute;p ứng được nhu cầu của c&aacute;c nh&agrave; l&agrave;m phim hay những người d&ugrave;ng c&oacute; hệ thống thư viện t&agrave;i sản lớn.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" height=\"470\" sizes=\"(max-width: 800px) 100vw, 800px\" src=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-9.jpg\" srcset=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-9.jpg 800w, https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-9-768x451.jpg 768w\" width=\"800\" /></p>\r\n\r\n<p>Tốc độ đọc v&agrave; ghi tr&ecirc;n SSD của CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) lần lượt được ghi nh&acirc;n l&agrave; 3.2Gbps v&agrave; 2.2 Gbps. V&agrave; n&oacute; được xem l&agrave; tốc độ SSD nhanh nhất trong c&aacute;c d&ograve;ng m&aacute;y t&iacute;nh x&aacute;ch tay tr&ecirc;n thị trường hiện nay.</p>\r\n\r\n<p>CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) đ&atilde; từ bỏ phi&ecirc;n bản SSD 256GB m&agrave; thay v&agrave;o đ&oacute; l&agrave; SSD 512GB v&agrave; 1TB cho những cấu h&igrave;nh ti&ecirc;u chuẩn khi được b&aacute;n ra. Ngo&agrave;i ra bạn cũng c&oacute; thể lựa chọn option n&acirc;ng cấp l&ecirc;n SSD 8TB. Tuy nhi&ecirc;n do SSD được h&agrave;n chết v&agrave;o board mạch chủ v&agrave; sẽ kh&ocirc;ng thể n&acirc;ng cấp sau khi đ&atilde; xuất xưởng n&ecirc;n nếu muốn mua bản n&acirc;ng cấp bạn cần đặt ri&ecirc;ng với Apple.</p>\r\n\r\n<h3>Hệ điều h&agrave;nh macOS</h3>\r\n\r\n<p>Nhờ sức mạnh v&agrave; độ tin cậy m&agrave; macOS lu&ocirc;n nhận được sự t&iacute;n nhiệm của người d&ugrave;ng. CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) được trang bị hệ điều h&agrave;nh MacOS Catanila mới nhất hiện nay. N&oacute; được thiết kế nhằm tận dụng tối đa sức mạnh trong phần cứng của M&agrave; đồng thời cung cấp c&aacute;c t&iacute;nh năng v&ocirc; c&ugrave;ng mạnh mẽ với hiệu suất cao nhất. Đồng thời n&oacute; c&ograve;n c&oacute; thể hoạt động trơn tru tr&ecirc;n c&aacute;c thiết bị kh&aacute;c của Apple.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" height=\"526\" sizes=\"(max-width: 810px) 100vw, 810px\" src=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-10.jpg\" srcset=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-10.jpg 1632w, https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-10-768x499.jpg 768w\" width=\"810\" /></p>\r\n\r\n<h3>MacOS với c&aacute;c t&iacute;nh năng vượt trội như:</h3>\r\n\r\n<p>Dark Mode: gi&uacute;p l&agrave;m nổi bật l&ecirc;n những nội dung chuy&ecirc;n nghiệp đồng thời gi&uacute;p CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) tiết kiệm năng lượng một c&aacute;ch đ&aacute;ng kể.<br />\r\nSidecar: đ&acirc;y l&agrave; một t&iacute;nh năng mới v&agrave; v&ocirc; c&ugrave;ng được y&ecirc;u th&iacute;ch tr&ecirc;n MacOS Catalina. N&oacute; cho ph&eacute;p bạn tận dụng iPad như một m&agrave;n h&igrave;nh thứ 2 hay bất kỳ một thiết bị đầu v&agrave;o n&agrave;o c&oacute; độ ch&iacute;nh x&aacute;c cao nhờ m&agrave;n h&igrave;nh cảm ứng v&agrave; Apple Pencil.</p>\r\n\r\n<p>MacOS tr&ecirc;n CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) gồm rất nhiều c&aacute;c ứng dụng như: Safari, Mail, Page, Number hay hỗ trợ c&aacute;c ứng dụng c&oacute; hiệu suất cao như Final Cut Pro X, Logic Pro X v&agrave; Xcode.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" height=\"280\" src=\"https://macstores.vn/wp-content/uploads/2019/11/danh-gia-macbook-pro-mvvk2-11.jpg\" width=\"435\" /></p>\r\n\r\n<p>Mặc d&ugrave; mới được Apple ra mắt v&agrave;i ng&agrave;y trước nhưng CTO &ndash; MacBook Pro 16 inch 2019 New&ndash; (Space Gray/i9 2.4Ghz/32GB/1TB/8GB) hiện nay đ&atilde; đạt được lượng đặt h&agrave;ng khổng lồ từ người d&ugrave;ng. Bạn c&oacute; thể truy cập trực tiếp v&agrave;o web site của It-stores&nbsp;để đặt h&agrave;ng sản phẩm cũng như xem th&ocirc;ng tin chi tiết hơn về sản phẩm.</p>', 92000000, 88000000, 3, 'Bộ sản phẩm', 'MacBook_Pro_16-in_Touch_Bar_Pure_Top_Open_Silver_SCREEN.jpg', 'Mac', 'APPLE', 1, NULL, '2021-07-02 18:09:33', '2021-07-27 21:32:58', 1, '2021-07-08 14:48:16');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (5, 'Điện thoại Samsung Galaxy Note 9', '<p><strong>Cấu h&igrave;nh Điện thoại Samsung Galaxy Note 9</strong></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>M&agrave;n h&igrave;nh: Super AMOLED6.4&quot;Quad HD+ (2K+)</p>\r\n	</li>\r\n	<li>\r\n	<p>Camera sau: 2 camera 12 MP</p>\r\n	</li>\r\n	<li>\r\n	<p>Camera trước:&nbsp;8 MP</p>\r\n	</li>\r\n	<li>\r\n	<p>Chip:&nbsp;Exynos 9810</p>\r\n	</li>\r\n	<li>\r\n	<p>RAM:&nbsp;6 GB</p>\r\n	</li>\r\n	<li>\r\n	<p>Bộ nhớ trong:&nbsp;128 GB</p>\r\n	</li>\r\n	<li>\r\n	<p>SIM:&nbsp;2 Nano SIM (SIM 2 chung khe thẻ nhớ)Hỗ trợ 4G</p>\r\n	</li>\r\n	<li>\r\n	<p>Pin sạc:&nbsp;4000 mAh</p>\r\n	</li>\r\n</ul>', '<h3><strong>Mang lại sự cải tiến đặc biệt trong c&acirc;y b&uacute;t S Pen, si&ecirc;u phẩm&nbsp;Samsung Galaxy Note 9&nbsp;c&ograve;n sở hữu dung lượng pin khủng l&ecirc;n tới 4.000 mAh c&ugrave;ng hiệu năng mạnh mẽ vượt bậc, xứng đ&aacute;ng l&agrave; một trong những chiếc&nbsp;điện thoại&nbsp;cao cấp nhất của Samsung.</strong></h3>\r\n\r\n<h3><strong>Một ch&uacute;t thay đổi trong thiết kế</strong></h3>\r\n\r\n<p>Chiếc&nbsp;điện thoại Samsung&nbsp;mới vẫn thừa hưởng lối thiết kế v&ocirc; c&ugrave;ng quyến rũ từ đ&agrave;n anh của m&igrave;nh với th&acirc;n h&igrave;nh mạnh mẽ v&agrave; được c&aacute;ch điệu bởi những đường cong mềm mại.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/154897/samsung-galaxy-note-9-6-1.jpg\" onclick=\"return false;\"><img alt=\"Thiết kế điện thoại Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/154897/samsung-galaxy-note-9-6-1.jpg\" title=\"Thiết kế điện thoại Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>Điểm thay đổi đ&aacute;ng ch&uacute; &yacute; phải kể đến mặt lưng khi m&agrave;&nbsp;cảm biến v&acirc;n tay&nbsp;của m&aacute;y đ&atilde; được đặt dưới cụm&nbsp;camera k&eacute;p&nbsp;với một vị tr&iacute; thuận lợi để bạn c&oacute; thể mở kh&oacute;a m&aacute;y một c&aacute;ch dễ d&agrave;ng.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/154897/samsung-galaxy-note-98-1.png\" onclick=\"return false;\"><img alt=\"Cảm biến vân tay trên điện thoại Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/154897/samsung-galaxy-note-98-1.png\" title=\"Cảm biến vân tay trên điện thoại Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>B&ecirc;n cạnh đ&oacute; Samsung đ&atilde; tối giản cạnh viền tr&ecirc;n dưới để mang lại cho bạn một trải nghiệm tuyệt vời hơn nữa với một m&agrave;n h&igrave;nh c&oacute; k&iacute;ch thước khủng l&ecirc;n đến 6.4 inch c&oacute; độ ph&acirc;n giải 2K+ với tỉ lệ tr&agrave;n viền 18.5:9.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/154897/samsung-galaxy-note-9-1-2.jpg\" onclick=\"return false;\"><img alt=\"Màn hình điện thoại Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/154897/samsung-galaxy-note-9-1-2.jpg\" title=\"Màn hình điện thoại Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>Nh&igrave;n chung với chỉ một ch&uacute;t thay đổi nhỏ trong thiết kế cũng đủ để gi&uacute;p&nbsp;Galaxy Note 9 trở n&ecirc;n nổi bật v&agrave; quyến rũ, cũng như khắc phục được những thiếu s&oacute;t từ đ&agrave;n anh Note 8.</p>\r\n\r\n<h3><strong>Hiệu năng lu&ocirc;n ở đỉnh cao</strong></h3>\r\n\r\n<p>L&agrave; một flagship cao cấp n&ecirc;n những g&igrave; mạnh mẽ nhất đều được hội tụ tr&ecirc;n&nbsp;Galaxy Note 9 với con chip&nbsp;Snapdragon 845&nbsp;hoặc&nbsp;Exynos 9810&nbsp;t&ugrave;y v&agrave;o từng thị trường kh&aacute;c nhau.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/154897/samsung-galaxy-note-9-2-2.jpg\" onclick=\"return false;\"><img alt=\"Điểm Antutu Benchmark trên điện thoại Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/154897/samsung-galaxy-note-9-2-2.jpg\" title=\"Điểm Antutu Benchmark trên điện thoại Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>Đi k&egrave;m theo đ&oacute; l&agrave; bộ nhớ RAM l&ecirc;n đến 6 GB đ&atilde; gi&uacute;p&nbsp;Note 9 trở th&agrave;nh một trong những smartphone mạnh mẽ nhất hiện nay đủ để chiến mọi thể loại game nặng nhất.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/154897/samsung-galaxy-note-9-gaming-2.gif\" onclick=\"return false;\"><img alt=\"Chơi game trên điện thoại Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/154897/samsung-galaxy-note-9-gaming-2.gif\" title=\"Chơi game trên điện thoại Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>M&aacute;y sở hữu phi&ecirc;n bản 128 GB v&agrave; c&oacute; cả một phi&ecirc;n bản cao cấp nhất,&nbsp;v&ocirc; c&ugrave;ng mạnh mẽ kh&aacute;c đ&oacute; ch&iacute;nh l&agrave; bộ nhớ trong l&ecirc;n tới 512 GB đi k&egrave;m với RAM 8 GB.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/183507/galaxy-note-9-6.jpg\" onclick=\"return false;\"><img alt=\"Giao diện Android điện thoại Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/183507/galaxy-note-9-6.jpg\" title=\"Giao diện Android điện thoại Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>Đ&aacute;ng tiếc m&aacute;y vẫn chỉ được sẵn&nbsp;Android 8.1 (Oreo)&nbsp;v&agrave; hứa hẹn trong thời gian tới sẽ được cập nhật nhanh ch&oacute;ng l&ecirc;n phi&ecirc;n bản Android mới nhất với nhiều t&iacute;nh năng mới mẻ.</p>\r\n\r\n<h3><strong>B&uacute;t S Pen cải tiến đến vi diệu</strong></h3>\r\n\r\n<p>Một sự thay đổi khiến bạn phải th&iacute;ch th&uacute; c&oacute; lẽ l&agrave; chiếc b&uacute;t S Pen đi k&egrave;m theo m&aacute;y với nhiều m&agrave;u sắc nổi bật.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/154897/samsung-galaxy-note-9-13.jpg\" onclick=\"return false;\"><img alt=\"Bút S Pen trên điện thoại Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/154897/samsung-galaxy-note-9-13.jpg\" title=\"Bút S Pen trên điện thoại Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>Chưa dừng ở đ&oacute;, chiếc b&uacute;t n&agrave;y c&ograve;n được trang bị khả năng đặc biệt gi&uacute;p điều khiển Note 9 dễ d&agrave;ng th&ocirc;ng qua Bluetooth.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/154897/samsung-galaxy-note-9-12-1.jpg\" onclick=\"return false;\"><img alt=\"Điều khiển bút S Pen trên điện thoại Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/154897/samsung-galaxy-note-9-12-1.jpg\" title=\"Điều khiển bút S Pen trên điện thoại Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>Cụ thể hơn, chỉ với một thao t&aacute;c nhấn đơn giản l&agrave; bạn c&oacute; thể dễ d&agrave;ng chụp ảnh selfie, tr&igrave;nh chiếu b&agrave;i thuyết tr&igrave;nh, ngưng/ph&aacute;t video c&ugrave;ng nhiều c&ocirc;ng năng kh&aacute;c nữa.</p>\r\n\r\n<h3><strong>Camera thay đổi&nbsp;khẩu độ&nbsp;dễ d&agrave;ng v&agrave; t&iacute;ch hợp AI</strong></h3>\r\n\r\n<p>Galaxy Note 9 sở hữu bộ đ&ocirc;i camera k&eacute;p c&oacute; c&ugrave;ng độ ph&acirc;n giải 12 MP c&oacute; khả năng thay đổi khẩu độ như&nbsp;Galaxy S9+&nbsp;v&agrave; được t&iacute;ch hợp th&ecirc;m c&ocirc;ng nghệ AI gi&uacute;p chất lượng ảnh chụp đẹp hơn đ&aacute;ng kể.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/154897/samsung-galaxy-note-9-7-1.jpg\" onclick=\"return false;\"><img alt=\"Bút S Pen trên điện thoại Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/154897/samsung-galaxy-note-9-7-1.jpg\" title=\"Bút S Pen trên điện thoại Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>Theo như những g&igrave; m&agrave; Samsung giới thiệu th&igrave; AI tr&ecirc;n Note 9 c&oacute; khả năng ph&acirc;n loại nhiều đối tượng, tự động điều chỉnh m&agrave;u sắc, độ tương phản v&agrave; độ s&aacute;ng trong bối cảnh chụp ảnh kh&aacute;c nhau.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/154897/samsung-galaxy-note-9-3-2.jpg\" onclick=\"return false;\"><img alt=\"Ảnh chụp bằng camera sau trên điện thoai Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/154897/samsung-galaxy-note-9-3-2.jpg\" title=\"Ảnh chụp bằng camera sau trên điện thoai Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>Chất lượng ảnh chụp của m&aacute;y v&ocirc; c&ugrave;ng ấn tượng với c&aacute;c chi tiết được thể hiện r&otilde; r&agrave;ng, m&agrave;u sắc c&acirc;n đối v&agrave; độ tương phản cao.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/154897/samsung-galaxy-note-9-1-3.jpg\" onclick=\"return false;\"><img alt=\"Ảnh selfie trên điện thoại Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/154897/samsung-galaxy-note-9-1-3.jpg\" title=\"Ảnh selfie trên điện thoại Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>Cũng như tr&ecirc;n Galaxy S9+ th&igrave; Note 9 cũng được trang bị khả năng quay phim&nbsp;Super Slow Motion&nbsp;gi&uacute;p bạn ghi lại những khoảnh khắc đ&aacute;ng nhớ trong cuộc sống.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/183507/galaxy-note-9-17.jpg\" onclick=\"return false;\"><img alt=\"Quay phim Super Slow Motion trên Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/183507/galaxy-note-9-17.jpg\" title=\"Quay phim Super Slow Motion trên Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3><strong>Dung lượng pin được cải tiến</strong></h3>\r\n\r\n<p>Sau những g&igrave; m&agrave; người d&ugrave;ng mong mỏi th&igrave; nay&nbsp;Note 9 l&agrave; chiếc&nbsp;điện thoại pin tr&acirc;u&nbsp;sở hữu một vi&ecirc;n pin to hơn, mạnh mẽ v&agrave; bền bỉ hơn với dung lượng l&ecirc;n đến 4000 mAh.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/154897/samsung-galaxy-note-9-5-1.jpg\" onclick=\"return false;\"><img alt=\"Đánh giá điện thoại Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/154897/samsung-galaxy-note-9-5-1.jpg\" title=\"Đánh giá điện thoại Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>Tuy kh&ocirc;ng thuộc dạng khủng nhất nhưng từng đ&oacute; cũng đủ để bạn c&oacute; thể h&agrave;i l&ograve;ng với c&aacute;c trải nghiệm hằng ng&agrave;y một c&aacute;ch trọn vẹn.</p>\r\n\r\n<p>Hơi thất vọng nhẹ khi m&aacute;y vẫn chỉ được trang bị c&ocirc;ng nghệ sạc nhanh&nbsp;Quick Charge 2.0&nbsp;n&ecirc;n thời gian sạc vẫn chưa được tối ưu nhất.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/183507/galaxy-note-9-20.jpg\" onclick=\"return false;\"><img alt=\"Cổng sạc trên điện thoại Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/183507/galaxy-note-9-20.jpg\" title=\"Cổng sạc trên điện thoại Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<h3><strong>Hỗ trợ nhiều t&iacute;nh năng đặc biệt kh&aacute;c</strong></h3>\r\n\r\n<p>T&iacute;nh năng&nbsp;Samsung DeX&nbsp;vẫn được hỗ trợ tr&ecirc;n Note 9 nhưng đ&atilde; được Samsung cải tiến th&ocirc;ng qua một sợi c&aacute;p nhỏ gọn mang t&ecirc;n&nbsp;DeX HDMI.</p>\r\n\r\n<p>Nhờ đ&oacute; m&agrave; việc kết nối&nbsp;điện thoại&nbsp;với một m&agrave;n h&igrave;nh bất kỳ&nbsp;đem đến một trải nghiệm như m&aacute;y t&iacute;nh trở n&ecirc;n thuận tiện hơn bao giờ hết.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.thegioididong.com/images/42/183507/galaxy-note-9-19.jpg\" onclick=\"return false;\"><img alt=\"Samsung Galaxy Note 9\" src=\"https://cdn.tgdd.vn/Products/Images/42/183507/galaxy-note-9-19.jpg\" title=\"Samsung Galaxy Note 9\" /></a></p>\r\n\r\n<p>Ngo&agrave;i ra, những t&iacute;nh năng như:&nbsp;mở kh&oacute;a bằng mống mắt,&nbsp;bảo mật khu&ocirc;n mặt,&nbsp;Samsung Pay&nbsp;hay&nbsp;khả năng chống nước IP68&nbsp;vẫn được giữ lại tr&ecirc;n&nbsp;Galaxy Note 9.</p>', 24500000, NULL, NULL, 'Bộ sản phẩm', 'samsung-galaxy-note-9-black-600x600.jpg', 'DT', 'SAM', 2, NULL, '2021-07-02 18:20:32', '2021-07-02 21:49:58', 1, '2021-07-02 18:47:54');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (6, 'Màn hình máy tính LG 27UP850-W 27 inch 4K IPS', '<h4><strong>M&ocirc; tả&nbsp;chi tiết</strong></h4>\r\n\r\n<p>H&atilde;ng sản xuất: LG - Model: 27UP850-W<br />\r\nK&iacute;ch thước m&agrave;n h&igrave;nh: 27 inch<br />\r\nĐộ ph&acirc;n giải: 4K UHD (3840 x 2160) - Tỉ lệ: 16:9<br />\r\nTấm nền m&agrave;n h&igrave;nh: IPS<br />\r\nĐộ s&aacute;ng: 400cd (typ)/320cd (Min)<br />\r\nM&agrave;u sắc hiển thị: 1.07B<br />\r\nĐộ tương phản: 100:1 (Min.), 1200:1 (Typ.)<br />\r\nTần số qu&eacute;t: 60Hz<br />\r\nCổng kết nối: 2 x HDMIUSB Type-C1 x DisplayPortHeadphone Out<br />\r\nThời gian đ&aacute;p ứng: 5ms (GtG at Faster)<br />\r\nG&oacute;c nh&igrave;n: 178˚(R/L), 178˚(U/D)<br />\r\nĐiện năng ti&ecirc;u thụ: 185W<br />\r\nK&iacute;ch thước: 613,5 x 363,5 x 45,4 mm -&nbsp;5,9kg<br />\r\nPhụ kiện: C&aacute;p nguồn, Hướng dẫn sử dụng,...</p>', '<h2><strong>M&agrave;n h&igrave;nh m&aacute;y t&iacute;nh LG 27UP850-W 27 inch 4K IPS&nbsp;</strong></h2>\r\n\r\n<h2><strong>D&Agrave;NH CHO NHỮNG S&Aacute;NG TẠO ĐAM M&Ecirc;</strong></h2>\r\n\r\n<p>Nhắc tới&nbsp;m&agrave;n h&igrave;nh&nbsp;cao cấp th&igrave; mọi người nghĩ ngay tới c&aacute;c sản phẩm&nbsp;m&agrave;n h&igrave;nh&nbsp;của thương hiệu LG.&nbsp;M&agrave;n h&igrave;nh LG&nbsp;n&agrave;y đ&atilde; kh&ocirc;ng ngừng cải tiến c&aacute;c sản phẩm để mang tới cho người d&ugrave;ng những gi&aacute; trị tốt nhất, với &nbsp;c&aacute;c c&ocirc;ng nghệ m&agrave;n h&igrave;nh tốt nh&acirc;t hiện nay, với nhiều tỷ lệ m&agrave;n h&igrave;nh kh&aacute;c nhau.</p>\r\n\r\n<p>Bạn đ&atilde; được trải nghiệm m&agrave;n h&igrave;nh 4K UHD của LG chưa? Nếu như Full HD đ&atilde; qu&aacute; quen thuộc, phổ th&ocirc;ng th&igrave; 4K UHD mang tới sự mới mẻ với khả năng&nbsp;hỗ trợ m&agrave;u sắc v&agrave; độ s&aacute;ng vượt trội so với m&agrave;n h&igrave;nh th&ocirc;ng thường, hứa hẹn l&agrave; c&ocirc;ng cụ đắc lực cho c&aacute;c nh&agrave; thiết kế h&igrave;nh ảnh, video, s&aacute;ng tạo nội dung v&agrave; chơi game giải tr&iacute;.</p>\r\n\r\n<p>Với mức gi&aacute; hơn 12 triệu đồng, m&agrave;n h&igrave;nh m&aacute;y t&iacute;nh&nbsp;<strong>LG 27UP850-W&nbsp;</strong>4K UHD mang tới sự đổi mới gi&uacute;p tăng năng suất l&agrave;m việc, giải tr&iacute; v&agrave; chơi game của bạn, chắc chắn sẽ kh&ocirc;ng khi&ecirc;n anh em phải thất vọng! C&ugrave;ng An Ph&aacute;t kh&aacute;m ph&aacute; em &yacute; nh&eacute;!</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://anphat.com.vn/media/lib/06-04-2021/27up850-w-bv-5.jpg\" width=\"897\" /></p>\r\n\r\n<p><strong>C&ugrave;ng t&igrave;m hiểu về thiết kế n&agrave;o!</strong></p>\r\n\r\n<p><strong>LG&nbsp;</strong>tối giản c&aacute;c chi tiết<strong>&nbsp;</strong>để người d&ugrave;ng c&oacute; thể dễ d&agrave;ng lắp đặt nhanh ch&oacute;ng, ch&iacute;nh x&aacute;c hơn. Phần ch&acirc;n đế của m&agrave;n h&igrave;nh&nbsp;kết nối với m&agrave;n h&igrave;nh ho&agrave;n to&agrave;n bằng khớp v&agrave; n&uacute;t bấm.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://anphat.com.vn/media/lib/06-04-2021/sd.png\" width=\"810\" /></p>\r\n\r\n<p>D&ugrave; l&agrave; d&ograve;ng m&agrave;n h&igrave;nh m&aacute;y t&iacute;nh n&agrave;o của LG th&igrave; họ vẫn lu&ocirc;n ch&uacute; trọng thiết kế viền mỏng 3 cạnh gi&uacute;p tăng tỉ lệ m&agrave;n h&igrave;nh tr&ecirc;n th&acirc;n m&aacute;y, mang tới tới trải h&igrave;nh ảnh ch&igrave;m đắm hơn rất nhiều. Gi&uacute;p người d&ugrave;ng sẽ tập trung v&agrave;o h&igrave;nh ảnh khi l&agrave;m việc v&agrave; giải tr&iacute; hơn.</p>\r\n\r\n<p>Ch&acirc;n đế h&igrave;nh b&aacute;n nguyệt lạ mắt, tạo điểm nhấn cho tổng thể chiếc m&agrave;n h&igrave;nh n&agrave;y. Ch&acirc;n đế chắc chắn nhưng với&nbsp;đường cong mềm mại mang tới cảm gi&aacute;c tao nh&atilde;, tinh tế. Ngo&agrave;i thẩm mĩ, ch&acirc;n đế c&ograve;n được thiết kế kh&aacute; th&ocirc;ng minh khi&nbsp;c&oacute; khả năng điều chỉnh linh hoạt độ cao, độ nghi&ecirc;ng v&agrave;&nbsp;Xoay 90&deg; dễ d&agrave;ng với trục xoay.</p>\r\n\r\n<p style=\"text-align:center\">&nbsp; &nbsp;<img alt=\"\" src=\"https://anphat.com.vn/media/lib/06-04-2021/27up850-w-bv-12.jpg\" width=\"808\" /></p>\r\n\r\n<p>LG đơn giản ho&aacute; c&aacute;c cổng kết nối ở mặt lưng, với c&aacute;c cổng kết nối phổ biến hiện nay gồm DisplayPort, HDMI (2 cổng) v&agrave; USB-C.&nbsp;<a href=\"https://www.anphatpc.com.vn/man-hinh-usb-type-c_dm1877.html\" target=\"_blank\"><strong>M&agrave;n h&igrave;nh&nbsp;</strong></a><a href=\"https://www.anphatpc.com.vn/man-hinh-usb-type-c_dm1877.html\" target=\"_blank\"><strong>USB Type-C</strong></a>&nbsp;đặc biệt hơn cả khi&nbsp;cho ph&eacute;p hiển thị video 4K với khung 60fps, truyền dữ liệu v&agrave; sạc pin cho m&aacute;y t&iacute;nh x&aacute;ch tay/thiết bị di động, tất cả c&ugrave;ng l&uacute;c tr&ecirc;n một d&acirc;y c&aacute;p duy nhất.&nbsp;Với cổng USB-C, ch&uacute;ng ta sẽ được trải nghiệm sự tiện lợi khi vừa kết nối m&agrave;n h&igrave;nh v&agrave; c&ograve;n hơn thế nữa.</p>\r\n\r\n<p>&nbsp;Ngo&agrave;i ra, LG cũng đ&atilde; &nbsp;sử dụng adapter rời &nbsp;để chiếc m&agrave;n h&igrave;nh của ch&uacute;ng ta trở n&ecirc;n mỏng v&agrave; nhẹ hơn.</p>\r\n\r\n<p style=\"text-align:center\">&nbsp; &nbsp;<img alt=\"\" src=\"https://anphat.com.vn/media/lib/06-04-2021/man-hinh-lg-27up850-w-3-songphuongvn_.jpg\" width=\"674\" /></p>\r\n\r\n<h3><strong>Chi tiết về cấu h&igrave;nh</strong></h3>\r\n\r\n<p><strong>Ti&ecirc;u chuẩn 4K tr&ecirc;n</strong>&nbsp;<strong>LG 27UP850-W&nbsp;</strong></p>\r\n\r\n<p><strong>M&agrave;n h&igrave;nh 4K</strong><strong>&nbsp;</strong>đang được coi l&agrave; xu hướng c&ocirc;ng ngh&ecirc; cho c&aacute;c d&ograve;ng m&agrave;n h&igrave;nh cao cấp của c&aacute;c thương hiệu lớn như SamSung, Sony, LG,&hellip; đ&atilde; v&agrave; đang kh&ocirc;ng ngừng ph&aacute;t triển.<strong>&nbsp;4K</strong>&nbsp;l&agrave; độ ph&acirc;n giải cao gấp nhiều lần so với độ ph&acirc;n giải m&agrave;n&nbsp;h&igrave;nh trước đ&acirc;y l&agrave;&nbsp;<strong>Full HD(1920&times;1080).&nbsp;</strong>Ch&iacute;nh v&igrave; vậy c&oacute; khả năng cho ph&eacute;p bạn trải nghiệm h&igrave;nh ảnh ch&acirc;n thực hơn sống động hơn, khung h&igrave;nh ho&agrave;n mỹ hơn ngay cả khi xem ở khoảng c&aacute;ch gần hoặc rất gần.</p>\r\n\r\n<p style=\"text-align:center\">&nbsp; &nbsp;<img alt=\"\" src=\"https://anphat.com.vn/media/lib/06-04-2021/2120_27uk850.png\" /></p>\r\n\r\n<p><strong>VESA DisplayHDR&trade; 400</strong></p>\r\n\r\n<p>M&agrave;n h&igrave;nh 4K tương th&iacute;ch chuẩn VESA DisplayHDR&trade; 400, cho m&agrave;u sắc vượt trội so với m&agrave;n h&igrave;nh th&ocirc;ng thường. Với độ s&aacute;ng tối đa đạt 400 nits cho h&igrave;nh ảnh nổi bật, ch&acirc;n thực như được t&aacute;i hiện trước măt bạn.</p>\r\n\r\n<p style=\"text-align:center\">&nbsp; &nbsp;&nbsp;<img alt=\"\" src=\"https://anphat.com.vn/media/lib/06-04-2021/p8-.png\" width=\"941\" /></p>\r\n\r\n<p><strong>sRGB 99%</strong></p>\r\n\r\n<p>Với những người l&agrave;m đồ họa chuy&ecirc;n nghiệp, chỉnh sửa h&igrave;nh ảnh, video rất cần một chiếc m&agrave;n h&igrave;nh c&oacute; chất lượng h&igrave;nh ảnh tốt, m&agrave;u sắc ch&iacute;nh x&aacute;c rất cao. Ch&iacute;nh v&igrave; vậy, LG đ&atilde; sử dụng tr&ecirc;n m&agrave;n h&igrave;nh độ bao phủ m&agrave;u 99%&nbsp;sRGB hỗ trợ đến 1.07 tỷ m&agrave;u sắc&nbsp;mang tới khả năng hiện thị m&agrave;u sắc ch&iacute;nh x&aacute;c cao vượt trội.</p>\r\n\r\n<p style=\"text-align:center\">&nbsp; &nbsp; &nbsp;&nbsp;<img alt=\"\" src=\"https://anphat.com.vn/media/lib/06-04-2021/4.png\" /></p>\r\n\r\n<p><strong>Tốc độ l&agrave;m mới: 60Hz&nbsp;v&agrave; Thời gian đ&aacute;p ứng: 5ms</strong></p>\r\n\r\n<p>Tốc độ l&agrave;m mới v&agrave; thời gian đ&aacute;p ứng c&oacute; th&ocirc;ng số kh&aacute; phổ th&ocirc;ng, kh&ocirc;ng phải suất sắc<strong>&nbsp;Thời gian đ&aacute;p ứng: 5msTốc độ l&agrave;m mới: 60HzThời gian đ&aacute;p ứng: 5ms</strong>nếu bạn muốn chơi những game y&ecirc;u cầu tốc độ cực nhanh. Nhưng với nhu cầu&nbsp;duyệt web, soạn văn bản hay chỉnh sửa ảnh, độ trễ giữa c&aacute;c m&agrave;u sắc thay đổi tr&ecirc;n m&agrave;n h&igrave;nh l&agrave; rất nhanh th&igrave;&nbsp;<strong>60Hz&nbsp;&nbsp;v&agrave; 5ms</strong>&nbsp;l&agrave; những th&ocirc;ng số rất chuẩn.</p>\r\n\r\n<p style=\"text-align:center\">&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<img alt=\"\" src=\"https://anphat.com.vn/media/lib/06-04-2021/27up850-w-bv-10.jpg\" width=\"885\" /></p>\r\n\r\n<p><strong>C&aacute;c c&ocirc;ng ngh&ecirc; được t&iacute;ch hợp</strong></p>\r\n\r\n<p><strong>Radeon FreeSync</strong></p>\r\n\r\n<p><strong>LG 27UP850-W&nbsp;</strong>&nbsp;được t&iacute;ch hợp sẵn c&ocirc;ng nghệ&nbsp;<strong>Radeon FreeSync,&nbsp;</strong>cho ph&eacute;p tốc độ l&agrave;m mới m&agrave;n h&igrave;nh đồng bộ h&oacute;a với tốc độ khung h&igrave;nh của tr&ograve; chơi.&nbsp;Đ&acirc;y l&agrave; c&ocirc;ng nghệ thường được trang bị&nbsp;tr&ecirc;n m&agrave;n h&igrave;nhgi&uacute;p ngăn chặn c&aacute;c hiện tượng như r&aacute;ch h&igrave;nh, hạn chế tối đa độ trễ đầu v&agrave;o trong khi chơi game v&agrave; ph&aacute;t video.</p>\r\n\r\n<p>M&agrave;n h&igrave;nh 60Hz chỉ thực hiện được 60 khung h&igrave;nh/gi&acirc;y v&agrave; đầu ra GPU của bạn giảm xuống, l&uacute;c n&agrave;y tốc độ l&agrave;m mới sẽ tự động khớp với m&agrave;n h&igrave;nh khi FreeSync được bật.</p>\r\n\r\n<p style=\"text-align:center\">&nbsp; &nbsp;&nbsp;<img alt=\"\" src=\"https://anphat.com.vn/media/lib/06-04-2021/f.png\" width=\"832\" /></p>\r\n\r\n<p><strong>Dynamic Action Sync</strong></p>\r\n\r\n<p>&nbsp;Nếu chỉ FreeSync l&agrave; chưa đủ, th&igrave; LG cũng đ&atilde; t&iacute;ch hợp th&ecirc;m c&ocirc;ng nghệ&nbsp;<strong>Dynamic Action Sync&nbsp;</strong>gi&uacute;p Game thủ c&oacute; thể trải nghiệm mượt m&agrave; c&aacute;c tr&ograve; chơi ở tốc độ cao hơn, c&aacute;c game RTS nhờ tối ưu h&oacute;a hơn với t&iacute;nh năng Đồng bộ h&agrave;nh động động, giảm thiểu độ trễ đầu v&agrave;o.</p>\r\n\r\n<p style=\"text-align:center\">&nbsp; &nbsp; &nbsp;<img alt=\"\" src=\"https://anphat.com.vn/media/lib/06-04-2021/ytry.png\" width=\"965\" /></p>\r\n\r\n<p><strong>C&acirc;n bằng tối</strong></p>\r\n\r\n<p>C&ograve;n với khả năng c&acirc;n bằng s&aacute;ng tối mang tới lợi thế lớn khi chơi game cho c&aacute;c game thủ khi người chơi game c&oacute; thể tr&aacute;nh c&aacute;c tay s&uacute;ng bắn tỉa trốn ở những nơi tối nhất v&agrave; nhanh ch&oacute;ng tho&aacute;t khỏi t&igrave;nh huống nguy hiểm.</p>\r\n\r\n<p>Nếu d&ugrave;ng thử với các tựa game như FPS, tính năng này sẽ<strong>&nbsp;</strong>phát huy rõ r&ecirc;̣t, game thủ d&ecirc;̃ dàng phản ứng nhanh hơn, đ&acirc;y ch&iacute;nh l&agrave; lợi thế để chiến thắng.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://anphat.com.vn/media/lib/06-04-2021/lll.png\" width=\"958\" /></p>\r\n\r\n<p><strong>&nbsp;</strong>Ngo&agrave;i ra, m&agrave;n h&igrave;nh c&ograve;n c&oacute;&nbsp;c&aacute;c chế độ chơi game kh&aacute;c nhau: Cho ph&eacute;p điều chỉnh m&agrave;u sắc h&igrave;nh ảnh cho ph&ugrave; hợp với từng tựa game FPS, RTS, Custom&hellip;</p>\r\n\r\n<p><strong>Tr&igrave;nh điều khiển m&agrave;n h&igrave;nh</strong></p>\r\n\r\n<p>Kh&ocirc;ng cần phải điều chỉnh bằng c&aacute;c n&uacute;t cứng tr&ecirc;n m&agrave;n h&igrave;nh, giờ đ&acirc;y bạn chỉ cần v&agrave;i c&uacute; nhấp chuột l&agrave; c&oacute; thể điều chỉnh:&nbsp;&Acirc;m lượng, độ s&aacute;ng, đặt sẵn chế độ h&igrave;nh ảnh, chế độ m&agrave;n h&igrave;nh 2.0 v&agrave; bộ điều khiển k&eacute;p v&agrave; nhiều c&agrave;i đặt kh&aacute;c. Sự tiện &iacute;ch n&agrave;y l&agrave; nhờ tr&igrave;nh điều khiển m&agrave;n h&igrave;nh đ&atilde; đưa nhiều c&agrave;i đặt m&agrave;n h&igrave;nh thiết yếu v&agrave;o 1 cửa sổ.</p>\r\n\r\n<p style=\"text-align:center\">&nbsp; &nbsp;&nbsp;<img alt=\"\" src=\"https://anphat.com.vn/media/lib/06-04-2021/yuyu.png\" /></p>\r\n\r\n<h2>Tương th&iacute;ch chuẩn HDCP 2.2</h2>\r\n\r\n<p>C&oacute; thể ph&aacute;t video từ dịch vụ trực tuyến 4K, m&aacute;y chơi game v&agrave; đầu đĩa Blu-ray Ultra HD do m&agrave;n h&igrave;nh n&agrave;y c&oacute; tương th&iacute;ch với khả năng bảo vệ chống sao ch&eacute;p HDCP 2.2</p>', 12550000, NULL, 6, 'Bộ sản phẩm', 'lg_27up850-w.jpg', 'MH', 'LG', 1, NULL, '2021-07-02 18:44:55', '2021-07-02 23:12:51', 1, '2021-07-02 22:52:33');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (7, 'Bàn phím cơ Leopold FC660M PD White Dark Grey', '<p><strong>Th&ocirc;ng số sản phẩm</strong></p>\r\n\r\n<ul>\r\n	<li>B&agrave;n ph&iacute;m Leopold FC660M PD</li>\r\n	<li>Thương hiệu b&agrave;n ph&iacute;m cơ l&acirc;u đời đến từ H&agrave;n Quốc</li>\r\n	<li>Thiết kế layout 60% gọn nhẹ, dễ mang đi mang lại</li>\r\n	<li>Keycap chất liệu PBT Doubleshot si&ecirc;u bền</li>\r\n	<li>Sử dụng 100% Switch Cherry chất lượng cao nhất được chọn lọc kĩ c&agrave;ng</li>\r\n	<li>Kh&ocirc;ng c&oacute; hệ thống đ&egrave;n Led, nhưng tối ưu tốt cảm gi&aacute;c g&otilde;</li>\r\n</ul>', '<h2><strong>B&agrave;n ph&iacute;m cơ Leopold FC660M PD White Dark Grey</strong></h2>\r\n\r\n<p>Leopold -&nbsp;thương hiệu b&agrave;n ph&iacute;m cơ lớn nhất H&agrave;n Quốc, đ&atilde; cho ra mắt sản phẩm mới với bộ m&agrave;u đẹp mắt. H&atilde;y c&ugrave;ng Playzone điểm qua c&aacute;c t&iacute;nh năng nổi bật của sản phẩm n&agrave;y nh&eacute;!</p>\r\n\r\n<h2><strong><u>1) T</u></strong><strong><u>&Iacute;NH NĂNG NỔI BẬT:</u></strong></h2>\r\n\r\n<h3>Sử dụng bộ Switch Cherry 100% ch&iacute;nh h&atilde;ng từ nước Đức</h3>\r\n\r\n<p>Ti&ecirc;u chuẩn của Leopold lu&ocirc;n đặt ở mức cao nhất. Bởi vậy những bộ b&agrave;n ph&iacute;m tới từ h&atilde;ng lu&ocirc;n c&oacute; 1 cảm gi&aacute;c g&otilde; đồng đều v&agrave; chất lượng nhất, mọi loại Switch được chọn lựa kĩ c&agrave;ng, mang lại sự c&acirc;n bằng cho người sử dụng</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://www.playzone.vn/image/catalog/san%20pham/leopold/ban-phim/900r-pd/white-grey/5.jpeg\" /></p>\r\n\r\n<h3>Keycap PBT Doubleshot</h3>\r\n\r\n<p>Với chất liệu nhựa keycap PBT Doubleshot d&agrave;y 1.5mm&nbsp;cao cấp nhất hiện nay g&oacute;p phần tăng cảm gi&aacute;c thoải m&aacute;i khi g&otilde; ph&iacute;m c&ugrave;ng với chất lượng kh&ocirc;ng hao m&ograve;n bởi thời gian.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://www.playzone.vn/image/catalog/san%20pham/leopold/ban-phim/900r-pd/white-grey/6.jpeg\" /></p>\r\n\r\n<h3>Thiết kế cổ điển, chất lượng tuyệt vời</h3>\r\n\r\n<p>B&agrave;n ph&iacute;m Leopold lu&ocirc;n được thiết kế sao cho ph&ugrave; hợp nhất với b&agrave;n tay người sử dụng. Với độ nghi&ecirc;ng vừa đủ với độ dốc c&oacute; t&iacute;nh to&aacute;n khoa học, Leopold tập trung hướng tới độ thoải m&aacute;i ph&ugrave; hợp nhu cầu g&otilde; phim cho người d&ugrave;ng. Cũng bởi vậy, b&agrave;n ph&iacute;m Leopold được thiết kế đơn giản tối đa nhất c&oacute; thể.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://www.playzone.vn/image/catalog/san%20pham/leopold/ban-phim/900r-pd/white-grey/4.jpeg\" /></p>\r\n\r\n<h3>Miếng vải l&oacute;t đệm ngăn tiếng ồn tối đa</h3>\r\n\r\n<p>Hầu hết mọi b&agrave;n ph&iacute;m cơ đều c&oacute; tiếng ồn khi g&otilde; kh&aacute; r&otilde; tiếng. Ch&iacute;nh v&igrave; điều n&agrave;y m&agrave; Leopold đ&atilde; trang bị một lớp vải r&aacute;p đặc biệt dưới bảng mạch ph&iacute;m, l&agrave;m giảm thiểu tiếng ồn kh&ocirc;ng cần thiết tr&aacute;nh sự sao nh&atilde;ng v&agrave; kh&oacute; chịu tới người d&ugrave;ng.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://www.playzone.vn/image/catalog/san%20pham/leopold/ban-phim/900r-pd/white-grey/9.jpg\" /></p>\r\n\r\n<h3>Độ ổn định cao cấp với khung&nbsp;CHERRY Stabilizer</h3>\r\n\r\n<h4>Với c&aacute;c ph&iacute;m Shift, Spacebar, Enter v&agrave; Backspace sẽ lu&ocirc;n lu&ocirc;n ở trạng th&aacute;i c&acirc;n bằng cho d&ugrave; bạn c&oacute; ấn ở g&oacute;c độ n&agrave;o đi chăng nữa. Với khung trục ổn định kh&ocirc;ng hề bị ảnh hưởng bởi thời gian. Chắc chắn sẽ cực k&igrave; hữu dụng!</h4>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://www.playzone.vn/image/catalog/san%20pham/leopold/ban-phim/900r-pd/white-grey/7.jpeg\" /></p>\r\n\r\n<h2>&nbsp;</h2>\r\n\r\n<h2>--------------------------------------------------------------------</h2>\r\n\r\n<h2 style=\"text-align:center\"><strong><u>2) H&Igrave;NH ẢNH SẢN PHẨM:</u></strong></h2>\r\n\r\n<p style=\"text-align:center\"><strong><u><img alt=\"\" src=\"https://www.playzone.vn/image/catalog/san%20pham/leopold/ban-phim/660m-pd/white-grey/1.jpg\" /></u></strong></p>\r\n\r\n<p style=\"text-align:center\"><strong><u><img alt=\"\" src=\"https://www.playzone.vn/image/catalog/san%20pham/leopold/ban-phim/660m-pd/white-grey/2.jpg\" /></u></strong></p>\r\n\r\n<p style=\"text-align:center\"><strong><u><img alt=\"\" src=\"https://www.playzone.vn/image/catalog/san%20pham/leopold/ban-phim/660m-pd/white-grey/3.jpg\" /></u></strong></p>', 2750000, NULL, 6, 'Bộ sản phẩm', 'leopold_fc660mpd_white_dark_grey.jpg', 'BPhim', 'LEOPOLD', 1, NULL, '2021-07-02 18:56:59', '2021-07-14 21:23:04', 1, '2021-07-05 16:44:55');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (8, 'Củ sạc ChargeAsap Omega 200W', '<h3><strong>Củ sạc 200W đầu ti&ecirc;n tr&ecirc;n thế giới</strong></h3>\r\n\r\n<h3><strong>Đặc t&iacute;nh Omega 200W</strong></h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Product Dimensions: 88 x 55 x 42mm / 3.46&Prime; x 2.17&Prime; x 1.65&Prime;</p>\r\n	</li>\r\n	<li>\r\n	<p>Product Weight: 220g / 0.49lb / 7.76oz</p>\r\n	</li>\r\n	<li>\r\n	<p>Power Input: AC 100-240V 50/60Hz 3.5A</p>\r\n	</li>\r\n	<li>\r\n	<p>Max Power Output: 100W</p>\r\n	</li>\r\n	<li>\r\n	<p>Ports: 2 x USB-C and 2 x USB-A</p>\r\n	</li>\r\n	<li>\r\n	<p>USB-C1: 100W Power Delivery 3.0, 5~15V/3A, 20V/3.25A, 20V/5A (PPS)</p>\r\n	</li>\r\n	<li>\r\n	<p>USB-C2: 100W Power Delivery 3.0, 5~15V/3A, 20V/3.25A, 20V/5A (PPS)</p>\r\n	</li>\r\n	<li>\r\n	<p>USB-A1: Quick Charge 3.0: 5V/3A, 9V/2A, 12V/1.5A (18W), SCP, VOOC: 5V/4.5A (22.5W)</p>\r\n	</li>\r\n	<li>\r\n	<p>USB-A2: Quick Charge 3.0: 5V/3A, 9V/2A, 12V/1.5A (18W), SCP, VOOC: 5V/4.5A (22.5W)</p>\r\n	</li>\r\n	<li>\r\n	<p>Device Operating Temperature: -10&ordm;C to 60&ordm;C</p>\r\n	</li>\r\n	<li>\r\n	<p>Enclosure: PC + ABS</p>\r\n	</li>\r\n	<li>\r\n	<p>Protection: Over-current, Over-voltage, Over-temperature, Short-circuit Protection</p>\r\n	</li>\r\n</ul>', '<p style=\"text-align:center\"><img alt=\"omega200w\" height=\"488\" sizes=\"(max-width: 695px) 100vw, 695px\" src=\"https://siliconz.vn/wp-content/uploads/2020/12/cac-cong-nghe.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2020/12/cac-cong-nghe.jpg 695w, https://siliconz.vn/wp-content/uploads/2020/12/cac-cong-nghe-300x211.jpg 300w\" width=\"695\" /></p>\r\n\r\n<h2><strong>Củ sạc 200W đầu ti&ecirc;n tr&ecirc;n thế giới</strong></h2>\r\n\r\n<h6><span style=\"font-size:14px\">Củ sạc Omega &nbsp;l&agrave; củ sạc đầu ti&ecirc;n sử dụng IC NV6127 để đạt được c&ocirc;ng suất l&ecirc;n đến 200W đồng thời cũng tăng hiệu suất để nhỏ gọn hơn 65% củ sạc th&ocirc;ng thường.</span></h6>\r\n\r\n<h1><strong>Với 4 cổng sạc c&ocirc;ng suất cao</strong></h1>\r\n\r\n<h6><span style=\"font-size:14px\">Củ sạc 200w được trang bị gồm 4 cổng gồm 2 cổng &nbsp;USB-C PD 3.0 v&agrave; 2 cổng USB -A ( hỗ trợ QC 3.0, AFC, VOOC, SCP&amp;FCP).</span></h6>\r\n\r\n<h6><span style=\"font-size:14px\">&ldquo;Một củ sạc duy nhất cho tất cả c&aacute;c thiết bị của bạn. Củ sạc 200W c&oacute; thể cho ph&eacute;p bạn sạc nhanh c&aacute;c thiết bị như laptop (Macbook Pro 16 &ldquo;), tablet ( iPad Pro), Smartphone (iPhone) v&agrave; c&aacute;c thiết bị kh&aacute;c như Airpods, Apple Watch c&ugrave;ng 1 l&uacute;c.&rdquo;</span></h6>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"omega\" height=\"735\" sizes=\"(max-width: 695px) 100vw, 695px\" src=\"http://pre.siliconz.vn/wp-content/uploads/2020/12/zksu4targxdisqa8ejfv_optimized.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2020/12/zksu4targxdisqa8ejfv_optimized.jpg 695w, https://siliconz.vn/wp-content/uploads/2020/12/zksu4targxdisqa8ejfv_optimized-284x300.jpg 284w\" width=\"695\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><strong>Nhỏ gọn v&agrave; tiết kiệm</strong></h2>\r\n\r\n<h6><span style=\"font-size:14px\">Chỉ với 1 cục sạc duy nhất cho tất cả c&aacute;c nhu cầu của bạn. Kh&ocirc;ng cần phải lo lắng mỗi lần ra ngo&agrave;i hay cho những chuyến đi xa.</span></h6>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"omega\" height=\"472\" sizes=\"(max-width: 695px) 100vw, 695px\" src=\"http://pre.siliconz.vn/wp-content/uploads/2020/12/wx93xto5addxet8bngtf_optimized.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2020/12/wx93xto5addxet8bngtf_optimized.jpg 695w, https://siliconz.vn/wp-content/uploads/2020/12/wx93xto5addxet8bngtf_optimized-300x204.jpg 300w\" width=\"695\" /></p>\r\n\r\n<h2>&nbsp;</h2>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><strong>Sạc đồng thời 2 Macbook Pro 16&Prime;</strong></h2>\r\n\r\n<h6><span style=\"font-size:14px\">Với 2 cổng USB C PD 3.0 hỗ trợ PPS, 1 củ sạc Omega 200w c&oacute; thể cung cấp điện năng đồng thời cho 2 Laptop Macbook 16&Prime;.<br />\r\nĐ&acirc;y l&agrave; củ sạc đầu ti&ecirc;n tr&ecirc;n thế giới c&oacute; thể đạt được c&ocirc;ng suất 200W.</span></h6>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"omega200w\" height=\"391\" sizes=\"(max-width: 695px) 100vw, 695px\" src=\"https://siliconz.vn/wp-content/uploads/2020/12/sacsongsong-1.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2020/12/sacsongsong-1.jpg 695w, https://siliconz.vn/wp-content/uploads/2020/12/sacsongsong-1-300x169.jpg 300w\" width=\"695\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><strong>Tương th&iacute;ch hầu hết c&aacute;c chuẩn sạc từ c&aacute;c h&atilde;ng</strong></h2>\r\n\r\n<h6><span style=\"font-size:14px\">Củ sạc Omega hỗ trợ đa dạng c&aacute;c chuẩn sạc từ QC 3.0, AFC, VOOC, SCP, FCP, đ&acirc;y l&agrave; những chuẩn sạc độc quyền từ Samsung, Huawei, Oppo, Vivo v&agrave; Oneplus.</span></h6>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"omega\" height=\"704\" sizes=\"(max-width: 695px) 100vw, 695px\" src=\"http://pre.siliconz.vn/wp-content/uploads/2020/12/pwgz9rv1zdueeesjbk0e_optimized.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2020/12/pwgz9rv1zdueeesjbk0e_optimized.jpg 695w, https://siliconz.vn/wp-content/uploads/2020/12/pwgz9rv1zdueeesjbk0e_optimized-296x300.jpg 296w, https://siliconz.vn/wp-content/uploads/2020/12/pwgz9rv1zdueeesjbk0e_optimized-100x100.jpg 100w\" width=\"695\" /></p>\r\n\r\n<h2><strong>K&iacute;ch thước bỏ t&uacute;i</strong></h2>\r\n\r\n<h6><span style=\"font-size:14px\">K&iacute;ch thước của Omega 200w chỉ ngang với 1 chiếc thẻ ATM v&agrave; với trọng lượng 220g, bạn c&oacute; thể dễ d&agrave;ng mang củ sạc n&agrave;y đi mọi l&uacute;c mọi nơi.</span></h6>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"omega200w\" height=\"392\" sizes=\"(max-width: 695px) 100vw, 695px\" src=\"https://siliconz.vn/wp-content/uploads/2020/12/yykhcjjh6mnpszb29qqc_optimized-1.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2020/12/yykhcjjh6mnpszb29qqc_optimized-1.jpg 695w, https://siliconz.vn/wp-content/uploads/2020/12/yykhcjjh6mnpszb29qqc_optimized-1-300x169.jpg 300w\" width=\"695\" /></p>\r\n\r\n<h2><strong>K&iacute;ch thước si&ecirc;u nhỏ</strong></h2>\r\n\r\n<h6>&nbsp;</h6>\r\n\r\n<p style=\"text-align:center\"><img alt=\"omega\" height=\"400\" sizes=\"(max-width: 695px) 100vw, 695px\" src=\"http://pre.siliconz.vn/wp-content/uploads/2020/12/nuzjtvwm4bglbwfjymm5_optimized.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2020/12/nuzjtvwm4bglbwfjymm5_optimized.jpg 695w, https://siliconz.vn/wp-content/uploads/2020/12/nuzjtvwm4bglbwfjymm5_optimized-300x173.jpg 300w\" width=\"695\" /></p>\r\n\r\n<h2>&nbsp;</h2>\r\n\r\n<h2><strong>Ch&acirc;n gấp 2 chiều</strong></h2>\r\n\r\n<h6><span style=\"font-size:14px\">ChargeAsap được cấp bằng thiết kế với ch&acirc;n sạc 2 chiều. Với thiết kế n&agrave;y gi&uacute;p cho Omega c&oacute; thể cắm bất kỳ vị tr&iacute; n&agrave;o.</span></h6>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"omega\" height=\"346\" sizes=\"(max-width: 695px) 100vw, 695px\" src=\"http://pre.siliconz.vn/wp-content/uploads/2020/12/rbdqaxoczrztakca3gyo_optimized.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2020/12/rbdqaxoczrztakca3gyo_optimized.jpg 695w, https://siliconz.vn/wp-content/uploads/2020/12/rbdqaxoczrztakca3gyo_optimized-300x149.jpg 300w\" width=\"695\" /></p>\r\n\r\n<h5><span style=\"font-size:14px\"><strong>C&aacute;ch chia d&ograve;ng 200W:</strong></span></h5>\r\n\r\n<h6><span style=\"font-size:14px\">&ndash; C1 or C2 = 100W<br />\r\n&ndash; C1 + C2 = 100W + 100W<br />\r\n&ndash; C1+ A1 + A2 = 100W + 12w + 12W<br />\r\n&ndash; C1+ C2 + A1 = 100W + 65W + 22.5W<br />\r\n&ndash; C1+ C2+ A2 = 100W + 65W + 22.5W<br />\r\n&ndash; C1+ A1= 100W + 22.5W<br />\r\n&ndash; C2+ A2 = 65W + 22.5W<br />\r\n&ndash; A1 + A2 = 12W + 12W<br />\r\n&ndash; A1 or A2 = 22.5W<br />\r\n&ndash; C1 + C2 + A1 + A2 : 100W+ 65W + 12W +12W</span></h6>', 1890000, NULL, 14, 'Bộ sản phẩm', 'ChargeAsap-Omega-200W.jpg', 'PK', 'CHANGEASAP', 1, NULL, '2021-07-02 21:17:59', '2021-07-14 21:24:49', 1, '2021-07-02 21:24:24');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (9, 'DELL XPS 15 9500', '<ul>\r\n	<li><strong>CPU</strong>&nbsp;Intel&reg; Core &trade; i7- 10750H</li>\r\n	<li><strong>Ram</strong>&nbsp;16GB DDR4 2933MHz</li>\r\n	<li><strong>Ổ cứng</strong>&nbsp;M.2 512GB PCIe NVMe</li>\r\n	<li><strong>M&agrave;n h&igrave;nh</strong>&nbsp;15.6&Prime; Full HD (1920 x 1080)</li>\r\n	<li><strong>VGA</strong>&nbsp;NVIDIA&reg; GeForce&reg; GTX 1650 Ti 4G</li>\r\n</ul>', '<p>Sau gần năm năm sử dụng c&ugrave;ng một khung gầm ch&iacute;nh x&aacute;c từ XPS 15 9550 cho đến XPS 15 7590, Dell XPS 15 9500 l&agrave; thiết kế lại ho&agrave;n to&agrave;n m&agrave; d&ograve;ng sản phẩm v&ocirc; c&ugrave;ng cần thiết. Hệ thống n&agrave;y mang đến một loạt c&aacute;c thay đổi to&agrave;n diện : cả b&ecirc;n trong v&agrave; b&ecirc;n ngo&agrave;i với m&agrave;n h&igrave;nh tỷ lệ khung h&igrave;nh 16:10 mới l&agrave; nổi bật nhất.</p>\r\n\r\n<p><strong>Một hơi thở kh&ocirc;ng kh&iacute; trong l&agrave;nh.&nbsp;</strong>Đ&acirc;y l&agrave; lần đại tu d&ograve;ng XPS 15 lớn nhất kể từ năm 2016, nhưng đ&oacute; c&oacute; phải l&agrave; tất cả những g&igrave; người h&acirc;m mộ XPS muốn? C&ugrave;ng t&igrave;m hiểu kỹ trong b&agrave;i đ&aacute;nh gi&aacute; sau đ&acirc;yHợp kim kim loại giờ đ&acirc;y củng cố c&aacute;c cạnh v&agrave; g&oacute;c tương phản với mẫu XPS 15 9570 năm ngo&aacute;i</p>\r\n\r\n<p><strong>Gi&aacute; Dell XPS 15 9500 ch&iacute;nh h&atilde;ng</strong><br />\r\nB&ecirc;n trong, CPU v&agrave; GPU đ&atilde; được cập nhật l&ecirc;n d&ograve;ng Comet Lake-H thế hệ thứ 10 của Intel v&agrave; GeForce GTX 1650 Ti t&ugrave;y chọn, c&ugrave;ng với RAM DDR4-2933 nhanh hơn v&agrave; c&aacute;c t&ugrave;y chọn hiển thị mới.&nbsp;Gi&aacute; khởi điểm dao động từ 30 triệu cho đến tận 53 triệu trở l&ecirc;n chưa VAT.&nbsp;Hệ thống ch&uacute;ng t&ocirc;i sẽ kiểm tra h&ocirc;m nay l&agrave; cấu h&igrave;nh &iacute;t tốn k&eacute;m nhất với CPU Core i5-10300H, RAM 8 GB, SSD NVMe 256 GB v&agrave; m&agrave;n h&igrave;nh 1200p.&nbsp;Y&ecirc;u cầu đ&aacute;nh gi&aacute; thứ hai về cấu h&igrave;nh Core i7 v&agrave; GeForce cao cấp hơn v&agrave;o một ng&agrave;y trong tương lai để ch&uacute;ng t&ocirc;i c&oacute; thể so s&aacute;nh ch&iacute;nh x&aacute;c hai SKU sẽ kh&aacute;c nhau như thế n&agrave;o.<br />\r\nC&aacute;c đối thủ cạnh tranh trực tiếp với XPS 15 bao gồm c&aacute;c Ultrabook 15,6 inch kh&aacute;c như HP Spectre x360 15 , Asus ZenBook 15 , MSI Prestige 15 , Lenovo Yoga C940-15 , Microsoft Surface Laptop 3 15 v&agrave; Apple MacBook Pro series.</p>\r\n\r\n<p><strong>Đ&aacute;nh gi&aacute; Dell XPS 15 9500<br />\r\nVỏ</strong><br />\r\n&nbsp; B&ecirc;n ngo&agrave;i, Dell đ&atilde; thực hiện một số thay đổi đối với khung XPS 15 với nhiều thay đổi tương tự như bước nhảy từ XPS 13 7390 sang XPS 13 9300 . V&iacute; dụ, tấm kim loại dưới c&ugrave;ng, b&acirc;y giờ tăng l&ecirc;n để che c&aacute;c cạnh v&agrave; g&oacute;c trong khi m&ocirc; h&igrave;nh năm ngo&aacute;i c&oacute; sợi carbon đen thay thế. Dell cho biết điều n&agrave;y sẽ tạo ra một khung gầm mạnh mẽ hơn c&oacute; khả năng chống va đập v&agrave; bầm t&iacute;m m&agrave; kh&ocirc;ng đi qu&aacute; xa so với thiết kế trực quan của thế hệ trước. Từ những g&igrave; ch&uacute;ng ta c&oacute; thể n&oacute;i, việc cố gắng vặn ch&acirc;n đế hoặc nắp kh&ocirc;ng cho thấy sự uốn cong nhiều hay &iacute;t hơn so với tr&ecirc;n XPS 15 7590.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 2560px) 100vw, 2560px\" src=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05577-DELL-PRECISION-5550-scaled.jpg\" srcset=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05577-DELL-PRECISION-5550-scaled.jpg 2560w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05577-DELL-PRECISION-5550-300x169.jpg 300w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05577-DELL-PRECISION-5550-1024x576.jpg 1024w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05577-DELL-PRECISION-5550-768x432.jpg 768w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05577-DELL-PRECISION-5550-1536x864.jpg 1536w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05577-DELL-PRECISION-5550-2048x1152.jpg 2048w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05577-DELL-PRECISION-5550-600x338.jpg 600w\" width=\"800\" /></p>\r\n\r\n<p>Những chiếc cọ bằng sợi carbon tương tự đ&atilde; được định nghĩa cho d&ograve;ng XPS. Thật kh&ocirc;ng may, vẫn l&agrave; si&ecirc;u b&aacute;m dấu v&acirc;n tay.</p>\r\n\r\n<p>Sự thay đổi đ&aacute;ng ch&uacute; &yacute; tiếp theo li&ecirc;n quan đến bản lề được thiết kế lại.&nbsp;Dell đ&atilde; bỏ bản lề thanh d&agrave;i của thiết kế trước đ&oacute; để ủng hộ bản lề k&eacute;p nhỏ hơn v&agrave; kh&ocirc;ng r&otilde; r&agrave;ng hơn.&nbsp;C&aacute;ch tiếp cận n&agrave;y đ&atilde; cho ph&eacute;p c&oacute; viền dưới rất hẹp v&agrave; tỷ lệ m&agrave;n h&igrave;nh tr&ecirc;n th&acirc;n m&aacute;y thậm ch&iacute; c&ograve;n cao hơn.&nbsp;Độ cứng bản lề vẫn đạt y&ecirc;u cầu m&agrave; kh&ocirc;ng bị ọp ẹp hoặc mọc răng khi điều chỉnh c&aacute;c g&oacute;c.<br />\r\nV&agrave; cuối c&ugrave;ng, kh&ocirc;ng gian trống ở hai b&ecirc;n của b&agrave;n ph&iacute;m giờ đ&acirc;y c&oacute; lưới tản nhiệt loa kh&ocirc;ng giống với Razer Blade Pro 17 . Những thay đổi trực quan n&agrave;y gi&uacute;p dễ d&agrave;ng ph&acirc;n biệt sự kh&aacute;c biệt giữa XPS 15 9500 so với c&aacute;c mẫu trước đ&oacute;.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 2560px) 100vw, 2560px\" src=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05593-DELL-PRECISION-5550-scaled.jpg\" srcset=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05593-DELL-PRECISION-5550-scaled.jpg 2560w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05593-DELL-PRECISION-5550-300x169.jpg 300w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05593-DELL-PRECISION-5550-1024x576.jpg 1024w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05593-DELL-PRECISION-5550-768x432.jpg 768w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05593-DELL-PRECISION-5550-1536x864.jpg 1536w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05593-DELL-PRECISION-5550-2048x1152.jpg 2048w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05593-DELL-PRECISION-5550-600x338.jpg 600w\" width=\"800\" /></p>\r\n\r\n<p>C&aacute;c vật liệu khung gầm kh&aacute;c giống như thế hệ v&agrave; do đ&oacute;, kết cấu của l&ograve;ng b&agrave;n tay bằng sợi carbon đen v&agrave; nắp ngo&agrave;i bằng hợp kim magi&ecirc; bạc sẽ ngay lập tức quen thuộc với bất kỳ chủ sở hữu XPS n&agrave;o.<br />\r\nNhư thể XPS 15 7590 kh&ocirc;ng đủ nhỏ, XPS 15 9500 thậm ch&iacute; c&ograve;n nhỏ hơn v&agrave; nhẹ hơn như được hiển thị bởi c&ocirc;ng cụ so s&aacute;nh của ch&uacute;ng t&ocirc;i dưới đ&acirc;y. Thiết kế mới hơn d&agrave;y hơn khoảng 1 mm, tuy nhi&ecirc;n, đ&oacute; l&agrave; một sự đ&aacute;nh đổi c&ocirc;ng bằng khi xem x&eacute;t việc tiết kiệm đ&aacute;ng kể hơn về trọng lượng v&agrave; k&iacute;ch thước.</p>\r\n\r\n<p>C&aacute;c cạnh v&agrave; g&oacute;c mịn. Thiết kế mới kết hợp nhiều lưới loa hơn bao giờ hết cho loạt.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 2560px) 100vw, 2560px\" src=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05551-DELL-PRECISION-5550-scaled.jpg\" srcset=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05551-DELL-PRECISION-5550-scaled.jpg 2560w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05551-DELL-PRECISION-5550-300x169.jpg 300w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05551-DELL-PRECISION-5550-1024x576.jpg 1024w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05551-DELL-PRECISION-5550-768x432.jpg 768w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05551-DELL-PRECISION-5550-1536x864.jpg 1536w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05551-DELL-PRECISION-5550-2048x1152.jpg 2048w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05551-DELL-PRECISION-5550-600x338.jpg 600w\" width=\"800\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>C&aacute;c viền dưới thậm ch&iacute; c&ograve;n hẹp hơn lần n&agrave;y đặc biệt l&agrave; dọc theo cạnh dưới. Logo Dell kh&ocirc;ng c&ograve;n ở đ&acirc;y</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Bản lề đ&atilde; được thiết kế lại để mỏng gọn, giống với d&ograve;ng Asus Zenbook hơn</p>\r\n\r\n<p><strong>Kết nối</strong><br />\r\nC&oacute; ba cổng USB Type-C v&agrave; tất cả đều c&oacute; khả năng sạc lại Laptop v&agrave; xuất ra m&agrave;n h&igrave;nh ngo&agrave;i.&nbsp;Tuy nhi&ecirc;n, chỉ c&oacute; hai dọc theo cạnh tr&aacute;i l&agrave; tương th&iacute;ch với c&aacute;c phụ kiện Thunderbolt 3.<br />\r\nKhi so s&aacute;nh với mẫu XPS 15 7590 đi, XPS 15 9500 đ&atilde; bỏ tất cả c&aacute;c cổng USB Type-A, cổng HDMI, cổng sạc th&ugrave;ng AC độc quyền v&agrave; n&uacute;t kiểm tra pin.&nbsp;Người d&ugrave;ng sẽ phải dựa v&agrave;o bộ điều hợp USB Type-C để tiến l&ecirc;n kh&ocirc;ng giống như hầu hết chủ sở hữu MacBook Pro.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 2560px) 100vw, 2560px\" src=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05570-DELL-PRECISION-5550-scaled.jpg\" srcset=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05570-DELL-PRECISION-5550-scaled.jpg 2560w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05570-DELL-PRECISION-5550-300x169.jpg 300w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05570-DELL-PRECISION-5550-1024x576.jpg 1024w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05570-DELL-PRECISION-5550-768x432.jpg 768w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05570-DELL-PRECISION-5550-1536x864.jpg 1536w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05570-DELL-PRECISION-5550-2048x1152.jpg 2048w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05570-DELL-PRECISION-5550-600x338.jpg 600w\" width=\"800\" /></p>\r\n\r\n<p>B&ecirc;n tr&aacute;i: Kh&oacute;a Noble, 2x Thunderbolt 3 w / Cung cấp năng lượng</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 2560px) 100vw, 2560px\" src=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05586-DELL-PRECISION-5550-scaled.jpg\" srcset=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05586-DELL-PRECISION-5550-scaled.jpg 2560w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05586-DELL-PRECISION-5550-300x169.jpg 300w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05586-DELL-PRECISION-5550-1024x576.jpg 1024w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05586-DELL-PRECISION-5550-768x432.jpg 768w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05586-DELL-PRECISION-5550-1536x864.jpg 1536w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05586-DELL-PRECISION-5550-2048x1152.jpg 2048w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05586-DELL-PRECISION-5550-600x338.jpg 600w\" width=\"800\" /></p>\r\n\r\n<p>Ph&iacute;a sau: Kh&ocirc;ng c&oacute; kết nối</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 2560px) 100vw, 2560px\" src=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05569-DELL-PRECISION-5550-scaled.jpg\" srcset=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05569-DELL-PRECISION-5550-scaled.jpg 2560w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05569-DELL-PRECISION-5550-300x169.jpg 300w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05569-DELL-PRECISION-5550-1024x576.jpg 1024w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05569-DELL-PRECISION-5550-768x432.jpg 768w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05569-DELL-PRECISION-5550-1536x864.jpg 1536w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05569-DELL-PRECISION-5550-2048x1152.jpg 2048w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05569-DELL-PRECISION-5550-600x338.jpg 600w\" width=\"800\" /></p>\r\n\r\n<p>Phải: USB Type-C 3.1 w / Cung cấp năng lượng v&agrave; DisplayPort, đầu đọc SD, &acirc;m thanh kết hợp 3,5 mm</p>\r\n\r\n<p>Mặt trước: Kh&ocirc;ng c&oacute; kết nối</p>\r\n\r\n<ul>\r\n	<li>Hub USB Type C tốt nhất 2020</li>\r\n</ul>\r\n\r\n<h4>Đầu đọc thẻ SD</h4>\r\n\r\n<p>Laptop XPS c&oacute; một số đầu đọc thẻ SD nhanh nhất cho bất kỳ Laptop d&agrave;nh cho người ti&ecirc;u d&ugrave;ng n&agrave;o v&agrave; XPS 15 mới cũng kh&ocirc;ng kh&aacute;c.&nbsp;Di chuyển 1 GB h&igrave;nh ảnh từ thẻ thử nghiệm&nbsp;thẻ nhớ tốc độ cao UHS-II&nbsp;của ch&uacute;ng t&ocirc;i sang m&aacute;y t&iacute;nh để b&agrave;n chỉ mất khoảng 5 đến 6 gi&acirc;y.</p>\r\n\r\n<p>Đầu đọc SD t&iacute;ch hợp kh&ocirc;ng được tải bằng l&ograve; xo. Thẻ SD được lắp đầy đủ vẫn nh&ocirc; ra gần một nửa chiều d&agrave;i của n&oacute;</p>\r\n\r\n<p><strong>Bảo tr&igrave;</strong><br />\r\nBảo dưỡng đ&ograve;i hỏi một cờ l&ecirc; T5 Torx v&agrave; một cạnh sắc n&eacute;t để cạy mở c&aacute;c cạnh.&nbsp;Bảng kim loại rất sắc n&eacute;t v&agrave; v&igrave; vậy điều n&agrave;y n&ecirc;n được thực hiện cẩn thận.<br />\r\nSau khi x&oacute;a, người d&ugrave;ng sẽ c&oacute; quyền truy cập trực tiếp v&agrave;o c&aacute;c khay lưu trữ, m&ocirc;-đun RAM v&agrave; pin.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://thegioiso365.com/wp-content/uploads/2020/06/dell-xps-15-9500-i7-10750h-gtx-1650ti-ram-32gb-ssd-512-tb-15-6-uhd-new-seal-bao-hanh-vn-2-nam-4862-12.jpg\" /></p>\r\n\r\n<p>XPS 15 9500</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://thegioiso365.com/wp-content/uploads/2020/06/dell-xps-15-9500-i7-10750h-gtx-1650ti-ram-32gb-ssd-512-tb-15-6-uhd-new-seal-bao-hanh-vn-2-nam-4862-13.jpg\" /></p>\r\n\r\n<p>XPS 15 7590 để so s&aacute;nh. Lưu &yacute; rằng mạng WLAN c&oacute; thể n&acirc;ng cấp tr&ecirc;n model cũ hơn</p>\r\n\r\n<p><strong>Phụ kiện v&agrave; bảo h&agrave;nh</strong><br />\r\nDell n&eacute;m v&agrave;o hai bộ điều hợp hữu &iacute;ch trong hộp: USB Type-C sang HDMI v&agrave; USB Type-C sang USB Type-A.&nbsp;Bạn chắc chắn sẽ muốn giữ ch&uacute;ng xung quanh v&igrave; sự đa dạng của cổng bị hạn chế hơn so với m&ocirc; h&igrave;nh năm ngo&aacute;i.<br />\r\nBảo h&agrave;nh giới hạn một năm ti&ecirc;u chuẩn được &aacute;p dụng với nhiều t&ugrave;y chọn gia hạn l&ecirc;n đến bốn năm.</p>\r\n\r\n<p><strong>B&agrave;n ph&iacute;m</strong><br />\r\nDell đ&atilde; t&acirc;n trang lại b&agrave;n ph&iacute;m cho XPS 15 9500. C&aacute;c ph&iacute;m giờ lớn hơn so với XPS 15 7590 với phản hồi sắc n&eacute;t hơn một ch&uacute;t khi nhấn để c&oacute; trải nghiệm g&otilde; tốt hơn.&nbsp;Du lịch đ&atilde; kh&ocirc;ng thay đổi đ&aacute;ng kể v&agrave; n&oacute; vẫn n&ocirc;ng hơn c&aacute;c ph&iacute;m tr&ecirc;n&nbsp;HP Spectre x360 15&nbsp;.&nbsp;Ch&uacute;ng t&ocirc;i đ&atilde; mong đợi một b&agrave;n ph&iacute;m giống với c&aacute;c ph&iacute;m MagLev của&nbsp;XPS 15 9575&nbsp;, nhưng Dell c&oacute; vẻ h&agrave;i l&ograve;ng với việc tinh chỉnh c&aacute;c ph&iacute;m m&agrave;ng ti&ecirc;u chuẩn thay v&agrave;o đ&oacute; v&agrave; ch&uacute;ng t&ocirc;i thực sự kh&ocirc;ng thể ph&agrave;n n&agrave;n về kết quả.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 2560px) 100vw, 2560px\" src=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05559-DELL-PRECISION-5550-scaled.jpg\" srcset=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05559-DELL-PRECISION-5550-scaled.jpg 2560w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05559-DELL-PRECISION-5550-300x169.jpg 300w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05559-DELL-PRECISION-5550-1024x576.jpg 1024w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05559-DELL-PRECISION-5550-768x432.jpg 768w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05559-DELL-PRECISION-5550-1536x864.jpg 1536w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05559-DELL-PRECISION-5550-2048x1152.jpg 2048w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05559-DELL-PRECISION-5550-600x338.jpg 600w\" width=\"800\" /></p>\r\n\r\n<p>Thay đổi bố cục nhẹ từ XPS 15 7590. Dell đ&atilde; bổ sung th&ecirc;m lưới tản nhiệt loa dọc theo c&aacute;c cạnh của b&agrave;n ph&iacute;m</p>\r\n\r\n<p>Clickpad rất lớn v&agrave; thoải m&aacute;i. Thật kh&ocirc;ng may, c&aacute;c ph&iacute;m bấm t&iacute;ch hơi xốp</p>\r\n\r\n<p>C&aacute;c ph&iacute;m mũi t&ecirc;n tr&aacute;i v&agrave; phải lớn hơn so với mẫu năm ngo&aacute;i</p>\r\n\r\n<p>C&aacute;c ph&iacute;m lớn hơn v&agrave; phản hồi sắc n&eacute;t hơn.</p>\r\n\r\n<p><strong>B&agrave;n di chuột</strong><br />\r\nVới k&iacute;ch thước 15,1 x 9 cm, b&agrave;n di chuột k&iacute;ch hoạt Precision lớn hơn 52% so với b&agrave;n di chuột tr&ecirc;n XPS 15 7590 (10,5 x 8,5 cm) l&agrave; một trong những b&agrave;n ph&iacute;m lớn nhất ch&uacute;ng t&ocirc;i từng thấy tr&ecirc;n bất kỳ Laptop Windows n&agrave;o.&nbsp;Thật kh&oacute; để quay trở lại với c&aacute;c b&agrave;n di chuột nhỏ hơn sau khi d&agrave;nh thời gian với XPS 15 9500. Lướt rất mượt v&agrave; đ&aacute;ng tin cậy khi kh&ocirc;ng c&oacute; con trỏ nhảy v&agrave; rất &iacute;t d&iacute;nh nếu di chuyển ở tốc độ chậm hơn.</p>\r\n\r\n<p>Tuy nhi&ecirc;n, d&ugrave; b&agrave;n ph&iacute;m c&oacute; thể lớn đến mức n&agrave;o, việc thiếu c&aacute;c ph&iacute;m chuột chuy&ecirc;n dụng khiến việc bấm ch&iacute;nh x&aacute;c trở n&ecirc;n kh&oacute; khăn.&nbsp;K&eacute;o v&agrave; thả vẫn dễ d&agrave;ng hơn tr&ecirc;n ThinkPad truyền thống như&nbsp;T490&nbsp;nơi c&oacute; sẵn c&aacute;c ph&iacute;m chuột chắc chắn.&nbsp;C&aacute;c ph&iacute;m bấm tr&ecirc;n b&agrave;n ph&iacute;m t&iacute;ch hợp tr&ecirc;n XPS 15 9500 mềm, &ecirc;m v&agrave; n&ocirc;ng với phản hồi yếu khi nhấn.</p>\r\n\r\n<p><strong>M&agrave;n h&igrave;nh</strong><br />\r\nM&agrave;n h&igrave;nh dễ d&agrave;ng l&agrave; điểm nổi bật của XPS 15 9500. Ngay cả cấu h&igrave;nh cơ bản ch&uacute;ng t&ocirc;i c&oacute; ở đ&acirc;y cũng đi k&egrave;m với một trong những m&agrave;n h&igrave;nh s&aacute;ng nhất m&agrave; ch&uacute;ng t&ocirc;i thấy tr&ecirc;n bất kỳ Laptop 15,6 inch n&agrave;o.&nbsp;Khi so s&aacute;nh với bảng điều khiển XPS 15 7590 FHD, XPS 15 9500 quản l&yacute; để cung cấp cả thời gian phản hồi nhanh hơn một ch&uacute;t v&agrave; độ bao phủ m&agrave;u rộng hơn m&agrave; kh&ocirc;ng ảnh hưởng đến độ s&aacute;ng hoặc độ tương phản.&nbsp;Điều chế độ rộng xung ho&agrave;n to&agrave;n biến mất cũng như cho trải nghiệm kh&ocirc;ng nhấp nh&aacute;y.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 2560px) 100vw, 2560px\" src=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05592-DELL-PRECISION-5550-1-scaled.jpg\" srcset=\"https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05592-DELL-PRECISION-5550-1-scaled.jpg 2560w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05592-DELL-PRECISION-5550-1-300x169.jpg 300w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05592-DELL-PRECISION-5550-1-1024x576.jpg 1024w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05592-DELL-PRECISION-5550-1-768x432.jpg 768w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05592-DELL-PRECISION-5550-1-1536x864.jpg 1536w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05592-DELL-PRECISION-5550-1-2048x1152.jpg 2048w, https://laptoptcc.com/wp-content/uploads/2019/06/AZZ05592-DELL-PRECISION-5550-1-600x338.jpg 600w\" width=\"800\" /></p>\r\n\r\n<p>Tỷ lệ khung h&igrave;nh 16:10 ngay lập tức r&otilde; r&agrave;ng cho diện t&iacute;ch m&agrave;n h&igrave;nh lớn hơn đ&aacute;ng ch&uacute; &yacute; khi so s&aacute;nh với Laptop 16: 9 th&ocirc;ng thường.&nbsp;Kh&ocirc;ng thể t&igrave;m thấy bảng điều khiển IPS LQ156N1 tr&ecirc;n bất kỳ Laptop n&agrave;o kh&aacute;c trong cơ sở dữ liệu của ch&uacute;ng t&ocirc;i v&igrave; Dell l&agrave; một trong những người đầu ti&ecirc;n cung cấp Ultrabook 16:10 để &aacute;p dụng đại tr&agrave;.</p>\r\n\r\n<p>Điểm hấp dẫn ch&iacute;nh của ch&uacute;ng t&ocirc;i l&agrave; m&agrave;n h&igrave;nh c&oacute; độ sần s&ugrave;i rất &iacute;t được mong đợi từ lớp phủ mờ.&nbsp;May mắn thay, Dell cung cấp c&aacute;c t&ugrave;y chọn b&oacute;ng để giảm bớt điều n&agrave;y.&nbsp;Lưu &yacute; rằng OLED kh&ocirc;ng c&ograve;n khả dụng v&igrave; kh&ocirc;ng c&oacute; đủ nguồn cung cấp tấm nền OLED 16:10 tr&ecirc;n thị trường.<br />\r\nKh&ocirc;ng gian m&agrave;u l&agrave; một điểm th&uacute; vị v&igrave; n&oacute; rộng hơn sRGB trong khi nhỏ hơn AdobeRGB.&nbsp;Tr&ecirc;n thực tế, chỉ 80 phần trăm kh&ocirc;ng gian m&agrave;u XPS 15 9500 l&agrave; đủ để bao phủ to&agrave;n bộ sRGB.&nbsp;Độ bao phủ 72% AdobeRGB cũng rộng hơn so với hầu hết c&aacute;c Ultrabook kh&aacute;c, trong đ&oacute; phạm vi 60% phổ biến hơn, nhưng người d&ugrave;ng sẽ phải n&acirc;ng cấp l&ecirc;n cấu h&igrave;nh 4K UHD + đắt tiền của Dell để c&oacute; phạm vi bảo hiểm AdobeRGB đầy đủ.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://thegioiso365.com/wp-content/uploads/2020/06/dell-xps-15-9500-i7-10750h-gtx-1650ti-ram-32gb-ssd-512-tb-15-6-uhd-new-seal-bao-hanh-vn-2-nam-4862-20.jpg\" /></p>\r\n\r\n<p>C&aacute;c ph&eacute;p đo kh&aacute;c với m&aacute;y đo m&agrave;u X-Rite cho thấy một bảng hiệu chỉnh ch&iacute;nh x&aacute;c ra khỏi hộp.&nbsp;M&agrave;u sắc v&agrave; thang độ x&aacute;m sẽ cải thiện chỉ một ch&uacute;t từ c&aacute;c gi&aacute; trị DeltaE trung b&igrave;nh lần lượt l&agrave; 3,9 đến 1,1 v&agrave; 2,9 đến 1,96, sau khi hiệu chỉnh bảng điều khiển.&nbsp;C&oacute; thể nhận được kết quả thậm ch&iacute; tốt hơn với tinh chỉnh nhiều hơn nếu hiệu chỉnh theo phổ sRGB do bảng điều khiển c&oacute; khả năng t&aacute;i tạo kh&ocirc;ng gian ho&agrave;n to&agrave;n.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://thegioiso365.com/wp-content/uploads/2020/06/dell-xps-15-9500-i7-10750h-gtx-1650ti-ram-32gb-ssd-512-tb-15-6-uhd-new-seal-bao-hanh-vn-2-nam-4862-21.jpg\" /></p>\r\n\r\n<p>Độ nhớt ngo&agrave;i trời tốt hơn so với hầu hết c&aacute;c Ultrabook kh&aacute;c đơn giản l&agrave; do m&agrave;n h&igrave;nh hiển thị s&aacute;ng tr&ecirc;n XPS 15. Bảng điều khiển mờ gi&uacute;p giảm độ ch&oacute;i cũng như điều đ&oacute; th&iacute;ch hợp hơn so với t&ugrave;y chọn b&oacute;ng khi ở ngo&agrave;i trời.</p>\r\n\r\n<p><strong>Hiệu suất</strong><br />\r\n&nbsp; &nbsp;Tất cả c&aacute;c SKU đều đi k&egrave;m với Core i5-10300H l&otilde;i tứ, Core i7-10750H hoặc Core i7-10875H l&otilde;i t&aacute;m . Kh&ocirc;ng c&oacute; t&ugrave;y chọn Core i9 n&agrave;o trong b&agrave;i viết n&agrave;y v&agrave; ch&uacute;ng t&ocirc;i chắc chắn kh&ocirc;ng ph&agrave;n n&agrave;n về hiệu năng Core i9 mờ nhạt tr&ecirc;n XPS 15 7590 .<br />\r\nT&ugrave;y chọn GPU ri&ecirc;ng biệt duy nhất l&agrave; GeForce GTX 1650 Ti Max-Q m&agrave; ch&uacute;ng t&ocirc;i sẽ kiểm tra v&agrave;o một ng&agrave;y sau đ&oacute;. Thật đ&aacute;ng tiếc khi kh&ocirc;ng c&oacute; t&ugrave;y chọn AMD n&agrave;o khả dụng.<br />\r\nTr&ecirc;n thực tế, hiệu năng được duy tr&igrave; khi chạy CineBench R15 Multi-Thread trong một v&ograve;ng lặp nhanh hơn khoảng 13% so với MSI GF75 được trang bị c&ugrave;ng CPU. Ch&uacute;ng t&ocirc;i sẽ kh&ocirc;ng mong đợi &iacute;t hơn, đặc biệt l&agrave; khi cấu h&igrave;nh XPS 15 của ch&uacute;ng t&ocirc;i bỏ qua GPU Nvidia rời rạc. Nếu hệ thống phải vật lộn để chạy Core i5-10300H, th&igrave; ch&uacute;ng t&ocirc;i sẽ lo lắng cho c&aacute;c SKU cao cấp đ&ograve;i hỏi khắt khe hơn.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://thegioiso365.com/wp-content/uploads/2020/06/dell-xps-15-9500-i7-10750h-gtx-1650ti-ram-32gb-ssd-512-tb-15-6-uhd-new-seal-bao-hanh-vn-2-nam-4862-22.jpg\" /></p>\r\n\r\n<p>N&acirc;ng cấp l&ecirc;n t&ugrave;y chọn Core i7-10750H hoặc Core i7-10875H sẽ gi&uacute;p người d&ugrave;ng mạng tương ứng với hiệu suất đa luồng cao hơn khoảng 40% v&agrave; 80%.&nbsp;Sự kh&aacute;c biệt hiệu suất CPU giữa c&aacute;c cấu h&igrave;nh sức mạnh Tối ưu h&oacute;a v&agrave; Si&ecirc;u hiệu suất của Dell dường như l&agrave; tối thiểu theo CineBench R20.</p>\r\n\r\n<p><strong>Hiệu suất hệ thống</strong><br />\r\n&nbsp; &nbsp;Điểm chuẩn PCMark lu&ocirc;n đi trước XPS 15 7590 Core i5 năm ngo&aacute;i &ndash; nếu chỉ vừa đủ. Bạn n&ecirc;n chạy c&aacute;c bản cập nhật Dell c&agrave;ng sớm c&agrave;ng tốt v&igrave; nh&agrave; sản xuất nổi tiếng về việc ph&aacute;t h&agrave;nh hotfix cho d&ograve;ng XPS của m&igrave;nh.</p>\r\n\r\n<p>Thật kỳ lạ, đơn vị thử nghiệm của ch&uacute;ng t&ocirc;i đ&ocirc;i khi kh&ocirc;ng nhận ra bộ thu USB Logitech của ch&uacute;ng t&ocirc;i khi cắm n&oacute; v&agrave;o một trong ba cổng USB Type-C. R&uacute;t ph&iacute;ch cắm v&agrave; cắm lại sẽ giải quyết vấn đề, nhưng d&ugrave; sao đ&oacute; cũng l&agrave; một điều kh&oacute; chịu. Ch&uacute;ng t&ocirc;i kh&ocirc;ng biết chắc chắn nếu đ&oacute; chỉ l&agrave; một vấn đề cụ thể đối với đơn vị của ch&uacute;ng t&ocirc;i hoặc nếu đ&oacute; l&agrave; một vấn đề lớn hơn.</p>\r\n\r\n<p><strong>Tiếng ồn hệ thống</strong><br />\r\n&nbsp; Hệ thống c&oacute; thể giữ im lặng l&acirc;u hơn nhiều so với hầu hết c&aacute;c Laptop kh&aacute;c. V&iacute; dụ, khi chạy cảnh chuẩn 90 gi&acirc;y trong 3DMark 06, c&aacute;c quạt trong XPS 15 ho&agrave;n to&agrave;n kh&ocirc;ng đập. Điều n&agrave;y c&oacute; thể thay đổi khi ch&uacute;ng t&ocirc;i kiểm tra SKU Core i7 cao cấp hơn với đồ họa GeForce GTX, nhưng &iacute;t nhất người d&ugrave;ng m&ocirc; h&igrave;nh cơ sở c&oacute; thể dễ d&agrave;ng biết rằng họ c&oacute; thể duyệt, gửi email v&agrave; ph&aacute;t video m&agrave; kh&ocirc;ng c&oacute; tiếng ồn của quạt.</p>\r\n\r\n<p>Tệ nhất, ch&uacute;ng t&ocirc;i c&oacute; thể ghi lại tiếng ồn của quạt l&agrave; 41,9 dB (A) khi chạy đồng thời cả Prime95 v&agrave; FurMark, &acirc;m lượng lớn hơn so với những g&igrave; ch&uacute;ng t&ocirc;i đ&atilde; ghi tr&ecirc;n m&ocirc; h&igrave;nh cơ sở Core i5 năm ngo&aacute;i. Đối với hầu hết người d&ugrave;ng, tiếng ồn của quạt thường sẽ duy tr&igrave; ở mức dưới 32 hoặc 36 dB (A).</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://thegioiso365.com/wp-content/uploads/2020/06/dell-xps-15-9500-i7-10750h-gtx-1650ti-ram-32gb-ssd-512-tb-15-6-uhd-new-seal-bao-hanh-vn-2-nam-4862-23.jpg\" /></p>\r\n\r\n<p>RAM rất may vẫn c&oacute; thể n&acirc;ng cấp. Ch&uacute;ng t&ocirc;i c&oacute; thể nhận thấy kh&ocirc;ng c&oacute; tiếng ồn điện tử hoặc tiếng r&ecirc;n rỉ từ đơn vị thử nghiệm của ch&uacute;ng t&ocirc;i</p>\r\n\r\n<p><strong>Loa ngo&agrave;i</strong><br />\r\n&nbsp; &nbsp; &nbsp;Dell đ&atilde; cải tiến c&aacute;c loa b&ecirc;n trong để bao gồm cả loa si&ecirc;u trầm v&agrave; loa tweeter v&agrave; chất lượng &acirc;m thanh thu được rất c&acirc;n bằng đặc biệt l&agrave; đối với một Ultrabook. C&aacute;c ph&eacute;p đo tiếng ồn m&agrave;u hồng cho thấy khởi động ở mức 200 Hz so với 300 Hz hoặc lớn hơn tr&ecirc;n hầu hết c&aacute;c Laptop rẻ hơn. Nhược điểm ch&iacute;nh l&agrave; boong b&agrave;n ph&iacute;m sẽ rung khi chạm nhiều hơn mong đợi ngay cả khi ở mức &acirc;m lượng 50 phần trăm. Ch&uacute;ng t&ocirc;i t&igrave;m thấy sự rung động đến mất tập trung khi xử l&yacute; văn bản v&igrave; l&ograve;ng b&agrave;n tay của bạn sẽ nằm tr&ecirc;n l&ograve;ng b&agrave;n tay.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://thegioiso365.com/wp-content/uploads/2020/06/dell-xps-15-9500-i7-10750h-gtx-1650ti-ram-32gb-ssd-512-tb-15-6-uhd-new-seal-bao-hanh-vn-2-nam-4862-24.jpg\" /></p>\r\n\r\n<p><strong>Tuổi thọ pin</strong><br />\r\n&nbsp; &nbsp; Hai t&ugrave;y chọn pin c&oacute; sẵn t&ugrave;y thuộc v&agrave;o SKU: 56 Wh v&agrave; 86 Wh. Mặc d&ugrave; ch&uacute;ng t&ocirc;i c&oacute; t&ugrave;y chọn 56 Wh &iacute;t hơn, thời gian chạy vẫn rất d&agrave;i với gần 9,5 giờ sử dụng mạng WLAN trong thế giới thực v&agrave; t&ugrave;y chọn 86 Wh sẽ kh&ocirc;ng thể tồn tại l&acirc;u hơn nữa. Lưu &yacute; rằng c&aacute;c hệ thống XPS 15 cũ hơn c&oacute; c&aacute;c t&ugrave;y chọn pin 97 Wh lớn hơn c&oacute; nghĩa l&agrave; dung lượng pin đ&atilde; giảm.<br />\r\nSạc từ trống đến hết c&ocirc;ng suất tương đối nhanh ở mức 1 đến 1,5 giờ.&nbsp;Tất nhi&ecirc;n, t&ugrave;y chọn 86 Wh c&oacute; thể sẽ mất nhiều thời gian hơn để sạc.</p>\r\n\r\n<p><strong>G&oacute;i gọn : M&agrave;n h&igrave;nh lớn hơn trong k&iacute;ch thước nhỏ hơn</strong><br />\r\n&nbsp; &nbsp;Từ quan điểm của một người ti&ecirc;u d&ugrave;ng trung b&igrave;nh, Dell XPS 15 9500 được l&agrave;m mới gần như tất cả c&aacute;c hộp b&ecirc;n phải. M&agrave;n h&igrave;nh 16:10 s&aacute;ng, phản hồi b&agrave;n ph&iacute;m được cải thiện, b&agrave;n ph&iacute;m rộng r&atilde;i, hệ thống &acirc;m thanh mở rộng, thời lượng pin d&agrave;i, quạt &ecirc;m, RAM n&acirc;ng cấp v&agrave; khe M.2 thứ cấp mới đều gi&uacute;p hệ thống trở n&ecirc;n th&uacute; vị khi sử dụng. Nếu bạn đang cố gắng n&acirc;ng cấp l&ecirc;n Dell XPS 15 9500, th&igrave; b&acirc;y giờ sẽ l&agrave; l&uacute;c để xem x&eacute;t lại bởi v&igrave; phi&ecirc;n bản mới nhất n&agrave;y cải thiện thiết kế cũ hơn theo những c&aacute;ch quan trọng. Việc bỏ s&oacute;t cả HDMI v&agrave; USB Type-A chắc chắn sẽ g&acirc;y phiền to&aacute;i, nhưng &iacute;t nhất c&aacute;c bộ điều hợp được bao gồm trong mỗi hộp nhiều hơn những g&igrave; ch&uacute;ng ta c&oacute; thể n&oacute;i cho MacBook Pro.<br />\r\nTuy nhi&ecirc;n, từ quan điểm của một người đam m&ecirc;, c&oacute; vẻ như giải ph&aacute;p l&agrave;m m&aacute;t đ&atilde; kh&ocirc;ng được cải thiện nhiều. Nhiệt độ l&otilde;i đ&atilde; đạt hơn 90 C tr&ecirc;n cấu h&igrave;nh cơ sở Core i5 l&otilde;i tứ của ch&uacute;ng t&ocirc;i, điều đ&oacute; c&oacute; nghĩa l&agrave; cấu h&igrave;nh Core i7 GeForce GTX cap cấp hơn sẽ chạy nhiều hơn v&agrave; ấm hơn.</p>', 42500000, 40500000, 4, 'Bộ sản phẩm', 'laptop_dell_xps_15_9500.png', 'LAP', 'DELL', 1, NULL, '2021-07-02 21:42:25', '2021-07-23 17:48:16', 1, '2021-07-06 15:15:03');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (10, 'Lenovo ThinkPad X1 Extreme Gen 1', '<ul>\r\n	<li>Thương hiệu: Lenovo</li>\r\n	<li><strong>Vi xử l&yacute;</strong>: Intel Core i7-8750H, 6 nh&acirc;n / 12 luồng</li>\r\n	<li><strong>M&agrave;n h&igrave;nh</strong>: 15.6&quot; FHD IPS (1920 x 1080), chống ch&oacute;i</li>\r\n	<li><strong>RAM</strong>: 16GB DDR4 bus 2666 MHz (N&acirc;ng cấp tối đa 64GB)</li>\r\n	<li><strong>Card đồ họa</strong>: NVIDIA GeForce GTX1050Ti 4GB</li>\r\n	<li><strong>Lưu trữ</strong>: 512GB m.2 NVMe(N&acirc;ng cấp tối đa 2TB)</li>\r\n	<li><strong>Pin</strong>: 80 WHr</li>\r\n	<li><strong>Kết nối ch&iacute;nh</strong>: 2 x USB-C, Thunderbolt 3, 2 x USB-A</li>\r\n	<li><strong>Hệ điều h&agrave;nh</strong>: Windows 10 bản quyền</li>\r\n	<li><strong>M&agrave;u sắc:&nbsp;</strong>Black</li>\r\n</ul>', '<h3><strong>Đ&aacute;nh gi&aacute; chi tiết</strong></h3>\r\n\r\n<p><strong>Ưu điểm</strong></p>\r\n\r\n<ul>\r\n	<li>Thiết kế mỏng nhẹ, tinh tế</li>\r\n	<li>Hiệu năng mạnh mẽ</li>\r\n	<li>Khả năng n&acirc;ng cấp dễ d&agrave;ng</li>\r\n	<li>M&agrave;n h&igrave;nh cho chất lượng hiển thị tốt</li>\r\n</ul>\r\n\r\n<p><strong>Nhược điểm</strong></p>\r\n\r\n<ul>\r\n	<li>M&aacute;y nhanh n&oacute;ng khi thực hiện t&aacute;c vụ nặng, đặc biệt l&agrave; tr&ecirc;n phi&ecirc;n bản Core i9</li>\r\n	<li>Lược bỏ cổng RJ-45</li>\r\n</ul>\r\n\r\n<p><strong>Đ&acirc;u l&agrave; đối tượng ph&ugrave; hợp cho chiếc m&aacute;y n&agrave;y?</strong></p>\r\n\r\n<p>Với thiết kế thức thời, hiện đại, c&ugrave;ng hiệu năng mạnh mẽ tới từ CPU v&agrave; GPU, ThinkPad X1 Extreme Gen 2 hướng tới những đối tượng truyền th&ocirc;ng đa phương tiện, cần phải di chuyển nhiều nhưng cần 1 chiếc m&aacute;y c&oacute; chất lượng b&agrave;n ph&iacute;m tốt.</p>\r\n\r\n<p><strong>L&agrave;n gi&oacute; mới của Ultrabook hiệu năng cao</strong></p>\r\n\r\n<p>Trước sức &eacute;p từ đối thủ l&agrave; d&ograve;ng XPS cao cấp, Lenovo đ&atilde; lần đầu ti&ecirc;n tung ra một chiếc Ultrabook hiệu năng cao với khả năng phục vụ cho c&aacute;c ng&agrave;nh đa phương tiện. Chiếc m&aacute;y vẫn mang một sắc đen truyền thống c&ugrave;ng c&aacute;c g&oacute;c cạnh sắc n&eacute;t. Chiếc m&aacute;y sử dụng hợp kim magnesium cho mặt lưng cũng như th&acirc;n m&aacute;y để tăng cường độ bền cũng như giảm đ&aacute;ng kể trọng lượng, b&ecirc;n cạnh đ&oacute;, h&atilde;ng sử dụng hợp kim nh&ocirc;m cho mặt đ&aacute;y nhằm tăng cường khả năng tản nhiệt cũng như tạo ra sự chắc chắn tuyệt đối. Chiếc m&aacute;y vẫn được phủ lớp sợi carbon gia cường nhằm tạo ra sự b&oacute;ng bẩy, cũng như tối đa h&oacute;a sự bền bỉ khi sử dụng ở nhiều điều kiện m&ocirc;i trường khắc nghiệt.</p>\r\n\r\n<p>Mặt nắp m&aacute;y được điểm l&ecirc;n chữ X1 quen thuộc, đ&atilde; từng xuất hiện tr&ecirc;n chiếc X1 Carbon Gen 6 v&agrave; Gen 7. Viền m&agrave;n h&igrave;nh được l&agrave;m mỏng, hợp thời. Cần gạt ThinkShutter được đặt gọn tr&ecirc;n viền tr&ecirc;n m&agrave;n h&igrave;nh, gi&uacute;p thao t&aacute;c dễ d&agrave;ng việc che camera. Cũng v&igrave; l&agrave; Ultrabook hiệu năng cao, chiếc m&aacute;y được thiết kế với kiểu bản lề liền khối, tăng tối đa khả năng tản nhiệt.</p>\r\n\r\n<p><strong>Tối ưu trải nghiệm m&agrave;n h&igrave;nh&nbsp;</strong></p>\r\n\r\n<p>ThinkPad P1 thế hệ thứ nhất được trang bị m&agrave;n h&igrave;nh Full HD IPS ti&ecirc;u chuẩn, c&oacute; độ phủ m&agrave;u 92% sRGB v&agrave; 61% AdobeRGB với độ s&aacute;ng ở mức trung b&igrave;nh, v&agrave;o khoảng 300 nits. Với độ phủ m&agrave;u cao như vậy, m&agrave;n h&igrave;nh n&agrave;y ph&ugrave; hợp với những người thiết kế đồ họa, hay phải l&agrave;m những c&ocirc;ng việc chỉnh ảnh chuy&ecirc;n nghiệp.</p>\r\n\r\n<p>Ngo&agrave;i ra, m&aacute;y c&ograve;n c&oacute; hai t&ugrave;y chọn nữa l&agrave; 4K v&agrave; 4K Touch, cho m&agrave;u sắc trung thực, sử dụng tốt trong c&ocirc;ng việc thiết kế chuy&ecirc;n nghiệp. Tuy nhi&ecirc;n, một m&agrave;n h&igrave;nh Full HD IPS c&oacute; lẽ l&agrave; đủ cho mọi nhu cầu c&ocirc;ng việc rồi.</p>\r\n\r\n<p><strong>Hiệu năng to&agrave;n diện</strong></p>\r\n\r\n<p>Chiếc m&aacute;y sử dụng d&ograve;ng CPU Intel Coffee Lake thế hệ 8 hiệu năng cao, gi&uacute;p người d&ugrave;ng c&oacute; thể chạy những chương tr&igrave;nh nặng như Render những thước phim 4K d&agrave;i hoặc chạy những phần mềm giả lập nặng, đặc biệt l&agrave; khi m&aacute;y được trang bị t&ugrave;y chọn Core i9 8950HK.</p>\r\n\r\n<p>Hệ thống card đồ họa cũng được ph&acirc;n chia cho ph&ugrave; hợp nhu cầu c&ocirc;ng việc, với t&ugrave;y chọn cơ bản l&agrave; Intel UHD 630. Ngo&agrave;i ra, m&aacute;y c&ograve;n c&oacute; t&ugrave;y chọn card đồ họa GTX 1050Ti, cho khả năng xử l&yacute; đồ họa cực tốt.</p>\r\n\r\n<p><strong>Tối ưu khi kết nối c&aacute;c thiết bị ngoại vi</strong></p>\r\n\r\n<p>M&aacute;y c&oacute; 2 cổng USB Type A 3.1 Gen 1 nằm ở cạnh phải, 2 cổng USB Type C 3.1 Gen 2 t&iacute;ch hợp Thunderbolt 3, một khe thẻ SD truyền thống, 1 cổng HDMI 2.0, một cổng kết nối Mini RJ-45 v&agrave; 1 jack tai nghe 3.5mm. Với số lượng cổng kết nối như n&agrave;y, người d&ugrave;ng kh&ocirc;ng c&ograve;n phải &aacute;i ngại mỗi khi định lắp th&ecirc;m c&aacute;c thiết bị kh&aacute;c như chuột v&agrave; b&agrave;n ph&iacute;m rời nữa.</p>\r\n\r\n<p><strong>B&agrave;n ph&iacute;m v&agrave; Touchpad</strong></p>\r\n\r\n<p>B&agrave;n ph&iacute;m c&oacute; h&agrave;nh tr&igrave;nh 2,2mm, khoảng c&aacute;ch c&aacute;c ph&iacute;m hợp l&yacute;, keycaps bo cong, &ocirc;m tay, mang lại sự thoải m&aacute;i khi g&otilde; li&ecirc;n tục trong thời gian d&agrave;i. C&oacute; lẽ, đ&acirc;y l&agrave; Ultrabook c&oacute; b&agrave;n ph&iacute;m tốt nhất hiện nay.</p>\r\n\r\n<p>Touchpad c&oacute; k&iacute;ch thước lớn, bề mặt phủ k&iacute;nh nhưng c&oacute; th&ecirc;m một lớp nh&aacute;m mềm mang lại cảm gi&aacute;c tiếp x&uacute;c rất tuyệt. Độ trễ khi di chuyển thấp, c&aacute;c thao t&aacute;c đa điểm nhạy nhờ v&agrave;o Windows Precision Driver. Hai b&ecirc;n chuột tr&aacute;i &ndash; phải cho độ nảy tốt, phản hồi nhanh.</p>\r\n\r\n<p>Trackpoint vẫn cho độ ch&iacute;nh x&aacute;c cao tuyệt đối. Cụm n&uacute;t chuột bổ trợ nhạy, c&oacute; điểm lực v&agrave; phản hồi kh&aacute; r&otilde; r&agrave;ng.</p>\r\n\r\n<p><strong>Khả năng bảo mật</strong></p>\r\n\r\n<p>X1 Extreme Gen 1 được trang bị cảm biến v&acirc;n tay 3 lớp ở gần cụm ph&iacute;m mũi t&ecirc;n, được nh&uacute;ng con chip dTPM 2.0 thẳng v&agrave;o Bios để thiết lập mật khẩu ổ cứng, mật khẩu l&uacute;c khởi động m&aacute;y. Th&ecirc;m v&agrave;o đ&oacute;, chiếc m&aacute;y c&ograve;n được trang bị cần gạt ThinkShutter quen thuộc, chống việc bị b&ecirc;n thứ 3 x&acirc;m nhập v&agrave;o. Ngo&agrave;i ra m&aacute;y c&ograve;n được trang bị mở kh&oacute;a khu&ocirc;n mặt Windows Hello với 2 cảm biến hồng ngoại si&ecirc;u nhạy.</p>\r\n\r\n<p><strong>ThinkPad X1 Extreme liệu c&oacute; thể đạt được ng&ocirc;i vương Ultrabook hiệu năng cao?</strong></p>\r\n\r\n<p>Với thiết kế mới ho&agrave;n to&agrave;n, c&ugrave;ng hiệu năng mạnh mẽ trong một chiếc Ultrabook, ThinkPad X1 Extreme thực sự l&agrave; một chiếc Ultrabook v&ocirc; c&ugrave;ng đ&aacute;ng gi&aacute;, ph&ugrave; hợp với những người vừa th&iacute;ch sự mỏng nhẹ, t&iacute;nh di động cao, đặc biệt l&agrave; th&iacute;ch th&uacute; trải nghiệm g&otilde; ph&iacute;m tr&ecirc;n ThinkPad.</p>', 37990000, NULL, NULL, 'Bộ sản phẩm', 'lenovo-thinkpad-x1-extreme-gen-1-ThinkPadX1EG101NO.jpg', 'LAP', 'LENOVO', 2, NULL, '2021-07-03 10:31:13', '2021-07-05 17:19:48', 1, '2021-07-05 17:19:48');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (11, 'Màn hình LG UltraFine 27MD5KA 27\" IPS 5K', '<p><strong>- Nh&agrave; sản xuất :</strong>&nbsp;LG</p>\r\n\r\n<p><strong>- M&agrave;u:</strong>&nbsp;</p>\r\n\r\n<p><strong>- T&igrave;nh trạng :</strong>&nbsp;NEW - 100%</p>\r\n\r\n<p><strong>- Bảo h&agrave;nh :</strong>&nbsp;24 th&aacute;ng</p>', '<p>Được sinh ra l&agrave; để d&agrave;nh cho c&aacute;c chuy&ecirc;n gia về h&igrave;nh ảnh, LG UltraFine 5K kh&ocirc;ng chỉ l&agrave; một thiết bị hiển thị m&agrave; c&ograve;n t&aacute;i hiện cả thế giới trong mắt bạn. Với những khả năng vượt ra ngo&agrave;i những g&igrave; m&agrave; một designer phổ th&ocirc;ng c&oacute; thể cần, chắc chắn LG UltraFine 5K sẽ l&agrave; sự lựa chọn ho&agrave;n hảo cho những người nghệ sĩ t&agrave;i hoa với đ&ocirc;i mắt tinh tường, kh&oacute; t&iacute;nh.</p>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://file.hstatic.net/1000026716/file/gearvn-ips-27-5k-lg-27md5ka-1_a8a93744d62c459d8a48dd1c190c6cba.jpg\" width=\"800\" /></p>\r\n\r\n<h2><strong>Vượt ngo&agrave;i ti&ecirc;u chuẩn</strong></h2>\r\n\r\n<p>Chiếc&nbsp;m&agrave;n h&igrave;nh LG&nbsp;n&agrave;y c&oacute; độ ph&acirc;n giải rất lớn, vượt ra ngo&agrave;i cả ti&ecirc;u chuẩn 4K th&ocirc;ng thường, đạt mức 5K, tương đương 5120 x 2880 điểm ảnh, mang đến cho bạn một kh&ocirc;ng gian l&agrave;m việc cực kỳ thoải m&aacute;i. Việc xử l&yacute; h&igrave;nh ảnh độ ph&acirc;n giải cao giờ đ&acirc;y cũng trở n&ecirc;n dễ d&agrave;ng hơn, gi&uacute;p bạn th&ecirc;m y&ecirc;u c&ocirc;ng việc, đam m&ecirc; của m&igrave;nh.</p>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://file.hstatic.net/1000026716/file/gearvn-ips-27-5k-lg-27md5ka-2_85b9fea562a34fe4b218378d8eaa0ce9.jpg\" width=\"800\" /></p>\r\n\r\n<h2><strong>Hơn cả hiện thực</strong></h2>\r\n\r\n<p>Độ ph&acirc;n giải cực lớn thu gọn trong một tấm nền 27 inch gi&uacute;p cho mật độ điểm ảnh trở n&ecirc;n d&agrave;y hơn đạt 218 điểm tr&ecirc;n inch, vẽ ra trước mắt bạn những h&igrave;nh ảnh cực kỳ sắc n&eacute;t, tinh xảo (n&oacute;i t&oacute;m lại l&agrave; nh&igrave;n kh&ocirc;ng thấy được điểm ảnh đ&acirc;u). Tấm nền IPS chất lượng cao cũng cho lại g&oacute;c nh&igrave;n cực rộng v&agrave; hạn chế tối thiểu hiện tượng biến m&agrave;u khi thay đổi g&oacute;c nh&igrave;n.</p>\r\n\r\n<p>Được sinh ra l&agrave; một chiếc&nbsp;m&agrave;n h&igrave;nh m&aacute;y t&iacute;nh&nbsp;d&agrave;nh cho designer chuy&ecirc;n nghiệp, khả năng hiển thị m&agrave;u sắc của LG UltraFine 5K cũng rất ấn tượng. Độ bao phủ m&agrave;u đạt 99% gam m&agrave;u điện ảnh DCI-P3 cho khả năng thể hiện m&agrave;u sắc ch&acirc;n thực kết hợp c&ugrave;ng độ s&acirc;u m&agrave;u 10bit (8bit + A-FRC) gi&uacute;p l&agrave;m mượt phần chuyển giữa c&aacute;c mảng m&agrave;u với nhau. Tất cả l&agrave; để tạo n&ecirc;n những sắc m&agrave;u chuẩn nhất, sống động nhất, l&agrave;m cơ sở để bạn s&aacute;ng tạo n&ecirc;n những t&aacute;c phẩm tr&ecirc;n cả hiện thực. Độ s&aacute;ng cao l&ecirc;n đến 500 nit gi&uacute;p bạn lu&ocirc;n c&oacute; được tầm nh&igrave;n tốt nhất bất kể độ s&aacute;ng m&ocirc;i trường.</p>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://file.hstatic.net/1000026716/file/gearvn-ips-27-5k-lg-27md5ka-4_f02b33dad5414f3e89ca207e852fe5d7.jpg\" width=\"800\" /></p>\r\n\r\n<p>Ngo&agrave;i ra th&igrave; mỗi một chiếc m&agrave;n h&igrave;nh LG UltraFine 5K cũng đều được c&acirc;n chỉnh m&agrave;u sắc ngay tại nh&agrave; m&aacute;y b&ecirc;n bạn c&oacute; thể mua l&agrave; cắm d&acirc;y v&agrave;o d&ugrave;ng lu&ocirc;n, tiết kiệm được cả chi ph&iacute; c&acirc;n m&agrave;u.</p>\r\n\r\n<h2><strong>Một cho tất cả</strong></h2>\r\n\r\n<p>M&agrave;n h&igrave;nh LG UltraFine 5K c&oacute; cổng Thunderbolt 3 c&oacute; thể truyền video, h&igrave;nh ảnh v&agrave; dữ liệu 5K đồng thời sạc pin cho d&ograve;ng m&aacute;y mới MacBook Pro (l&ecirc;n đến 85W) chỉ đơn giản với một sợi c&aacute;p duy nhất. Kh&ocirc;ng những thế, LG UltraFine 5K c&ograve;n trang bị th&ecirc;m ba cổng kết nối USB-C (downstream USB 5 Gbps) cho ph&eacute;p bạn kết nối th&ecirc;m c&aacute;c thiết bị khi cần.</p>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://file.hstatic.net/1000026716/file/gearvn-ips-27-5k-lg-27md5ka-5_59578a518505463dad857581c2ede54e.jpg\" width=\"800\" /></p>\r\n\r\n<h2><strong>Nhiều hơn những g&igrave; bạn cần</strong></h2>\r\n\r\n<p>LG UltraFine 5K kh&ocirc;ng chỉ l&agrave; một chiếc m&agrave;n h&igrave;nh, n&oacute; l&agrave;m được hơn thế nữa kia. Chiếc m&agrave;n h&igrave;nh n&agrave;y được trang bị một cặp loa stereo 5Wx2 77dB, gi&uacute;p bạn xuất &acirc;m thanh m&agrave; kh&ocirc;ng cần đến loa rời hoặc tai nghe. T&iacute;ch hợp camera cho ph&eacute;p bạn tham gia gọi video m&agrave; kh&ocirc;ng cần gắn webcam. Những tiện &iacute;ch n&agrave;y sẽ gi&uacute;p bạn dễ d&agrave;ng tham gia hoạt động giải tr&iacute; v&agrave; truyền th&ocirc;ng, cho ph&eacute;p bạn xem phim v&agrave; tr&ograve; chuyện bằng video m&agrave; kh&ocirc;ng cần phải đầu tư bất kỳ thiết bị n&agrave;o nữa.</p>\r\n\r\n<p>Ngo&agrave;i ra chiếc m&agrave;n h&igrave;nh c&ograve;n được trang bị cảm biến &aacute;nh s&aacute;ng m&ocirc;i trường sẽ gi&uacute;p chiếc m&agrave;n h&igrave;nh nhận biết điều kiện s&aacute;ng để đưa ra mức điều chỉnh độ s&aacute;ng ph&ugrave; hợp cho bạn một c&aacute;ch tự động ho&agrave;n to&agrave;n.&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://file.hstatic.net/1000026716/file/6498744091279360.png\" width=\"800\" /></p>', 25950000, NULL, NULL, 'Bộ sản phẩm', 'lg_ultrafine_27md5ka.jpg', 'MH', 'LG', 2, NULL, '2021-07-03 10:37:02', '2021-07-05 15:05:05', 1, '2021-07-05 15:05:05');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (12, 'Chuột Apple Magic Mouse 2', '<ul>\r\n	<li>Thiết kế mới nhẹ hơn, kh&ocirc;ng c&ograve;n sử dụng pin truyền thống, m&agrave; sạc pin qua c&aacute;p lightning được k&egrave;m theo trong hộp sản phẩm</li>\r\n	<li>Chỉ cần sạc 2 tiếng cho thời gian sử dụng li&ecirc;n tục tới 1 th&aacute;ng</li>\r\n	<li>Tương th&iacute;ch với thiết bị Mac c&oacute; hỗ trợ MacOS phi&ecirc;n bản 10.11 trở l&ecirc;n</li>\r\n</ul>', '<h3>Đặc điểm nổi bật</h3>\r\n\r\n<p><strong>Đến từ thương hiệu c&ocirc;ng nghệ lừng danh Apple,&nbsp;Chuột kh&ocirc;ng d&acirc;y Magic Mouse 2 White&nbsp;l&agrave; phụ kiện l&yacute; tưởng cho những ai đang t&igrave;m kiếm một bộ chuột kh&ocirc;ng d&acirc;y c&oacute; c&ocirc;ng nghệ hiện đại, thiết kế sang trọng v&agrave; khả năng tương th&iacute;ch tối ưu với d&ograve;ng m&aacute;y Mac.</strong></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"chuột không dây Apple Magic Mouse 2\" src=\"http://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/AnhNQ/1310/Mo-ta-san-pham-chuot-khong-day-apple-magic-mouse-2-1(1).jpg\" width=\"100%\" /></p>\r\n\r\n<h3><strong>Thiết kế thanh lịch, tối giản v&agrave; liền mạch</strong></h3>\r\n\r\n<p>Diện mạo của Magic Mouse 2 mang đậm dấu ấn Apple khi sử dụng ng&ocirc;n ngữ thiết kế tối giản với vẻ ngo&agrave;i liền mạch b&oacute;ng bẩy, k&iacute;ch cỡ gọn g&agrave;ng v&agrave; logo T&aacute;o cắn dở hiện diện b&ecirc;n tr&ecirc;n.</p>\r\n\r\n<p>Bạn sẽ cảm thấy y&ecirc;u th&iacute;ch Magic Mouse 2 ngay từ lần đầu cầm nắm v&agrave; trải nghiệm bởi sự thanh lịch, trọng lượng nhẹ nh&agrave;ng v&agrave; những thao t&aacute;c cử chỉ tiện dụng m&agrave; n&oacute; mang lại.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Thiết kế chuột Magic Mouse 2\" src=\"http://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/AnhNQ/1310/Mo-ta-san-pham-chuot-khong-day-apple-magic-mouse-2-3(1).jpg\" width=\"100%\" /></p>\r\n\r\n<h3><strong>Sạc pin</strong><strong>&nbsp;dễ d&agrave;ng, thời gian sử dụng&nbsp;</strong><strong>d&agrave;i l&acirc;u</strong></h3>\r\n\r\n<p>Một ưu thế lớn của Magic Mouse 2 so với đa số d&ograve;ng&nbsp;chuột kh&ocirc;ng d&acirc;y&nbsp;kh&aacute;c tr&ecirc;n thị trường l&agrave; việc sản phẩm n&agrave;y sử dụng pin liền được t&iacute;ch hợp sẵn b&ecirc;n trong.</p>\r\n\r\n<p>Chỉ với một lần sạc hai tiếng th&ocirc;ng qua cổng lightning ở mặt dưới, bạn c&oacute; thể nạp đầy năng lượng để sử dụng&nbsp;phụ kiện&nbsp;n&agrave;y trong khoảng một th&aacute;ng. H&atilde;y tạm biệt những phiền phức của pin rời với Magic Mouse 2.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Magic Mouse 2 Sạc pin dễ dàng\" src=\"http://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/AnhNQ/1310/Mo-ta-san-pham-chuot-khong-day-apple-magic-mouse-2-4(1).jpg\" width=\"100%\" /></p>\r\n\r\n<h3><strong>Tương th&iacute;ch tối ưu với MacOS</strong></h3>\r\n\r\n<p>Nếu bạn l&agrave; chủ nh&acirc;n của một chiếc&nbsp;iMac&nbsp;hay&nbsp;MacBook, việc sắm sửa ch&uacute; chuột kh&ocirc;ng d&acirc;y Magic Mouse 2 sẽ gi&uacute;p bạn ph&aacute;t huy tối đa khả năng tương th&iacute;ch của Mac OS để hỗ trợ cho qu&aacute; tr&igrave;nh l&agrave;m việc v&agrave; học tập.</p>\r\n\r\n<p>C&aacute;c thao t&aacute;c như cuộn trang l&ecirc;n xuống, chuyển tab Safari, ph&oacute;ng to thu nhỏ h&igrave;nh ảnh hay k&iacute;ch hoạt như chế độ bird&rsquo;s-eye đều được thực hiện dễ d&agrave;ng hơn nhiều nếu bạn sử dụng Magic Mouse 2 kết nối với m&aacute;y Mac.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Magic Mouse 2 Tương thích tối ưu với Mac OS\" src=\"http://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/AnhNQ/1310/Mo-ta-san-pham-chuot-khong-day-apple-magic-mouse-2-2.jpg\" /></p>\r\n\r\n<h3><strong>Khả năng kết nối kh&ocirc;ng d&acirc;y tốc độ cao</strong></h3>\r\n\r\n<p>Magic Mouse 2 hỗ trợ c&ocirc;ng nghệ kết nối Wireless, Lightning port v&agrave; Bluetooth. C&aacute;c kĩ sư của Apple thiết kế đầu thu t&iacute;n hiệu nhỏ gọn nhưng vẫn đảm bảo tối đa khả năng hoạt động ổn định v&agrave; độ nhạy, mỗi c&uacute; click chuột đều được phản hồi nhanh ch&oacute;ng, mượt m&agrave; v&agrave; c&oacute; thể l&agrave;m h&agrave;i l&ograve;ng bất cứ kh&aacute;ch h&agrave;ng kh&oacute; t&iacute;nh n&agrave;o.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Khả năng kết nối Magic Mouse 2\" src=\"http://fptshop.com.vn/Uploads/images/2015/Tin-Tuc/AnhNQ/1310/Mo-ta-san-pham-chuot-khong-day-apple-magic-mouse-2-5(1).jpg\" width=\"100%\" /></p>\r\n\r\n<h3><strong>T&iacute;ch hợp&nbsp;</strong><strong>sẵn c&aacute;p</strong><strong>&nbsp;kết nối Lightning đi k&egrave;m</strong></h3>\r\n\r\n<p>Để hỗ trợ người d&ugrave;ng sạc Magic Mouse 2 một c&aacute;ch tiện dụng v&agrave; dễ d&agrave;ng nhất, Apple bố tr&iacute; sẵn trong hộp đựng sản phẩm sợi c&aacute;p Lightning ti&ecirc;u chuẩn.</p>\r\n\r\n<p>Bạn c&oacute; thể sử dụng d&acirc;y c&aacute;p n&agrave;y để nạp năng lượng cho Magic Mouse 2 hay&nbsp;iPhone,&nbsp;iPad&nbsp;hoặc kết nối m&aacute;y Mac với tất cả c&aacute;c thiết bị sử dụng cổng Lightning của Apple. Kh&ocirc;ng chỉ l&agrave; c&ocirc;ng cụ hỗ trợ sạc pin, đ&acirc;y c&ograve;n l&agrave; lợi thế gi&uacute;p gia tăng khả năng tương t&aacute;c giữa c&aacute;c thiết bị nằm trong hệ sinh th&aacute;i Apple.</p>', 1700000, NULL, 4, 'Bộ sản phẩm', 'magic-mouse-2-5(1).jpg', 'MOUSE', 'APPLE', 1, NULL, '2021-07-02 17:25:42', '2021-07-23 22:16:17', 1, '2021-07-03 10:24:43');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (13, 'Dell XPS 15 9570', '<p>CPU: i7- 8750HQ (12 * 2.2 GHZ upto 4.1 GHZ 9MB cache )<br />\r\nRAM: 16 GB PC4L- 2666 MHz<br />\r\nSSD: 512 GB NVME<br />\r\nCard Đồ Họa : Intel&reg; HD Graphics , Nvidia GTX 1050Ti (4GB)<br />\r\nM&agrave;n h&igrave;nh: 15.6 inch 4K (3840 *2160) Cảm ứng<br />\r\nWindows : 10 PRO Bản quyền<br />\r\nBảo h&agrave;nh : 12 th&aacute;ng<br />\r\nT&igrave;nh Trạng : H&agrave;ng x&aacute;ch tay mỹ mới 99%</p>', '<h3>Thiết kế chắc chắc v&agrave; quyến rũ</h3>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Image result for dell xps 9570\" src=\"https://thegioiso365.com/wp-content/uploads/2019/08/dell-xps-15-9570-i9-8950h-ram-32gb-ssd-1tb-15-6-uhd-nvidia-gtx1050ti-max-q-3006.jpg\" /></p>\r\n\r\n<p>Nắp v&agrave; phần dưới của m&aacute;y được cấu tạo bởi chất liệu nh&ocirc;m CNC cao cấp gi&uacute;p cho chiếc m&aacute;y tr&ocirc;ng vừa quyến rũ lại vừa chắc chắn, c&oacute; thể chiu được những điều kiện khắc nghiệt b&ecirc;n ngo&agrave;i. Phần khung m&aacute;y được l&agrave;m từ hợp kim magi&ecirc; v&agrave; sợi carbon tạo n&ecirc;n một cảm gi&aacute;c v&ocirc; c&ugrave;ng cứng c&aacute;p. Bản lề của m&aacute;y được đ&aacute;nh gi&aacute; l&agrave; tốt nhất tr&ecirc;n thị trường hiện nay với độ chắc chắn cao.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>Chiếc laptop mỏng nhẹ nhất h&agrave;nh tinh</h3>\r\n\r\n<p>Với độ d&agrave;y chỉ l&agrave; 11-17mm v&agrave; nặng chỉ 1.8kg, Dell XPS 9570 ch&iacute;nh l&agrave; chiếc laptop 15.6 inch mỏng nhẹ nhất tr&ecirc;n thế giới hiện nay. Điều n&agrave;y khiến cho t&iacute;nh cơ động của chiếc m&aacute;y tăng l&ecirc;n rất nhiều, cho ph&eacute;p bạn c&oacute; thế dễ d&agrave;ng mang đi mọi l&uacute;c mọi nơi.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Image result for dell xps 9570\" src=\"https://thegioiso365.com/wp-content/uploads/2019/08/dell-xps-15-9570-i9-8950h-ram-32gb-ssd-1tb-15-6-uhd-nvidia-gtx1050ti-max-q-3006-1.jpg\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>Viền m&agrave;n h&igrave;nh si&ecirc;u mỏng</h3>\r\n\r\n<p><strong>Dell XPS</strong>&nbsp;l&agrave; d&ograve;ng laptop sở hữu c&ocirc;ng nghệ m&agrave;n h&igrave;nh h&agrave;ng đầu hiện nay. Với việc thu nhỏ viền m&agrave;n h&igrave;nh lại, Dell XPS 9570 d&ugrave; l&agrave; laptop 15.6 inch nhưng tr&ocirc;ng kh&ocirc;ng kh&aacute;c g&igrave; laptop 14 inch.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"A stunning view, wherever you go\" src=\"https://thegioiso365.com/wp-content/uploads/2019/08/dell-xps-15-9570-i9-8950h-ram-32gb-ssd-1tb-15-6-uhd-nvidia-gtx1050ti-max-q-3006-2.jpg\" /></p>\r\n\r\n<p>Dell XPS 9570 sở hữu một m&agrave;n h&igrave;nh c&oacute; độ ph&acirc;n giải l&agrave; FHD (1920 x 1080), c&oacute; t&ugrave;y chọn cấu h&igrave;nh l&ecirc;n tới 4K, kết hợp với c&ocirc;ng nghệ m&agrave;n h&igrave;nh Si&ecirc;u Sắc (UltraSharp) của Dell hứa hẹn sẽ mang đến cho bạn những h&igrave;nh ảnh v&ocirc; c&ugrave;ng sắc n&eacute;t v&agrave; ch&acirc;n thực tới từng chi tiết. Hơn nữa, độ bao phủ m&agrave;u sắc của m&agrave;n h&igrave;nh c&ograve;n l&ecirc;n tới 98,8% sRGB, rất ph&ugrave; hợp với những người đam m&ecirc; thiết kế đồ họa.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>&Acirc;m thanh như trong rạp chiếu phim</h3>\r\n\r\n<p>Với c&ocirc;ng nghệ &acirc;m thanh v&ograve;m Waves MaxxAudio c&ugrave;ng con ch&iacute;p Realtek High Difinition, &acirc;m thanh ph&aacute;t ra từ Dell XPS 9570 sẽ trở n&ecirc;n rất thực tế v&agrave; sống động cho ph&eacute;p bạn tận hưởng những gi&acirc;y ph&uacute;t giải tr&iacute; tuyệt vời nhất.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>Laptop = Smartphone?</h3>\r\n\r\n<p>Touchpad của tr&ecirc;n Dell XPS 9570 ch&iacute;nh l&agrave; touchpad tốt nhất trong c&aacute;c d&ograve;ng m&aacute;y chạy hệ điều h&agrave;nh Windows. Với khả năng cảm biến lực tuyệt vời c&ugrave;ng độ nhạy + phản hồi v&ocirc; c&ugrave;ng ch&iacute;nh x&aacute;c, bạn c&oacute; thể thoải m&aacute;i thực hiện những thao t&aacute;c đa điểm, hệt như tr&ecirc;n điện thoại th&ocirc;ng minh.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>C&oacute; thể kết nối tới 3 m&agrave;n h&igrave;nh c&oacute; độ ph&acirc;n giải 4K</h3>\r\n\r\n<p>Với c&ocirc;ng nghệ Thunderbolt 3, Dell XPS 9570 c&oacute; thể kết nối tới 2 m&agrave;n h&igrave;nh c&oacute; độ ph&acirc;n giải 4K, cộng th&ecirc;m với cổng HDMI, ta c&oacute; thể kết nối tới 3 m&agrave;n h&igrave;nh. Hơn nữa, Thunderbolt 3 c&oacute; tốc độ truyền tải l&ecirc;n tới 40Gbs, nhanh gấp 4 lần tốc độ th&ocirc;ng thường gi&uacute;p bạn c&oacute; thể giảm thiểu thời gian truyền tải th&ocirc;ng tin.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>Cấu h&igrave;nh mạnh mẽ v&agrave; ổn định</h3>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Image result for dell xps 9570 touchpad\" src=\"https://thegioiso365.com/wp-content/uploads/2019/08/dell-xps-15-9570-i9-8950h-ram-32gb-ssd-1tb-15-6-uhd-nvidia-gtx1050ti-max-q-3006-3.jpg\" /></p>\r\n\r\n<p>Cấu h&igrave;nh được trang bị tr&ecirc;n Dell XPS 9570 bao gồm CPU Intel Core i9-8950HK&nbsp; 12 MB cache (6 l&otilde;i 12 luồng) hỗ trợ xử l&yacute; những t&aacute;c vụ nặng v&agrave; l&agrave;m nhiều c&ocirc;ng việc c&ugrave;ng l&uacute;c rất tốt, 16GB RAM, Card đồ họa 1050Ti gi&uacute;p bạn c&oacute; thể chiến tốt hầu hết mọi tựa game hiện nay.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>Khởi động windows trong nh&aacute;y mắt</h3>\r\n\r\n<p>Với ổ SSD c&oacute; tốc độ đọc ghi tới 2500Mbs, bạn c&oacute; thể khởi động m&aacute;y trong nh&aacute;y mắt. Hơn nữa, với tốc độ truyền dữ liệu l&ecirc;n đến 30Gbs, thời gian của bạn sẽ được tiết kiệm rất nhiều.</p>', 29900000, NULL, 4, 'Bộ sản phẩm', 'dell_9570-510x340.jpg', 'LAP', 'DELL', 1, NULL, '2021-07-03 10:41:58', '2021-07-27 20:51:58', 0, NULL);
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (14, 'Cáp USB-C  to USB-C 2m Hyperdrive data & charging 10GBps + 100W', '<p><strong>Th&ocirc;ng tin kỹ thuật</strong></p>\r\n\r\n<ul>\r\n	<li>Sygn &amp; Charge</li>\r\n	<li>Chất liệu: Alumium 2 đầu c&aacute;p, d&acirc;y l&agrave;m bằng vải Nylon chống đứt</li>\r\n	<li>Chịu sức nặng 70Kgs</li>\r\n	<li>C&ocirc;ng suất sạc: 100W</li>\r\n	<li>Băng th&ocirc;ng tốc độ: 10 Gbps</li>\r\n	<li>K&iacute;ch thước: 2M/6.6FT</li>\r\n</ul>\r\n\r\n<p><strong>Bảo H&agrave;nh:</strong>&nbsp;2 năm (1 đổi 1)<br />\r\n<strong>Thương hiệu:</strong>&nbsp;Sản phẩm ch&iacute;nh h&atilde;ng của HYPER thuộc tập đo&agrave;n điện tử Sanho Corporation (USA)</p>', '<p>Chiếc c&aacute;p USB-C to USB-C 100W + 10Gbps của HyperDrive c&oacute; lẽ sẽ gi&uacute;p cho ch&uacute;ng ta c&oacute; th&ecirc;m một giải ph&aacute;p tối ưu v&agrave; v&ocirc; c&ugrave;ng cần thiết cho những ai đang cần một sợi c&aacute;p C to C cho MacBook Pro 13&Prime; 60W, MacBook Pro 15&Prime; 87W, Macbook 16&Prime; 96W hay c&aacute;c d&ograve;ng Laptop kh&aacute;c. C&aacute;i quan trọng nhất l&agrave; sợi c&aacute;p với một chất liệu bền bỉ để thay thế cho những sợi c&aacute;p C to C chất liệu TPU b&igrave;nh thường kh&aacute;c v&agrave; HD-CBG601 kh&ocirc;ng chỉ l&agrave; sợi c&aacute;p để sạc th&ocirc;ng thường m&agrave; n&oacute; c&ograve;n hỗ trợ truyền tải dữ liệu (data) với tốc độ cao 10Gbps.</p>\r\n\r\n<p><strong>Vải chống đạn v&agrave; thời trang</strong><br />\r\nĐ&acirc;y c&oacute; lẽ l&agrave; điều đặc biệt đối với sợi c&aacute;p C to C của HyperDrive, ch&uacute;ng ta sẽ cảm thấy v&ocirc; c&ugrave;ng th&iacute;ch th&uacute; v&agrave; thoải m&aacute;i khi cầm tr&ecirc;n tay chiếc c&aacute;p n&agrave;y. B&ecirc;n ngo&agrave;i sợi c&aacute;p được dệt bằng những sợi vải v&ocirc; c&ugrave;ng tỉ mỉ, thời trang đẹp mắt, m&agrave;u sắc trang nh&atilde; thanh lịch th&iacute;ch hợp cho cả nam v&agrave; nữ. Ch&uacute;ng ta sẽ thật sự bất ngờ về một sợi c&aacute;p mềm mại lại c&oacute; độ bền tuyệt vời đến thế bởi C&aacute;p HyperJuice C to C được dệt bằng vải nylon chống đạn đảm bảo một độ bền ho&agrave;n hảo chịu được sức nặng l&ecirc;n đến 70Kg.<br />\r\nC&aacute;p cũng gi&uacute;p cho việc sử dụng v&ocirc; c&ugrave;ng linh hoạt, dễ d&agrave;ng v&agrave; chống rối.</p>\r\n\r\n<p><strong>Chiều d&agrave;i 2M (6.6 ft) đảm bảo sạc v&agrave; truyền tải dữ liệu nhanh.</strong><br />\r\nChiếc c&aacute;p USB-C to USB-C gi&uacute;p bạn thoải m&aacute;i sạc pin v&agrave; kết nối truyền tải dữ liệu ở một khoảng c&aacute;ch xa với ổ cắm tr&ecirc;n tường hoặc m&aacute;y t&iacute;nh với chiều d&agrave;i l&ecirc;n đến 2M nhưng vẫn đảm b&aacute;o c&ocirc;ng suất sạc nhanh v&agrave; truyền tải dữ liệu nhanh nhất.</p>\r\n\r\n<p><strong>Charge &amp; Sync dữ liệu</strong><br />\r\nHỗ trợ sạc cấp nguồn điện v&agrave; truyền tải dữ liệu giữa c&aacute;c thiết bị m&aacute;y t&iacute;nh bảng, m&aacute;y t&iacute;nh x&aacute;ch tay,&hellip;sử dụng cổng USB-C. HD-CBG601 c&oacute; c&ocirc;ng suất sạc nhanh l&ecirc;n đến 100W n&ecirc;n c&oacute; thể sạc nhanh full c&ocirc;ng suất cho c&aacute;c d&ograve;ng Macbook Pro 13&Prime;/Macbook Pro 15&Prime;/Macbook 16&Prime; v&agrave; c&aacute;c d&ograve;ng Laptop sử dụng cổng USB-C c&oacute; c&ocirc;ng suất từ 100W trở xuống, HD-CBG601 cũng c&oacute; thể hỗ trợ sạc cho c&aacute;c thiết bị sử dụng cổng USB-C c&oacute; c&ocirc;ng suất tr&ecirc;n 100W.</p>\r\n\r\n<p><strong>Đầu C&aacute;p thiết kế mỏng</strong><br />\r\n2 đầu c&aacute;p USB-C HD-CBG601 được thiết kế bằng Alumium cao cấp, mỏng nhẹ chắc chắn đảm bảo sẽ hoạt động với hầu hết với trong mọi trường hợp một c&aacute;ch tốt nhất</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 884px) 100vw, 884px\" src=\"https://hangdang.vn/wp-content/uploads/2020/11/HyperDriveUSB-CtoUSB-CCable100W_10Gbps-2_2048x-1024x1024.jpg\" srcset=\"https://hangdang.vn/wp-content/uploads/2020/11/HyperDriveUSB-CtoUSB-CCable100W_10Gbps-2_2048x-1024x1024.jpg 1024w, https://hangdang.vn/wp-content/uploads/2020/11/HyperDriveUSB-CtoUSB-CCable100W_10Gbps-2_2048x-300x300.jpg 300w, https://hangdang.vn/wp-content/uploads/2020/11/HyperDriveUSB-CtoUSB-CCable100W_10Gbps-2_2048x-100x100.jpg 100w, https://hangdang.vn/wp-content/uploads/2020/11/HyperDriveUSB-CtoUSB-CCable100W_10Gbps-2_2048x-600x600.jpg 600w, https://hangdang.vn/wp-content/uploads/2020/11/HyperDriveUSB-CtoUSB-CCable100W_10Gbps-2_2048x-150x150.jpg 150w, https://hangdang.vn/wp-content/uploads/2020/11/HyperDriveUSB-CtoUSB-CCable100W_10Gbps-2_2048x-768x768.jpg 768w, https://hangdang.vn/wp-content/uploads/2020/11/HyperDriveUSB-CtoUSB-CCable100W_10Gbps-2_2048x-1536x1536.jpg 1536w, https://hangdang.vn/wp-content/uploads/2020/11/HyperDriveUSB-CtoUSB-CCable100W_10Gbps-2_2048x.jpg 2048w\" width=\"800\" /></p>', 690000, NULL, 8, 'Bộ sản phẩm', 'HyperDriveUSB-CtoUSB-CCable100W_10Gbps-1_2048x-600x600.jpg', 'PK', 'HYPER', 1, NULL, '2021-07-03 10:47:14', '2021-07-14 21:24:49', 1, '2021-07-11 07:48:20');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (15, 'Máy đọc sách Kindle Oasis 3 (2019)', '<ul>\r\n	<li>Model: Kindle Oasis 3</li>\r\n	<li>Nh&agrave; sản xuất: Amazon</li>\r\n	<li>Xuất xứ: Mỹ</li>\r\n	<li>Trọng lượng: 191 gram</li>\r\n	<li>Thời gian pin: 2 tuấn nếu mỗi ng&agrave;y đọc s&aacute;ch 30 ph&uacute;t</li>\r\n	<li>Thương hiệu: Kindle</li>\r\n	<li>Xuất xứ thương hiệu: Mỹ</li>\r\n	<li>Thời gian sạc: khoảng 2 tiếng</li>\r\n	<li>Hỗ trợ định dạng: EPUB, EPUB3, PDF, MOBI, JPEG, GIF, PNG, BMP, TIFF, TXT, HTML, RTF, CBZ, CBR</li>\r\n	<li>Loại/ C&ocirc;ng nghệ m&agrave;n h&igrave;nh: e-ink</li>\r\n	<li>Phụ kiện đi k&egrave;m: Kh&ocirc;ng c&oacute;</li>\r\n</ul>', '<p>&nbsp; B&ocirc;̣ nhớ: 8 GB hoặc 32 GB M&agrave;n h&igrave;nh: 7 inch Độ ph&acirc;n giải: 300 PPI M&agrave;u m&agrave;n h&igrave;nh s&aacute;ng trắng - s&aacute;ng v&agrave;ng Chống nước chuẩn IPX 8 Kết nối Bluetooth, Wifi Thiết kế mỏng nhẹ Định dạng hỗ trợ: EPUB, EPUB3, PDF, MOBI, JPEG, GIF, PNG, BMP, TIFF, TXT, HTML, RTF, CBZ, CBR</p>\r\n\r\n<h3><strong>Độ ph&acirc;n giải m&agrave;n h&igrave;nh cực cao</strong></h3>\r\n\r\n<p><strong>&nbsp; M&aacute;y đọc s&aacute;ch Kindle Oasis 32G</strong>&nbsp;với m&agrave;n h&igrave;nh 7 inch v&agrave; mật độ ảnh 300 ppi, văn bản hiển thị tr&ecirc;n thiết bị với chất lượng sắc n&eacute;t, đọc như giấy thật ngay cả trong &aacute;nh s&aacute;ng mặt trời.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Máy Đọc Sách Kindle Oasis 32G - Hàng Nhập Khẩu - Silver\" height=\"500\" src=\"https://vcdn.tikicdn.com/ts/tmp/04/89/34/0417ddc015769a3ae6e795843ab48dd6.jpg\" width=\"750\" /></p>\r\n\r\n<h3><strong>Thiết kế cực mỏng nhẹ</strong></h3>\r\n\r\n<p>&nbsp; Kindle Oasis c&oacute; độ mỏng chỉ 3.4mm với vỏ k&iacute;nh chắc chắn v&agrave; vỏ nh&ocirc;m b&oacute;ng mượt. M&aacute;y được thiết kế để c&oacute; thể d&ugrave;ng một tay, đồng thời k&iacute;ch thước nhỏ gọn gi&uacute;p bạn dễ d&agrave;ng mang thiết bị đến bất kỳ nơi n&agrave;o khi cần thiết.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Máy Đọc Sách Kindle Oasis 32G - Hàng Nhập Khẩu - Silver\" height=\"500\" src=\"https://vcdn.tikicdn.com/ts/tmp/fc/39/f8/70592d9215bee55a78ade5502285daa6.jpg\" width=\"750\" /></p>\r\n\r\n<h3><strong>L&yacute; tưởng để đọc một tay</strong></h3>\r\n\r\n<p>&nbsp; M&aacute;y đọc s&aacute;ch Kindle Oasis 32GB với thiết kế Ergonomic gi&uacute;p chuyển trọng t&acirc;m m&aacute;y nằm gọn v&agrave;o l&ograve;ng b&agrave;n tay của bạn. Thiết kế n&agrave;y tập trung c&aacute;c n&uacute;t chuyển trang về một b&ecirc;n, một b&ecirc;n d&agrave;y hơn một b&ecirc;n mỏng, việc d&ugrave;ng 1 tay l&agrave; v&ocirc; c&ugrave;ng dễ d&agrave;ng thậm ch&iacute; bạn thuận tay tr&aacute;i hay phải. Chỉ cần xoay m&agrave;n h&igrave;nh, cảm biến sẽ phục vụ bạn sao cho khớp nhất.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Máy Đọc Sách Kindle Oasis 32G - Hàng Nhập Khẩu - Silver\" height=\"500\" src=\"https://vcdn.tikicdn.com/ts/tmp/70/94/c2/fa67057098aa0ddb5f0866ece6ff79ea.jpg\" width=\"750\" /></p>\r\n\r\n<h3><strong>Đọc ở mọi nơi</strong></h3>\r\n\r\n<p>&nbsp; M&aacute;y tự động điều chỉnh độ s&aacute;ng của m&agrave;n h&igrave;nh dựa tr&ecirc;n m&ocirc;i trường xung quanh - d&ugrave; bạn đang ở trong một căn ph&ograve;ng c&oacute; &aacute;nh s&aacute;ng lờ mờ hay ngo&agrave;i trời với &aacute;nh s&aacute;ng ch&oacute;i chang, m&aacute;y đều phục vụ tốt, ngo&agrave;i ra bạn c&oacute; thể điều chỉnh tốt hơn nữa dựa tr&ecirc;n sở th&iacute;ch c&aacute; nh&acirc;n.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Máy Đọc Sách Kindle Oasis 32G - Hàng Nhập Khẩu - Silver\" height=\"750\" src=\"https://vcdn.tikicdn.com/ts/tmp/d4/32/65/55c5287a4c017dbe2aff145c409963ff.jpg\" width=\"750\" /></p>\r\n\r\n<h3><strong>Đọc s&aacute;ch theo c&aacute;ch của bạn</strong></h3>\r\n\r\n<p>&nbsp; Nhiều t&ugrave;y chọn hơn bao giờ hết để c&aacute; nh&acirc;n h&oacute;a c&agrave;i đặt của bạn với thay đổi k&iacute;ch thước ph&ocirc;ng chữ, mức độ đậm nhạ k&yacute; tự v&agrave; c&aacute;c t&iacute;nh năng trợ năng mới.&nbsp; Kết hợp với m&agrave;n h&igrave;nh 7-inch mới, đọc tr&ecirc;n Kinda Oasis 2017 thoải m&aacute;i hơn bao giờ hết.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Máy Đọc Sách Kindle Oasis 32G - Hàng Nhập Khẩu - Silver\" height=\"750\" src=\"https://vcdn.tikicdn.com/ts/tmp/02/5d/b3/5b8c94f93320c7aede5cd14e1f4026ad.jpg\" width=\"750\" /></p>\r\n\r\n<h3><strong>Chống nước chuẩn IPX 8</strong></h3>\r\n\r\n<p>&nbsp; Điểm nổi bật lớn nhất với Kindle Oasis l&agrave; n&oacute; được n&acirc;ng cấp khả năng chống nước, một t&iacute;nh năng được y&ecirc;u cầu từ người h&acirc;m mộ Kindle. M&aacute;y đ&atilde; được thử nghiệm trong hai m&eacute;t nước trong 60 ph&uacute;t, v&agrave; cũng đ&atilde; được thử nghiệm trong c&aacute;c m&ocirc;i trường nước kh&aacute;c nhau, như bồn tắm nước n&oacute;ng, bể bơi, v&agrave; bồn tắm x&agrave; ph&ograve;ng.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Máy Đọc Sách Kindle Oasis 32G - Hàng Nhập Khẩu - Silver\" height=\"500\" src=\"https://vcdn.tikicdn.com/ts/tmp/23/7a/80/c226121feeac5b24147bbf00e356606f.jpg\" width=\"750\" /></p>\r\n\r\n<h3><strong>Lật qua s&aacute;ch trong khi lưu vị tr&iacute; của bạn</strong></h3>\r\n\r\n<p>&nbsp; T&iacute;nh năng Page Flip gi&uacute;p bạn dễ d&agrave;ng t&igrave;m kiếm h&igrave;nh ảnh, biểu đồ, bản đồ v&agrave; thậm ch&iacute; cả ghi ch&uacute; v&agrave; điểm nổi bật từ c&aacute;c phần kh&aacute;c nhau của một cuốn s&aacute;ch. Trong khi bạn vuốt sang c&aacute;c trang kh&aacute;c hoặc thu nhỏ để xem h&igrave;nh thu nhỏ của trang, Page Flip sẽ tự động lưu trang m&agrave; bạn đang đọc, ghim n&oacute; ở b&ecirc;n cạnh m&agrave;n h&igrave;nh của bạn, do đ&oacute; bạn sẽ kh&ocirc;ng bao giờ phải t&igrave;m lại vị tr&iacute; m&igrave;nh đang đọc dở dang.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Máy Đọc Sách Kindle Oasis 32G - Hàng Nhập Khẩu - Silver\" height=\"500\" src=\"https://vcdn.tikicdn.com/ts/tmp/e9/7e/f7/85db4f09a7d8b66cedef3a0a7d3d1d35.jpg\" width=\"750\" /></p>\r\n\r\n<h3><strong>Văn bản tối, sắc n&eacute;t</strong></h3>\r\n\r\n<p>&nbsp; Thưởng thức văn bản đọc giống như trang in, với ph&ocirc;ng chữ Bookerly, c&oacute; thể dễ d&agrave;ng điều chỉnh bằng tay sao cho thuận tiện nhất.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Máy Đọc Sách Kindle Oasis 32G - Hàng Nhập Khẩu - Silver\" height=\"500\" src=\"https://vcdn.tikicdn.com/ts/tmp/db/b5/49/d53f477b268aa4d4ea703e795465f46b.jpg\" width=\"750\" /></p>\r\n\r\n<h3><strong>Xuất v&agrave; chia sẻ ghi ch&uacute;</strong></h3>\r\n\r\n<p>&nbsp; Giờ đ&acirc;y, bạn dễ d&agrave;ng xuất c&aacute;c ghi ch&uacute; v&agrave; điểm nổi bật từ s&aacute;ch ra e-mail, v&igrave; vậy bạn lu&ocirc;n c&oacute; thể lấy ch&uacute;ng để tham khảo. Nhận ghi ch&uacute; của bạn dưới dạng một tệp PDF v&agrave; c&oacute; thể xem ch&uacute;ng bất cứ l&uacute;c n&agrave;o.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Máy Đọc Sách Kindle Oasis 32G - Hàng Nhập Khẩu - Silver\" height=\"500\" src=\"https://vcdn.tikicdn.com/ts/tmp/63/53/22/eafcc12f8611effdd3c4d47d26d604ef.jpg\" width=\"750\" /></p>\r\n\r\n<h3><strong>Biết mất bao l&acirc;u để ho&agrave;n th&agrave;nh chương cuối</strong></h3>\r\n\r\n<p>&nbsp; Thời gian để đọc được c&aacute; nh&acirc;n ho&aacute; dựa tr&ecirc;n tốc độ đọc của bạn v&agrave; được cập nhật li&ecirc;n tục do tốc độ v&agrave; th&oacute;i quen. Trong nh&aacute;y mắt, bạn sẽ biết c&oacute; bao nhi&ecirc;u thời gian để ho&agrave;n th&agrave;nh một chương hay một cuốn s&aacute;ch.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Máy Đọc Sách Kindle Oasis 32G - Hàng Nhập Khẩu - Silver\" height=\"500\" src=\"https://vcdn.tikicdn.com/ts/tmp/55/1d/1a/70d91414160e2b8ae79415377b3fa7d8.jpg\" width=\"750\" /></p>\r\n\r\n<h3><strong>Dịch c&aacute;c đoạn văn ngay lập tức</strong></h3>\r\n\r\n<p>&nbsp; Chạm v&agrave;o bất kỳ từ n&agrave;o hoặc đ&aacute;nh dấu phần để dịch ngay sang c&aacute;c ng&ocirc;n ngữ kh&aacute;c, bao gồm tiếng T&acirc;y Ban Nha, tiếng Nhật v&agrave; nhiều thứ kh&aacute;c. C&aacute;c bản dịch được cung cấp bởi Bing Translator. Tuy nhi&ecirc;n hiện tại Tiếng Việt chưa được hỗ trợ.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Máy Đọc Sách Kindle Oasis 32G - Hàng Nhập Khẩu - Silver\" height=\"500\" src=\"https://vcdn.tikicdn.com/ts/tmp/93/8c/f6/f4b22caabd85c286398be60f4a99f694.jpg\" width=\"750\" /></p>\r\n\r\n<p>&nbsp; Gi&aacute; sản phẩm tr&ecirc;n Tiki đ&atilde; bao gồm thuế theo luật hiện h&agrave;nh. Tuy nhi&ecirc;n tuỳ v&agrave;o từng loại sản phẩm hoặc phương thức, địa chỉ giao h&agrave;ng m&agrave; c&oacute; thể ph&aacute;t sinh th&ecirc;m chi ph&iacute; kh&aacute;c như ph&iacute; vận chuyển, phụ ph&iacute; h&agrave;ng cồng kềnh, .....</p>', 6700000, NULL, 4, 'Bộ sản phẩm', 'Máy đọc sách Kindle Oasis 3 10th màn hình 7 300PPI_320x320.jpg', 'READING', 'KINDLE', 1, NULL, '2021-07-05 10:04:03', '2021-07-05 17:05:46', 1, '2021-07-05 13:08:32');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (16, 'Cáp Incharge X - Đa năng và mạnh mẽ', '<p><strong>Si&ecirc;u nhỏ</strong></p>\r\n\r\n<p><strong>Đa năng</strong></p>\r\n\r\n<p><strong>Hỗ trợ c&ocirc;ng suất l&ecirc;n đến 100W</strong></p>\r\n\r\n<p><strong>Bảo h&agrave;nh 12 th&aacute;ng</strong></p>\r\n\r\n<p><strong>Sản phẩm từ RollingSquare</strong></p>', '<h2><strong>inCharge X: Sợi c&aacute;p 6-in-1 tốt nhất tr&ecirc;n thế giới</strong></h2>\r\n\r\n<p>Tiếp nối sự th&agrave;nh c&ocirc;ng từ inCharge 6 sau qu&aacute; tr&igrave;nh lắng nghe từ &yacute; kiến người d&ugrave;ng. Giờ đ&acirc;y RollingSquare đem đến một sợi c&aacute;p sạc đa năng v&agrave; mạnh mẽ nhất hiện nay.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 860px) 100vw, 860px\" src=\"https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-1-copy-2.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-1-copy-2.jpg 860w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-1-copy-2-170x300.jpg 170w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-1-copy-2-579x1024.jpg 579w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-1-copy-2-768x1359.jpg 768w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-1-copy-2-700x1239.jpg 700w\" width=\"800\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 860px) 100vw, 860px\" src=\"https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-4.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-4.jpg 860w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-4-300x219.jpg 300w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-4-768x560.jpg 768w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-4-700x510.jpg 700w\" width=\"800\" /></p>\r\n\r\n<h2><strong>Nhỏ gọn v&agrave; &nbsp;mạnh mẽ: Hỗ trợ sạc nhanh c&ocirc;ng suất 100W</strong></h2>\r\n\r\n<p>inCharge X hỗ trợ sạc PD với c&ocirc;ng suất l&ecirc;n đến 100W.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 800px) 100vw, 860px\" src=\"https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-gia-re-copy-1.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-gia-re-copy-1.jpg 860w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-gia-re-copy-1-286x300.jpg 286w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-gia-re-copy-1-768x805.jpg 768w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-gia-re-copy-1-700x733.jpg 700w\" /></p>\r\n\r\n<p>Đồng thời inCharge X c&ograve;n hỗ trợ sạc nhanh với c&aacute;c thiết bị Apple với c&ocirc;ng suất sạc từ 18W.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 860px) 100vw, 860px\" src=\"https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-6in1-copy-1.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-6in1-copy-1.jpg 860w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-6in1-copy-1-233x300.jpg 233w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-6in1-copy-1-794x1024.jpg 794w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-6in1-copy-1-768x990.jpg 768w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-6in1-copy-1-700x903.jpg 700w\" width=\"800\" /></p>\r\n\r\n<h2><strong>Thiết kế m&oacute;c kho&aacute; nhỏ gọn -&nbsp;</strong><strong>Lu&ocirc;n b&ecirc;n bạn</strong></h2>\r\n\r\n<p>inCharge X c&oacute; thiết kế nhỏ gọn, chỉ với 25g. Đ&acirc;y sẽ l&agrave; phụ kiện c&ocirc;ng nghệ hữu &iacute;ch nhất m&agrave; bạn lu&ocirc;n c&oacute; thể mang theo b&ecirc;n m&igrave;nh.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://siliconz.vn/wp-content/uploads/2021/05/Gif-different-Position.gif\" width=\"800\" /></p>\r\n\r\n<h2><strong>inCharge X &ndash; Hỗ trợ nhiều chuẩn sạc phổ biến hiện nay</strong></h2>\r\n\r\n<p>C&agrave;ng ng&agrave;y bạn c&agrave;ng sở hữu nhiều thiết bị c&ocirc;ng nghệ, k&egrave;m theo đ&oacute; l&agrave; ch&uacute;ng ta sở hữu nhiều loại c&aacute;p sạc hơn. Tuy nhi&ecirc;n bạn kh&ocirc;ng thể mang theo b&ecirc;n m&igrave;nh tất cả những loại c&aacute;p sạc ấy b&ecirc;n m&igrave;nh, inCharge X ch&iacute;nh l&agrave; giải ph&aacute;p d&agrave;nh cho bạn. Hỗ trợ c&aacute;c chuẩn kết nối th&ocirc;ng dụng như Lighting, type C v&agrave; Micro USB.</p>\r\n\r\n<p>Ngo&agrave;i ra với phi&ecirc;n bản inCharge X Max d&agrave;i hơn, bạn c&oacute; thay thế c&aacute;c sợi c&aacute;p th&ocirc;ng thường của bạn.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 860px) 100vw, 860px\" src=\"https://siliconz.vn/wp-content/uploads/2021/05/soi-cap-incharge-x-copy-2.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2021/05/soi-cap-incharge-x-copy-2.jpg 860w, https://siliconz.vn/wp-content/uploads/2021/05/soi-cap-incharge-x-copy-2-152x300.jpg 152w, https://siliconz.vn/wp-content/uploads/2021/05/soi-cap-incharge-x-copy-2-518x1024.jpg 518w, https://siliconz.vn/wp-content/uploads/2021/05/soi-cap-incharge-x-copy-2-768x1517.jpg 768w, https://siliconz.vn/wp-content/uploads/2021/05/soi-cap-incharge-x-copy-2-777x1536.jpg 777w, https://siliconz.vn/wp-content/uploads/2021/05/soi-cap-incharge-x-copy-2-700x1383.jpg 700w\" width=\"800\" /></p>\r\n\r\n<h2><strong>Thiết kế tất cả trong một</strong></h2>\r\n\r\n<p>Với thiết kế 6 đầu sạc trong 1, inCharge X l&agrave; lựa chọn tốt nhất cho bạn để thay thế được tất cả c&aacute;p sạc của bạn.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 860px) 100vw, 860px\" src=\"https://siliconz.vn/wp-content/uploads/2021/05/cap-incharge-x-copy-1.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2021/05/cap-incharge-x-copy-1.jpg 860w, https://siliconz.vn/wp-content/uploads/2021/05/cap-incharge-x-copy-1-157x300.jpg 157w, https://siliconz.vn/wp-content/uploads/2021/05/cap-incharge-x-copy-1-535x1024.jpg 535w, https://siliconz.vn/wp-content/uploads/2021/05/cap-incharge-x-copy-1-768x1471.jpg 768w, https://siliconz.vn/wp-content/uploads/2021/05/cap-incharge-x-copy-1-802x1536.jpg 802w, https://siliconz.vn/wp-content/uploads/2021/05/cap-incharge-x-copy-1-700x1341.jpg 700w\" width=\"800\" /></p>\r\n\r\n<h2><strong>Sợi c&aacute;p kiểu d&aacute;ng m&oacute;c kho&aacute; nhỏ gọn v&agrave; tốt nhất hiện nay</strong></h2>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 759px) 100vw, 759px\" src=\"https://siliconz.vn/wp-content/uploads/2021/05/Thong-tin-inCharge-X.png\" srcset=\"https://siliconz.vn/wp-content/uploads/2021/05/Thong-tin-inCharge-X.png 759w, https://siliconz.vn/wp-content/uploads/2021/05/Thong-tin-inCharge-X-86x300.png 86w, https://siliconz.vn/wp-content/uploads/2021/05/Thong-tin-inCharge-X-295x1024.png 295w, https://siliconz.vn/wp-content/uploads/2021/05/Thong-tin-inCharge-X-442x1536.png 442w, https://siliconz.vn/wp-content/uploads/2021/05/Thong-tin-inCharge-X-700x2432.png 700w\" width=\"800\" /></p>\r\n\r\n<h2><strong>Chia sẻ nguồn điện giữa c&aacute;c thiết bị</strong></h2>\r\n\r\n<p>Nếu chẳng may bạn kh&ocirc;ng t&igrave;m được bất kỳ nguồn sạc n&agrave;o? Với t&iacute;nh năng chia sẻ nguồn sạc th&ocirc;ng minh, bạn c&oacute; thể sử dụng smartphone, m&aacute;y t&iacute;nh bảng hay Laptop để l&agrave;m nguồn sạc thay thế củ sạc cho chiếc điện thoại của bạn. (T&iacute;nh năng n&agrave;y chỉ hoạt động với nguồn v&agrave;o l&agrave; cổng type-C).</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 860px) 100vw, 860px\" src=\"https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-siliconz-copy-2.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-siliconz-copy-2.jpg 860w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-siliconz-copy-2-182x300.jpg 182w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-siliconz-copy-2-620x1024.jpg 620w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-siliconz-copy-2-768x1268.jpg 768w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-siliconz-copy-2-700x1156.jpg 700w\" width=\"800\" /></p>\r\n\r\n<h2><strong>inCharge X Max &ndash; Th&ecirc;m lựa chọn d&acirc;y d&agrave;i tiện lợi</strong></h2>\r\n\r\n<p>inCharge X c&ograve;n đem đến tuỳ chọn d&acirc;y d&agrave;i 1.5m gi&uacute;p bạn thuận tiện hơn khi sử dụng để sạc Laptop hay ở những nơi xa nguồn điện một c&aacute;ch dễ d&agrave;ng nhất.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 860px) 100vw, 860px\" src=\"https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-1-1-copy-2.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-1-1-copy-2.jpg 860w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-1-1-copy-2-203x300.jpg 203w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-1-1-copy-2-693x1024.jpg 693w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-1-1-copy-2-768x1135.jpg 768w, https://siliconz.vn/wp-content/uploads/2021/05/incharge-x-1-1-copy-2-700x1035.jpg 700w\" width=\"800\" /></p>\r\n\r\n<h2><strong>Hỗ trợ sạc nhanh với c&ocirc;ng suất l&ecirc;n đến 100W</strong></h2>\r\n\r\n<p>Hỗ trợ chuẩn sạc PD l&ecirc;n đến 100W. Nghĩa l&agrave; bạn ho&agrave;n to&agrave;n c&oacute; thể sạc Macbook với sợi c&aacute;p n&agrave;y.</p>\r\n\r\n<p>Đ&acirc;y l&agrave; sợi c&aacute;p đa năng đầu ti&ecirc;n c&oacute; thể sạc được cho Laptop của bạn.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 860px) 100vw, 860px\" src=\"https://siliconz.vn/wp-content/uploads/2021/04/XU_5578-scaled.jpg\" srcset=\"https://siliconz.vn/wp-content/uploads/2021/04/XU_5578-scaled.jpg 2560w, https://siliconz.vn/wp-content/uploads/2021/04/XU_5578-300x200.jpg 300w, https://siliconz.vn/wp-content/uploads/2021/04/XU_5578-1024x683.jpg 1024w, https://siliconz.vn/wp-content/uploads/2021/04/XU_5578-768x512.jpg 768w, https://siliconz.vn/wp-content/uploads/2021/04/XU_5578-1536x1024.jpg 1536w, https://siliconz.vn/wp-content/uploads/2021/04/XU_5578-2048x1365.jpg 2048w, https://siliconz.vn/wp-content/uploads/2021/04/XU_5578-700x467.jpg 700w\" width=\"800\" /></p>', 600000, 550000, 19, 'Bộ sản phẩm', 'Incharge-X-C-p-6-In1-PD-100W-Truy-n-D-Li.jpg', 'PK', 'NO', 1, NULL, '2021-07-06 15:39:01', '2021-07-14 21:24:49', 1, '2021-07-06 15:39:12');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (17, 'Microsoft Surface Pro 3 Cũ', '<p><strong>VI XỬ L&Yacute;</strong>: Intel&reg; Core&trade; i5-1065G7</p>\r\n\r\n<p><strong>HỆ ĐIỀU H&Agrave;NH</strong>: Window 10</p>\r\n\r\n<p><strong>Bộ nhớ</strong>: SSD 128GB</p>\r\n\r\n<p><strong>RAM</strong>: 4GB</p>\r\n\r\n<p><strong>M&agrave;n h&igrave;nh</strong>: 12.3 inch</p>\r\n\r\n<p><strong>Khuyến mại đi k&egrave;m:&nbsp;</strong>T&uacute;i chống sốc trị gi&aacute; 350.000VNĐ, c&agrave;i đặt phần mềm trọn đời m&aacute;y.</p>\r\n\r\n<p><strong>Bảo h&agrave;nh:&nbsp;</strong>3 th&aacute;ng</p>', '<h4><strong>Th&ocirc;ng số kỹ thuật</strong></h4>\r\n\r\n<ul>\r\n	<li><strong>Hệ điều h&agrave;nh</strong>: Window 10</li>\r\n	<li><strong>CPU</strong>: Intel&reg; Core&trade; i5-1065G7</li>\r\n	<li><strong>Card đồ họa</strong>: Intel&reg; UHD Graphics</li>\r\n	<li><strong>Bộ nhớ</strong>: SSD 128GB</li>\r\n	<li><strong>Ram</strong>: 4GB</li>\r\n	<li><strong>M&agrave;n h&igrave;nh</strong>: 12.3 inch Pixel Sense, 2736 &times; 1824 (267 ppi), tỷ lệ 3:2, cảm ứng 10 điểm</li>\r\n	<li><strong>Camera trước</strong>: Camera trước 5.0MP, c&oacute; khả năng quay video 1080p full HD</li>\r\n	<li><strong>Camera sau</strong>: Camera sau 8.0MP tự động lấy n&eacute;t, c&oacute; khả năng quay video 1080p full HD</li>\r\n	<li><strong>Cổng kết nối</strong>: 1 USB-C&reg;, 1 USB-A, 1 jack tai nghe 3.5 mm,1 Surface Connect, 1 khe cắm thẻ nhớ MicroSDXC</li>\r\n	<li><strong>Trọng lượng</strong>: 0.790 kg</li>\r\n	<li><strong>K&iacute;ch thước</strong>: 308 mm x 223 mm x 14.5 mm</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3><strong>M&ocirc; tả sản phẩm Surface Pro 3 Core i5/ RAM 4GB/ SSD 128GB</strong></h3>\r\n\r\n<p>&nbsp; D&ugrave; t&iacute;nh từ l&uacute;c c&oacute; mặt tr&ecirc;n thị trường đến nay đ&atilde; xuất hiện nhiều mẫu m&aacute;y kh&aacute;c những Surface Pro 3 vẫn l&agrave; chiếc m&aacute;y khiến người d&ugrave;ng y&ecirc;u th&iacute;ch. Kh&ocirc;ng chỉ bởi mức gi&aacute; đ&atilde; hạ nhiệt m&agrave; những gi&aacute; trị sản phẩm đem lại vẫn c&ograve;n rất cạnh tranh. Điểm qua một số điều khiến chiếc m&aacute;y n&agrave;y trở th&agrave;nh một khoản đầu tư xứng đ&aacute;ng.&nbsp;</p>\r\n\r\n<h4><strong>Ngoại h&igrave;nh xuất sắc</strong></h4>\r\n\r\n<p>&nbsp; T&iacute;nh từ thời điểm ra mắt đến hiện tại kh&oacute; c&oacute; thể t&igrave;m được chiếc m&aacute;y n&agrave;o sở hữu thiết kế ri&ecirc;ng biệt như Surface Pro 3. Với một người y&ecirc;u th&iacute;ch c&ocirc;ng nghệ, Surface Pro 3 giống như một ng&ocirc;i sao, lu&ocirc;n tỏa s&aacute;ng giữa đ&aacute;m đ&ocirc;ng. C&ograve;n nếu kh&ocirc;ng phải người thường xuy&ecirc;n theo d&otilde;i c&ocirc;ng nghệ th&igrave; chỉ cần xuất hiện trong tầm mắt sẽ khiến mọi người phải liếc nh&igrave;n.&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Surface Pro 3\" sizes=\"(max-width: 400px) 100vw, 400px\" src=\"https://laptopdep.vn/wp-content/uploads/2021/06/Snapseed-2-1-1024x1024.jpg\" srcset=\"https://laptopdep.vn/wp-content/uploads/2021/06/Snapseed-2-1-1024x1024.jpg 1024w, https://laptopdep.vn/wp-content/uploads/2021/06/Snapseed-2-1-300x300.jpg 300w, https://laptopdep.vn/wp-content/uploads/2021/06/Snapseed-2-1-150x150.jpg 150w, https://laptopdep.vn/wp-content/uploads/2021/06/Snapseed-2-1-768x768.jpg 768w, https://laptopdep.vn/wp-content/uploads/2021/06/Snapseed-2-1-1536x1536.jpg 1536w, https://laptopdep.vn/wp-content/uploads/2021/06/Snapseed-2-1-2048x2048.jpg 2048w, https://laptopdep.vn/wp-content/uploads/2021/06/Snapseed-2-1-270x270.jpg 270w, https://laptopdep.vn/wp-content/uploads/2021/06/Snapseed-2-1-600x600.jpg 600w, https://laptopdep.vn/wp-content/uploads/2021/06/Snapseed-2-1-100x100.jpg 100w\" width=\"400\" /></p>\r\n\r\n<p>&nbsp; Surface 3 l&agrave; những g&igrave; đặc trưng của d&ograve;ng Surface cao cấp nh&agrave; Microsoft. Kh&ocirc;ng kh&oacute; hiểu khi h&atilde;ng n&agrave;y đ&atilde; đầu tư rất nhiều cho ngoại h&igrave;nh chiếc m&aacute;y. Chất liệu cấu th&agrave;nh l&agrave; hợp kim Nh&ocirc;m- Magie. Tăng t&iacute;nh chắc chắn cho chiếc m&aacute;y si&ecirc;u mỏng si&ecirc;u nhẹ. Cảm gi&aacute;c sờ v&agrave;o m&aacute;t lạnh, cao cấp.&nbsp;</p>\r\n\r\n<h4><strong>M&agrave;n h&igrave;nh hướng đến sự ch&acirc;n thực</strong></h4>\r\n\r\n<p>&nbsp; Surface Pro 3 được trang bị m&agrave;n h&igrave;nh 12.5 inch. Độ ph&acirc;n giải 2160 x 1440 px. H&igrave;nh ảnh căng đều với tỉ lệ 3:2. Chưa c&oacute; bất cứ lời ph&agrave;n n&agrave;n n&agrave;o về chất lượng h&igrave;nh ảnh của Surface Pro 3 v&igrave; n&oacute; đ&atilde; qu&aacute; đẹp rồi. H&igrave;nh ảnh hiển thị r&otilde; n&eacute;t, t&aacute;i tạo m&agrave;u sắc ở mức tốt.&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Surface Pro 3\" sizes=\"(max-width: 1044px) 100vw, 1044px\" src=\"https://laptopdep.vn/wp-content/uploads/2021/06/screenshot_1624693535-1.png\" srcset=\"https://laptopdep.vn/wp-content/uploads/2021/06/screenshot_1624693535-1.png 1044w, https://laptopdep.vn/wp-content/uploads/2021/06/screenshot_1624693535-1-300x197.png 300w, https://laptopdep.vn/wp-content/uploads/2021/06/screenshot_1624693535-1-1024x673.png 1024w, https://laptopdep.vn/wp-content/uploads/2021/06/screenshot_1624693535-1-150x99.png 150w, https://laptopdep.vn/wp-content/uploads/2021/06/screenshot_1624693535-1-768x505.png 768w, https://laptopdep.vn/wp-content/uploads/2021/06/screenshot_1624693535-1-600x394.png 600w\" width=\"100%\" /></p>\r\n\r\n<p>&nbsp; M&agrave;n h&igrave;nh cảm ứng đa điểm cực nhạy với c&aacute;c thao t&aacute;c. Tuy nhi&ecirc;n vẫn khiến người d&ugrave;ng cảm thấy việc chạm tr&ecirc;n m&agrave;n h&igrave;nh kh&ocirc;ng bị qu&aacute; ảo.&nbsp;</p>\r\n\r\n<h4><strong>Surface Pro 3 phi&ecirc;n bản Core i5, Ram 4Gb chiếc m&aacute;y d&agrave;nh cho c&ocirc;ng việc hơn giải tr&iacute;</strong></h4>\r\n\r\n<p>&nbsp; Microsoft Surface Pro 3 vi xử l&yacute; Core i5, Ram 8Gb c&oacute; thể đảm nhiệm nhiều mục đ&iacute;ch kh&aacute;c nhau nhưng tr&ecirc;n hết vẫn l&agrave; chiếc m&aacute;y d&agrave;nh cho c&ocirc;ng việc&nbsp;</p>\r\n\r\n<p>&nbsp; Hệ điều h&agrave;nh Windows 10. Khi bạn sở hữu một chiếc Surface Pro 3 th&igrave; giống như sở hữu 2 thiết bị. Hiệu năng tương đương với một chiếc laptop tầm trung. C&oacute; thể xử l&yacute; rất nhiều t&aacute;c vụ văn ph&ograve;ng kh&aacute;c nhau.</p>\r\n\r\n<h4><strong>Tập chung v&agrave;o t&iacute;nh tiện lợi</strong></h4>\r\n\r\n<p>&nbsp; Bạn chỉ cần một mua một sản phẩm đ&atilde; sở hữu t&iacute;nh năng của 2 sản phẩm c&ugrave;ng l&uacute;c. Surface Pro 3 c&oacute; hiệu năng kh&ocirc;ng thua k&eacute;m một chiếc laptop tầm trung. M&aacute;y cũng c&oacute; một b&agrave;n ph&iacute;m hỗ trợ cho việc soạn văn bản. Khi kh&ocirc;ng muốn d&ugrave;ng nữa c&oacute; thể th&aacute;o rời v&agrave; cất v&agrave;o cặp.</p>\r\n\r\n<p>&nbsp; Bạn c&oacute; thể mở rộng hoạt động l&ecirc;n m&agrave;n h&igrave;nh cảm ứng, ngo&agrave;i việc nhanh ch&oacute;ng thao t&aacute;c trực tiếp bằng tay như một chiếc điện thoại th&ocirc;ng minh, Microsoft c&ograve;n cho Surface Pro 3 một c&acirc;y b&uacute;t m&agrave; bạn sẽ rất y&ecirc;u th&iacute;ch.</p>\r\n\r\n<p>&nbsp; Những người đ&atilde; từng sử dụng đ&aacute;nh gi&aacute; cao c&acirc;y b&uacute;t n&agrave;y. N&oacute; đem lại cảm gi&aacute;c như khi bạn d&ugrave;ng một c&acirc;y b&uacute;t thật tr&ecirc;n nền giấy. C&aacute;c thao t&aacute;c hay c&aacute;c n&eacute;t đều chuẩn x&aacute;c đến từng milimet.&nbsp;</p>\r\n\r\n<h4><strong>Thời lượng pin</strong></h4>\r\n\r\n<p>&nbsp; Sử dụng li&ecirc;n tục th&igrave; thời lượng pin l&agrave; 3 giờ 57 ph&uacute;t. Ho&agrave;n to&agrave;n đủ với mục đ&iacute;ch c&ocirc;ng việc v&agrave; học tập&nbsp;</p>\r\n\r\n<p>&nbsp; Sở hữu một chiếc Laptop Surface Pro 3, bạn sẽ đạt được mong muốn c&oacute; một chiếc m&aacute;y t&iacute;nh bảng c&oacute; thể thay thế ho&agrave;n to&agrave;n laptop, mang t&iacute;nh di động cao.</p>', 8000000, 7500000, 4, 'Bộ sản phẩm', 'Surface_Pro-3.jpg', 'LAP', 'SUR', 1, NULL, '2021-07-08 16:54:16', '2021-07-19 18:33:53', 1, '2021-07-08 16:57:20');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (18, 'Màn hình Dell UltraSharp U2721DE', '<p>K&iacute;ch thước m&agrave;n h&igrave;nh: 27Inch IPS</p>\r\n\r\n<p>Độ ph&acirc;n giải: 2K (2560x1440)</p>\r\n\r\n<p>Cổng giao tiếp:</p>\r\n\r\n<ul>\r\n	<li>- 1 x DP 1.4 (HDCP 1.4)</li>\r\n	<li>- 1 x HDMI1.4 (HDCP 1.4)</li>\r\n	<li>- x USB Type-C (Alternate mode with DisplayPort 1.4</li>\r\n	<li>- USB 3.1 upstream port</li>\r\n	<li>- Power Delivery PD up to 65 W)</li>\r\n	<li>- 1 x DP (Out) with MST (HDCP 1.4 )</li>\r\n	<li>- 2 x USB 3.0 downstream port</li>\r\n</ul>', '<p>&nbsp; Màn hình Dell UltraSharp U2721DE sở hữu chất lượng h&igrave;nh ảnh v&ocirc; c&ugrave;ng xuất sắc, đ&acirc;y chắc chắn l&agrave; lựa chọn ho&agrave;n hảo cho người d&ugrave;ng thiết kế đồ họa chuy&ecirc;n nghiệp cần m&agrave;n h&igrave;nh đẹp, hiển thị r&otilde; n&eacute;t, l&ecirc;n m&agrave;u chuẩn.</p>\r\n\r\n<h3>Tối ưu h&oacute;a kh&ocirc;ng gian l&agrave;m việc</h3>\r\n\r\n<p><br />\r\n&nbsp; Dell UltraSharp U2721DE tối ưu h&oacute;a kh&ocirc;ng gian l&agrave;m việc của bạn với m&agrave;n h&igrave;nh Dell thời trang c&oacute; cấu h&igrave;nh bảng mỏng, ch&acirc;n đế nhỏ gọn v&agrave; khe quản l&yacute; c&aacute;p gi&uacute;p bạn dễ d&agrave;ng lắp đặt m&agrave;n tr&ecirc;n b&agrave;n l&agrave;m việc.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Màn hình Dell U2721DE mặt trước\" src=\"https://hanoicomputercdn.com/media/product/54445_dell_u2721de__2_.png\" width=\"800\" /></p>\r\n\r\n<h3>H&igrave;nh ảnh sắc n&eacute;t, m&agrave;u sắc hiển thị ch&iacute;nh x&aacute;c</h3>\r\n\r\n<p><br />\r\n&nbsp; Thiết kế m&agrave;n h&igrave;nh m&aacute;y t&iacute;nh UltraSharp U2721DE hướng đến người d&ugrave;ng thiết kế đồ họa chuy&ecirc;n nghiệp v&agrave; được Dell hiệu chỉnh sẵn độ ch&iacute;nh x&aacute;c m&agrave;u sắc trước khi xuất xưởng.</p>\r\n\r\n<p>&nbsp; Về mặt c&ocirc;ng nghệ, mẫu UltraSharp U2721DE được trang bị tấm nền IPS, độ ph&acirc;n giải 2K QHD (2.560 x 1.440 pixel) c&ugrave;ng khả năng t&aacute;i tạo đến 99% dải m&agrave;u theo ti&ecirc;u chuẩn sRGB. Mang tới h&igrave;nh ảnh sắc n&eacute;t, ch&acirc;n thực v&agrave; sống động c&ugrave;ng m&agrave;u sắc hiển thị ch&iacute;nh x&aacute;c.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Màn hình Dell U2721DE chính diện\" src=\"https://hanoicomputercdn.com/media/product/54445_dell_u2721de__3_.png\" width=\"800\" /></p>\r\n\r\n<h3>Đảm bảo chất lượng hiển thị ở mọi g&oacute;c nh&igrave;n</h3>\r\n\r\n<p>&nbsp; C&ocirc;ng nghệ InfinityEdge tr&ecirc;n m&agrave;n h&igrave;nh 27 inch với viền si&ecirc;u mỏng ở cả 4 cạnh, mang lại sự tinh xảo hơn trong thiết kế so với thế hệ trước.</p>\r\n\r\n<p>&nbsp; Dell UltraSharp U2721DE sở hữu độ tương phản 1000: 1, h&igrave;nh ảnh tr&ecirc;n m&agrave;n h&igrave;nh Dell lu&ocirc;n c&oacute; m&agrave;u sắc rực rỡ. Tất nhi&ecirc;n điểm đặc trưng của d&ograve;ng UltraSharp ch&iacute;nh l&agrave; ch&acirc;n đế tiện lợi c&oacute; thể xoay m&agrave;n h&igrave;nh một c&aacute;ch dễ d&agrave;ng. Dell U2721DE cho thấy sự thuận tiện trong việc bố tr&iacute; m&agrave;n h&igrave;nh nhưng vẫn đảm bảo chất lượng hiển thị ở mọi g&oacute;c nh&igrave;n.</p>\r\n\r\n<p>Màn hình Dell UltraSharp U2721DE 27 inch 2K QHD IPS</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Màn hình Dell U2721DE mặt sau\" src=\"https://hanoicomputercdn.com/media/product/54445_dell_u2721de__1_.png\" width=\"800\" /></p>\r\n\r\n<h3>Cổng kết nối đa dạng</h3>\r\n\r\n<p><br />\r\n&nbsp; C&aacute;c cổng kết nối tr&ecirc;n Dell UltraSharp U2721DE cũng v&ocirc; c&ugrave;ng đầy đủ khi sở hữu cổng HDMI, cổng USB 3.0, RJ45, DP, Analog 2.0 audio line out,... Tuy nhi&ecirc;n việc c&oacute; th&ecirc;m cổng USB C hỗ trợ sạc nhanh PD 65W gi&uacute;p m&agrave;n h&igrave;nh n&agrave;y trở n&ecirc;n ph&ugrave; hợp hơn nữa cho c&aacute;c nh&agrave; thiết kế đồ họa khi thường sử dụng laptop v&agrave; cần một sản phẩm m&agrave;n h&igrave;nh gọn g&agrave;ng truyền dữ liệu nhanh cũng như c&oacute; thể sạc cho laptop chỉ với 1 d&acirc;y duy nhất.</p>', 10550000, NULL, 9, 'Bộ sản phẩm', 'dell_u2721de_.png', 'MH', 'DELL', 1, NULL, '2021-07-08 20:35:39', '2021-07-19 20:11:40', 1, '2021-07-08 20:36:46');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (19, 'Máy đọc sách Kindle Paperwhite 4 Gen 10', '<h4>Th&ocirc;ng số kỹ thuật<br />\r\nK&iacute;ch thước m&agrave;n h&igrave;nh: 6.0 inches<br />\r\nBộ nhớ trong: 8 GB<br />\r\nPin: 1500maH<br />\r\nT&iacute;nh năng m&agrave;n h&igrave;nh: Mật độ điểm ảnh: 300 ppi<br />\r\nC&oacute; chế độ Darkmode khi đọc s&aacute;ch<br />\r\nK&iacute;ch thước: 167 x 116 x 8.18 mm<br />\r\nTrọng lượng: 182g<br />\r\nBluetooth: C&oacute; (sử dụng để nghe s&aacute;ch n&oacute;i Audible)</h4>', '<h2><strong>Máy đọc sách Kindle PaperWhite Gen4 10th - Đọc sách và nghe sách ti&ecirc;̣n lợi</strong></h2>\r\n\r\n<p>Bạn là m&ocirc;̣t người có sở thích đọc sách và mong mu&ocirc;́n được đọc những quy&ecirc;̉n sách mình y&ecirc;u thích trong thời gian rảnh r&ocirc;̃i? Giờ đ&acirc;y bạn kh&ocirc;ng phải vác theo nhi&ecirc;̀u quy&ecirc;̉n sách nặng n&ecirc;̀ nữa, khi đã có trong tay&nbsp;<strong><a href=\"https://cellphones.com.vn/tablet/may-doc-sach/kindle.html\" target=\"_self\" title=\"Máy đọc sách Kindle chính hãng\">máy đọc sách Kindle</a>&nbsp;PaperWhite Gen 4 10th</strong>&nbsp;bản 8 GB&nbsp;hi&ecirc;̣n đại và nhỏ gọn.</p>\r\n\r\n<h3><strong>Kích thước nhỏ gọn vừa tay c&acirc;̀m, màn hình phẳng&nbsp;</strong><strong>6 inch</strong></h3>\r\n\r\n<p>Máy đọc sách Kindle PaperWhite 4 Gen 10 r&acirc;́t thích hợp cho nhu c&acirc;̀u đọc sách ti&ecirc;̣n lợi mà kh&ocirc;ng c&acirc;̀n phải mang theo quá nhi&ecirc;̀u quy&ecirc;̉n sách g&acirc;y c&ocirc;̀ng k&ecirc;̀nh. Chi&ecirc;́c máy đọc sách này có hình dáng gi&ocirc;́ng m&ocirc;̣t chi&ecirc;́c máy tính bảng, nhưng kích cỡ nhỏ gọn vừa tay c&acirc;̀m n&ecirc;n bạn d&ecirc;̃ dàng mang theo b&ecirc;n mình b&acirc;́t kỳ lúc nào.</p>\r\n\r\n<p>M&aacute;y với b&ocirc;́n tùy chọn màu sắc bao g&ocirc;̀m Đen, Xanh, Xám Xanh và Tím sẽ giúp bạn d&ecirc;̃ chọn ra chi&ecirc;́c máy đọc sách phù hợp với cá tính bản th&acirc;n.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Kích thước nhỏ gọn vừa tay cầm, màn hình phẳng 6 inch\" src=\"https://cdn.cellphones.com.vn/media/wysiwyg/accessories/may-doc-sach-kindle-paperwhite-4-gen-10-8gb-den-1.jpg\" /></p>\r\n\r\n<p>Máy đọc sách Kindle PaperWhite 4 Gen 10 sử dụng loại màn hình E-ink kích thước 6 inch với đ&ocirc;̣ ph&acirc;n giải 300 PPI, hi&ecirc;̉n thị màu mực rõ nét hơn và đẹp như trang sách th&acirc;̣t. Ngoài ra chi&ecirc;́c máy đọc sách này h&ocirc;̃ trợ đọc sách trong ch&ecirc;́ đ&ocirc;̣ t&ocirc;́i (dark mode) cho những ai đã quen với giao di&ecirc;̣n t&ocirc;́i tr&ecirc;n thi&ecirc;́t bị c&ocirc;ng ngh&ecirc;̣.</p>\r\n\r\n<h3><strong>Dung lượng chứa sách 8GB,&nbsp;pin 1500 mah,</strong><strong>&nbsp;h&ocirc;̃ trợ nghe sách qua Bluetooth</strong></h3>\r\n\r\n<p>Máy đọc sách Kindle PaperWhite 4 Gen 10 có dung lượng chứa sách là 8 GB giúp bạn thỏa thích lưu trữ những quy&ecirc;̉n sách đi&ecirc;̣n tử bạn y&ecirc;u thích. Dung lượng pin 1500mAh sẽ đảm bảo bạn có th&ecirc;̉ đọc sách tr&ecirc;n Kindle PaperWhite 4 Gen 10 l&acirc;u dài, m&ocirc;̃i ngày đọc 30 phút kh&ocirc;ng WiFi sẽ kéo dài t&acirc;̣n 6-8 tu&acirc;̀n.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Dung lượng chứa sách 8GB, pin 1500 mah, hỗ trợ nghe sách qua Bluetooth\" src=\"https://cdn.cellphones.com.vn/media/wysiwyg/accessories/may-doc-sach-kindle-paperwhite-4-gen-10-8gb-den-2.jpg\" /></p>\r\n\r\n<p>Máy đọc sách Kindle PaperWhite 4 Gen 10 kh&ocirc;ng chỉ h&ocirc;̃ trợ k&ecirc;́t n&ocirc;́i WiFi, mà còn cả Bluetooth giúp bạn nghe sách audible thỏa thích. Đặc bi&ecirc;̣t, Kindle PaperWhite 4 Gen 10 còn có khả năng ch&ocirc;́ng nước tr&ecirc;n chi&ecirc;́c máy, n&ecirc;n bạn có th&ecirc;̉ y&ecirc;n t&acirc;m và mang máy đọc sách theo b&ecirc;n mình những lúc c&acirc;̀n thi&ecirc;́t.</p>\r\n\r\n<h2><strong>Sở hữu máy đọc sách Kindle PaperWhite 4 Gen 10 8GB chính hãng tại h&ecirc;̣ th&ocirc;́ng CellphoneS</strong></h2>\r\n\r\n<p>Với những tín đ&ocirc;̀ đọc sách, máy đọc sách Kindle PaperWhite 4 Gen 10 8GB là sản ph&acirc;̉m kh&ocirc;ng th&ecirc;̉ thi&ecirc;́u nhằm giúp quá trình đọc sách trở n&ecirc;n thú vị hơn. Và hi&ecirc;̣n nay bạn đã có th&ecirc;̉ đ&ecirc;́n cửa hàng CellphoneS g&acirc;̀n nh&acirc;́t và thử ngay tr&ecirc;n tay sản ph&acirc;̉m máy đọc sách Kindle PaperWhite 4 Gen 10 8GB.</p>', 3000000, NULL, 5, 'Bộ sản phẩm', 'may-doc-sach-kindle-paperwhite-4-gen-10-2019_.jpg', 'READING', 'KINDLE', 1, NULL, '2021-07-11 07:57:27', '2021-07-11 07:57:49', 1, '2021-07-11 07:57:49');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (20, 'Chuột không dây Microsoft Arc Mouse Bluetooth (màu đen)', '<h3>Th&ocirc;ng số sản phẩm</h3>\r\n\r\n<ul>\r\n	<li>Chuột kh&ocirc;ng d&acirc;y Microsoft Arc Mouse Bluetooth (m&agrave;u đen)</li>\r\n	<li>Mỏng nhẹ, nhỏ gọn</li>\r\n	<li>N&uacute;t cuộn tr&aacute;i phải cảm ứng cho trải nghiệm tuyệt vời.</li>\r\n	<li>Kết nối Bluetooth tiện lợi</li>\r\n	<li>T&iacute;nh năng SwiftPair cho kết nối nhanh ch&oacute;ng với</li>\r\n	<li>Windows</li>\r\n	<li>C&ocirc;ng nghệ Bluetrack cho ph&eacute;p lướt tr&ecirc;n mọi bề mặt</li>\r\n</ul>', '<h3>Thiết kế hiện đại</h3>\r\n\r\n<p>Chuột kh&ocirc;ng d&acirc;y Microsoft Arc Mouse được thiết kế với chất liệu cao cấp, k&iacute;ch thước nhỏ gọn cho người d&ugrave;ng cảm gi&aacute;c mỏng nhẹ, c&oacute; thể mang đi mọi l&uacute;c mọi nơi m&agrave; kh&ocirc;ng lo về trọng lượng thay v&igrave; mang theo một con chuột d&acirc;y truyền thống cồng kềnh. Bạn chỉ cần duỗi phẳng chuột l&agrave; c&oacute; thể cho v&agrave;o t&uacute;i x&aacute;ch, balo hay thậm ch&iacute; l&agrave; t&uacute;i quần &aacute;o để mang theo b&ecirc;n m&igrave;nh rồi.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Chuột không dây Microsoft Arc Mouse Bluetooth (màu đen) (ELG-00005) có thiết kế hiện đại\" height=\"349\" src=\"https://hanoicomputercdn.com/media/lib/55092_thiet-ke-cua-chuot-khong-day-microsoft-arc-mouse-bluetooth-mau-den-elg-00005.png\" width=\"1036\" /></p>\r\n\r\n<h3>Tương t&aacute;c trực quan</h3>\r\n\r\n<p>Chuột kh&ocirc;ng d&acirc;y Microsoft Arc Mouse cho ph&eacute;p bạn cuộn theo cả chiều dọc v&agrave; chiều ngang thoải m&aacute;i m&agrave; kh&ocirc;ng lo hư hại sản phẩm. N&uacute;t cuộn tr&aacute;i cảm ứng cho trải nghiệm tuyệt vời. Tuy chỉ l&agrave; một con chuột kh&ocirc;ng d&acirc;y nhỏ gọn nhưng Microsoft đ&atilde; cho ch&uacute;ng ta thấy c&ocirc;ng nghệ của họ ti&ecirc;n tiến đến nhường n&agrave;o. Bật tắt chuột rất đơn giản, chỉ cần gập cong chuột Arc của Microsoft để bật nguồn v&agrave; duỗi thẳng chuột để tắt nguồn.&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Chuột không dây Microsoft Arc Mouse Bluetooth (màu đen) (ELG-00005) có thể tương tác dễ dàng bằng cảm ứng\" src=\"https://hanoicomputercdn.com/media/lib/55092_tuong-tac-chuot-khong-day-microsoft-arc-mouse-bluetooth-mau-den-elg-00005.png\" width=\"100%\" /></p>\r\n\r\n<h3>T&iacute;nh năng SwiftPair kết nối nhanh ch&oacute;ng</h3>\r\n\r\n<p>Chuột kh&ocirc;ng d&acirc;y Microsoft Arc Mouse 2020&nbsp; được trang bị kết nối kh&ocirc;ng d&acirc;y qua Bluetooth. Ngo&agrave;i ra bạn c&oacute; thể kết nối nhanh ch&oacute;ng với PC chạy Windows bằng t&iacute;nh năng SwiftPair. Sản phẩm được t&iacute;ch hợp &ocirc;ng nghệ Bluetrack, gi&uacute;p bạn di chuyển &ecirc;m &aacute;i, nhẹ nh&agrave;ng, lướt tr&ecirc;n mọi mặt phẳng m&agrave; kh&ocirc;ng bị cản trở độ nhạy. Phạm vi kết nối kh&ocirc;ng d&acirc;y 10 m&eacute;t trong khu vực mở v&agrave; tối đa 5 m&eacute;t trong m&ocirc;i trường văn ph&ograve;ng điển h&igrave;nh.</p>\r\n\r\n<p>&nbsp;</p>', 1850000, 1700000, 15, 'Bộ sản phẩm', '55092_chuot_khong_day_microsoft_arc_mouse_bluetooth_mau_den_elg_00005_0000_1.jpg', 'MOUSE', 'MICROSOFT', 1, NULL, '2021-07-15 09:29:24', '2021-07-15 15:40:08', 1, '2021-07-15 10:41:54');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (21, 'Chuột không dây bluetooth Microsoft Modern Mouse (Đen)', '<h3>Th&ocirc;ng số sản phẩm</h3>\r\n\r\n<ul>\r\n	<li>Chuột kh&ocirc;ng d&acirc;y Microsoft Modern Mobile</li>\r\n	<li>Thiết kế mỏng nhẹ, gọn g&agrave;ng, dễ d&agrave;ng mang đi mang lại</li>\r\n	<li>Kết nối Bluetooth tiện lợi</li>\r\n	<li>C&ocirc;ng nghệ BlueTrack gi&uacute;p chuột hoạt động tốt tr&ecirc;n nhiều loại bề mặt phẳng</li>\r\n</ul>', '<h3>Thiết kế thanh lịch</h3>\r\n\r\n<p>Chuột kh&ocirc;ng d&acirc;y Bluetooth Microsoft Modern Mobile nổi bật với thiết kế thời trang, th&iacute;ch hợp với m&aacute;y t&iacute;nh cao cấp mỏng nhẹ. Chuột t&iacute;ch hợp c&ocirc;ng nghệ BlueTrack sẽ gi&uacute;p chuột c&oacute; thể hoạt động tr&ecirc;n nhiều bề mặt kh&aacute;c nhau như: b&agrave;n ăn ngo&agrave;i trời, s&agrave;n ph&ograve;ng kh&aacute;ch, chỗ g&aacute;c tay tr&ecirc;n ghế tựa hay thậm ch&iacute; tr&ecirc;n ống quần của bạn. Nhờ đ&oacute;, Chuột kh&ocirc;ng d&acirc;y Bluetooth Microsoft Modern Mobile v&ocirc; c&ugrave;ng l&yacute; tưởng khi bạn mang chuột theo b&ecirc;n m&igrave;nh để sử dụng.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Chuột không dây Microsoft Modern Mobile (KTF-00005) có thiết kế thanh lịch\" src=\"https://hanoicomputercdn.com/media/lib/15-04-2021/thiet-ke-cua-chuot-khong-day-microsoft-modern-mobile-ktf-00005.jpg\" width=\"800\" /></p>\r\n\r\n<h3>C&ocirc;ng nghệ kh&ocirc;ng d&acirc;y 2.4GHz ti&ecirc;n tiến</h3>\r\n\r\n<p>Chuột kh&ocirc;ng d&acirc;y Bluetooth Microsoft Modern Mobile được trang bị c&ocirc;ng nghệ kết nối kh&ocirc;ng d&acirc;y ti&ecirc;n tiến 2.4GHz c&oacute; độ tin cậy cao. C&ocirc;ng nghệ n&agrave;y đảm bảo kết nối li&ecirc;n tục giữa chuột v&agrave; m&aacute;y t&iacute;nh, cho ph&eacute;p dữ liệu được truyền tải ch&iacute;nh x&aacute;c, kh&ocirc;ng bị gi&aacute;n đoạn v&agrave; nhanh hơn 60% so với c&ocirc;ng nghệ cũ trước đ&acirc;y. C&ocirc;ng nghệ kh&ocirc;ng d&acirc;y gi&uacute;p người sử dụng thoải m&aacute;i trong việc di chuyển cũng như hỗ trợ c&aacute;c chức năng giảng dạy, học tập v&agrave; l&agrave;m việc.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Chuột không dây Microsoft Modern Mobile (KTF-00005) sử dụng công nghệ không dây tiên tiến\" src=\"https://hanoicomputercdn.com/media/lib/15-04-2021/cong-nghe-cua-chuot-khong-day-microsoft-modern-mobile-ktf-00005.jpg\" width=\"800\" /></p>\r\n\r\n<h3>Một cảm gi&aacute;c kh&aacute;c biệt khi điều khiển d&ograve;ng chuột mới của Microsoft&nbsp;</h3>\r\n\r\n<p>Chuột kh&ocirc;ng d&acirc;y Bluetooth Microsoft Modern Mobile hỗ trợ điều khiển một c&aacute;ch ch&iacute;nh x&aacute;c c&aacute;c đối tượng tr&ecirc;n m&agrave;n h&igrave;nh bởi trọng lượng nhẹ v&agrave; ổn định của n&oacute;.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Chuột không dây Microsoft Modern Mobile (KTF-00005) cho cảm giác sử dụng khác biệt\" src=\"https://hanoicomputercdn.com/media/lib/15-04-2021/hieu-nang-cua-chuot-khong-day-microsoft-modern-mobile-ktf-00005.jpg\" width=\"800\" /></p>', 690000, NULL, 18, 'Bộ sản phẩm', 'chuot-khong-day-bluetooth-microsoft-modern-mouse-den.png', 'MOUSE', 'MICROSOFT', 1, NULL, '2021-07-15 09:42:43', '2021-07-15 10:56:31', 1, '2021-07-15 10:41:36');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (22, 'Chuột Microsoft Bluetooth Ergonomic (Xám trắng)', '<ul>\r\n	<li>Tần số kh&ocirc;ng d&acirc;y &nbsp;Dải tần 2,4 GHz</li>\r\n	<li>Phạm vi kết nối: 10 m trong khu vực mở, 5 m trong m&ocirc;i trường văn ph&ograve;ng</li>\r\n	<li>Tương th&iacute;ch: &nbsp;Windows 10/8.1, Hỗ trợ Bluetooth 4.0 trở l&ecirc;n</li>\r\n	<li>Thời lượng pin l&acirc;u</li>\r\n	<li>Kết nối tối đa với 3 thiết bị</li>\r\n	<li>Con lăn gia c&ocirc;ng bằng nh&ocirc;m, đế teflon v&agrave; cảm biến theo d&otilde;i ch&iacute;nh x&aacute;c</li>\r\n	<li>C&oacute; phần để đặt ng&oacute;n c&aacute;i, mềm, dễ nắm</li>\r\n</ul>', '<p><a href=\"http://127.0.0.1:8000/danhmuc/sanpham/MOUSE\">Mouse</a> <a href=\"http://127.0.0.1:8000/thuonghieu/sanpham/MICROSOFT\">Microsoft</a>&nbsp;Bluetooth Ergonomic 222-00028 (x&aacute;m trắng) với thiết kế c&ocirc;ng th&aacute;i học hỗ trợ đặt b&agrave;n tay ở vị tr&iacute; trung lập. C&oacute; phần để đặt ng&oacute;n c&aacute;i, mềm, dễ nắm, gi&uacute;p tăng th&ecirc;m sự thoải m&aacute;i.&nbsp;Lớp bề mặt kh&ocirc;ng c&oacute; mối nối, c&oacute; nhiều m&agrave;u sắc đa dạng.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.tnc.com.vn/uploads/product/hien122020/thumbs/570x470_Microsoft-Bluetooth-Ergonomi-222-00028-1.jpg\" rel=\"gallery\"><img alt=\"\" src=\"https://www.tnc.com.vn/uploads/product/hien122020/thumbs/570x470_Microsoft-Bluetooth-Ergonomi-222-00028-1.jpg\" /></a></p>\r\n\r\n<p>Con lăn gia c&ocirc;ng bằng nh&ocirc;m, đế teflon v&agrave; cảm biến theo d&otilde;i ch&iacute;nh x&aacute;c gi&uacute;p dễ d&agrave;ng di chuyển tr&ecirc;n nhiều bề mặt.&nbsp;<a href=\"http://127.0.0.1:8000/danhmuc/sanpham/MOUSE\">Mouse</a> <a href=\"http://127.0.0.1:8000/thuonghieu/sanpham/MICROSOFT\">Microsoft</a>&nbsp;Bluetooth Ergonomic 222-00028 (x&aacute;m trắng) c&oacute; thể d&ugrave;ng được trong 15 th&aacute;ng sau mỗi lần sạc.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://www.tnc.com.vn/uploads/product/gallery/thumbs/570x470_Microsoft-Bluetooth-Ergonomic-222-00028.jpg\" rel=\"gallery\"><img alt=\"\" src=\"https://www.tnc.com.vn/uploads/product/gallery/thumbs/570x470_Microsoft-Bluetooth-Ergonomic-222-00028.jpg\" /></a></p>', 1850000, 1590000, 15, 'Bộ sản phẩm', 'Microsoft Bluetooth Ergonomic Wireless Mouse.jpg', 'MOUSE', 'MICROSOFT', 1, NULL, '2021-07-15 09:56:46', '2021-07-21 17:36:59', 0, NULL);
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (23, 'Chuột Microsoft Bluetooth Ergonomic (Đen)', '<ul>\r\n	<li>Tần số kh&ocirc;ng d&acirc;y &nbsp;Dải tần 2,4 GHz</li>\r\n	<li>Phạm vi kết nối: 10 m trong khu vực mở, 5 m trong m&ocirc;i trường văn ph&ograve;ng</li>\r\n	<li>Tương th&iacute;ch: &nbsp;Windows 10/8.1, Hỗ trợ Bluetooth 4.0 trở l&ecirc;n</li>\r\n	<li>Thời lượng pin l&acirc;u</li>\r\n	<li>Kết nối tối đa với 3 thiết bị</li>\r\n	<li>Con lăn gia c&ocirc;ng bằng nh&ocirc;m, đế teflon v&agrave; cảm biến theo d&otilde;i ch&iacute;nh x&aacute;c</li>\r\n	<li>C&oacute; phần để đặt ng&oacute;n c&aacute;i, mềm, dễ nắm</li>\r\n</ul>', '<h3>Chuột kh&ocirc;ng d&acirc;y Microsoft Bluetooth Enogormic c&oacute; được k&iacute;ch thước nhỏ gọn v&agrave; tiện lợi, kết hợp c&ugrave;ng dải tần 2.4GHz gi&uacute;p chuột c&oacute; thể dễ d&agrave;ng kết nối được với c&aacute;c thiết bị điện tử th&ocirc;ng minh. Đồng thời, với c&ocirc;ng nghệ kết nối tối đa 3 thiết bị đỉnh cao. Đ&acirc;y ch&iacute;nh l&agrave; sản phẩm m&agrave; ai cũng mong muốn được sở hữu.</h3>\r\n\r\n<h4><strong>Thiết kế v&ocirc; c&ugrave;ng đơn giản, sở hữu tần số kh&ocirc;ng d&acirc;y với dải tần cao tận 2.4GHz</strong></h4>\r\n\r\n<p>Chuột kh&ocirc;ng d&acirc;y Microsoft Bluetooth Enogormic c&oacute; được thiết kế v&ocirc; c&ugrave;ng đơn giản với tone đen huyền b&iacute;, đồng thời c&ograve;n sở hữu th&ecirc;m được k&iacute;ch thước nhỏ gọn khi nặng tầm 91g v&agrave; chỉ 118.2 x 76.3 x 42.4 mm, v&ocirc; c&ugrave;ng dễ d&agrave;ng v&agrave; thuận tiện để bạn đem đến mọi nơi nhằm mục đ&iacute;ch l&agrave;m việc v&agrave; học tập.</p>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://storage.googleapis.com/teko-gae.appspot.com/media/image/2021/6/24/20210624_5157f10e-f8ef-436a-a450-721eccb08836.jpg\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Kh&ocirc;ng những thế, chuột kh&ocirc;ng d&acirc;y c&ograve;n sở hữu được dải tần cao tận 2.4GHz, gi&uacute;p chuột c&oacute; thể dễ d&agrave;ng kết nối được với c&aacute;c loại thiết bị điện tử th&ocirc;ng minh, hạn chế t&igrave;nh trạng kh&ocirc;ng t&igrave;m thấy được kết nối của chuột l&agrave;m gi&aacute;n đoạn c&ocirc;ng việc của mọi người.</p>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://storage.googleapis.com/teko-gae.appspot.com/media/image/2021/6/24/20210624_b8f6a5c4-305b-4431-b3ee-62048e59592f.png\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h4><strong>C&oacute; được phạm vi kết nối tối đa tận 10m rộng r&atilde;i, tương th&iacute;ch với hầu hết c&aacute;c loại nền tảng th&ocirc;ng dụng hiện nay</strong></h4>\r\n\r\n<p>B&ecirc;n cạnh đ&oacute;, chuột kh&ocirc;ng d&acirc;y Microsoft Bluetooth Enogormic c&ograve;n c&oacute; được phạm vi kết nối đỉnh cao khi rộng đến tận 10m trong khu vực mở v&agrave; kh&ocirc;ng chịu ảnh hưởng của những vật cản lớn, c&ograve;n ở trong m&ocirc;i trường văn ph&ograve;ng th&igrave; độ kết nối thu hẹp lại c&ograve;n 5m.</p>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://storage.googleapis.com/teko-gae.appspot.com/media/image/2021/6/24/20210624_5dd722cf-ac98-4cf0-82a0-e3c1281c49dd.jpg\" /></p>\r\n\r\n<p>Đặc biệt hơn, chuột Microsoft tương th&iacute;ch được với hầu hết c&aacute;c loại nền tảng Windows 10/8.1 m&agrave; c&oacute; hỗ trợ bluetooth 4.0 trở l&ecirc;n, kh&ocirc;ng hề k&eacute;n chọn d&ograve;ng m&aacute;y, đem lại độ tiện lợi v&ocirc; c&ugrave;ng cao cho người ti&ecirc;u d&ugrave;ng.</p>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://storage.googleapis.com/teko-gae.appspot.com/media/image/2021/6/24/20210624_b08ccf7b-d5bf-450a-a5c1-4d45eac182ee.png\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h4><strong>Sở hữu thời lượng sử dụng pin kh&aacute; l&acirc;u, kết nối tối đa với 3 thiết bị tiện &iacute;ch</strong></h4>\r\n\r\n<p>Song song đ&oacute;, chuột kh&ocirc;ng d&acirc;y Microsoft Bluetooth Enogormic c&ograve;n sở hữu được thời lượng sử dụng pin kh&aacute; l&acirc;u bền, cho ph&eacute;p bạn c&oacute; thể sử dụng li&ecirc;n tục m&agrave; kh&ocirc;ng cần phải thường xuy&ecirc;n thay pin.</p>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://storage.googleapis.com/teko-gae.appspot.com/media/image/2021/6/24/20210624_bd74cdcc-f30e-4ce6-8aff-46db65fefadc.jpg\" /></p>\r\n\r\n<p>Đồng thời, chuột kh&ocirc;ng d&acirc;y c&ograve;n c&oacute; khả năng kết nối tối đa với 3 thiết bị, gi&uacute;p mọi c&ocirc;ng việc của bạn đều sẽ được ho&agrave;n th&agrave;nh nhanh ch&oacute;ng trong một nốt nhạc v&agrave; một c&uacute; click chuột.</p>\r\n\r\n<h4><strong>Được trang bị c&ocirc;ng nghệ Microsoft BlueTrack hiện đại, kết hợp c&ugrave;ng con lăn gia c&ocirc;ng bằng nh&ocirc;m ti&ecirc;n tiến</strong></h4>\r\n\r\n<p>Ngo&agrave;i ra, chuột kh&ocirc;ng d&acirc;y Microsoft Bluetooth Enogormic c&ograve;n được trang bị c&ocirc;ng nghệ Microsoft BlueTrack hiện đại, gi&uacute;p chuột c&oacute; thể lướt nhanh ch&oacute;ng tr&ecirc;n mọi bề mặt vật liệu kh&aacute;c nhau, bao gồm: b&agrave;n ăn c&ocirc;ng cộng, sảnh ph&ograve;ng kh&aacute;ch hoặc l&agrave; c&aacute;c chỗ g&aacute;c tay của ghế tựa vẫn c&oacute; thể sử dụng được.</p>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://storage.googleapis.com/teko-gae.appspot.com/media/image/2021/6/24/20210624_ac77330c-6549-4e85-9ae2-1830b042ed87.png\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Kh&ocirc;ng dừng lại ở đ&oacute;, chuột m&aacute;y t&iacute;nh c&ograve;n sở hữu được con lăn gia c&ocirc;ng được l&agrave;m bằng nh&ocirc;m ti&ecirc;n tiến, kết hợp th&ecirc;m để teflon v&agrave; cảm biến để theo d&otilde;i được ch&iacute;nh x&aacute;c từng chuyển động nhanh nhạy nhất của chuột. Hạn chế được sự hư hỏng, đảm bảo được độ bền l&acirc;u cho sản phẩm.</p>\r\n\r\n<p>Chuột c&ograve;n c&oacute; được phần để đặt ng&oacute;n c&aacute;i mềm v&agrave; dễ nắm, đem lại cảm gi&aacute;c thoải m&aacute;i cho người d&ugrave;ng khi phải l&agrave;m việc trong một khoảng thời gian cực l&acirc;u d&agrave;i.</p>', 1850000, 1590000, 15, 'Bộ sản phẩm', 'Microsoft_Bluetooth_Ergonomic_(Den).png', 'MOUSE', 'MICROSOFT', 1, NULL, '2021-07-15 10:40:35', '2021-07-21 17:41:51', 2, '2021-07-21 17:41:51');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (24, 'Dell XPS 13 9300 (2020)', '<ul>\r\n	<li>CPU:&nbsp;10th Generation Intel&reg; Core&trade; i5-1035G1 Processor (6MB Cache, up to 3.6 GHz)</li>\r\n	<li>RAM:&nbsp;8&nbsp;GB LPDDR4 -&nbsp;3733 MHz</li>\r\n	<li>SSD:&nbsp;&nbsp;256&nbsp;GB M.2&nbsp;PCIe NVME SSD</li>\r\n	<li>Card Đồ Họa :&nbsp;Intel&reg; UHD Graphics</li>\r\n	<li>M&agrave;n h&igrave;nh:&nbsp;&nbsp;13.4 inches FHD&nbsp;Non-Touch, Infinity Edge Display (1920x1080), 400 Nits</li>\r\n	<li>Windows :&nbsp;10 Bản quyền</li>\r\n	<li>Bảo h&agrave;nh :&nbsp;12&nbsp; th&aacute;ng 1 đổi 1 tại nh&agrave;</li>\r\n	<li>T&igrave;nh Trạng :&nbsp;H&agrave;ng New 100% Fullbox</li>\r\n</ul>', '<p>Một trong những thay đổi đ&aacute;ng ch&uacute; &yacute; nhất của&nbsp;<strong>Dell XPS 13 9300</strong>&nbsp;l&agrave; độ mỏng của viền dưới của m&aacute;y t&iacute;nh x&aacute;ch tay.&nbsp;M&aacute;y t&iacute;nh x&aacute;ch tay c&oacute; tỷ lệ m&agrave;n h&igrave;nh so với th&acirc;n m&aacute;y l&agrave; 91,5%.&nbsp;M&agrave;n h&igrave;nh c&oacute; sẵn ở c&aacute;c phi&ecirc;n bản FHD cảm ứng v&agrave; kh&ocirc;ng cảm ứng, cũng như phi&ecirc;n bản cảm ứng 4K.&nbsp;M&agrave;n h&igrave;nh hỗ trợ Dolby Vision HDR với CinemaColor.&nbsp;Về mặt &acirc;m thanh, Dell XPS 13 hỗ trợ Waves MaxxAudio Pro với CinemaSound.</p>\r\n\r\n<h3><strong>1. Thiết kế</strong></h3>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 920px) 100vw, 920px\" src=\"https://thegioiso365.com/wp-content/uploads/2020/06/ae98bbdfe1c71c9945d6-533x400.jpg\" srcset=\"https://thegioiso365.com/wp-content/uploads/2020/06/ae98bbdfe1c71c9945d6-533x400.jpg 533w, https://thegioiso365.com/wp-content/uploads/2020/06/ae98bbdfe1c71c9945d6-1066x800.jpg 1066w, https://thegioiso365.com/wp-content/uploads/2020/06/ae98bbdfe1c71c9945d6-263x197.jpg 263w, https://thegioiso365.com/wp-content/uploads/2020/06/ae98bbdfe1c71c9945d6-768x576.jpg 768w, https://thegioiso365.com/wp-content/uploads/2020/06/ae98bbdfe1c71c9945d6-1536x1152.jpg 1536w, https://thegioiso365.com/wp-content/uploads/2020/06/ae98bbdfe1c71c9945d6-2048x1537.jpg 2048w, https://thegioiso365.com/wp-content/uploads/2020/06/ae98bbdfe1c71c9945d6-600x450.jpg 600w\" width=\"800\" /></p>\r\n\r\n<p>Dell XPS 13 9300 sử dụng khung vỏ m&aacute;y được thiết kế lại ho&agrave;n to&agrave;n so với model trước đ&oacute;, nhưng ng&ocirc;n ngữ thiết kế nh&igrave;n chung vẫn c&ograve;n kh&aacute; nhiều điểm tương đồng. Một thiết kế mới với b&agrave;n ph&iacute;m gần như kh&ocirc;ng viền (đặc biệt l&agrave; ở ph&iacute;a dưới).</p>\r\n\r\n<p>Nắp m&agrave;n h&igrave;nh cũng như đ&aacute;y đều sử dụng chất liệu nh&ocirc;m m&agrave;u bạc, trong khi mặt tr&ecirc;n phần b&agrave;n ph&iacute;m c&oacute; m&agrave;u đen mờ với hoa văn sợi carbon cao su quen thuộc tương tự c&aacute;c mẫu trước. Với phi&ecirc;n bản m&agrave;u trắng Dell sử dụng sợi thủy tinh cho phần mặt tr&ecirc;n b&agrave;n ph&iacute;m. Nh&igrave;n chung, vật liệu Dell sử dụng để lại ấn tượng rất tinh xảo v&agrave; thiết bị được ho&agrave;n thiện tốt. Đặc biệt m&aacute;y kh&ocirc;ng thấy vấn đề với dấu v&acirc;n tay hoặc dầu mỡ trong suốt thời gian đ&aacute;nh gi&aacute;. Độ chắc chắn của nắp mỏng rất tốt, kh&ocirc;ng c&oacute; tiếng k&ecirc;u c&oacute;t k&eacute;t v&agrave; thậm ch&iacute; khi ấn phần nắp m&aacute;y kh&ocirc;ng xuất hiện gợn s&oacute;ng tr&ecirc;n m&agrave;n h&igrave;nh. Độ chắc chắn của th&acirc;n m&aacute;y cũng rất tốt, bề mặt kh&ocirc;ng biến dạng dưới &aacute;p lực.</p>\r\n\r\n<p>Kh&ocirc;ng c&oacute; vấn đề g&igrave; khi mở m&aacute;y bằng một tay v&agrave; g&oacute;c mở tối đa l&agrave; khoảng 135 độ. Bản lề được điều chỉnh tốt v&agrave; giữ cho m&agrave;n h&igrave;nh ở vị tr&iacute; kh&ocirc;ng bị nảy. Cấu tr&uacute;c bản lề mới cho ph&eacute;p Dell XPS 13 9300 c&oacute; viền dưới mỏng hơn nhiều.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3><strong>2. M&agrave;n h&igrave;nh</strong></h3>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 1020px) 100vw, 1020px\" src=\"https://thegioiso365.com/wp-content/uploads/2020/06/9d51eb0bb1134c4d1502-1066x800.jpg\" srcset=\"https://thegioiso365.com/wp-content/uploads/2020/06/9d51eb0bb1134c4d1502-1066x800.jpg 1066w, https://thegioiso365.com/wp-content/uploads/2020/06/9d51eb0bb1134c4d1502-533x400.jpg 533w, https://thegioiso365.com/wp-content/uploads/2020/06/9d51eb0bb1134c4d1502-263x197.jpg 263w, https://thegioiso365.com/wp-content/uploads/2020/06/9d51eb0bb1134c4d1502-768x576.jpg 768w, https://thegioiso365.com/wp-content/uploads/2020/06/9d51eb0bb1134c4d1502-1536x1152.jpg 1536w, https://thegioiso365.com/wp-content/uploads/2020/06/9d51eb0bb1134c4d1502-2048x1536.jpg 2048w, https://thegioiso365.com/wp-content/uploads/2020/06/9d51eb0bb1134c4d1502-600x450.jpg 600w\" width=\"800\" /></p>\r\n\r\n<p>M&agrave;n h&igrave;nh tỉ lệ 16:10 tr&ecirc;n XPS 13 2020 c&oacute; độ ph&acirc;n giải 3840 x 2400 pixel v&agrave; n&oacute; được trang bị lớp phủ mờ. Ấn tượng h&igrave;nh ảnh ban đầu l&agrave; rất tốt, mặc d&ugrave; bề mặt được phủ mờ nhưng c&aacute;c khu vực s&aacute;ng kh&ocirc;ng xuất hiện hạt. Chiếc laptop n&agrave;y đo được độ s&aacute;ng trung b&igrave;nh thậm ch&iacute; l&agrave; 590 Nits. Gi&aacute; trị m&agrave;u đen kh&ocirc;ng qu&aacute; cao ở 0,35 khi c&agrave;i đặt độ s&aacute;ng cao, cho tỷ lệ tương phản rất tốt 1700:1. M&aacute;y cho dải m&agrave;u kh&aacute; c&aacute;o&nbsp;97.5% sRGB v&agrave;&nbsp;63% AdobeRGB, với những th&ocirc;ng số như vậy chắc chắn sẽ cho trải nghiệm thị gi&aacute;c khi sử dụng l&agrave; v&ocirc; c&ugrave;ng tuyệt vời.</p>\r\n\r\n\r\n<h3><strong>3. Hiệu suất</strong></h3>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 1020px) 100vw, 1020px\" src=\"https://thegioiso365.com/wp-content/uploads/2020/06/ee7d2b3c71248c7ad535-1067x800.jpg\" srcset=\"https://thegioiso365.com/wp-content/uploads/2020/06/ee7d2b3c71248c7ad535-1067x800.jpg 1067w, https://thegioiso365.com/wp-content/uploads/2020/06/ee7d2b3c71248c7ad535-533x400.jpg 533w, https://thegioiso365.com/wp-content/uploads/2020/06/ee7d2b3c71248c7ad535-263x197.jpg 263w, https://thegioiso365.com/wp-content/uploads/2020/06/ee7d2b3c71248c7ad535-768x576.jpg 768w, https://thegioiso365.com/wp-content/uploads/2020/06/ee7d2b3c71248c7ad535-1536x1152.jpg 1536w, https://thegioiso365.com/wp-content/uploads/2020/06/ee7d2b3c71248c7ad535-2048x1536.jpg 2048w, https://thegioiso365.com/wp-content/uploads/2020/06/ee7d2b3c71248c7ad535-600x450.jpg 600w\" width=\"800\" /></p>\r\n\r\n<p><strong>Sức mạnh được đảm bảo:</strong>&nbsp;Với bộ xử l&yacute; di động thế hệ thứ 10 InteI&reg; Core &trade;, giờ đ&acirc;y bạn c&oacute; thể tận hưởng giải tr&iacute; v&ocirc; c&ugrave;ng hấp dẫn tr&ecirc;n một chiếc m&aacute;y t&iacute;nh x&aacute;ch tay mỏng v&agrave; nhẹ đ&aacute;ng kể.&nbsp;C&aacute;c hệ thống hỗ trợ bộ xử l&yacute; Intel&reg; Core &trade; thế hệ thứ 10 c&oacute; đồ họa Intel&reg; Iris&reg; Plus mới nhất đ&atilde; c&oacute; một bước tiến lớn trong việc chơi game, ph&aacute;t trực tuyến v&agrave; s&aacute;ng tạo, mang lại trải nghiệm mượt m&agrave;, chi tiết v&agrave; sống động hơn bao giờ hết tr&ecirc;n c&aacute;c thiết bị di động cao.&nbsp;Khi bạn thấy biểu tượng &ldquo;Kỹ thuật cho hiệu suất di động&rdquo; b&ecirc;n cạnh c&aacute;c cấu h&igrave;nh được chọn, bạn sẽ biết n&oacute; được thiết kế để theo kịp với cuộc sống nhịp độ nhanh của bạn.</p>\r\n\r\n<p><strong>Dell Power Manager với hiệu suất th&iacute;ch ứng:</strong>M&aacute;y t&iacute;nh x&aacute;ch tay n&agrave;y sử dụng hiệu suất th&iacute;ch ứng dựa tr&ecirc;n C&ocirc;ng nghệ điều chỉnh động mới nhất của Intel.&nbsp;Với c&ocirc;ng cụ dự đo&aacute;n v&agrave; th&iacute;ch ứng mới n&agrave;y, m&aacute;y t&iacute;nh x&aacute;ch tay của ch&uacute;ng t&ocirc;i đang t&iacute;ch cực thay đổi sức mạnh của CPU để tối ưu h&oacute;a khối lượng c&ocirc;ng việc cụ thể của bạn, tăng hiệu suất khi bạn cần.&nbsp;*</p>\r\n\r\n<p><strong>Bộ nhớ nhanh hơn, lưu trữ nhiều hơn:</strong>&nbsp;Hệ thống của bạn khởi động v&agrave; tiếp tục lại sau v&agrave;i gi&acirc;y nhờ v&agrave;o bộ nhớ ổ cứng thể rắn l&ecirc;n tới 512GB.&nbsp;Đa t&aacute;c vụ trong nh&aacute;y mắt ngay cả tr&ecirc;n c&aacute;c ứng dụng cường độ cao với bộ nhớ l&ecirc;n tới 16GB.</p>\r\n\r\n\r\n<h3><strong>4. Cổng kết nối</strong></h3>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" sizes=\"(max-width: 1020px) 100vw, 1020px\" src=\"https://thegioiso365.com/wp-content/uploads/2020/06/1a5670132a0bd7558e1a-1067x800.jpg\" srcset=\"https://thegioiso365.com/wp-content/uploads/2020/06/1a5670132a0bd7558e1a-1067x800.jpg 1067w, https://thegioiso365.com/wp-content/uploads/2020/06/1a5670132a0bd7558e1a-533x400.jpg 533w, https://thegioiso365.com/wp-content/uploads/2020/06/1a5670132a0bd7558e1a-263x197.jpg 263w, https://thegioiso365.com/wp-content/uploads/2020/06/1a5670132a0bd7558e1a-768x576.jpg 768w, https://thegioiso365.com/wp-content/uploads/2020/06/1a5670132a0bd7558e1a-1536x1152.jpg 1536w, https://thegioiso365.com/wp-content/uploads/2020/06/1a5670132a0bd7558e1a-2048x1536.jpg 2048w, https://thegioiso365.com/wp-content/uploads/2020/06/1a5670132a0bd7558e1a-600x450.jpg 600w\" width=\"800\" /></p>\r\n\r\n<p>Tương tự như phi&ecirc;n bản trước của XPS 13, m&aacute;y trang bị hai cổng USB-C (với Thunderbolt 3, giao diện PCIe x4 full). Dell cũng đ&oacute;ng g&oacute;i k&egrave;m bộ chuyển đổi USB-A trong hộp, nhưng v&igrave; một cổng sử dụng cấp nguồn, n&ecirc;n bạn chỉ c&oacute; thể sử dụng một trong hai với cổng USB, v&agrave; c&oacute; 1 jack tai nghe 3.5mm.</p>\r\n\r\n\r\n<h3><strong>5. B&agrave;n ph&iacute;m v&agrave;&nbsp;Touchpad</strong></h3>\r\n\r\n<p>B&agrave;n ph&iacute;m đ&atilde; được thiết kế lại, trải nghiệm g&otilde; tổng quan c&oacute; thể thấy được cải thiện hơn một ch&uacute;t. Cho cảm gi&aacute;c kh&aacute; thoải m&aacute;i khi nhập liệu c&aacute;c văn bản d&agrave;i.&nbsp;N&uacute;t nguồn cũng được t&iacute;ch hợp đầu đọc v&acirc;n tay, n&oacute; hoạt động kh&aacute; tốt.&nbsp;M&aacute;y được trang bị đ&egrave;n nền b&agrave;n ph&iacute;m hai cấp độ. N&oacute; sẽ tắt sau một v&agrave;i gi&acirc;y theo mặc định, nhưng bạn c&oacute; thể thay đổi thời gian trong BIOS hoặc thậm ch&iacute; bật n&oacute; vĩnh viễn.</p>\r\n\r\n<p>Touchpad của XPS 13 c&oacute; k&iacute;ch thước 11,2 x 6,5 cm, n&oacute; cung cấp nhiều kh&ocirc;ng gian cho bạn thao t&aacute;c. N&oacute;&nbsp;cảm gi&aacute;c mượt của b&agrave;n di v&agrave; c&aacute;c thao t&aacute;c cơ bản kh&aacute; nhạy.</p>\r\n\r\n\r\n<h3><strong>6. Thời lượng pin</strong></h3>\r\n\r\n<p>Dung lượng pin vẫn l&agrave; 52 Wh v&agrave; thời lượng pin sử dụng rất tốt. Thử nghiệm WLAN thực tế XPS 13 9300 chạy trong gần 12 giờ v&agrave; đạt 8&nbsp;giờ nếu độ s&aacute;ng m&agrave;n h&igrave;nh tối đa. Thử nghiệm ph&aacute;t video của ch&uacute;ng t&ocirc;i ở độ s&aacute;ng 150 Nits thậm ch&iacute; XPS 13 9300 duy tr&igrave; trong khoảng 14,5 giờ.</p>', 26000000, NULL, 10, 'Bộ sản phẩm', 'xps_9300-07-07-510x509.jpg', 'LAP', 'DELL', 1, NULL, '2021-07-15 11:13:57', '2021-07-15 15:40:08', 1, '2021-07-15 14:11:17');
INSERT INTO `sanpham` (`Id`, `TenSanPham`, `MoTa`, `NoiDung`, `GiaSanPham`, `GiaKhuyenMai`, `SoLuong`, `DonVi`, `AnhSanPham`, `DanhMucId`, `ThuongHieuId`, `TrangThaiId`, `DaBan`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (25, 'Bàn phím cơ AULA F3068 Led RGB', '<h4>Th&ocirc;ng số kỹ thuật:</h4>\r\n\r\n<ul>\r\n	<li>M&ocirc; h&igrave;nh: AULA F3068</li>\r\n	<li>Loại sản phẩm: USB C&oacute; D&acirc;y B&agrave;n Ph&iacute;m Cơ</li>\r\n	<li>Chất liệu: NHỰA PBT</li>\r\n	<li>Đ&egrave;n nền Loại: Đ&egrave;n RGB</li>\r\n	<li>Ph&iacute;m: 68 ph&iacute;m</li>\r\n	<li>Kết nối: Hỗ Trợ Bluetooth kh&ocirc;ng d&acirc;y hoặc USB Loại C</li>\r\n	<li>Giao diện: USB Loại C</li>\r\n	<li>USB-C C&aacute;p Chiều D&agrave;i (m): 1.5m/4.921ft (Xấp Xỉ.)</li>\r\n	<li>B&agrave;n ph&iacute;m Tuổi Thọ (lần): hơn 100 triệu</li>\r\n	<li>Hỗ trợ cho luetooth Phi&ecirc;n Bản: Hỗ TrợBluetooth chế độ k&eacute;p</li>\r\n	<li>C&ocirc;ng suất Điện: Cổng USB</li>\r\n	<li>Th&iacute;ch hợp cho: PC</li>\r\n</ul>', '<h3>&nbsp;</h3>\r\n\r\n<h4>Bộ sản phẩm bao gồm:</h4>\r\n\r\n<ul>\r\n	<li>1 * trao đổi n&oacute;ng B&agrave;n ph&iacute;m Cơ</li>\r\n	<li>1 * Type-C C&aacute;p kết nối (c&aacute;p sạc)</li>\r\n	<li>6 * trao đổi n&oacute;ng chuyển đổi (C&oacute; Thể Thay Thế Được chuyển đổi)</li>\r\n	<li>1 * Keycap Puller</li>\r\n	<li>1 * C&ocirc;ng tắc kh&oacute;a k&eacute;o</li>\r\n	<li>1 * Hướng dẫn sử dụng</li>\r\n</ul>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://ae01.alicdn.com/kf/H770c68641637461ab95846bf85e18ec08.jpg\" width=\"800\" /></p>\r\n\r\n<h4>F3068 B&agrave;n Ph&iacute;m Cơ</h4>\r\n\r\n<p>Hỗ trợ cho bluetooth/C&oacute; D&acirc;y chế độ k&eacute;p | Đầy Đủ ph&iacute;m n&oacute;ng-weap c&ocirc;ng tắc | T&ugrave;y Chỉnh c&ocirc;ng tắc | Nhiều M&agrave;u Sắc chiếu s&aacute;ng</p>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://ae01.alicdn.com/kf/H4b39e74f6453450894f2467b68c6bb3cf.jpg\" /></p>\r\n\r\n<p>BT/c&oacute; d&acirc;y chuyển đổi miễn ph&iacute;</p>\r\n\r\n<h4>Hai chế độ kết nối</h4>\r\n\r\n<h4>Phong ph&uacute; hơn mechical trải nghiệm | Mới trục thay đổi sẽ</h4>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://ae01.alicdn.com/kf/Hd4a482c01e9a428fb2ed2a598a511c23R.jpg\" /></p>\r\n\r\n<h4>Phản ứng nhanh ch&oacute;ng đồng thời gian | Đầy Đủ ph&iacute;m Anti-Ghosting</h4>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://ae01.alicdn.com/kf/Had038dc79acc4b968e207eb470ebca0fh.jpg\" /></p>\r\n\r\n<h4>Thay thế c&ocirc;ng tắc t&ugrave;y th&iacute;ch, t&ugrave;y chỉnh một b&agrave;n ph&iacute;m d&agrave;nh cho bạn.</h4>\r\n\r\n<p>(Chỉ hỗ trợ 3 ch&acirc;n cắm chuyển đổi - Hotswap 3 ch&acirc;n)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://ae01.alicdn.com/kf/H853f66da9fbb48d1a8e7450d2c6e1d36F.jpg\" /></p>\r\n\r\n<h4>Đặc biệt h&igrave;nh cầu Keycaps | D&agrave;y b&ecirc;n trong tường | Tinh Tế cảm ứng nh&aacute;m | lnclined thiết kế ph&ugrave; hợp với ng&oacute;n tay</h4>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://ae01.alicdn.com/kf/H3f00a20033854c6babf85f7745ba5b36h.jpg\" /></p>\r\n\r\n<h4>Đơn giản h&oacute;a thiết kế, giữ lại đầy đủ chức năng, c&ograve;n nhỏ v&agrave; tinh tế</h4>\r\n\r\n<p style=\"text-align:center\"><img src=\"https://ae01.alicdn.com/kf/Hf6d6763487bf45648dcab35c832eeda8I.jpg\" /></p>\r\n\r\n<h4>C&ocirc;ng tắc introductio</h4>\r\n\r\n<p style=\"text-align:center\"><img height=\"800\" src=\"https://ae01.alicdn.com/kf/He868a3241e5b4215b9198bfc0e7f9e19s.jpg\" width=\"800\" />\\</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h4>Thời trang &amp; t&agrave;i năng B&agrave;n ph&iacute;m cơ</h4>\r\n\r\n<p style=\"text-align:center\"><img height=\"800\" src=\"https://ae01.alicdn.com/kf/Hf4b853b4521b458aa565f2edf08fb2c21.jpg\" width=\"800\" /></p>\r\n\r\n<h4>AULA F3068 B&agrave;n Ph&iacute;m Cơ | Nhiệt qu&aacute; tr&igrave;nh thăng hoa</h4>\r\n\r\n<p style=\"text-align:center\"><img height=\"800\" src=\"https://ae01.alicdn.com/kf/H6e944fdd7a314d8e871101bf80b766cec.jpg\" width=\"800\" /></p>', 1200000, NULL, 16, 'Bộ sản phẩm', 'Aula F3068 68 Keys.jpg', 'BPhim', 'RK', 1, NULL, '2021-07-15 15:34:01', '2021-07-15 15:40:08', 1, '2021-07-15 15:34:47');
COMMIT;

