INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('APPLE', 'Apple', 'Hãng quả táo đến từ thung lũng Silicon');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('ASUS', 'Asus', 'Hãng máy tính Asus');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('CHANGEASAP', 'ChangeAsap', 'ChargeAsap là thương hiệu được thành lập ở Úc với sứ mệnh sáng tạo nên những sản phẩm sạc với công suất cao dành cho thiết bi di động.\r\nChúng tôi đã tạo nên những sản phẩm cáp từ tính công suất cao 100W, Pin dự phòng công suất cao 210W, và bây giờ là củ sạc công suất lên đến 200W.\r\nChargeAsap cũng hướng tới sản phẩm dễ tiếp cận với người dùng.\r\nVà còn nhiều sản phẩm hơn thế nữa . . .');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('DELL', 'Dell', 'Hãng máy tính nồi đồng cối đá Dell');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('HP', 'HP', 'Hãng máy tính Hewlett-Packard được viết tắt là HP');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('HYPER', 'Hyperdrive', 'Hyper là một nhánh công ty thuộc tập đoàn IT và Phụ kiện điện thoại di động Sanho Cooperation danh tiếng thế giới có trụ sở đặt tại thung lũng Silicon, California');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('KEYDOUS', 'Keydous', 'Hãng bàn phím đến từ tung của');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('KINDLE', 'Kindle', 'Nói đến máy đọc sách chắc hẳn mọi người đều nghĩ ngay đến Kindle - Thương hiệu máy đọc sách bán chạy nhất trên thế giới. Kindle là thương hiệu máy đọc sách uy tín đến từ Amazon. Với thiết kế tinh tế, cầm khá vừa tay và tương đối nhẹ chỉ bằng một cuốn sách mỏng cùng màn hình e-ink được điều chỉnh ánh sáng tự nhiên và không gây cảm giác mỏi mắt, Kindle mang lại cho người dùng trải nghiệm như đang đọc sách giấy. Với những người yêu sách và có thói quen đọc sách trước khi ngủ, Kindle chính là lựa chọn mà bạn không thể bỏ lỡ. Giờ đây cả kệ sách sẽ được thu gọn lại chỉ trong một màn ảnh và bạn có thể đọc bất kỳ cuốn sách nào mà bạn muốn chỉ với Kindle.');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('LENOVO', 'Lenovo', 'Hãng máy tính Lenovo');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('LEOPOLD', 'Leopold', 'Hãng chuyên phím cơ đến từ Hàn Quốc');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('LG', 'LG', 'LG (tiếng Anh: Lucky Goldstar, Hangul: 럭키금성, phiên âm: Lucky Geumseong - tức \"Lạc Hỷ Kim Tinh\" hay \"Ngôi Sao vàng may mắn\") là một tập đoàn công nghiệp nặng đa quốc gia của Hàn Quốc, có trụ sở chính được đặt tại thành phố Seoul. Các sản phẩm chính của tập đoàn này bao gồm: điện tử tiêu dùng, thiết bị viễn thông, điện thoại thông minh (nhưng đã khai tử từ năm 2021)[2], chất bán dẫn, Pin và các sản phẩm từ hóa chất, dầu khí,... Tập đoàn hiện sở hữu rất nhiều công ty con, hầu hết đang hoạt động dướ');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('LOGITECH', 'Logitech', 'Logitech International S.A. (thường được gọi là Logitech hay gọi cách điệu là Logi) là doanh nghiệp toàn cầu có trụ sở đặt tại Lausanne, Thụy Sĩ. Logitech chuyên sản xuất và cung ứng các thiết bị phụ kiện của máy tính cá nhân hay máy tính bảng như bàn phím, chuột máy tính, microphone, thiết bị chơi game, webcam. Ngoài ra, doanh nghiệp này cũng sản xuất các thiết bị âm thanh dùng kèm máy tính như loa, tai nghe, thậm chí cả máy MP3 và điện thoại.');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('MICROSOFT', 'Microsoft', 'Một trong những tập đoàn công nghệ hàng đầu của Mỹ');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('NO', 'Không rõ', 'Chưa biết thông tin thương hiệu');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('RK', 'Royal Kludge', NULL);
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('SAM', 'Samsung', 'Hãng công nghệ đến từ Hàn Quốc');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('SUR', 'Surface', 'Surface là dòng máy tính bảng cao cấp đến từ nhà Microsoft. Những chiếc máy tính này được người dùng ưa chuộng bởi thiết kế sang trọng, mỏng nhẹ, hiệu năng \"đủ dùng\" cùng mức giá thành hợp lý');
INSERT INTO `thuonghieu` (`Id`, `ThuongHieu`, `MoTa`) VALUES ('TOM', 'Tomtoc', 'Tomtoc là một thương hiệu có xuất xứ từ Mỹ, chuyên về sản xuất những sản phẩm balo và túi xách chống sốc dành cho laptop, máy tính bảng và một số thiết bị chơi game');
COMMIT;

