-- ----------------------------
-- Table structure for tintuc
-- ----------------------------
DROP TABLE IF EXISTS `tintuc`;
CREATE TABLE `tintuc` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `TieuDe` varchar(500) NOT NULL,
  `MoTa` text NOT NULL,
  `NoiDung` text,
  `Anh` varchar(255) DEFAULT NULL,
  `LuotXem` int DEFAULT NULL,
  `ChuDeId` varchar(50) DEFAULT NULL,
  `BloggerId` int NOT NULL,
  `NgayTao` datetime DEFAULT NULL,
  `NgaySua` datetime DEFAULT NULL,
  `DaDuyet` tinyint DEFAULT NULL,
  `NgayDuyet` datetime DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `fk_chude_id` (`ChuDeId`),
  KEY `fk_nguoidung_id` (`BloggerId`),
  CONSTRAINT `fk_chude_id` FOREIGN KEY (`ChuDeId`) REFERENCES `chude` (`Id`),
  CONSTRAINT `fk_nguoidung_id` FOREIGN KEY (`BloggerId`) REFERENCES `nguoidung` (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb3;

-- ----------------------------
-- Records of tintuc
-- ----------------------------
BEGIN;
INSERT INTO `tintuc` (`Id`, `TieuDe`, `MoTa`, `NoiDung`, `Anh`, `LuotXem`, `ChuDeId`, `BloggerId`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (1, 'ĐÁNH GIÁ MACBOOK PRO DÙNG CHIP M1: KHI CHỮ ‘PRO’ NẰM Ở. . . QUẠT TẢN NHIỆT', '<p><strong>Chiếc <a href=\"http://127.0.0.1:8000/danhmuc/sanpham/Mac\">MacBook</a> Pro mới sử dụng chip M1 c&oacute; rất nhiều ưu điểm đ&aacute;ng ca ngợi, song b&ecirc;n cạnh đ&oacute; vẫn c&ograve;n tồn tại một v&agrave;i &quot;hạt sạn&quot; đ&aacute;ng tiếc.</strong></p>', '<h3><img alt=\"Đánh giá MacBook Pro dùng chip M1: Khi chữ ‘pro\' nằm ở… quạt tản nhiệt\" src=\"https://vnreview.vn/image/21/64/89/2164894.jpg?t=1611737991155\" width=\"100%\" /></h3>\r\n\r\n<p>C&aacute;ch đơn giản nhất v&agrave; hữu hiệu nhất để m&ocirc; tả về mẫu MacBook Pro mới nhất sử dụng chip M1 của Apple c&oacute; thể g&oacute;i gọn trong c&acirc;u sau: Đ&acirc;y l&agrave; một chiếc MacBook Air được bổ sung th&ecirc;m&hellip; quạt tản nhiệt!</p>\r\n\r\n<p>T&ocirc;i n&oacute;i nghi&ecirc;m t&uacute;c đ&oacute;, kh&ocirc;ng đ&ugrave;a đ&acirc;u. Quạt tản nhiệt c&oacute; lẽ l&agrave; chi tiết kh&aacute;c biệt r&otilde; r&agrave;ng nhất giữa hai mẫu laptop đầu ti&ecirc;n của Apple sử dụng con chip M1 tuỳ biến của ch&iacute;nh T&aacute;o khuyết: mẫu MacBook Air - kh&ocirc;ng c&oacute; quạt tản nhiệt - sẽ cần phải &quot;b&oacute;p&quot; hiệu năng khi nhiệt độ của chip xử l&yacute; tăng qu&aacute; cao. Tuy nhi&ecirc;n, chiếc MacBook Pro thay v&agrave;o đ&oacute; c&oacute; thể đơn giản &quot;bật&quot; quạt l&ecirc;n v&agrave; nhờ vậy, c&oacute; thể duy tr&igrave; hiệu suất xử l&yacute; cao trong khoảng thời gian d&agrave;i hơn.</p>\r\n\r\n<p>Dĩ nhi&ecirc;n, vẫn c&oacute; những điểm kh&aacute;c biệt kh&aacute;c b&ecirc;n cạnh c&aacute;i quạt: MacBook Pro c&oacute; m&agrave;n h&igrave;nh chất lượng tốt hơn một ch&uacute;t, micro v&agrave; loa cũng to hơn, tốt hơn. Chiếc m&aacute;y n&agrave;y cũng c&oacute; pin lớn hơn v&agrave; nhờ vậy, thời lượng pin của n&oacute; cũng d&agrave;i hơn. Một chi tiết dễ nhận ra nữa: chiếc m&aacute;y n&agrave;y c&oacute; thanh Touch Bar vốn g&acirc;y nhiều tranh c&atilde;i thay v&igrave; h&agrave;ng ph&iacute;m chức năng truyền thống. Tuy nhi&ecirc;n về mặt hiệu năng, MacBook Pro gần như tương tự MacBook Air - trừ phi bạn &quot;bắt&quot; n&oacute; l&agrave;m việc trong thời gian d&agrave;i. V&agrave; do đ&oacute;, c&oacute; thể n&oacute;i, chiếc quạt tản nhiệt ch&iacute;nh l&agrave; sự kh&aacute;c biệt quan trọng nhất.</p>\r\n\r\n<p>Đối với một số người, sự vượt trội rất nhỏ về hiệu năng đ&oacute; c&oacute; thể gi&uacute;p MacBook Pro trở n&ecirc;n &quot;đ&aacute;ng đồng tiền b&aacute;t gạo&quot; hơn so với MacBook Air. Mẫu MacBook Pro khởi điểm gi&aacute; 1.299 USD (khoảng 30 triệu đồng) được trang bị chip M1 với bộ xử l&yacute; đồ hoạ (GPU) 8 nh&acirc;n, 8GB bộ nhớ RAM, 256GB ổ cứng SSD - c&oacute; gi&aacute; cao hơn 300 USD (khoảng 6,9 triệu đồng) so với phi&ecirc;n bản cấu h&igrave;nh thấp nhất của MacBook Air. Trong khi đ&oacute;, phi&ecirc;n bản MacBook Pro c&oacute; cấu h&igrave;nh cao cấp hơn (ổ cứng 512GB) c&oacute; gi&aacute; l&agrave; 1.499 USD (khoảng 34,6 triệu đồng), đắt hơn 250 USD (khoảng 5,8 triệu đồng) so với mẫu MacBook Air c&oacute; cấu h&igrave;nh tương đương. Vậy n&ecirc;n c&oacute; thể n&oacute;i, nếu so s&aacute;nh với những mẫu MacBook của năm 2019, chiếc m&aacute;y n&agrave;y kh&ocirc;ng gặp trục trặc về thiết kế b&agrave;n ph&iacute;m, thời lượng pin xuất sắc v&agrave; thậm ch&iacute; hiệu năng cũng nhỉnh hơn. R&otilde; r&agrave;ng, đ&acirc;y l&agrave; một sự n&acirc;ng cấp mạnh mẽ về mọi mặt.</p>\r\n\r\n<p>C&oacute; rất nhiều chi tiết kỹ thuật đ&aacute;ng để b&agrave;n đến về con chip M1, chẳng hạn như c&aacute;ch vận h&agrave;nh c&aacute;c ứng dụng thiết kế cho chip Intel tr&ecirc;n chiếc m&aacute;y n&agrave;y, hay liệu n&oacute; sẽ gợi mở ra tương lai n&agrave;o cho những chiếc m&aacute;y t&iacute;nh Mac? C&acirc;u trả lời ngắn gọn l&agrave; chiếc m&aacute;y n&agrave;y sẽ rất ấn tượng, v&agrave; MacBook Pro thực sự l&agrave; một chiếc laptop xuất sắc với hiệu suất cao v&agrave; thời lượng pin ấn tượng. Nhưng nếu bạn c&oacute; &yacute; định mua một chiếc m&aacute;y t&iacute;nh Mac chạy chip M1, liệu những n&acirc;ng cấp của MacBook Pro so với MacBook Air c&oacute; thực sự đ&aacute;ng với số tiền m&agrave; bạn phải bỏ ra hay kh&ocirc;ng? C&acirc;u trả lời l&agrave;&hellip; c&oacute; thể, với một sự ngập ngừng!</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Đánh giá MacBook Pro dùng chip M1: Khi chữ ‘pro\' nằm ở… quạt tản nhiệt\" src=\"https://vnreview.vn/image/21/64/90/2164906.jpg?t=1611738012707\" width=\"100%\" /></p>\r\n\r\n<h4><strong>Chấm điểm Apple MacBook Pro 13-inch (hai cổng USB-C, phi&ecirc;n bản Late 2020): 8,5/10 điểm</strong></h4>\r\n\r\n<p><strong>Điểm mạnh:</strong></p>\r\n\r\n<p><em>- Hiệu năng tuyệt vời.</em></p>\r\n\r\n<p><em>- Thời lượng pin xuất sắc.</em></p>\r\n\r\n<p><em>- M&agrave;n h&igrave;nh cho chất lượng hiển thị tốt.</em></p>\r\n\r\n<p><strong>Điểm yếu</strong></p>\r\n\r\n<p><em>- Chỉ c&oacute; 2 cổng USB-C.</em></p>\r\n\r\n<p><em>- Kh&ocirc;ng thể c&oacute; nhiều hơn 16GB RAM.</em></p>\r\n\r\n<p><em>- Webcam cho chất lượng &quot;đ&aacute;ng buồn&quot;.</em></p>\r\n\r\n<p><em>- Thanh Touch Bar đ&ocirc;i l&uacute;c khiến mọi thứ trở n&ecirc;n kh&oacute; d&ugrave;ng hơn (thay v&igrave; dễ hơn).</em></p>\r\n\r\n<p>C&aacute;c laptop Windows với vi xử l&yacute; ARM từ Qualcomm nh&igrave;n chung chậm hơn, nhiều lỗi hơn, v&agrave; phức tạp hơn c&aacute;c laptop với chip Intel. D&ugrave; t&ocirc;i đ&atilde; đo&aacute;n trước Apple sẽ xử l&yacute; qu&aacute; tr&igrave;nh chuyển đổi từ Intel sang ARM tốt hơn c&aacute;c h&atilde;ng kh&aacute;c, song t&ocirc;i kh&ocirc;ng hề nghĩ mọi thứ lại hoạt động tốt như thế n&agrave;y. Việc c&aacute;c ứng dụng của macOS n&oacute;i chung v&agrave; của ch&iacute;nh Apple n&oacute;i ri&ecirc;ng chạy mượt l&agrave; điều dễ hiểu, bởi nhiều trong số ch&uacute;ng đ&atilde; được tinh chỉnh để hoạt động với vi xử l&yacute; mới. Điều khiến bạn phải sốc l&agrave;&nbsp;<strong>mọi ứng dụng đều chạy mượt</strong>.</p>\r\n\r\n<p>Th&ocirc;ng thường, c&aacute;c ứng dụng được x&acirc;y dựng để l&agrave;m việc với một loại vi xử l&yacute; cụ thể, do đ&oacute; khi ch&uacute;ng chạy tr&ecirc;n một cỗ m&aacute;y với một vi xử l&yacute; kh&aacute;c, bạn cần một v&agrave;i c&ocirc;ng cụ hỗ trợ ẩn s&acirc;u b&ecirc;n dưới hệ thống. Tr&ecirc;n m&aacute;y Mac, c&ocirc;ng việc n&agrave;y được giao cho một phần mềm gọi l&agrave; Rosetta 2 - thứ sẽ được c&agrave;i đặt v&agrave;o lần đầu ti&ecirc;n bạn chạy một ứng dụng viết cho chip Intel.</p>\r\n\r\n<p>Kh&ocirc;ng như Windows, Rosetta 2 kh&ocirc;ng thực sự l&agrave; một tr&igrave;nh giả lập, n&oacute; l&agrave; một tr&igrave;nh bi&ecirc;n dịch. C&oacute; nghĩa l&agrave; c&aacute;c ứng dụng chạy qua Rosetta 2 sẽ khởi động l&acirc;u hơn một ch&uacute;t, nhưng một khi đ&atilde; chạy, ch&uacute;ng sẽ chạy mượt. T&ocirc;i chưa từng gặp bất kỳ vấn đề n&agrave;o li&ecirc;n quan tương th&iacute;ch ứng dụng.</p>\r\n\r\n<p>N&oacute;i t&oacute;m lại, Apple đ&atilde; thực sự đạt được những th&agrave;nh tựu đ&aacute;ng ngạc nhi&ecirc;n trong việc l&agrave;m cho c&aacute;c ứng dụng vốn được viết cho chip Intel c&oacute; thể chạy được tr&ecirc;n chip M1, tuy nhi&ecirc;n, c&aacute;c ứng dụng iOS khi chạy tr&ecirc;n nền tảng n&agrave;y hầu hết kh&aacute; &quot;lộn xộn&quot; do chưa c&oacute; sự tương th&iacute;ch tốt giữa c&aacute;c thao t&aacute;c cảm ứng tr&ecirc;n iOS v&agrave; c&aacute;c thao t&aacute;c với b&agrave;n ph&iacute;m/chuột truyền thống của m&aacute;y t&iacute;nh (Tuy nhi&ecirc;n, ở thời điểm b&agrave;i n&agrave;y được dịch, Apple đ&atilde; tung ra một bản cập nhật iOS nhằm &quot;chặn&quot; kh&ocirc;ng cho người d&ugrave;ng c&agrave;i đặt v&agrave; chạy c&aacute;c ứng dụng iOS tr&ecirc;n m&aacute;y t&iacute;nh Mac.)</p>\r\n\r\n<p>Những nhận x&eacute;t ở tr&ecirc;n đ&uacute;ng với cả MacBook Air. Tuy nhi&ecirc;n, ri&ecirc;ng với MacBook Pro, thứ l&agrave;m n&ecirc;n sự kh&aacute;c biệt ch&iacute;nh l&agrave; quạt tản nhiệt v&agrave; linh kiện n&agrave;y rất c&oacute; &yacute; nghĩa đối với hiệu năng của con chip M1. V&agrave; do về bản chất, chip M1 hoạt động ho&agrave;n to&agrave;n kh&aacute;c so với những con chip x86 ch&uacute;ng ta vẫn thường quen tr&ecirc;n những chiếc laptop truyền thống, sẽ c&ograve;n nhiều điều để kh&aacute;m ph&aacute;.</p>\r\n\r\n<p>Một con chip Intel ti&ecirc;u chuẩn, chẳng hạn như chip Core i5 bốn nh&acirc;n xung nhịp 2GHz được Apple trang bị cho những mẫu MacBook Pro cao cấp kh&ocirc;ng phải l&uacute;c n&agrave;o cũng chạy ở xung nhịp 2GHz. Đ&acirc;y l&agrave; tốc độ xung nhịp ti&ecirc;u chuẩn. Tuy nhi&ecirc;n khi cần đạt hiệu năng cao hơn, con chip n&agrave;y c&oacute; thể được tăng tốc (&quot;turbo boost&quot;) l&ecirc;n 3,8GHz. V&agrave; khi m&aacute;y cần phải hạ nhiệt độ hay tiết kiệm năng lượng, xung nhịp của chip c&oacute; thể giảm xuống dưới mốc 2GHz ti&ecirc;u chuẩn. Đ&acirc;y được gọi l&agrave; hiện tượng &quot;thắt cổ chai&quot; hiệu năng do nhiệt, v&agrave; ảnh hưởng của nhiệt độ đối với hiện tượng giảm hiệu năng của m&aacute;y vẫn lu&ocirc;n l&agrave; chi tiết m&agrave; ch&uacute;ng t&ocirc;i muốn đ&aacute;nh gi&aacute; kĩ nhất trong c&aacute;c b&agrave;i đ&aacute;nh gi&aacute; laptop Mac.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Đánh giá MacBook Pro dùng chip M1: Khi chữ ‘pro\' nằm ở… quạt tản nhiệt\" src=\"https://vnreview.vn/image/21/64/90/2164903.jpg?t=1611738012707\" width=\"100%\" /></p>\r\n\r\n<p>Tuy nhi&ecirc;n, chip M1 hoạt động hơi kh&aacute;c một ch&uacute;t: Apple cho biết con chip n&agrave;y kh&ocirc;ng c&oacute; t&iacute;nh năng tăng tốc turbo boost. Chip hoạt động ở tốc độ xung nhịp tối đa trong đa số mọi trường hợp, v&agrave; khi hệ thống ph&aacute;t hiện ra rằng m&aacute;y kh&ocirc;ng thể l&agrave;m m&aacute;t con chip một c&aacute;ch hiệu quả được nữa, n&oacute; sẽ tự động giảm hiệu năng xuống. Đ&acirc;y l&agrave; điều ch&uacute;ng ta sẽ dễ d&agrave;ng nhận ra tr&ecirc;n chiếc MacBook Air kh&ocirc;ng c&oacute; quạt tản nhiệt - cụ thể, điểm Cinebench của MacBook Air sẽ giảm dần sau khi ch&uacute;ng t&ocirc;i cho m&aacute;y chạy b&agrave;i test nhiều lần trong khoảng thời gian 30 ph&uacute;t li&ecirc;n tục. Khung nh&ocirc;m của MacBook Air cuối c&ugrave;ng cũng kh&ocirc;ng đủ sức để l&agrave;m m&aacute;t con chip M1 sau một khoảng thời gian d&agrave;i hoạt động, v&agrave; do đ&oacute; m&aacute;y sẽ chạy chậm lại. Điều n&agrave;y c&oacute; thể chấp nhận được với một mẫu laptop d&agrave;nh cho người d&ugrave;ng phổ th&ocirc;ng, nhưng kh&ocirc;ng thể l&agrave; điều m&agrave; ch&uacute;ng ta c&oacute; thể chấp nhận tr&ecirc;n một mẫu m&aacute;y &quot;pro&quot; được.</p>\r\n\r\n<p>V&agrave; như vậy, đối với MacBook Pro, Apple đ&atilde; trang bị cho m&aacute;y một chiếc quạt tản nhiệt. V&agrave; thật vậy, khi ch&uacute;ng t&ocirc;i thực hiện b&agrave;i test Cinebench li&ecirc;n tục trong khoảng thời gian 30 ph&uacute;t, quạt đ&atilde; được khởi động chỉ sau v&agrave;i ph&uacute;t v&agrave; chạy li&ecirc;n tục trong suốt khoảng thời gian b&agrave;i test được chạy. Tuy nhi&ecirc;n, về mặt thiết kế tản nhiệt, mẫu m&aacute;y MacBook Pro c&oacute; thiết kế tốt hơn MacBook Air về tổng thể: ch&uacute;ng t&ocirc;i thực hiện b&agrave;i test xuất video độ ph&acirc;n giải 4K ti&ecirc;u chuẩn trong phần mềm Adobe Premiere Pro một v&agrave;i lần, v&agrave; quạt tản nhiệt kh&ocirc;ng hề phải khởi động, tuy nhi&ecirc;n thời gian xuất file cũng kh&ocirc;ng thay đổi (Ch&uacute;ng t&ocirc;i nhận thấy c&oacute; một lỗi k&igrave; lạ của lớp &quot;giả lập&quot; Rosetta trong b&agrave;i test n&agrave;y: ch&uacute;ng t&ocirc;i thiết lập để phần mềm Premiere xuất file với bitrate 40Mb/s, tuy nhi&ecirc;n khi chạy b&agrave;i test xuất file n&agrave;y tr&ecirc;n 3 chiếc m&aacute;y t&iacute;nh sử dụng chip M1 kh&aacute;c nhau th&ocirc;ng qua giả lập Rosetta, file kết quả lại chỉ c&oacute; bitrate l&agrave;&hellip; 20. Khi thiết lập xuất l&ecirc;n 80Mb/s th&igrave; file cho ra mới l&agrave; 40Mb/s. Khi li&ecirc;n hệ với Adobe, c&ocirc;ng ty cho biết việc chạy c&aacute;c ứng dụng Creative Cloud th&ocirc;ng qua Rosetta 2 kh&ocirc;ng phải l&agrave; phương thức được h&atilde;ng hỗ trợ ch&iacute;nh thức. Do đ&oacute;, bạn h&atilde;y cẩn thận!)</p>\r\n\r\n<table align=\"center\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<p><strong>B&agrave;i test</strong></p>\r\n			</td>\r\n			<td>\r\n			<p><strong>MacBook Air</strong></p>\r\n			</td>\r\n			<td>\r\n			<p><strong>MacBook Pro</strong></p>\r\n			</td>\r\n			<td>\r\n			<p><strong>Mac mini</strong></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cinebench R23 Multi</p>\r\n			</td>\r\n			<td>\r\n			<p>6803</p>\r\n			</td>\r\n			<td>\r\n			<p>7729</p>\r\n			</td>\r\n			<td>\r\n			<p>7729</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cinebench R23 Single</p>\r\n			</td>\r\n			<td>\r\n			<p>1494</p>\r\n			</td>\r\n			<td>\r\n			<p>1519</p>\r\n			</td>\r\n			<td>\r\n			<p>1520</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cinebench R23 Multi (lặp đi lặp lại trong 30 ph&uacute;t)</p>\r\n			</td>\r\n			<td>\r\n			<p>5369</p>\r\n			</td>\r\n			<td>\r\n			<p>7729</p>\r\n			</td>\r\n			<td>\r\n			<p>7780</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Geekbench 5.3 CPU Multi</p>\r\n			</td>\r\n			<td>\r\n			<p>7510</p>\r\n			</td>\r\n			<td>\r\n			<p>7554</p>\r\n			</td>\r\n			<td>\r\n			<p>7711</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Geekbench 5.3 CPU Single</p>\r\n			</td>\r\n			<td>\r\n			<p>1730</p>\r\n			</td>\r\n			<td>\r\n			<p>1730</p>\r\n			</td>\r\n			<td>\r\n			<p>1754</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Geekbench 5.3 OpenCL/ Compute</p>\r\n			</td>\r\n			<td>\r\n			<p>18357</p>\r\n			</td>\r\n			<td>\r\n			<p>19211</p>\r\n			</td>\r\n			<td>\r\n			<p>19654</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>Trong thực tế, nh&igrave;n chung, kh&aacute; kh&oacute; để c&oacute; thể &quot;buộc&quot; c&aacute;i quạt tản nhiệt của MacBook Pro phải bật l&ecirc;n. Những t&aacute;c vụ c&oacute; thể ngay lập tức khiến quạt tản nhiệt của chiếc MacBook Pro 16-inch sử dụng chip Intel phải bật l&ecirc;n, chẳng hạn như sử dụng Google Meet tr&ecirc;n Chrome, gần như kh&ocirc;ng l&agrave;m kh&oacute; được MacBook Pro M1. Trừ phi bạn thường xuy&ecirc;n xử l&yacute; những c&ocirc;ng việc nặng tr&ecirc;n laptop của m&igrave;nh trong thời gian d&agrave;i, sự kh&aacute;c biệt giữa MacBook Air v&agrave; Pro hầu như kh&aacute; kh&oacute; nhận ra.</p>\r\n\r\n<p>T&ocirc;i thực sự muốn nhấn mạnh rằng tất cả những g&igrave; ch&uacute;ng ta biết về con chip M1 của Apple hầu như đến từ ch&iacute;nh Apple v&agrave; rất kh&oacute; để c&oacute; thể kiểm tra lại một c&aacute;ch độc lập. Th&ocirc;ng tin duy nhất m&agrave; ch&uacute;ng ta biết về hiệu năng v&agrave; năng lượng ti&ecirc;u thụ của chip M1 l&agrave; th&ocirc;ng qua biểu đồ n&agrave;y, song Apple cũng kh&ocirc;ng ghi r&otilde; đ&acirc;y l&agrave; kết quả thử nghiệm của họ trong trường hợp n&agrave;o, với mục đ&iacute;ch sử dụng n&agrave;o.</p>\r\n\r\n<p>T&oacute;m lại, cũng như MacBook Air, hiệu năng của MacBook Pro chạy chip M1 l&agrave; vượt xa những kỳ vọng của ch&uacute;ng t&ocirc;i.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Đánh giá MacBook Pro dùng chip M1: Khi chữ ‘pro\' nằm ở… quạt tản nhiệt\" src=\"https://vnreview.vn/image/21/64/89/2164891.jpg?t=1611737991155\" width=\"100%\" /></p>\r\n\r\n<p><em>Biểu đồ minh hoạ sức mạnh của chip M1 do Apple c&ocirc;ng bố</em></p>\r\n\r\n<p>Apple trả lời phỏng vấn của ch&uacute;ng t&ocirc;i rằng c&aacute;c đường cong của đồ thị được vẽ tr&ecirc;n quy m&ocirc; tuyến t&iacute;nh v&agrave; cũng lưu &yacute; rằng chip M1 mang đến hiệu suất gấp đ&ocirc;i so với chip đối thủ cạnh tranh (kh&ocirc;ng r&otilde; thương hiệu hay model cụ thể) ở mức c&ocirc;ng suất 10 watt. Điều đ&aacute;ng ch&uacute; &yacute; nữa l&agrave; đường cong của M1 dừng lại&hellip; giữa chừng. Apple cho biết nh&oacute;m ph&aacute;t triển chip của họ quan t&acirc;m nhiều đến thời lượng pin cũng như hiệu suất v&agrave; họ đ&atilde; thiết kế con chip M1 để mang đến sự c&acirc;n bằng của cả hai yếu tố tr&ecirc;n, chứ kh&ocirc;ng phải mang tới hiệu suất tối đa bằng mọi gi&aacute;.</p>\r\n\r\n<p>Điều đ&oacute; c&oacute; nghĩa l&agrave; thời lượng pin tr&ecirc;n Pro l&agrave; tuyệt vời, giống như với MacBook Air. Apple đ&atilde; c&oacute; những c&ocirc;ng bố t&aacute;o bạo về c&aacute;c cải tiến li&ecirc;n quan đến thời lượng pin tr&ecirc;n MacBook Pro chạy chip M1 - theo đ&oacute;, thời lượng pin của những mẫu m&aacute;y n&agrave;y gấp đ&ocirc;i so với c&aacute;c m&aacute;y t&iacute;nh sử dụng chip Intel - v&agrave; mặc d&ugrave; t&ocirc;i kh&ocirc;ng thấy đ&uacute;ng sự thật đ&oacute;, nhưng t&ocirc;i cũng đ&atilde; c&oacute; thể dễ d&agrave;ng c&oacute; được 10 tiếng sử dụng chỉ sau một lần sạc pin v&agrave; phải thực sự &quot;&eacute;p&quot; chiếc m&aacute;y n&agrave;y l&agrave;m việc rất &quot;căng&quot; mới c&oacute; thể &quot;đốt&quot; hết vi&ecirc;n pin trong 8 tiếng (C&oacute; l&uacute;c, t&ocirc;i đ&atilde; cho ph&aacute;t video 4K tr&ecirc;n YouTube bằng Chrome ở chế độ nền, nhằm... l&agrave;m ti&ecirc;u hao pin nhanh hơn.) C&aacute;c ứng dụng vốn nổi tiếng với việc &quot;ngốn&quot; pin - như Chrome v&agrave; c&aacute;c ứng dụng của Electron như Slack - dường như vẫn c&ograve;n chạy kh&aacute; tốn pin trong chế độ &quot;giả lập&quot; Rosetta 2, v&igrave; vậy ch&uacute;ng ta sẽ phải chờ xem mọi thứ c&oacute; kh&aacute;c kh&ocirc;ng khi c&aacute;c nh&agrave; ph&aacute;t triển tung ra phi&ecirc;n bản d&agrave;nh ri&ecirc;ng cho chip Apple của những ứng dụng n&agrave;y.</p>\r\n\r\n<p>Điều đ&oacute; cho thấy rằng ch&uacute;ng t&ocirc;i bị giới hạn về mặt th&ocirc;ng tin v&agrave; phải rất vất vả để c&oacute; thể suy luận ra những th&ocirc;ng số kỹ thuật chi tiết của con chip M1 chỉ dựa v&agrave;o một c&aacute;i biểu đồ kh&ocirc;ng-mấy-hữu-&iacute;ch từ Apple v&agrave; những b&agrave;i test benchmark. Giống như c&aacute;c chip di động kh&aacute;c của h&atilde;ng tự thiết kế, Apple sẽ kh&ocirc;ng cung cấp th&ocirc;ng tin kỹ thuật chi tiết về M1; cửa sổ &quot;Giới thiệu về m&aacute;y Mac n&agrave;y&quot; (About This Mac) thậm ch&iacute; kh&ocirc;ng hiển thị tốc độ xung nhịp của con chip (tuy nhi&ecirc;n Geekbench v&agrave; Cinebench đều đưa ra con số về tốc độ xung nhịp nằm trong khoảng 3,2GHz.) Cũng kh&oacute; t&igrave;m thấy bất kỳ kết quả n&agrave;o về nhiệt độ, điện năng ti&ecirc;u thụ hoặc tốc độ xung nhịp trực tiếp n&agrave;o nếu tra cứu th&ocirc;ng qua c&aacute;c c&ocirc;ng cụ ti&ecirc;u chuẩn của macOS - Tất nhi&ecirc;n, ứng dụng Power Gadget của Intel cũng kh&ocirc;ng hoạt động với con chip n&agrave;y - v&agrave; Apple cũng kh&ocirc;ng cho biết liệu những th&ocirc;ng tin n&agrave;y c&oacute; hiển thị trong bất kỳ tiện &iacute;ch n&agrave;o ra mắt trong tương lai hay kh&ocirc;ng. V&igrave; vậy, mặc d&ugrave; con chip n&agrave;y cho hiệu suất rất tốt trong c&aacute;c thử nghiệm thực tế của ch&uacute;ng t&ocirc;i, nhưng rất kh&oacute; để n&oacute;i ch&iacute;nh x&aacute;c điều g&igrave; đang diễn ra b&ecirc;n trong chip M1 trong c&aacute;c trường hợp sử dụng cụ thể. D&ugrave; vậy, tin tốt l&agrave; hiệu suất thực tế tuyệt vời d&ugrave; sao cũng quan trọng hơn so với việc biết được những th&ocirc;ng số kỹ thuật chi tiết, đối với đa số người d&ugrave;ng.</p>\r\n\r\n<p>C&aacute;c giới hạn của con chip M1 cũng trở n&ecirc;n r&otilde; r&agrave;ng hơn tr&ecirc;n mẫu laptop &quot;pro&quot;. Kh&ocirc;ng c&oacute; laptop M1 n&agrave;o được trang bị bộ nhớ RAM tr&ecirc;n 16GB v&agrave; cũng kh&ocirc;ng c&oacute; mẫu m&aacute;y n&agrave;o hỗ trợ người d&ugrave;ng n&acirc;ng cấp bộ nhớ RAM cả. M&aacute;y cũng chỉ hỗ trợ kết nối với một m&agrave;n h&igrave;nh ngo&agrave;i. Apple cho biết c&ocirc;ng ty đ&atilde; ph&aacute;t triển bộ điều khiển (controller) Thunderbolt của ri&ecirc;ng họ v&agrave; n&oacute; được t&iacute;ch hợp v&agrave;o b&ecirc;n trong con chip M1, nhưng ch&uacute;ng t&ocirc;i chưa thấy mẫu laptop M1 n&agrave;o được trang bị nhiều hơn hai cổng Thunderbolt cả. Bạn cũng kh&ocirc;ng thể sử dụng GPU rời với c&aacute;c cổng Thunderbolt n&agrave;y như c&aacute;c m&aacute;y t&iacute;nh sử dụng chip Intel. Đ&acirc;y l&agrave; tất cả những hạn chế c&oacute; thể chấp nhận được tr&ecirc;n mẫu MacBook Air - vốn hướng đến đối tượng người ti&ecirc;u d&ugrave;ng th&ocirc;ng thường; nhưng tr&ecirc;n MacBook Pro, ch&uacute;ng khiến cho chiếc m&aacute;y n&agrave;y trở n&ecirc;n k&eacute;m hấp dẫn hơn trong mắt người d&ugrave;ng.</p>\r\n\r\n<p>Con chip M1 cũng mở ra một số thay đổi lớn kh&aacute;c đối với nền tảng Mac, tuy nhi&ecirc;n những thay đổi n&agrave;y kh&ocirc;ng hiện hữu ngay ở thời điểm hiện tại với những chiếc MacBook Pro M1 đầu ti&ecirc;n - song c&oacute; thể c&oacute; &yacute; nghĩa rất lớn trong tương lai. C&aacute;c m&aacute;y MacBook M1 hiện &aacute;p dụng một &quot;nh&oacute;m&quot; bộ nhớ duy nhất được chia sẻ chung, đ&oacute;ng vai tr&ograve; của cả bộ nhớ hệ thống v&agrave; bộ nhớ đồ hoạ, giống với iOS, được gọi l&agrave; Kiến tr&uacute;c bộ nhớ hợp nhất (UMA), mang tới hiệu suất xử l&yacute; đồ họa nhanh hơn so với đồ họa t&iacute;ch hợp, nhưng cahcs l&agrave;m n&agrave;y c&oacute; thể đ&aacute;nh dấu sự kết th&uacute;c của những chiếc GPU rời tr&ecirc;n m&aacute;y t&iacute;nh Mac. V&agrave; mặc d&ugrave; UMA kh&ocirc;ng g&acirc;y ra bất kỳ vấn đề tương th&iacute;ch n&agrave;o với c&aacute;c ứng dụng trong thử nghiệm của ch&uacute;ng t&ocirc;i, nhưng c&oacute; thể c&oacute; những ứng dụng chuy&ecirc;n biệt cần phải được cập nhật để c&oacute; thể hoạt động tr&ecirc;n những m&aacute;y n&agrave;y.</p>\r\n\r\n<p>Điều đ&oacute; cho thấy rằng, một trong những điều m&agrave; Apple cứ nhắc đi nhắc lại về những chiếc m&aacute;y t&iacute;nh M1, rằng ch&uacute;ng vẫn l&agrave; những chiếc m&aacute;y Mac, m&ocirc; h&igrave;nh hệ điều h&agrave;nh v&agrave; ứng dụng cũng c&oacute; t&iacute;nh mở như bất kỳ chiếc m&aacute;y Mac n&agrave;o kh&aacute;c. Hy vọng rằng điều đ&oacute; c&oacute; nghĩa rằng ch&uacute;ng ta sẽ sớm được biết những th&ocirc;ng tin hữu &iacute;ch về giới hạn của những con chip M1, khi ng&agrave;y c&agrave;ng c&oacute; nhiều người, nhiều đơn vị tạo ra những tiện &iacute;ch v&agrave; phần mềm test hiệu năng (benchmark) cho n&oacute;. V&agrave; t&ocirc;i hy vọng Apple sẽ cung cấp th&ecirc;m th&ocirc;ng tin cụ thể hơn về con chip của họ, khi c&ocirc;ng ty tiến h&agrave;nh mở rộng việc &aacute;p dụng kiến tr&uacute;c chip n&agrave;y sang c&aacute;c d&ograve;ng m&aacute;y kh&aacute;c của h&atilde;ng - những người d&ugrave;ng chuy&ecirc;n nghiệp hoạt động trong lĩnh vực thiết kế c&aacute;c ứng dụng chắc chắn sẽ muốn biết th&ocirc;ng tin n&agrave;y.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Đánh giá MacBook Pro dùng chip M1: Khi chữ ‘pro\' nằm ở… quạt tản nhiệt\" src=\"https://vnreview.vn/image/21/64/90/2164909.jpg?t=1611738012707\" width=\"100%\" /></p>\r\n\r\n<p>Phần c&ograve;n lại của chiếc MacBook Pro 13-inch n&agrave;y giống hệt như mẫu MacBook Pro sử dụng chip Intel gần nhất m&agrave; c&ocirc;ng ty ra mắt: hai cổng kết nối USB-C, một m&agrave;n h&igrave;nh độ s&aacute;ng 500 nit, b&agrave;n ph&iacute;m &quot;cũ m&agrave; mới&quot; với thiết kế lẫy k&eacute;o, thanh Touch Bar v&agrave; webcam độ ph&acirc;n giải &quot;đ&aacute;ng buồn&quot; l&agrave; 720p.</p>\r\n\r\n<p>Apple cho biết c&ocirc;ng ty sử dụng những kỹ thuật xử l&yacute; h&igrave;nh ảnh mang từ iPhone l&ecirc;n m&aacute;y Mac M1 để cải thiện h&igrave;nh ảnh thu được từ webcam, v&agrave; bạn c&oacute; thể thấy r&otilde; kết quả của những tinh chỉnh đ&oacute;. Mặt người được l&agrave;m s&aacute;ng hơn, v&agrave; phần phơi s&aacute;ng hậu cảnh cũng đẹp hơn. Nhưng bạn cũng c&oacute; thể nhận thấy trong một số trường hợp, sự &quot;xử l&yacute;&quot; đ&oacute; cũng khiến chất lượng h&igrave;nh ảnh tổng thể trở n&ecirc;n tệ hơn thay v&igrave; tốt l&ecirc;n. L&uacute;c đầu, ch&uacute;ng t&ocirc;i thực sự c&oacute; &yacute; định cho chiếc m&aacute;y n&agrave;y 10/10 điểm đ&aacute;nh gi&aacute;, nhưng chất lượng camera đ&atilde; khiến ch&uacute;ng t&ocirc;i kh&ocirc;ng thể l&agrave;m vậy, nhất l&agrave; khi đ&acirc;y l&agrave; một chiếc laptop &quot;pro&quot;, đắt hơn so với MacBook Air.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Đánh giá MacBook Pro dùng chip M1: Khi chữ ‘pro\' nằm ở… quạt tản nhiệt\" src=\"https://vnreview.vn/image/21/64/89/2164897.jpg?t=1611738012707\" width=\"100%\" /></p>\r\n\r\n<p>T&ocirc;i cũng sẽ kh&ocirc;ng đề cập đến thanh Touch Bar qu&aacute; nhiều ngoại trừ việc b&igrave;nh thường, t&ocirc;i sẽ kh&ocirc;ng cần nh&igrave;n v&agrave;o b&agrave;n ph&iacute;m khi g&otilde; đ&acirc;u, nhưng nếu khi g&otilde; m&agrave; cứ phải nh&igrave;n xuống m&agrave;n h&igrave;nh nhỏ của Touch Bar để điều chỉnh những thứ như &acirc;m lượng v&agrave; độ s&aacute;ng th&igrave; th&agrave; d&ugrave;ng ph&iacute;m vật l&yacute; c&ograve;n hơn, v&agrave; thậm ch&iacute; điều n&agrave;y c&ograve;n nghi&ecirc;m trọng hơn khi c&aacute;c n&uacute;t điều khiển của macOS Big Sur đ&atilde; được thiết kế lại tr&ocirc;ng giống như tr&ecirc;n iOS&hellip; Việc n&agrave;y khiến t&ocirc;i cứ bị nhầm, cứ chạm tay v&agrave;o m&agrave;n h&igrave;nh của MacBook trong khi n&oacute; l&agrave;m g&igrave; c&oacute; cảm ứng!</p>\r\n\r\n<p>Sự &quot;cứng đầu&quot; của Apple khi cho rằng m&agrave;n h&igrave;nh cảm ứng tr&ecirc;n laptop l&agrave; kh&ocirc;ng cần thiết v&agrave; phiền phức đ&atilde; trở n&ecirc;n ngớ ngẩn, đặc biệt l&agrave; khi việc n&agrave;y tr&ecirc;n iPad v&agrave; thế giới laptop Windows đ&acirc;u c&oacute; đem lại điều g&igrave; phiền phức đ&acirc;u. Hy vọng rằng trong năm tới, c&ocirc;ng ty sẽ &quot;giả vờ&quot; th&ocirc;ng b&aacute;o rằng họ đ&atilde; ph&aacute;t hiện ra một c&aacute;ch mới để hiện thực ho&aacute; &quot;điều hiển nhi&ecirc;n&quot;, đ&oacute; l&agrave; đưa m&agrave;n h&igrave;nh cảm ứng l&ecirc;n Mac v&agrave; loại bỏ thanh Touch Bar.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Đánh giá MacBook Pro dùng chip M1: Khi chữ ‘pro\' nằm ở… quạt tản nhiệt\" src=\"https://vnreview.vn/image/21/64/90/2164900.jpg?t=1611738012707\" width=\"100%\" /></p>\r\n\r\n<p>C&oacute; hai điều để n&oacute;i về chiếc MacBook Pro 13-inch sử dụng chip M1: một l&agrave;, bản th&acirc;n con chip M1 v&agrave; biết bao c&ocirc;ng sức m&agrave; Apple đ&atilde; đổ v&agrave;o để gi&uacute;p việc chuyển đổi nền tảng vi xử l&yacute; trở n&ecirc;n nhẹ nh&agrave;ng l&agrave; một th&agrave;nh c&ocirc;ng đ&aacute;ng ca ngợi; v&agrave; thứ hai, ch&iacute;nh chiếc MacBook Pro 13-inch n&agrave;y đ&atilde; kh&ocirc;ng thể chứng tỏ rằng n&oacute; l&agrave; một bản n&acirc;ng cấp đ&aacute;ng để người d&ugrave;ng &quot;r&uacute;t hầu bao&quot; so với chiếc MacBook Air M1.</p>\r\n\r\n<p>Thật vậy, n&oacute; chỉ mang đến hiệu năng tốt hơn ch&uacute;t x&iacute;u trong trường hợp bạn phải thao t&aacute;c trong thời gian d&agrave;i v&agrave; thời lượng pin cao hơn đ&ocirc;i ch&uacute;t so với MacBook Air. Nhưng th&ocirc;i, th&agrave; đ&aacute;nh đổi v&agrave;i gi&acirc;y render nhanh hơn của chiếc m&aacute;y n&agrave;y để đổi lấy sự &quot;biến mất&quot; của Touch Bar tr&ecirc;n MacBook Air M1 c&ograve;n hơn! V&agrave; thực ra, nếu bạn thực sự nghi&ecirc;m t&uacute;c v&agrave; cần sức mạnh xử l&yacute; cao hơn, th&igrave; c&oacute; lẽ bạn sẽ cần nhiều hơn 2 cổng kết nối, nhiều hơn 16GB bộ nhớ RAM, v&agrave; nhiều hơn 1 m&agrave;n h&igrave;nh ngo&agrave;i&hellip; Thế n&ecirc;n, c&oacute; thể n&oacute;i chiếc m&aacute;y n&agrave;y giống như một c&ocirc; cậu tuổi teen - một thiếu ni&ecirc;n xuất sắc, năng động - nhưng vẫn chỉ l&agrave; &quot;teen&quot; m&agrave; th&ocirc;i, chứ chưa trưởng th&agrave;nh.</p>', 'MacBook-Pro-M1-blog.jpg', 9, 'REVIEW', 2, '2021-07-18 21:39:28', '2021-07-19 15:41:11', 1, '2021-07-19 15:41:11');
INSERT INTO `tintuc` (`Id`, `TieuDe`, `MoTa`, `NoiDung`, `Anh`, `LuotXem`, `ChuDeId`, `BloggerId`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (2, 'Review  bàn phím cơ Keydous NJ68', '', '<p>Đ&acirc;y l&agrave;&nbsp;review&nbsp;về&nbsp;<a href=\"http://127.0.0.1:8000/thuonghieu/sanpham/KEYDOUS\">Keydous</a> NJ68&nbsp;của m&igrave;nh. M&igrave;nh mua n&oacute; với gi&aacute; 3 triệu cả keycap. Hi vọng phần review sẽ hữu &iacute;ch cho bạn n&agrave;o muốn mua nh&eacute;, nếu bạn c&oacute; c&acirc;u hỏi g&igrave; th&igrave; h&atilde;y comment v&ocirc; b&agrave;i n&agrave;y nha.</p>\r\n\r\n<h3><strong>Những thứ m&igrave;nh th&iacute;ch:</strong></h3>\r\n\r\n<p>Con n&agrave;y m&igrave;nh mới mua để mang l&ecirc;n c&ocirc;ng ty, bản m&agrave;u đen. Con trắng hồng để nh&agrave; d&ugrave;ng<br />\r\nInfo con trắng: Switch alpacas, keycap SA Maxkey Pink White<br />\r\nInfo con đen: Switch C3 tangerine, keycap gốc<br />\r\nC&aacute; nh&acirc;n thấy những điểm nổi trội của con n&agrave;y như sau:</p>\r\n\r\n<ul>\r\n	<li>Build cứng c&aacute;p, vỏ nhựa nhưng b&ecirc;n trong c&oacute; khung th&eacute;p, plate th&eacute;p n&ecirc;n rất ok chứ kh&ocirc;ng hề c&oacute; hiện tượng flex</li>\r\n	<li>Hot Swap. Điểm ăn tiền nhất với m&igrave;nh v&igrave; m&igrave;nh hay th&iacute;ch trải nghiệm nhiều loại switch kh&aacute;c nhau. Hiện tại con cả 2 con trắng đen đều lắp switch linear (con đen lắp C3 tangerine, trắng lắp alpacas, đều l&agrave; linear h&agrave;ng t&oacute;p hiện nay)</li>\r\n	<li>Nhiều loại phụ kiện: thay top cover c&aacute;c m&agrave;u trắng, đen, v&agrave;ng, trong suốt. Tr&ecirc;n chợ ph&iacute;m cơ rất nhiều</li>\r\n	<li>Dễ mua: Con n&agrave;y tr&ecirc;n chợ ph&iacute;m cơ rất nhiều anh em mua/b&aacute;n, chỉ l&ecirc;n hỏi 1 tẹo l&agrave; c&oacute; người b&aacute;n</li>\r\n	<li>Kết nối: Lựa chọn giữa bluetooth v&agrave; c&oacute; d&acirc;y, bluetooth nhanh, ổn định, wake từ sleep l&ecirc;n cũng rất nhanh</li>\r\n	<li>Rẻ: Kit kh&ocirc;ng switch full mod (l&oacute;t foam, mod stab) chỉ khoảng 1tr4, keycap gốc 300k, switch d&ugrave;ng gateron milky yellow chỉ khoảng 500k full mod, tổng 2tr2 l&agrave; đ&atilde; c&oacute; 1 con ph&iacute;m cơ cực ngon rồi. Tầm tiền n&agrave;y đập chết ăn thịt mọi thể loại ph&iacute;m stock</li>\r\n</ul>\r\n\r\n<h3><strong>C&ograve;n m&igrave;nh kh&ocirc;ng th&iacute;ch những thứ như sau:</strong></h3>\r\n\r\n<ul>\r\n	<li>Led kh&ocirc;ng qu&aacute; s&aacute;ng, tuy nhi&ecirc;n m&igrave;nh kh&ocirc;ng d&ugrave;ng led mấy n&ecirc;n đ&acirc;y cũng kh&ocirc;ng thật sự l&agrave; 1 điểm trừ</li>\r\n	<li>Stab gốc kh&ocirc;ng qu&aacute; ngon, như m&igrave;nh th&igrave; thay lu&ocirc;n</li>\r\n</ul>\r\n\r\n<h4><strong>H&igrave;nh ảnh:</strong></h4>\r\n\r\n<p style=\"text-align:center\"><img alt=\"photo_2021-02-19_11-16-29.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2021/02/5357208_photo_2021-02-19_11-16-29.jpg\" width=\"100%\" /><br />\r\n<br />\r\n<img alt=\"photo_2021-02-19_11-16-29 (3).jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2021/02/5357167_photo_2021-02-19_11-16-29_3.jpg\" width=\"100%\" /><br />\r\n<br />\r\n<img alt=\"photo_2021-02-19_11-16-29 (2).jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2021/02/5357168_photo_2021-02-19_11-16-29_2.jpg\" width=\"100%\" /><br />\r\n<br />\r\n<img alt=\"photo_2021-02-19_11-18-45.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2021/02/5357195_photo_2021-02-19_11-18-45.jpg\" width=\"100%\" /></p>', 'nj68-blog.jpg', 14, 'REVIEW', 2, '2021-07-18 23:06:46', '2021-07-19 12:20:53', 1, '2021-07-19 10:06:16');
INSERT INTO `tintuc` (`Id`, `TieuDe`, `MoTa`, `NoiDung`, `Anh`, `LuotXem`, `ChuDeId`, `BloggerId`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (3, 'Trên tay màn hình LG 27UL850: 27\" 4K, kết nối USB-C, thích hợp làm đồ họa, giải trí: giá 9.5 triệu', '<p><strong><a href=\"http://127.0.0.1:8000/thuonghieu/sanpham/LG\">LG</a>&nbsp;UL850 l&agrave; một trong những d&ograve;ng sản phẩm <a href=\"http://127.0.0.1:8000/danhmuc/sanpham/MH\">m&agrave;n h&igrave;nh m&aacute;y t&iacute;nh</a> hỗ trợ độ ph&acirc;n giải 4K UHD ở ph&acirc;n kh&uacute;c cao cấp. Với k&iacute;ch thước 27&rdquo;, m&agrave;n h&igrave;nh n&agrave;y ph&ugrave; hợp với đối tượng người d&ugrave;ng thiết kế đồ hoạ, xem phim tương th&iacute;ch với chuẩn HDR10 v&agrave; kết nối USB-C tiện dụng.</strong></p>', '<p>Theo t&ecirc;n gọi, UL850 được định vị ở ph&acirc;n kh&uacute;c cao cấp của LG d&agrave;nh cho m&agrave;n h&igrave;nh độ ph&acirc;n giải UHD. Trước đ&acirc;y, LG từng b&aacute;n phi&ecirc;n bản m&agrave;n h&igrave;nh UD88 c&oacute; th&ocirc;ng số tương tự. Đ&acirc;y l&agrave; một phi&ecirc;n bản mới hơn của chiếc m&agrave;n h&igrave;nh đ&oacute;.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_2.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4699996_LG_27UL850_tinhte_2.jpg\" width=\"100%\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>LG đ&atilde; thiết kế chiếc m&agrave;n h&igrave;nh n&agrave;y hướng đến việc lắp đặt nhanh ch&oacute;ng. Ch&acirc;n đế được kết nối với m&agrave;n h&igrave;nh ho&agrave;n to&agrave;n bằng khớp v&agrave; n&uacute;t bấm. B&ecirc;n cạnh đ&oacute; gi&aacute; đỡ v&agrave; ch&acirc;n k&ecirc; m&agrave;n h&igrave;nh cũng sử dụng v&iacute;t c&oacute; hỗ trợ xiết bằng tay, v&igrave; vậy ch&uacute;ng ta kh&ocirc;ng cần phải d&ugrave;ng v&iacute;t để cố định những th&agrave;nh phần của m&agrave;n h&igrave;nh n&agrave;y lại.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_4.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4699998_LG_27UL850_tinhte_4.jpg\" width=\"100%\" /></p>\r\n\r\n<p>Về thiết kế, LG vẫn trung th&agrave;nh với kiểu d&aacute;ng viền mỏng 3 cạnh đ&atilde; &aacute;p dụng tr&ecirc;n nhiều d&ograve;ng sản phẩm m&agrave;n h&igrave;nh gần đ&acirc;y. So với phi&ecirc;n bản UD88 trước đ&oacute;, cạnh dưới của m&agrave;n h&igrave;nh tiếp gi&aacute;p với miếng nhựa nẹp ở ph&iacute;a trước được thu gọn hơn. C&aacute;c cạnh c&ograve;n lại c&oacute; khung mỏng, k&iacute;nh bảo vệ ốp l&ecirc;n ph&iacute;a tr&ecirc;n tấm nền thiết kế tr&agrave;n viền. B&ecirc;n trong phần viền m&agrave;n h&igrave;nh c&oacute; 3 cạnh mỏng thiết kế đều.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_6.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4700000_LG_27UL850_tinhte_6.jpg\" width=\"100%\" /></p>\r\n\r\n<p>LG sử dụng lớp phủ chống ch&oacute;i cho m&agrave;n h&igrave;nh. V&igrave; vậy n&oacute; sẽ kh&ocirc;ng bị phản chiếu &aacute;nh s&aacute;ng hay vật thể giống như m&agrave;n h&igrave;nh phủ gương. UL850 vẫn sử dụng tấm nền IPS độ ph&acirc;n giải 3.840 x 2.160 pixel với độ phủ m&agrave;u 99% sRGB theo nh&agrave; sản xuất c&ocirc;ng bố. M&agrave;n h&igrave;nh n&agrave;y hỗ trợ c&ocirc;ng nghệ hiển thị HDR 10 v&agrave; DisplayHDR&trade; 400, độ s&aacute;ng tối đa đạt mức 350 cd/m&sup2;.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_11.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4700005_LG_27UL850_tinhte_11.jpg\" width=\"100%\" /></p>\r\n\r\n<p>LG đơn giản ho&aacute; c&aacute;c cổng kết nối ở mặt lưng, thay v&igrave; đặt ở cạnh dưới để mang lại một thiết kế đẹp mắt. Việc sử dụng adapter rời cũng khiến m&agrave;n h&igrave;nh mỏng v&agrave; nhẹ hơn. C&aacute;c kết nối t&iacute;n hiệu phổ biến hiện nay được nh&agrave; sản xuất trang bị gồm DisplayPort, HDMI (2 cổng) v&agrave; USB-C. Trong đ&oacute; USB-C c&oacute; 3 vai tr&ograve;: xuất t&iacute;n hiệu từ thiết bị ph&aacute;t, hỗ trợ sạc cho thiết bị di động l&ecirc;n đến 60W v&agrave; l&agrave;m d&acirc;y kết nối t&iacute;n hiệu cho cổng USB-A ở ph&iacute;a sau. LG kh&ocirc;ng đặt c&aacute;c cổng kết nối USB ở b&ecirc;n h&ocirc;ng m&agrave;n h&igrave;nh như một số d&ograve;ng m&agrave;n h&igrave;nh cho doanh nghiệp.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_18.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4700018_LG_27UL850_tinhte_18.jpg\" width=\"100%\" /></p>\r\n\r\n<p>Với những nguồn v&agrave;o kh&aacute;c nhau, m&agrave;n h&igrave;nh tự nhận diện những th&ocirc;ng số ph&ugrave; hợp cho việc hiển thị. V&igrave; vậy khi m&igrave;nh kết nối m&aacute;y t&iacute;nh MacBook hay điện thoại v&agrave;o th&igrave; m&agrave;u sắc thể hiện tương đồng. Ri&ecirc;ng chiếc iPad Pro 2018 mới sử dụng iOS 13 cần tắt chức năng hiển thị HDR sẽ ra đ&uacute;ng m&agrave;u sắc mong muốn.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_8.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4700002_LG_27UL850_tinhte_8.jpg\" width=\"100%\" /></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>UL850 tiếp tục sử dụng ph&iacute;m nguồn dạng điều khiển 5 chiều. N&uacute;t chức năng n&agrave;y rất hữu &iacute;ch khi bạn c&oacute; thể điều chỉnh nhanh chức năng chỉnh &acirc;m lượng với loa đi k&egrave;m chỉ bằng 1-2 lần thao t&aacute;c.</p>\r\n\r\n<p>N&oacute;i chung, ph&acirc;n kh&uacute;c m&agrave;n h&igrave;nh 4K ở Việt Nam vẫn chưa c&oacute; nhiều lựa chọn k&iacute;ch thước nhỏ hơn 27&rdquo;. V&igrave; vậy những sản phẩm ở k&iacute;ch thước n&agrave;y vẫn l&agrave; sự lựa chọn ph&ugrave; hợp cho việc sử dụng đa mục đ&iacute;ch: sử dụng Windows, Mac, tr&igrave;nh chiếu nội dung từ set-top-box&hellip; Với cổng USB-C, anh em sẽ c&oacute; được sự tiện lợi khi vừa kết nối m&agrave;n h&igrave;nh, vừa sạc pin thiết bị di động. Chi tiết trải nghiệm s&acirc;u hơn về chiếc m&agrave;n h&igrave;nh n&agrave;y sẽ được tr&igrave;nh b&agrave;y trong một b&agrave;i viết kh&aacute;c. Anh em quan t&acirc;m h&atilde;y đ&oacute;n theo d&otilde;i nh&eacute;.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_1.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4699995_LG_27UL850_tinhte_1.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_3.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4699997_LG_27UL850_tinhte_3.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_7.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4700001_LG_27UL850_tinhte_7.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_12.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4700024_LG_27UL850_tinhte_12.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_9.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4700003_LG_27UL850_tinhte_9.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_10.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4700004_LG_27UL850_tinhte_10.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_15.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4700009_LG_27UL850_tinhte_15.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_14.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4700025_LG_27UL850_tinhte_14.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_13.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4700021_LG_27UL850_tinhte_13.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_5.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4699999_LG_27UL850_tinhte_5.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_16.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4700010_LG_27UL850_tinhte_16.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"LG_27UL850_tinhte_17.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2019/06/4700017_LG_27UL850_tinhte_17.jpg\" width=\"100%\" /></p>', '4700029_cover_LG_27UL850_tinhte_blog.jpg', 12, 'ONHAND', 5, '2021-07-19 15:00:01', '2021-07-19 15:13:00', 1, '2021-07-19 15:10:30');
INSERT INTO `tintuc` (`Id`, `TieuDe`, `MoTa`, `NoiDung`, `Anh`, `LuotXem`, `ChuDeId`, `BloggerId`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (4, 'MacBook Air vs. MacBook Pro mới: khác biệt ở quạt tản nhiệt; số nhân GPU tuy cùng sử dụng Apple M1', '<p><strong>Hơi lạ khi&nbsp;MacBook Air&nbsp;v&agrave;&nbsp;MacBook Pro 13&quot;&nbsp;mới c&oacute; cấu h&igrave;nh rất giống nhau: c&ugrave;ng l&agrave; chip&nbsp;Apple M1&nbsp;mới, nhưng hai m&aacute;y lại c&oacute; mức gi&aacute; ch&ecirc;nh lệch kh&aacute; nhiều: $999 vs. $1299. Kh&ocirc;ng lẽ chỉ v&igrave; thiết kế kh&aacute;c nhau v&agrave; th&ecirc;m c&aacute;i Touch Bar m&agrave; sự kh&aacute;c biệt nhiều vậy sao? H&oacute;a ra sự kh&aacute;c biệt c&ograve;n nằm ở nhiều chỗ hơn nữa: quạt, v&agrave; ch&iacute;nh con chip&nbsp;Apple M1&nbsp;cho hai m&aacute;y n&agrave;y cũng kh&aacute;c nhau.</strong></p>', '<h4><strong>Quạt l&agrave; điểm kh&aacute;c biệt lớn</strong></h4>\r\n\r\n<p><br />\r\nĐầu ti&ecirc;n l&agrave; quạt tản nhiệt. Tr&ecirc;n&nbsp;<a href=\"https://tinhte.vn/macbook/\">MacBook</a>&nbsp;Air 13&quot; mới,&nbsp;<a href=\"https://tinhte.vn/tags/apple/\">Apple</a>&nbsp;kh&ocirc;ng sử dụng quạt tản nhiệt, đ&acirc;y l&agrave; cơ chế tản nhiệt thụ động gần giống như c&aacute;ch m&agrave; thiết bị di động tản nhiệt. Trong khi đ&oacute;, MacBook Pro 13&quot; c&oacute; quạt l&agrave;m m&aacute;t giống như nhiều chiếc laptop truyền thống (Apple gọi l&agrave; l&agrave;m m&aacute;t chủ động - active cooling). C&oacute; một điều th&uacute; vị, đ&oacute; l&agrave; điểm d&agrave;y nhất của MacBook Air l&agrave; 1,61cm, tức d&agrave;y hơn cả điểm d&agrave;y nhất của MacBook Pro mới l&agrave; 1,56cm.<br />\r\n<br />\r\nKh&ocirc;ng chỉ ri&ecirc;ng với chip M1 m&agrave; c&aacute;c CPU hiện đại ng&agrave;y nay đều c&oacute; khả năng hoạt động nhanh hơn, hiệu năng cao hơn khi được l&agrave;m m&aacute;t tốt hơn. C&aacute;c con chip ng&agrave;y nay c&oacute; thể tăng xung nhịp của nh&acirc;n xử l&yacute; l&ecirc;n rất cao, l&ecirc;n mức 3-4GHz, cho tới khi ch&uacute;ng chạm một ngưỡng nhiệt độ nhất định th&igrave; sẽ giảm xung lại v&agrave; hoạt động chậm hơn để giảm nhiệt lượng tỏa ra. Nếu bạn l&agrave;m m&aacute;t cho CPU đủ tốt, ch&uacute;ng c&oacute; thể duy tr&igrave; việc hoạt động ở mức hiệu năng cao trong thời gian d&agrave;i hơn so với việc kh&ocirc;ng được l&agrave;m m&aacute;t.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"macbook_pro_fan_gif.gif\" src=\"https://photo2.tinhte.vn/data/attachment-files/2020/11/5217588_macbook_pro_fan_gif.gif\" /></p>\r\n\r\n<p>Apple x&aacute;c nhận với trang The Verge rằng chip Apple M1 trong MacBook Air, MacBook Pro v&agrave; Mac Mini mới hoạt động theo c&aacute;ch tương tự. 3 d&ograve;ng m&aacute;y n&agrave;y d&ugrave;ng chung bộ xử l&yacute; với nhau (thật ra c&oacute; kh&aacute;c một ch&uacute;t, sẽ n&oacute;i tới sau), tức l&agrave; theo l&yacute; thuyết ch&uacute;ng sẽ chạy được ở c&ugrave;ng tốc độ với nhau, nhưng nhờ quạt của MacBook Pro v&agrave; Mac Mini n&ecirc;n chip Apple M1 trong 2 chiếc m&aacute;y n&agrave;y c&oacute; thể chạy ở mức hiệu năng cao trong thời gian&nbsp;<em><strong>d&agrave;i hơn</strong></em>&nbsp;so với MacBook Air.<br />\r\n<br />\r\nĐiều n&agrave;y l&agrave; hợp l&yacute; v&igrave; người d&ugrave;ng MacBook Pro, Mac Mini thường phải l&agrave;m những việc nặng hơn so với MacBook Air, v&iacute; dụ như xuất phim 4K, chỉnh sửa h&agrave;ng loạt ảnh hoặc c&aacute;c ảnh độ ph&acirc;n giải rất cao, thậm ch&iacute; l&agrave; chạy m&aacute;y ảo, bi&ecirc;n dịch code, chạy c&aacute;c t&aacute;c vụ machine learning, phần mềm kĩ thuật&hellip; Với những t&aacute;c vụ n&agrave;y, hiệu năng cao hơn sẽ r&uacute;t ngắn thời gian chờ đợi để ra được kết quả.<br />\r\n&nbsp;</p>\r\n\r\n<h4><strong>Ngo&agrave;i ra con chip Apple M1 cũng kh&aacute;c nhau nữa nh&eacute;!</strong></h4>\r\n\r\n<p><br />\r\nNghe lạ đ&uacute;ng kh&ocirc;ng? Ủa c&ugrave;ng l&agrave; chip M1 m&agrave; sao kh&aacute;c nhau được.<br />\r\n<br />\r\nThật ra l&agrave; c&oacute; đấy, v&agrave; n&oacute; cũng đ&atilde; xuất hiện từ l&acirc;u trong thế giới chip, b&aacute;n dẫn.&nbsp;C&oacute; một kh&aacute;i niệm gọi l&agrave; chip binning, hay CPU binning. Vi xử l&yacute; được sản xuất từ c&aacute;c tấm wafer silicon v&agrave; đ&acirc;y l&agrave; một qu&aacute; tr&igrave;nh sản xuất đ&ograve;i hỏi độ ch&iacute;nh x&aacute;c cực cao. Tấm wafer h&igrave;nh tr&ograve;n cỡ lớn được xử l&yacute; bằng nhiều vật liệu v&agrave; được in quang khắc vi mạch theo kiến tr&uacute;c vi xử l&yacute; đ&atilde; thiết kế. Qu&aacute; tr&igrave;nh sản xuất c&ograve;n c&oacute; nhiều kh&acirc;u như bắn ph&aacute; bằng ch&ugrave;m ion năng lượng cao, sửa cấu tr&uacute;c tinh thể v&agrave; tạo ra một lớp silicon oxide trong l&ograve; hấp rồi lại đưa v&agrave;o buồng ch&acirc;n kh&ocirc;ng để lắng đọng th&ecirc;m một lớp đồng v&agrave; khắc c&aacute;c lớp kim loại hay oxide bằng acid mạnh.<br />\r\n<br />\r\nVới h&agrave;ng t&aacute; c&aacute;c kh&acirc;u xử l&yacute; phức tạp, thời gian xử l&yacute; c&oacute; khi ngắn chỉ v&agrave;i gi&acirc;y c&oacute; khi d&agrave;i trong khi điều kiện xử l&yacute; c&oacute; thể rất khắc nghiệt như nhiệt độ cao, m&ocirc;i trường acid cao, chưa kể l&agrave; khiếm khuyết về vật liệu &hellip; v&agrave; đế chip th&igrave; lại qu&aacute; nhỏ th&agrave;nh ra những kh&aacute;c biệt tr&ecirc;n đế chip xuất hiện. Sẽ c&oacute; những đế chip cực tốt nhưng cũng c&oacute; những đế k&eacute;m chất lượng. Những đế chip n&agrave;y được đưa v&agrave;o một quy tr&igrave;nh kiểm tra v&agrave; s&agrave;ng lọc rồi ph&acirc;n loại dựa tr&ecirc;n hiệu năng của n&oacute;.<br />\r\n<br />\r\nCPU Core i9, i7, i5, i3 ra đời cũng dựa tr&ecirc;n sự s&agrave;ng lọc n&agrave;y. Chẳng hạn như d&ograve;ng Core i5, nếu một con CPU th&agrave;nh phẩm kh&ocirc;ng đ&aacute;p ứng được c&aacute;c ti&ecirc;u chuẩn đặt ra th&igrave; Intel sẽ &quot;bin&quot; n&oacute; th&agrave;nh một con Core i3.</p>\r\n\r\n<p><br />\r\nQuay trở lại với d&ograve;ng chip Apple M1:</p>\r\n\r\n<ul>\r\n	<li>Tr&ecirc;n chiếc MacBook Air cấu h&igrave;nh thấp nhất gi&aacute; $999, n&oacute; chỉ c&oacute; 7 nh&acirc;n GPU thay v&igrave; 8 nh&acirc;n, đ&acirc;y ch&iacute;nh l&agrave; những con chip &ldquo;yếu hơn&rdquo; được ph&acirc;n loại ra trong qu&aacute; tr&igrave;nh binning. Apple cố t&igrave;nh v&ocirc; hiệu h&oacute;a 1 nh&acirc;n GPU để chip giữ được hiệu năng đủ tốt</li>\r\n	<li>Nhưng chiếc MacBook Air cấu h&igrave;nh cao gi&aacute; $1249 lại c&oacute; đầy đủ 8 nh&acirc;n GPU</li>\r\n	<li>Chiếc MacBook Pro 13&quot; khởi điểm $1299 c&oacute; đầy đủ 8 nh&acirc;n GPU</li>\r\n</ul>\r\n\r\n<p style=\"text-align:center\"><img alt=\"apple_m1_gpu.jpg\" src=\"https://photo2.tinhte.vn/data/attachment-files/2020/11/5217586_apple_m1_gpu.jpg\" width=\"100%\" /></p>\r\n\r\n<p>H&atilde;y nh&igrave;n v&agrave;o tấm h&igrave;nh tr&ecirc;n, đ&acirc;y l&agrave; slide giới thiệu chip Apple M1. Họ n&oacute;i l&agrave; &ldquo;tối đa 8 nh&acirc;n&rdquo;, chứ kh&ocirc;ng phải chip M1 n&agrave;o cũng c&oacute; 8 nh&acirc;n nh&eacute;.<br />\r\n<br />\r\nMột số điểm kh&aacute;c biệt kh&aacute;c:</p>\r\n\r\n<ul>\r\n	<li>Ngo&agrave;i ra MacBook Pro 13&quot; c&oacute; dung lượng pin to hơn so với MacBook Air (58.2Wh vs. 49.9Wh), đ&acirc;y l&agrave; l&yacute; do ch&iacute;nh dẫn đến việc Pro 13&quot; c&oacute; thời gian d&ugrave;ng pin l&ecirc;n tới 20 tiếng trong khi Air chỉ 18 tiếng</li>\r\n	<li>M&agrave;n h&igrave;nh của MacBook Pro 13&quot; c&oacute; độ s&aacute;ng cao hơn (500 nit vs 400 nit)</li>\r\n	<li>MacBook Pro 13&quot; c&oacute; Touch Bar thay v&igrave; h&agrave;ng ph&iacute;m Fn vật l&yacute; trong khi MacBook Air kh&ocirc;ng c&oacute;, nhưng cả hai đều sở hữu cảm biến v&acirc;n tay.</li>\r\n</ul>\r\n\r\n<p><br />\r\nHiện tại dung lượng RAM tối đa m&agrave; chip Apple M1 c&oacute; thể đảm đương l&agrave; 16GB, n&ecirc;n bạn sẽ kh&ocirc;ng thể t&igrave;m thấy t&ugrave;y chọn cấu h&igrave;nh cao hơn. Thật ra 16GB l&agrave; đủ d&ugrave;ng cho đa số mọi người rồi n&ecirc;n đoạn n&agrave;y kh&ocirc;ng cần lăn tăn.</p>', 'cover_home_macbook_air_pro_Apple_M1.jpg', 4, 'COMPARE', 3, '2021-07-19 15:22:07', '2021-07-21 17:30:57', 2, '2021-07-21 17:30:57');
INSERT INTO `tintuc` (`Id`, `TieuDe`, `MoTa`, `NoiDung`, `Anh`, `LuotXem`, `ChuDeId`, `BloggerId`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (5, 'Hot: Đây là củ sạc Omega 200W - Tương lai với của sạc di động', '<p><strong>Đ&acirc;y l&agrave; củ sạc Omega 200w đến từ thương hiệu ChargeAsap. Dự &aacute;n n&agrave;y đang được k&ecirc;u gọi vốn tr&ecirc;n Kickstarter v&agrave; đạt được th&agrave;nh c&ocirc;ng ngo&agrave;i mong đợi với số tiền l&ecirc;n đến 1.5 triệu đ&ocirc;.</strong></p>', '<p>C&ugrave;ng với bản Omega 200W th&igrave; ChargeAsap Việt Nam cũng tiết lộ những mẫu sạc Omega c&oacute; c&ocirc;ng suất 100W v&agrave; 65W với k&iacute;ch thước si&ecirc;u nhỏ cũng sẽ sắp c&oacute; mặt tại Việt Nam</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://channel.mediacdn.vn/2020/12/4/photo-1-16070508871121154351831.jpg\" target=\"_blank\" title=\"Những hình ảnh được cung cấp với ChargeAsap Việt Nam\"><img alt=\"Hot: Đây là củ sạc Omega 200W – Tương lai với của sạc di động - Ảnh 1.\" height=\"\" src=\"https://channel.mediacdn.vn/thumb_w/640/2020/12/4/photo-1-16070508871121154351831.jpg\" title=\"Hot: Đây là củ sạc Omega 200W – Tương lai với của sạc di động - Ảnh 1.\" width=\"\" /></a></p>\r\n\r\n<p>Những h&igrave;nh ảnh được cung cấp với ChargeAsap Việt Nam</p>\r\n\r\n<p>Đầu ti&ecirc;n về ngoại h&igrave;nh tuy c&oacute; c&ocirc;ng suất l&ecirc;n đến 200W nhưng rất bất ngờ khi m&agrave; Omega chỉ to đ&uacute;ng bằng 1 chiếc thẻ ATM m&agrave; th&ocirc;i. Phi&ecirc;n bản tr&ecirc;n h&igrave;nh c&oacute; t&ocirc;ng m&agrave;u v&agrave;ng đen với t&ecirc;n h&atilde;ng ChargeAsap được in ngược nhau ở 2 mặt. Phần m&agrave;u đen của sạc được phủ 1 lớp nhung mỏng cho cảm gi&aacute;c cầm cực kỳ th&iacute;ch tay v&agrave; cảm gi&aacute;c cầm nắm cũng được cải thiện nhưng với chất liệu n&agrave;y th&igrave; khi d&ugrave;ng sẽ kh&aacute; b&aacute;m mồ h&ocirc;i cũng như dấu v&acirc;n tay.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://channel.mediacdn.vn/2020/12/4/photo-1-16070508894542108719125.jpg\" target=\"_blank\" title=\"\"><img alt=\"Hot: Đây là củ sạc Omega 200W – Tương lai với của sạc di động - Ảnh 2.\" height=\"\" src=\"https://channel.mediacdn.vn/thumb_w/640/2020/12/4/photo-1-16070508894542108719125.jpg\" title=\"Hot: Đây là củ sạc Omega 200W – Tương lai với của sạc di động - Ảnh 2.\" width=\"\" /></a></p>\r\n\r\n<p>Phần thiết kế với 2 m&agrave;u n&agrave;y rất nổi bật v&agrave; n&oacute; nh&igrave;n kh&aacute; lạ mắt với những h&atilde;ng kh&aacute;c tr&ecirc;n thị trường.</p>\r\n\r\n<p>Về phần cổng kết nối Omega 200W c&oacute; tổng cộng 4 cổng trong đ&oacute; 2 cổng C cho c&ocirc;ng suất d&ograve;ng ra l&ecirc;n đến 100W v&agrave; hỗ trợ Power Delivery, 2 cổng A với c&ocirc;ng suất c&oacute; thể đạt l&ecirc;n đến 45W v&agrave; hỗ trợ đủ c&aacute;c chuẩn sạc nhanh đang c&oacute; mặt tại thị trường</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://channel.mediacdn.vn/2020/12/4/photo-3-1607050889462229035653.jpg\" target=\"_blank\" title=\"\"><img alt=\"Hot: Đây là củ sạc Omega 200W – Tương lai với của sạc di động - Ảnh 3.\" height=\"\" src=\"https://channel.mediacdn.vn/thumb_w/640/2020/12/4/photo-3-1607050889462229035653.jpg\" title=\"Hot: Đây là củ sạc Omega 200W – Tương lai với của sạc di động - Ảnh 3.\" width=\"\" /></a></p>\r\n\r\n<p>Đi s&acirc;u 1 t&iacute; v&agrave;o b&ecirc;n trong bảng mạch của Omega cũng kh&aacute; th&uacute; vị khi thiết kế theo kiểu 2 bảng mạch nằm l&ecirc;n nhau với thiết kế như vậy sạc của ch&uacute;ng ta sẽ c&oacute; được kh&ocirc;ng gian để tản nhiệt tốt hơn v&agrave; nhắc đến tản nhiệt ChargeAsap cực kỳ quan t&acirc;m đến vấn đề n&agrave;y khi sử dụng vật liệu Graphene đ&oacute;ng vai tr&ograve; tản nhiệt. Vật liệu Graphene được rất nhiều h&atilde;ng tin tưởng trong đ&oacute; c&oacute; cả Tesla trang bị cho pin của xe điện. Ngo&agrave;i ra h&atilde;ng cũng trang bị c&ocirc;ng nghệ tản nhiệt nano mật độ cao tăng cường khả năng tản nhiệt của sạc.&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://channel.mediacdn.vn/2020/12/4/photo-4-1607050889471469888982.jpg\" target=\"_blank\" title=\"\"><img alt=\"Hot: Đây là củ sạc Omega 200W – Tương lai với của sạc di động - Ảnh 4.\" height=\"\" src=\"https://channel.mediacdn.vn/thumb_w/640/2020/12/4/photo-4-1607050889471469888982.jpg\" title=\"Hot: Đây là củ sạc Omega 200W – Tương lai với của sạc di động - Ảnh 4.\" width=\"\" /></a></p>\r\n\r\n<p>ChargeAsap đ&atilde; trang bị đến 2 con chip GaN NV6127 với khả năng cung cấp c&ocirc;ng suất sạc l&ecirc;n đến 200W nhưng vẫn giữ được mức nhiệt độ vừa phải c&oacute; thể khi hoạt động. Đ&acirc;y l&agrave; củ sạc ti&ecirc;n phong tr&ecirc;n thế giới trang bị IC mới nhất từ Navista.</p>\r\n\r\n<p style=\"text-align:center\"><a href=\"https://channel.mediacdn.vn/2020/12/4/photo-5-1607050889475146094071.jpg\" target=\"_blank\" title=\"\"><img alt=\"Hot: Đây là củ sạc Omega 200W – Tương lai với của sạc di động - Ảnh 5.\" height=\"\" src=\"https://channel.mediacdn.vn/thumb_w/640/2020/12/4/photo-5-1607050889475146094071.jpg\" title=\"Hot: Đây là củ sạc Omega 200W – Tương lai với của sạc di động - Ảnh 5.\" width=\"\" /></a></p>\r\n\r\n<p>C&ocirc;ng suất cao l&agrave; vậy nhưng chia d&ograve;ng điện hiệu quả lại l&agrave; 1 c&acirc;u chuyện kh&aacute;c nhiều củ sạc tr&ecirc;n thị trường tuy hỗ trợ c&ocirc;ng suất cao nhưng khi bạn cắm 2 sợi c&aacute;p c&ugrave;ng l&uacute;c th&igrave; c&ocirc;ng suất đ&atilde; bị chia nhỏ ra v&agrave; điều n&agrave;y l&agrave; ảnh hưởng tới khả năng hoạt động của thiết bị. Rất may với Omega h&atilde;ng đ&atilde; trang bị khả năng chia d&ograve;ng th&ocirc;ng minh dựa theo bảng dưới đ&acirc;y :&nbsp;</p>\r\n\r\n<p>C&aacute;c ph&acirc;n chia d&ograve;ng</p>\r\n\r\n<p>&bull; C1 or C2 = 100W</p>\r\n\r\n<p>&bull; C1 + C2 = 100W + 100W</p>\r\n\r\n<p>&bull; C1+ A1 + A2 = 100W + 12w + 12W</p>\r\n\r\n<p>&bull; C1+ C2 + A1 = 100W + 65W + 22.5W</p>\r\n\r\n<p>&bull; C1+ C2+&nbsp; A2 = 100W + 65W + 22.5W</p>\r\n\r\n<p>&bull; C1+ A1= 100W + 22.5W</p>\r\n\r\n<p>&bull; C2+ A2 = 65W + 22.5W</p>\r\n\r\n<p>&bull; A1 + A2 = 12W + 12W&nbsp;</p>\r\n\r\n<p>&bull; A1 or A2 = 22.5W</p>\r\n\r\n<p>&bull; 4 cổng sạc c&ugrave;ng l&uacute;c c&ocirc;ng suất sẽ tuần tự l&agrave; : 100W+ 65W + 12W +12W&nbsp;</p>\r\n\r\n<p>&bull; Ch&uacute; th&iacute;ch : C1 C2 l&agrave; Usb type C/ A1 A2 l&agrave; cổng Usb A.</p>\r\n\r\n<p>Dựa theo th&ocirc;ng số tr&ecirc;n bạn c&oacute; thể thấy cổng C1 cho c&ocirc;ng suất lu&ocirc;n lu&ocirc;n l&agrave; 100W gi&uacute;p cung cấp đủ điện cho laptop của bạn. Ngo&agrave;i ra 3 cổng c&ograve;n lại đều đ&aacute;p ứng tốt những nhu cầu sạc cho thiết bị của bạn. Ngo&agrave;i ra tốc độ chia d&ograve;ng của Omega cũng rất nhanh. Khi cắm c&aacute;c cổng kh&aacute;c v&agrave;o th&igrave; sẽ mất tầm 3s để chia d&ograve;ng nhưng sản phẩm n&agrave;y chỉ mất 0.5s để chia lại d&ograve;ng khi cắm 2 cổng C v&agrave; kh&ocirc;ng mất th&ecirc;m nếu cắm v&agrave;o cổng A.</p>\r\n\r\n<p>Mức gi&aacute; sản phẩm n&agrave;y hiện tại tr&ecirc;n Kickstarter tầm 90$ chưa bao gồm ph&iacute; Ship v&agrave; thuế, nhưng nh&agrave; ph&acirc;n phối Charge Asap Việt Nam tiết lộ rằng sẽ c&oacute; mức gi&aacute; hấp dẫn trong thời gian đầu.</p>', 'change-asap_photo-1-blog.jpg', 11, 'ONHAND', 2, '2021-07-19 16:01:16', '2021-07-19 16:03:22', 1, '2021-07-19 16:01:52');
INSERT INTO `tintuc` (`Id`, `TieuDe`, `MoTa`, `NoiDung`, `Anh`, `LuotXem`, `ChuDeId`, `BloggerId`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (6, '“Cân” Chuột Logitech MX Master 3 và chuột MX Anywhere 2S: Nên chọn ai về đội mình đây?', '<p><strong>Chuột Logitech MX Master 3 v&agrave; chuột MX Anywhere 2S đều được xem l&agrave; h&agrave;ng si&ecirc;u phẩm từ Logitech. Mỗi model c&oacute; thế mạnh, đặc trưng v&agrave; nh&oacute;m kh&aacute;ch h&agrave;ng ph&ugrave; hợp ri&ecirc;ng. C&ugrave;ng xem thử đ&acirc;u sẽ l&agrave; lựa chọn tốt nhất cho m&igrave;nh nh&eacute;.</strong></p>', '<h3>Đầu ti&ecirc;n h&atilde;y n&oacute;i về chuột Logitech MX Master 3</h3>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Logitech MX Master 3 Advanced Wireless Mouse Review - Console Monster\" src=\"https://i2.wp.com/www.consolemonster.com/wp-content/uploads/2020/02/Logitech-MX-Master-3.jpg?fit=1280%2C864&amp;ssl=1\" width=\"100%\" /></p>\r\n\r\n<p><strong>Ưu điểm:&nbsp;</strong></p>\r\n\r\n<ul>\r\n	<li>N&uacute;t cuộn nhanh, chạy mượt v&agrave; rất y&ecirc;n tĩnh</li>\r\n	<li>Cảm gi&aacute;c khi cầm chuột trong tay rất thoải m&aacute;i</li>\r\n	<li>C&oacute; thể control tới tận 3 PC c&ugrave;ng l&uacute;c</li>\r\n	<li>C&oacute; t&iacute;nh năng chia sẻ file, text, h&igrave;nh ảnh tr&ecirc;n cả 3 PC đang d&ugrave;ng</li>\r\n	<li>Cấu h&igrave;nh ứng dụng được lập tr&igrave;nh trước v&agrave; c&oacute; thể t&ugrave;y chỉnh dễ d&agrave;ng</li>\r\n	<li>Kết nối được cả bằng 2.4 GHz hoặc Bluetooth.</li>\r\n</ul>\r\n\r\n<p><strong>Nhược điểm:</strong></p>\r\n\r\n<ul>\r\n	<li>N&uacute;t nghỉ tay ch&uacute;ng t&ocirc;i cho rằng c&oacute; thể cần được thiết kế thoải m&aacute;i hơn hiện tại</li>\r\n	<li>T&ugrave;y ch&igrave;nh DPI c&oacute; nhưng đ&ocirc;i khi kh&ocirc;ng ch&iacute;nh x&aacute;c</li>\r\n	<li>Kh&ocirc;ng c&oacute; bộ lưu trữ USB</li>\r\n	<li>Đắt tiền</li>\r\n</ul>\r\n\r\n<h4><strong>Đ&aacute;nh gi&aacute; chung chuột MX Master 3</strong></h4>\r\n\r\n<p>Logitech MX Master 3 phải c&ocirc;ng nhận l&agrave; chuột văn ph&ograve;ng tốt nhất của năm 2020 đến từ thương hiệu lớn Logitech, thậm ch&iacute; c&ograve;n vượt qua cả mong đợi từ một ch&uacute; chuột văn ph&ograve;ng cao cấp. Nổi trội ở MX Master 3 ch&iacute;nh l&agrave; ở độ ho&agrave;n thiện của phần cứng, từ thiết kế c&ocirc;ng th&aacute;i học cho đến ngoại h&igrave;nh bắt mắt, c&aacute;c n&uacute;t nằm ở vị tr&iacute; rất hợp l&yacute; v&agrave; thoải m&aacute;i d&ugrave;ng trong thời gian d&agrave;i. Một điểm kh&aacute;c biệt nữa l&agrave; ở khả năng t&ugrave;y chỉnh độ nhạy switch DPI cho ph&eacute;p người d&ugrave;ng c&oacute; thể t&ugrave;y chỉnh độ nhạy click kh&aacute;c nhau theo nhu cầu v&agrave; thời điểm kh&aacute;c nhau trong ng&agrave;y. Một số report cho rằng t&ugrave;y chỉnh DPI n&agrave;y đ&ocirc;i khi kh&ocirc;ng ch&iacute;nh x&aacute;c, nhưng với một chuột văn ph&ograve;ng đa năng, kh&ocirc;ng qu&aacute; ch&uacute; trọng v&agrave;o việc chơi game tốc độ cao th&igrave; khả năng chỉnh DPI đ&atilde; l&agrave; một c&ocirc;ng nghệ vượt bậc.</p>\r\n\r\n<p>Phần cảm biến Darkfield 4000 DPI cũng l&agrave; điều g&acirc;y ngạc nhi&ecirc;n khi c&oacute; thể hoạt động cực nhay, hoạt động tốt tr&ecirc;n mọi bề mặt kể cả k&iacute;nh. Chuột n&agrave;y cũng c&oacute; khả năng kết nối đa thiết bị, đa hệ điều h&agrave;nh c&oacute; d&acirc;y hoặc kh&ocirc;ng d&acirc;y đền ổn định như nhau. Cụ thể l&agrave; kết nối tối đa 3 thiết bị c&ugrave;ng l&uacute;c th&ocirc;ng qua đầu thu Bluetooth Low Energy hoặc Unifying USB.&nbsp; V&agrave; một điều th&uacute; vị l&agrave; người d&ugrave;ng c&oacute; thể chuyển nhanh giữa c&aacute;c thiết bị chỉ bằng một n&uacute;t bấm. Qu&aacute; sức l&agrave; tiện lợi.</p>\r\n\r\n<p>Nếu c&oacute; &yacute; định d&ugrave;ng cho c&ocirc;ng việc thường xuy&ecirc;n di chuyển th&igrave; cũng kh&ocirc;ng c&oacute; g&igrave; phải đắn đo v&igrave; em n&oacute; c&oacute; thể d&ugrave;ng được trong 70 ng&agrave;y chỉ với một lần sạc đầy pin (tốn khoảng gần 3 tiếng đồng hồ sạc). Với d&acirc;n văn ph&ograve;ng th&igrave; con số n&agrave;y l&agrave; th&agrave;nh t&iacute;ch đ&aacute;ng nể so với c&aacute;c d&ograve;ng chuột l&agrave;m việc hiện đang c&oacute; tr&ecirc;n thị trường.</p>\r\n\r\n<h3><strong>Review chi tiết Chuột Logitech MX Master 3</strong></h3>\r\n\r\n<h4>Về thiết kế</h4>\r\n\r\n<p>Logitech lu&ocirc;n n&oacute;i về đặc t&iacute;nh c&ocirc;ng th&aacute;i học mỗi khi tung một model chuột mới ra thị trường. V&agrave; nếu c&oacute; theo d&otilde;i hẳn mọi người cũng đ&atilde; nhận thấy với d&ograve;ng chuột Master, Logitech đ&atilde; d&agrave;nh rất nhiều t&acirc;m huyết theo đuổi thiết kế c&ocirc;ng th&aacute;i học, từ những phi&ecirc;n bản đầu ti&ecirc;n đến nay đ&atilde; l&agrave; thế hệ Master 3, v&agrave; thật sự d&ograve;ng chuột n&agrave;y đ&atilde; mang lại c&aacute;i nh&igrave;n kh&aacute;c từ người ti&ecirc;u d&ugrave;ng: Logitech nay đ&atilde; chỉnh chu v&agrave; t&acirc;m l&yacute; hơn rất nhiều khi thiết kế chuột c&oacute; h&igrave;nh d&aacute;ng th&acirc;n thiện, giảm thiểu c&aacute;c bất tiện khi d&ugrave;ng v&agrave; đặc biệt l&agrave; cảm gi&aacute;c d&ugrave;ng rất thoải m&aacute;i d&ugrave; trong thời gian l&acirc;u. Chuột Master ph&ugrave; hợp với tất cả mọi người kể cả người c&oacute; b&agrave;n tay to. C&aacute;c đường uốn lượn th&ocirc;ng minh gi&uacute;p &ocirc;m trọn lấy những b&agrave;n tay nhỏ, đồng thời c&oacute; nhiều chỗ trống nghỉ ngơi thoải m&aacute;i hơn cho c&aacute;c b&agrave;n tay to. Nhiều người c&ograve;n đặc biệt th&iacute;ch phần để ng&oacute;n tay c&aacute;i rất đặc biệt của Master 3, rất thoải m&aacute;i, gi&uacute;p ng&oacute;n tay &ldquo;tự tin&rdquo; hơn tr&ecirc;n th&acirc;n chuột v&agrave; tạo khoảng trống để c&oacute; thể b&aacute;m lấy chuột dễ d&agrave;ng m&agrave; kh&ocirc;ng cần bất cứ lực giữ n&agrave;o.</p>\r\n\r\n<p>Chuột MX Master 3 hiện c&oacute; hai version về m&agrave;u sắc: m&agrave;u than ch&igrave; v&agrave; m&agrave;u x&aacute;m trung t&iacute;nh.&nbsp; Nh&igrave;n chung rất nh&atilde; nhặn, thanh lịch v&agrave; chuy&ecirc;n nghiệp, rất th&iacute;ch hợp cho giới văn ph&ograve;ng.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"The Logitech MX Master 3 is a Bonafide upgrade for the best work mouse of  all time\" src=\"https://i.kinja-img.com/gawker-media/image/upload/c_fill,f_auto,fl_progressive,g_center,h_675,pg_1,q_80,w_1200/ylw0hanjvq6ugqfuq1fx.jpg\" width=\"100%\" /></p>\r\n\r\n<h4>Về t&iacute;nh năng v&agrave; hoạt động</h4>\r\n\r\n<p>Nếu nh&igrave;n v&agrave;o hộp sản phẩm của chuột MX Master 3, anh em sẽ thấy ngo&agrave;i chuột c&ograve;n c&oacute;:</p>\r\n\r\n<ul>\r\n	<li>C&aacute;p USB-C: đ&acirc;y l&agrave; điểm bổ sung tiện lợi v&ocirc; c&ugrave;ng, tr&ecirc;n chuột c&oacute; sẵn cổng USB ở mặt trước, việc sạc pin trong 3 giờ đầy kh&ocirc;ng c&ograve;n l&agrave; vấn đề nữa, vẫn c&oacute; thể vừa sạc vừa d&ugrave;ng chuột b&igrave;nh thường. M&agrave; mỗi lần sạc lại d&ugrave;ng tới 70 ng&agrave;y, tha hồ vi vu.</li>\r\n	<li>Đầu thu USB hợp nhất: th&ecirc;m một c&aacute;ch để kết nối chuột với m&aacute;y t&iacute;nh, c&oacute; thể qua đầu thu n&agrave;y hoặc qua Bluetooth đều c&oacute; t&iacute;nh ổn định ngang nhau.</li>\r\n</ul>\r\n\r\n<p>Mặt dưới chuột l&agrave; c&aacute;c n&uacute;t bật/ tắt; n&uacute;t chuyển đổi giữa 3 thiết bị kết nối. Như vậy l&agrave; d&ugrave; kết nối bằng c&aacute;ch n&agrave;o, ta sẽ c&oacute; tối đa 3 thiết bị được control c&ugrave;ng l&uacute;c bằng chuột, v&agrave; chỉ cần một thao t&aacute;c nhấn n&uacute;t mặt dưới sẽ chuyển qua lại 3 thiết bị n&agrave;y dễ d&agrave;ng.</p>\r\n\r\n<p>Mặt tr&aacute;i của chuột l&agrave; một b&aacute;nh xe lăn lớn đ&atilde; được thiết kế lại v&agrave; khu vực để ng&oacute;n c&aacute;i rộng r&atilde;i b&ecirc;n dưới n&uacute;t b&aacute;nh xe. N&uacute;t b&aacute;nh xe n&agrave;y c&oacute; k&iacute;ch thước kh&aacute; lớn v&agrave; được thiết kế ở mặt b&ecirc;n để tiện cho việc d&ugrave;ng ng&oacute;n c&aacute;i hay ng&oacute;n trỏ để điều khiển ch&uacute;ng. Giữa n&uacute;t cuộn v&agrave; khu vực ng&oacute;n c&aacute;i l&agrave; hai n&uacute;t gesture d&ugrave;ng thiết lập v&agrave; thực hiện một số c&aacute;c t&aacute;c vụ kh&aacute;c nhau.</p>\r\n\r\n<p>Mặt tr&ecirc;n vẫn như chuột truyền thống, c&oacute; một n&uacute;t bấm phải, một n&uacute;t bấm tr&aacute;i v&agrave; con cuộn nằm giữa. N&oacute;i ri&ecirc;ng về con cuộn chuột n&agrave;y một ch&uacute;t. Ở d&ograve;ng chuột MX Master 3, Logitech đ&atilde; nhấn mạnh t&iacute;nh năng mac speed wheel. Đ&acirc;y l&agrave; một b&aacute;nh xe d&ugrave;ng nam ch&acirc;m điện v&agrave; kh&ocirc;ng c&oacute; t&iacute;nh cơ học cao n&ecirc;n tạo ra &iacute;t lực ma s&aacute;t hơn hẳn trước đ&acirc;y. Kết quả l&agrave; n&uacute;t cuộn hoạt động mềm, trơn tru v&agrave; cực kỳ nhẹ nh&agrave;ng, c&oacute; thể l&ecirc;n tới h&agrave;ng ngh&igrave;n flow trong một gi&acirc;y, con số kinh khủng m&agrave; từ đ&oacute; giờ chưa c&oacute; ai đạt tới (trừ c&aacute;c d&ograve;ng chuột gaming cao cấp). Ngo&agrave;i ra th&igrave; c&aacute;c n&uacute;t bấm cũng cực kỳ nhạy, phản hồi x&uacute;c gi&aacute;c tốt v&agrave; bấm rất y&ecirc;n tĩnh kh&ocirc;ng hề c&oacute; &acirc;m thanh ch&oacute;i tai n&agrave;o. Ph&iacute;a tr&ecirc;n&nbsp; cụm n&agrave;y c&ograve;n c&oacute; một n&uacute;t nhỏ c&oacute; nhiệm vụ điều chỉnh độ nhanh của n&uacute;t cuộn, cho ph&eacute;p d&ugrave;ng nhiều mục đ&iacute;ch kh&aacute;c nhau m&agrave; vẫn giữ được độ ch&iacute;nh x&aacute;c cần thiết của chuột.</p>\r\n\r\n<p>Ngo&agrave;i ra chuột MX Master 3 cũng c&oacute; một chức năng th&uacute; vị kh&aacute;c l&agrave; sao ch&eacute;p v&agrave; chia sẻ dữ liệu giữa c&aacute;c m&aacute;y t&iacute;nh đang control với nhau. Rất tiện cho c&aacute;c c&ocirc;ng việc chuy&ecirc;n nghiệp đ&ograve;i hỏi nhiều thiết bị c&ugrave;ng l&uacute;c.</p>\r\n\r\n<p>Master 3 thật sự l&agrave; một con chuột m&aacute;y t&iacute;nh văn ph&ograve;ng đa năng rất tốt, mạnh mẽ v&agrave; đạt hiệu quả rất cao. Thậm ch&iacute; c&oacute; thể d&ugrave;ng n&oacute; để chơi game, edit phim ảnh, giải tr&iacute; tại nh&agrave; cũng tốt như thường. Ch&uacute;ng t&ocirc;i đ&aacute;nh gi&aacute; rất cao hiệu suất v&agrave; t&iacute;nh năng của chuột Logitech MX Master 3 n&agrave;y. Nếu đang c&oacute; những nhu cầu cao cấp về tốc độ, hiệu quả l&agrave;m việc v&agrave; t&iacute;nh c&ocirc;ng th&aacute;i học trong c&ocirc;ng việc chuy&ecirc;n m&ocirc;n th&igrave; Master 3 sẽ l&agrave; một chọn lựa cực kỳ tốt, c&oacute; thể n&oacute;i l&agrave; tốt nhất trong năm 2020 n&agrave;y.</p>\r\n\r\n<h3>Tiếp theo l&agrave; Chuột Logitech MX Anywhere 2S</h3>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Review - Logitech MX Anywhere 2S : One Mouse, 3 Machines | Nasi Lemak Tech\" src=\"https://i1.wp.com/nasilemaktech.com/wp-content/uploads/2017/09/Logitech-MX-Anywhere-2S-header.jpg?fit=1920%2C1272&amp;ssl=1\" width=\"100%\" /></p>\r\n\r\n<p><strong>Ưu điểm:</strong></p>\r\n\r\n<ul>\r\n	<li>Hoạt động liền mạch trơn tru tr&ecirc;n nhiều thiết bị</li>\r\n	<li>Chạy tốt tr&ecirc;n mọi mặt b&agrave;n</li>\r\n	<li>Pin c&oacute; thể sạc</li>\r\n	<li>N&uacute;t cuộn trơn mượt nhẹ nh&agrave;ng</li>\r\n</ul>\r\n\r\n<p><strong>Nhược điểm:</strong></p>\r\n\r\n<ul>\r\n	<li>Kh&ocirc;ng c&oacute; chỗ giữ bộ thu USB, g&acirc;y bất tiện c&oacute; thể dễ l&agrave;m mất</li>\r\n	<li>Gi&aacute; hơi cao</li>\r\n</ul>\r\n\r\n<h4><strong>Đ&aacute;nh gi&aacute; chung chuột MX Anywhere 2S</strong></h4>\r\n\r\n<p>Đ&acirc;y l&agrave; chuột kh&ocirc;ng d&acirc;y nhỏ gọn, hiệu suất cao c&oacute; khả năng kết nối đa m&agrave;n h&igrave;nh. Với h&igrave;nh d&aacute;ng cổ điển v&agrave; c&aacute;c t&iacute;nh năng kh&aacute; chuy&ecirc;n s&acirc;u, chuột MX Anywhere 2S vốn được thiết kế kh&ocirc;ng chỉ đơn thuần d&agrave;nh cho c&aacute;c y&ecirc;u cầu di chuyển, m&agrave; n&oacute; r&otilde; r&agrave;ng l&agrave; sản phẩm mang trong m&igrave;nh chiến thuật kinh tế l&acirc;u d&agrave;i của nh&agrave; chuột Logitech.</p>\r\n\r\n<p>Nổi bật nhất ở model chuột Anywhere 2S n&agrave;y ch&iacute;nh l&agrave; t&iacute;nh năng Flow, sẽ rất hữu &iacute;ch cho c&aacute;c bạn trẻ nghiện c&ocirc;ng việc, c&oacute; nhu cầu kết hợp nhiều hệ thống c&ugrave;ng l&uacute;c khi đang l&agrave;m việc. V&agrave; nh&oacute;m ph&acirc;n kh&uacute;c n&agrave;y hiện đang ng&agrave;y c&agrave;ng nhiều, dự b&aacute;o tiềm năng v&ocirc; c&ugrave;ng lớn cho model chuột n&agrave;y.</p>\r\n\r\n<h3>Review chi tiết Chuột Logitech MX Anywhere 2S</h3>\r\n\r\n<h4>Về thiết kế</h4>\r\n\r\n<p>Bộ kit chuột Logitech MX Anywhere 2S gồm: Chuột, đầu thu USB, s&aacute;ch hướng dẫn v&agrave; c&aacute;p sạc. Anywhere 2S hiện c&oacute; ba m&agrave;u: than ch&igrave;, xanh k&eacute;t v&agrave; x&aacute;m trung t&iacute;nh. H&igrave;nh d&aacute;ng chuột n&agrave;y kh&aacute; nhỏ, trọng lượng nhẹ nh&agrave;ng chỉ khoảng 100g, v&oacute;c d&aacute;ng kinh điển rất dễ mang theo khi di chuyển. Đ&acirc;y l&agrave; sự kh&aacute;c biệt lớn đầu ti&ecirc;n về thiết kế của Anywhere 2S với Master 3 ở tr&ecirc;n. Tất nhi&ecirc;n với một số người, em chuột n&agrave;y sẽ c&oacute; vẻ hơi nhỏ, nhưng nếu muốn t&igrave;m một chuột m&aacute;y t&iacute;nh rộng đường du lịch c&ocirc;ng t&aacute;c khắp nơi th&igrave; đ&acirc;y sẽ l&agrave; một lựa chọn th&ocirc;ng minh.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"logitech mx master 3 vs anywhere 2s (1)\" src=\"https://www.thestyleinspiration.com/wp-content/uploads/2020/07/logitech-mx-master-3-vs-anywhere-2s-1.jpg\" width=\"100%\" /></p>\r\n\r\n<h4>Về chức năng v&agrave; hiệu suất l&agrave;m việc</h4>\r\n\r\n<p>Tr&ecirc;n chuột Anywhere 2S c&oacute; một số n&uacute;t c&oacute; thể được lập tr&igrave;nh bằng phần mềm t&ugrave;y chọn Logitech trực quan dễ d&ugrave;ng. Anh em c&oacute; thể t&ugrave;y chỉnh thoải m&aacute;i theo &yacute; m&igrave;nh v&agrave; g&aacute;n c&aacute;c chức năng kh&aacute;c nhau cho từng n&uacute;t tr&ecirc;n c&aacute;c chương tr&igrave;nh kh&aacute;c nhau. V&iacute; dụ đang d&ugrave;ng Chrome th&igrave; c&aacute;c n&uacute;t lập tr&igrave;nh n&agrave;y c&oacute; thể d&ugrave;ng để tiến hoặc l&ugrave;i, nhưng khi d&ugrave;ng một chương tr&igrave;nh kh&aacute;c như Final Cut Pro/ Adobe Premiere th&igrave; hai n&uacute;t n&agrave;y lại trở th&agrave;nh c&ocirc;ng cụ sao ch&eacute;p. Việc bạn cần l&agrave;m sau khi lập tr&igrave;nh n&uacute;t xong l&agrave; nhấn một n&uacute;t kh&aacute;c để chuyển đổi qua lại giữa c&aacute;c chương tr&igrave;nh ứng dụng n&agrave;y th&ocirc;i.</p>\r\n\r\n<p>Th&ecirc;m một n&uacute;t nữa c&oacute; thể được lập tr&igrave;nh l&agrave; n&uacute;t ngay dưới con cuộn, n&oacute; c&oacute; thể được lập tr&igrave;nh để thay cho con cuộn v&igrave; một số người sẽ cảm thấy thoải m&aacute;i hơn khi di chuột bằng n&uacute;t bấm thay v&igrave; con lăn dễ g&acirc;y rối mắt trong c&aacute;c đoạn văn bản qu&aacute; d&agrave;i.</p>\r\n\r\n<p>Chuột Anywhere 2S cũng c&oacute; thể kết nối cả Bluetooth lẫn đầu thu USB c&oacute; sẵn trong hộp sản phẩm. Ri&ecirc;ng Bluetooth c&oacute; thể nối với tối đa 3 thiết bị kh&aacute;c nhau, v&agrave; chuột đ&atilde; c&oacute; sẵn một n&uacute;t chuyển đổi nhanh nằm ở mặt dưới tiện lợi v&ocirc; c&ugrave;ng. Phần c&ocirc;ng tắc nguồn cũng nằm ở mặt dưới chuột, ngay cạnh n&uacute;t chuyển thiết bị.</p>\r\n\r\n<p>Anywhere 2S c&oacute; k&iacute;ch thước du lịch rất nhỏ gọn n&ecirc;n dẫn tới một nhược điểm l&agrave; tr&ecirc;n chuột kh&ocirc;ng c&oacute; chỗ để giữ đầu thu USB, mất l&agrave; toang.</p>\r\n\r\n<h4>Bảng so s&aacute;nh th&ocirc;ng số kỹ thuật của Chuột Logitech MX Master 3 vs chuột MX Anywhere 2S</h4>\r\n\r\n<table class=\"table table-bordered\">\r\n	<tbody>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td><strong>LOGITECH MX MASTER 3</strong></td>\r\n			<td><strong>LOGITECH MX ANYWHERE 2S</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Thương hiệu</strong></td>\r\n			<td>Logitech</td>\r\n			<td>Logitech</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Series</strong></td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Model</strong></td>\r\n			<td>910-005647</td>\r\n			<td>910-005132</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>T&ecirc;n thiết bị input</strong></td>\r\n			<td><strong>LOGITECH MX MASTER 3</strong></td>\r\n			<td><strong>LOGITECH MX ANYWHERE 2S</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>C&ocirc;ng nghệ kết nối</strong></td>\r\n			<td>C&oacute; d&acirc;y/ Kh&ocirc;ng d&acirc;y</td>\r\n			<td>Kh&ocirc;ng d&acirc;y</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Giao diện</strong></td>\r\n			<td>USB &amp; Bluetooth</td>\r\n			<td>2.4 GHz, USB</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>C&ocirc;ng nghệ ph&aacute;t hiện chuyển động</strong></td>\r\n			<td>Quang học</td>\r\n			<td>Laser</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Movement Resolution</strong></td>\r\n			<td>4000 dpi</td>\r\n			<td>4000 dpi</td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Số n&uacute;t</strong></td>\r\n			<td>7</td>\r\n			<td>7</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>PIN</strong>PIN</td>\r\n			<td>L&ecirc;n tới 70 n&agrave;y nếu sạc đầy pin</td>\r\n			<td>L&ecirc;n tới 70 n&agrave;y nếu sạc đầy pin</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Y&ecirc;u cầu tr&ecirc;n OS</strong></td>\r\n			<td>Linux, Microsoft Windows 7 / 8 / 10, Apple macOS 10.13 trở l&ecirc;n</td>\r\n			<td>Bluetooth Windows 8 trở l&ecirc;n, Mac OS X 10.10 trở l&ecirc;n\r\n			<p>Tương th&iacute;ch bộ thu Windows 10 trở l&ecirc;n, Windows 8, Windows 7 Mac OS X 10.10 trở l&ecirc;n</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>K&iacute;ch cỡ, trọng lượng</strong></td>\r\n			<td>WxDxH = 3.3 x 4.97 x 2 inch, 4,97 oz</td>\r\n			<td>WxDxH = 2.43 x 1.35 x 3.95 inch, 3,73 oz</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>C&Aacute;C T&Iacute;NH NĂNG CH&Iacute;NH</strong></td>\r\n			<td>Cuộn điện từ MagSpeed nhanh, ch&iacute;nh x&aacute;c v&agrave; cực kỳ nhạy.</td>\r\n			<td>Nổi trội nhất l&agrave; khả năng điều khiển đa m&aacute;y t&iacute;nh cực mạnh v&agrave; hiệu quả</td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>H&igrave;nh dạng thoải m&aacute;i, phần điều khiển ng&oacute;n tay c&aacute;i rất dễ d&ugrave;ng v&agrave; trực quan.</td>\r\n			<td>C&oacute; khả năng track mọi l&uacute;c mọi nơi</td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>C&oacute; app t&ugrave;y chỉnh tốc độ để ph&ugrave; hợp với từng loại c&ocirc;ng việc.</td>\r\n			<td>Cầm tay l&agrave; d&ugrave;ng kh&ocirc;ng c&oacute; độ trễ n&agrave;o</td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>Điều khiến m&aacute;y t&iacute;nh ch&eacute;o dạng luồng tr&ecirc;n nhiều m&aacute;y c&ugrave;ng l&uacute;c.</td>\r\n			<td>Ph&iacute;m cuộn si&ecirc;u nhanh</td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>Cảm biến Darkfield 4000 DPI cực nhay, hoạt động tốt tr&ecirc;n mọi bề mặt kể cả k&iacute;nh.</td>\r\n			<td>Dễ d&agrave;ng chuyển đổi v&agrave; c&oacute; kết nối k&eacute;p</td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>Tương th&iacute;ch đa thiết bị v&agrave; đa hệ điều h&agrave;nh.</td>\r\n			<td>H&igrave;nh d&aacute;ng thiết kế chuẩn mực, thon gọn, nhẹ nh&agrave;ng.</td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>Kết nối tối đa 3 thiết bị c&ugrave;ng l&uacute;c th&ocirc;ng qua đầu thu Bluetooth Low Energy hoặc Unifying USB.&nbsp; V&agrave; chuyển nhanh giữa c&aacute;c thiết bị chỉ bằng một n&uacute;t bấm</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>C&oacute; thể sạc pin lại qua cổng USB-C, với mỗi lần sạc đầy pin (gần 3 tiếng) sẽ d&ugrave;ng được trong khoảng 70 ng&agrave;y.</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>Hy vọng anh em đ&atilde; t&igrave;m được ch&acirc;n l&yacute; đời m&igrave;nh với b&agrave;i review dạng so s&aacute;nh nhanh n&agrave;y giữa chuột MX Master 3 v&agrave; chuột MX Anywhere 2S. T&oacute;m gọn lại l&agrave; l&agrave;m việc cố định, cần nhiều t&iacute;nh năng setting cao cấp hơn th&igrave; chọn Master 3, c&ograve;n cần tốc độ nhanh, di chuyển nhiều th&igrave; chọn Anywhere 2S l&agrave; tiện nhất.</p>\r\n\r\n<p>Ch&uacute;c cả nh&agrave; sớm t&igrave;m được chuột m&aacute;y t&iacute;nh đ&uacute;ng &yacute; m&igrave;nh.</p>', 'logitech-mx-master-3-vs-anywhere-2s-1-1-blog.jpg', 13, 'COMPARE', 2, '2021-07-19 16:19:56', '2021-07-19 16:26:16', 1, '2021-07-19 16:20:32');
INSERT INTO `tintuc` (`Id`, `TieuDe`, `MoTa`, `NoiDung`, `Anh`, `LuotXem`, `ChuDeId`, `BloggerId`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (7, 'Trên tay Apple Magic Mouse 2 và Magic Trackpad 2: tiện, đẹp nhưng quá mắc', '<p><strong>Nếu như gi&aacute; của&nbsp;<a href=\"http://127.0.0.1:8000/sanphamchitiet/12\">Magic Mouse 2</a>&nbsp;vẫn được coi l&agrave; chấp nhận được với d&ograve;ng chuột cao cấp th&igrave;&nbsp;Magic Trackpad 2&nbsp;lại trở n&ecirc;n qu&aacute; mắc: 129$ so với chỉ 69$ của phi&ecirc;n bản trước. Magic Trackpad 2 c&oacute; rất nhiều thay đổi, đẹp hơn rất nhiều, nhiều t&iacute;nh năng hơn v&agrave; kh&ocirc;ng phải lo đến việc thay pin nhưng r&otilde; r&agrave;ng 129$ l&agrave; c&aacute;i gi&aacute; qu&aacute; cao cho bất cứ chiếc trackpad n&agrave;o.</strong></p>', '<h4><strong>Magic Mouse 2:</strong></h4>\r\n\r\n<p>Magic Mouse 2 được thiết kế giống hệt như phi&ecirc;n bản trước, nhưng ngay khi cầm l&ecirc;n bạn sẽ thấy n&oacute; nhẹ hơn đ&aacute;ng kể để gi&uacute;p ch&uacute;ng ta di chuyển chuột dễ d&agrave;ng hơn. Đ&acirc;y ch&iacute;nh l&agrave; ưu điểm lớn nhất v&agrave; nếu đang h&agrave;i l&ograve;ng với Magic Mouse đời đầu th&igrave; bạn sẽ rất hạnh ph&uacute;c với Magic Mouse 2, m&igrave;nh cam đoan l&agrave; vậy.<br />\r\n<br />\r\nTuy vậy, thiết kế kỳ lạ của Magic Mouse vẫn l&agrave;m tay ch&uacute;ng ta mỏi v&igrave; kh&ocirc;ng c&oacute; điểm tựa, một đặc điểm m&agrave; Apple vẫn duy tr&igrave; gần 7 năm qua tr&ecirc;n con chuột cũ của họ. Khoảng 5 năm trước m&igrave;nh c&oacute; d&ugrave;ng Magic Mouse nhưng sau đ&oacute; th&igrave; bỏ lu&ocirc;n chuột v&agrave; chỉ x&agrave;i trackpad.</p>\r\n\r\n<p>Tr&ecirc;n Magic Mouse 2, phần đ&aacute;y của chuột được bổ sung th&ecirc;m một cổng Lightning để sạc. Với c&aacute;ch thiết kế n&agrave;y th&igrave; bạn kh&ocirc;ng thể vừa x&agrave;i vừa sạc được nhưng cũng đừng qu&aacute; lo lắng. Apple n&oacute;i rằng cắm sạc 2 ph&uacute;t th&igrave; chuột sẽ x&agrave;i được 9 tiếng. Thời lượng pin của con chuột n&agrave;y v&agrave;o khoảng 1 th&aacute;ng, theo th&ocirc;ng tin từ Apple.<br />\r\n<br />\r\nTrong hộp Magic Mouse 2 c&oacute; một sợi c&aacute;p Lightning để sạc, bạn c&oacute; thể d&ugrave;ng n&oacute; chung với iPhone hay iPad.</p>\r\n\r\n<p>Với những thay đổi về trọng lượng, pin v&agrave; tặng một sợi c&aacute;p Lightning th&igrave; mức gi&aacute; Magic Mouse 2 c&oacute; thể cho l&agrave; hợp l&yacute;.</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-2.jpg\" src=\"https://s3.cloud.cmctelecom.vn/tinhte1/2015/10/3524067_Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-2.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><em>Cầm l&ecirc;n l&agrave; bạn sẽ thấy n&oacute; nhẹ hơn hẳn so với bản cũ, tuyệt hơn rất nhiều</em></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-4.jpg\" src=\"https://s3.cloud.cmctelecom.vn/tinhte1/2015/10/3524069_Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-4.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><em>Nếu kh&ocirc;ng ph&acirc;n biệt được th&igrave; bạn lật mặt dưới n&oacute; l&ecirc;n sẽ thấy c&oacute; cổng Lightning v&agrave; mất nắp che pin</em></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-6.jpg\" src=\"https://s3.cloud.cmctelecom.vn/tinhte1/2015/10/3524071_Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-6.jpg\" width=\"100%\" /></p>\r\n\r\n<p style=\"text-align:center\"><em>Chuột kh&ocirc;ng bấm</em></p>\r\n\r\n<p style=\"text-align:center\"><em>&nbsp;<img alt=\"Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-7.jpg\" src=\"https://s3.cloud.cmctelecom.vn/tinhte1/2015/10/3524068_Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-7.jpg\" width=\"100%\" /></em></p>\r\n\r\n<p style=\"text-align:center\"><em>V&agrave; c&oacute; bấm, chắc c&aacute;c bạn cũng thấy được sự kh&aacute;c biệt</em></p>\r\n\r\n<p style=\"text-align:center\"><em><img alt=\"Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-8.jpg\" src=\"https://s3.cloud.cmctelecom.vn/tinhte1/2015/10/3524076_Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-8.jpg\" width=\"100%\" /></em></p>\r\n\r\n<p style=\"text-align:center\"><em>Cổng Lightning l&agrave;m rất đẹp</em></p>\r\n\r\n<p style=\"text-align:center\"><em><img alt=\"Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-17.jpg\" src=\"https://s3.cloud.cmctelecom.vn/tinhte1/2015/10/3524082_Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-17.jpg\" width=\"100%\" /></em></p>\r\n\r\n<p style=\"text-align:center\"><em>Sạc th&igrave; khỏi x&agrave;i&nbsp;<img alt=\"laugh\" height=\"23\" src=\"http://127.0.0.1:8000/ckeditor/plugins/smiley/images/teeth_smile.png\" title=\"laugh\" width=\"23\" /></em></p>\r\n\r\n<h4><strong>Magic Trackpad 2:</strong></h4>\r\n\r\n<p>Nếu như Magic Mouse 2 kh&ocirc;ng c&oacute; nhiều thay đổi th&igrave; Magic Trackpad 2 lại kh&aacute;c rất nhiều so với đời trước. N&oacute; mỏng hơn, đẹp hơn v&agrave; cao cấp hơn hẳn đời trước. Việc loại bỏ pin gắn ngo&agrave;i cũng đồng thời l&agrave;m cho Magic Trackpad 2 c&oacute; thiết kế c&acirc;n bằng hơn. Nh&igrave;n Magic Trackpad 2 giống một t&aacute;c phẩm nghệ thuật hơn l&agrave; một thiết bị ngoại vi đơn thuần.<br />\r\n<br />\r\nVề mặt thiết kế, c&oacute; một điểm m&igrave;nh kh&ocirc;ng th&iacute;ch ở magic trackpad đời đầu cũng như Magic Trackpad 2 l&agrave; kh&ocirc;ng c&oacute; c&aacute;c gờ xung quanh. Khi di ng&oacute;n tay tr&ecirc;n trackpad m&aacute;y t&iacute;nh x&aacute;ch tay, c&aacute;c gờ xung quanh l&agrave;m m&igrave;nh cảm gi&aacute;c được đ&acirc;u l&agrave; đ&iacute;ch nhưng trackpad n&agrave;y lại kh&ocirc;ng như vậy. Đ&acirc;y l&agrave; cảm nhận c&aacute; nh&acirc;n n&ecirc;n c&oacute; thể n&oacute; sẽ l&agrave; ưu điểm của người n&agrave;y nhưng lại l&agrave; nhược điểm của người kh&aacute;c.<br />\r\n<br />\r\nMagic Trackpad 2 hỗ trợ Force Touch, t&iacute;nh năng m&agrave; Apple mới giới thiệu tr&ecirc;n OS X 10.11. Ch&iacute;nh v&igrave; vậy m&agrave; cả n&oacute; v&agrave; Magic Mouse 2 đều y&ecirc;u cầu m&aacute;y OS X 10.11 để sử dụng, ưu ti&ecirc;n nhất cho những m&aacute;y d&ugrave;ng Bluetooth 4.0 tiết kiệm năng lượng.<br />\r\n<br />\r\nCũng như Magic Mouse 2, Trackpad 2 đi k&egrave;m một sợi d&acirc;y Lightning để sạc v&agrave; đồng bộ với m&aacute;y t&iacute;nh. Ở lần sử dụng đầu ti&ecirc;n, bạn chỉ việc cắm d&acirc;y v&agrave;o Trackpad, đầu c&ograve;n lại cắm v&agrave;o m&aacute;y t&iacute;nh l&agrave; đ&atilde; c&oacute; thể sử dụng ngay m&agrave; kh&ocirc;ng cần thiết lập hay c&agrave;i đặt g&igrave; phức tạp.</p>\r\n\r\n<p>Với về mặt lớn hơn v&agrave; Trackpad được thiết kế hơi nghi&ecirc;ng th&igrave; trải nghiệm Magic Trackpad 2 l&agrave; rất tuyệt. Bề mặt cảm ứng của n&oacute; chỉ được k&iacute;ch hoạt khi bạn mở nguồn, nếu kh&ocirc;ng mở nguồn th&igrave; d&ugrave; bạn c&oacute; nhấn bao nhi&ecirc;u lần v&agrave; mạnh thế n&agrave;o đi nữa th&igrave; phần cơ cảm ứng vẫn kh&ocirc;ng di chuyển.</p>\r\n\r\n<p style=\"text-align:center\"><em><img alt=\"Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-9.jpg\" src=\"https://s3.cloud.cmctelecom.vn/tinhte1/2015/10/3524073_Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-9.jpg\" width=\"100%\" /></em></p>\r\n\r\n<p style=\"text-align:center\"><em>Trackpad n&agrave;y lớn hơn khoảng 30% so với bản cũ&nbsp;</em></p>\r\n\r\n<p style=\"text-align:center\"><em><img alt=\"Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-10.jpg\" src=\"https://s3.cloud.cmctelecom.vn/tinhte1/2015/10/3524074_Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-10.jpg\" width=\"100%\" /></em></p>\r\n\r\n<p style=\"text-align:center\"><em>4 n&uacute;t ở đằng sau m&aacute;y c&oacute; vẻ như l&agrave; 4 n&uacute;t cảm ứng để trackpad nhấn xuống</em></p>\r\n\r\n<p style=\"text-align:center\"><em><img alt=\"Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-11.jpg\" src=\"https://s3.cloud.cmctelecom.vn/tinhte1/2015/10/3524075_Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-11.jpg\" width=\"100%\" /></em></p>\r\n\r\n<p style=\"text-align:center\"><em>Trackpad n&agrave;y cũng c&oacute; pin b&ecirc;n trong, Apple c&ocirc;ng bố l&agrave; d&ugrave;ng được khoảng một th&aacute;ng</em></p>\r\n\r\n<p style=\"text-align:center\"><em><img alt=\"Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-12.jpg\" src=\"https://s3.cloud.cmctelecom.vn/tinhte1/2015/10/3524077_Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-12.jpg\" width=\"100%\" /></em></p>\r\n\r\n<p style=\"text-align:center\"><em>Ph&iacute;m nguồn khi tắt m&agrave;u bạc</em></p>\r\n\r\n<p style=\"text-align:center\"><em>&nbsp;<img alt=\"Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-13.jpg\" src=\"https://s3.cloud.cmctelecom.vn/tinhte1/2015/10/3524078_Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-13.jpg\" width=\"100%\" /></em></p>\r\n\r\n<p style=\"text-align:center\"><em>Mở l&agrave; m&agrave;u xanh l&aacute;</em></p>\r\n\r\n<p style=\"text-align:center\"><em><img alt=\"Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-14.jpg\" src=\"https://s3.cloud.cmctelecom.vn/tinhte1/2015/10/3524079_Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-14.jpg\" width=\"100%\" /></em></p>\r\n\r\n<p style=\"text-align:center\"><em>Trackpad bấm</em></p>\r\n\r\n<p style=\"text-align:center\"><em><img alt=\"Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-15.jpg\" src=\"https://s3.cloud.cmctelecom.vn/tinhte1/2015/10/3524080_Apple_Magic_Mouse_2_Magic_Trackpad_2_tinhte.vn-15.jpg\" width=\"100%\" /></em></p>\r\n\r\n<p style=\"text-align:center\"><em>v&agrave; kh&ocirc;ng bấm, cũng rất kh&oacute; để thấy được sự kh&aacute;c biệt</em></p>', '3524081_Apple_Magic_Mouse_2_Magic_Trackpad_2-blog.png', 21, 'ONHAND', 6, '2021-07-21 16:55:53', '2021-07-24 17:29:46', 0, NULL);
INSERT INTO `tintuc` (`Id`, `TieuDe`, `MoTa`, `NoiDung`, `Anh`, `LuotXem`, `ChuDeId`, `BloggerId`, `NgayTao`, `NgaySua`, `DaDuyet`, `NgayDuyet`) VALUES (8, 'Đánh giá Logitech MX Master 3: Đỉnh cao của chuột văn phòng', '<p><strong>Nếu bạn đang c&oacute; nhu cầu muốn mua một con chuột để n&acirc;ng cao năng suất l&agrave;m việc l&ecirc;n mức cao nhất th&igrave; chuột kh&ocirc;ng d&acirc;y Logitech MX Master 3 l&agrave; lựa chọn tốt nhất ở thời điểm hiện tại. Tại sao m&igrave;nh lại n&oacute;i như vậy? H&atilde;y c&ugrave;ng Reviewed t&igrave;m hiểu ngay trong b&agrave;i viết n&agrave;y.</strong></p>', '<h3 style=\"text-align:center\">Đỉnh cao của chuột văn ph&ograve;ng!</h3>\r\n\r\n<p>C&oacute; lẽ việc tr&igrave;nh b&agrave;y th&ocirc;ng số kỹ thuật v&agrave; t&iacute;nh năng của Master 3 l&agrave; kh&ocirc;ng cần thiết. Đơn giản l&agrave; bởi v&igrave; bạn c&oacute; thể dễ d&agrave;ng t&igrave;m những thứ n&agrave;y ở trang chủ của Logitech.</p>\r\n\r\n<p>Giờ h&atilde;y c&ugrave;ng m&igrave;nh t&igrave;m hiểu xem, con chuột Logitech MX Master 3 n&agrave;y ph&ugrave; hợp với ai? N&oacute; c&oacute; ưu, nhược điểm g&igrave;?</p>\r\n\r\n<h3>Ai n&ecirc;n mua Logitech MX Master 3?</h3>\r\n\r\n<p>Nếu bạn l&agrave; một game thủ th&igrave; bạn c&oacute; thể đ&oacute;ng b&agrave;i viết n&agrave;y lại được rồi. V&igrave; m&igrave;nh nghĩ rằng với hơn 2 triệu bạn sẽ c&oacute; rất nhiều con chuột gaming tốt hơn Master 3 nhiều.</p>\r\n\r\n<p>Nhưng nếu bạn đang cần một con chuột để:</p>\r\n\r\n<ul>\r\n	<li>L&agrave;m c&aacute;c c&ocirc;ng việc văn ph&ograve;ng như xử l&yacute; file word d&agrave;i cả v&agrave;i trăm trang, xử l&yacute; file excel với cả ngh&igrave;n d&ograve;ng t&iacute;nh. N&oacute;i chung l&agrave; c&ocirc;ng việc cần phải c&oacute; một con lăn dọc đỉnh cao th&igrave; Master 3 sẽ ph&ugrave; hợp với bạn</li>\r\n	<li>Vẽ 3D, chỉnh sửa ảnh, edit video một c&aacute;ch thường xuy&ecirc;n. N&oacute;i chung l&agrave; những c&ocirc;ng việc cần độ ch&iacute;nh x&aacute;c cao, nhiều thao t&aacute;c phức tạp trong qu&aacute; tr&igrave;nh l&agrave;m việc. Th&igrave; Logitech MX Master 3 sẽ l&agrave; lựa chọn rất s&aacute;ng gi&aacute;</li>\r\n</ul>\r\n\r\n<p>Tại sao m&igrave;nh lại n&oacute;i như vậy? M&igrave;nh đ&atilde; sử dụng con chuột n&agrave;y trong khoảng 1 th&aacute;ng v&agrave; dưới đ&acirc;y l&agrave; những đ&aacute;nh gi&aacute; của m&igrave;nh.</p>\r\n\r\n<h3>Ưu điểm</h3>\r\n\r\n<h4>Thiết kế c&ocirc;ng th&aacute;i học</h4>\r\n\r\n<p>Nếu bạn hỏi m&igrave;nh, con chuột dạng truyền thống n&agrave;o c&oacute; thiết kế c&ocirc;ng th&aacute;i học nhất hiện nay th&igrave; m&igrave;nh c&oacute; thể tự tin trả lời: Đ&oacute; l&agrave; Logitech MX Master 3. Tại sao ư? Bạn h&atilde;y nh&igrave;n h&iacute;nh dưới xem:</p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Logitech MX Master 3\" height=\"560\" sizes=\"(max-width: 840px) 100vw, 840px\" src=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03410-1024x683.jpg\" srcset=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03410-1024x683.jpg 1024w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03410-300x200.jpg 300w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03410-768x512.jpg 768w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03410-1536x1024.jpg 1536w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03410-2048x1365.jpg 2048w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03410-788x525.jpg 788w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03410.jpg 1200w\" width=\"100%\" /><img alt=\"review Logitech MX Master 3\" height=\"560\" sizes=\"(max-width: 840px) 100vw, 840px\" src=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03418-1024x683.jpg\" srcset=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03418-1024x683.jpg 1024w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03418-300x200.jpg 300w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03418-768x512.jpg 768w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03418-1536x1024.jpg 1536w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03418-2048x1365.jpg 2048w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03418-788x525.jpg 788w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03418.jpg 1200w\" width=\"100%\" /><img alt=\"review Logitech MX Master 3\" height=\"560\" sizes=\"(max-width: 840px) 100vw, 840px\" src=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03419-1024x683.jpg\" srcset=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03419-1024x683.jpg 1024w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03419-300x200.jpg 300w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03419-768x512.jpg 768w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03419-1536x1024.jpg 1536w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03419-2048x1365.jpg 2048w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03419-788x525.jpg 788w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03419.jpg 1200w\" width=\"100%\" />\r\n\r\n<p><ul>\r\n	<li>Thiết kế đẹp mắt, sang trọng, độ ho&agrave;n thiện đỉnh cao</li>\r\n	<li>To&agrave;n bộ th&acirc;n tr&ecirc;n của chuột được bọc một lớp cao su c&oacute; độ mềm v&agrave; nh&aacute;m vừa đủ. Cho trải nghiệm rất ổn</li>\r\n	<li>L&ograve;ng b&agrave;n tay của bạn sẽ đặt một c&aacute;ch tự nhi&ecirc;n l&ecirc;n th&acirc;n chuột. Th&acirc;n chuột c&oacute; một độ nghi&ecirc;ng vừa đủ để bạn c&oacute; thể thoải m&aacute;i sử dụng trong thời gian d&agrave;i m&agrave; kh&ocirc;ng bị mỏi</li>\r\n	<li>Chuột c&oacute; phần đỡ ng&oacute;n tay c&aacute;i n&ecirc;n khi di chuột ng&oacute;n c&aacute;i sẽ kh&ocirc;ng tỳ xuống mặt b&agrave;n. C&aacute;i n&agrave;y m&igrave;nh tin l&agrave; nhiều bạn sẽ rất th&iacute;ch đ&oacute;, trong đ&oacute; c&oacute; m&igrave;nh!</li>\r\n</ul></p>\r\n\r\n<h4>Nhiều n&uacute;t bấm, khả năng t&ugrave;y chỉnh n&uacute;t linh hoạt</h4>\r\n\r\n<p style=\"text-align:center\"><img alt=\"Logitech MX Master 3\" height=\"560\" sizes=\"(max-width: 840px) 100vw, 840px\" src=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03414-1024x683.jpg\" srcset=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03414-1024x683.jpg 1024w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03414-300x200.jpg 300w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03414-768x512.jpg 768w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03414-1536x1024.jpg 1536w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03414-2048x1365.jpg 2048w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03414-788x525.jpg 788w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03414.jpg 1200w\" width=\"100%\" /><img alt=\"đánh giá Logitech MX Master 3\" height=\"560\" sizes=\"(max-width: 840px) 100vw, 840px\" src=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03417-1024x683.jpg\" srcset=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03417-1024x683.jpg 1024w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03417-300x200.jpg 300w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03417-768x512.jpg 768w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03417-1536x1024.jpg 1536w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03417-2048x1365.jpg 2048w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03417-788x525.jpg 788w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03417.jpg 1200w\" width=\"100%\" /></p>\r\n\r\n<ul>\r\n	<li>C&aacute;c n&uacute;t bấm tr&ecirc;n chuột được bố tr&iacute; hợp l&yacute;, gi&uacute;p bạn thao t&aacute;c dễ d&agrave;ng hơn.</li>\r\n	<li>Bạn c&oacute; thể set t&iacute;nh năng thường d&ugrave;ng cho từng n&uacute;t bấm. Logitech cũng cung cấp c&aacute;c t&ugrave;y chỉnh sẵn c&oacute; cho từng c&ocirc;ng việc kh&aacute;c nhau như chỉnh sửa ảnh, edit video, duyệt web, Excel. Ch&iacute;nh việc n&agrave;y sẽ gi&uacute;p bạn kh&ocirc;ng phải di chuyển tay nhiều. Từ đ&oacute; l&agrave;m giảm đau mỏi tay hơn nhiều!</li>\r\n	<li>Chất lượng n&uacute;t bấm th&igrave; khỏi b&agrave;n nha bạn. N&oacute; c&oacute; độ nảy tốt, độ &ecirc;m vừa đủ, độ bền th&igrave; chắc m&igrave;nh kh&ocirc;ng cần n&oacute;i nhiều đ&acirc;u v&igrave; Logitech m&agrave;!</li>\r\n</ul>\r\n\r\n<h4>Con lăn đỉnh cao</h4>\r\n\r\n<p style=\"text-align:center\"><img alt=\"đánh giá Logitech MX Master 3\" height=\"560\" sizes=\"(max-width: 840px) 100vw, 840px\" src=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03416-1024x683.jpg\" srcset=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03416-1024x683.jpg 1024w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03416-300x200.jpg 300w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03416-768x512.jpg 768w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03416-1536x1024.jpg 1536w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03416-2048x1365.jpg 2048w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03416-788x525.jpg 788w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03416.jpg 1200w\" width=\"100%\" /><img alt=\"review Logitech MX Master 3\" height=\"560\" sizes=\"(max-width: 840px) 100vw, 840px\" src=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03421-1024x683.jpg\" srcset=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03421-1024x683.jpg 1024w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03421-300x200.jpg 300w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03421-768x512.jpg 768w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03421-1536x1024.jpg 1536w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03421-2048x1365.jpg 2048w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03421-788x525.jpg 788w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03421.jpg 1200w\" width=\"100%\" /></p>\r\n\r\n<p>Logitech MX Master 3 được trang bị 2 con lăn: Dọc v&agrave; ngang. Cả 2 con lăn đều thuộc h&agrave;ng đỉnh cao nha bạn.</p>\r\n\r\n<ul>\r\n	<li>Cả 2 con lăn đều được l&agrave;m bằng kim loại. Chỉ cần chạm v&agrave;o th&ocirc;i l&agrave; đ&atilde; thấy ph&ecirc; rồi bạn &agrave;!</li>\r\n	<li>Con lăn dọc thuộc loại con lăn từ t&iacute;nh. Tức l&agrave; bạn chỉ cần gẩy ng&oacute;n tay đủ mạnh n&oacute; sẽ lăn v&ocirc; hạn lu&ocirc;n. Kiểu như b&aacute;nh xe &ocirc; t&ocirc; lăn tr&ecirc;n đường đ&oacute;. Với t&iacute;nh năng n&agrave;y m&igrave;nh c&oacute; thể cuộn cả ngh&igrave;n d&ograve;ng Excel chỉ trong v&ograve;ng chưa tới 1 gi&acirc;y. Nếu d&ugrave;ng n&oacute; để lướt web, lướt face th&igrave; n&oacute; mượt d&atilde; man lu&ocirc;n bạn &agrave;. D&ugrave;ng con chuột n&agrave;y n&oacute; đem lại đ&uacute;ng cảm gi&aacute;c &ldquo;lướt&rdquo; face lu&ocirc;n!</li>\r\n	<li>Con lăn ngang được bố tr&iacute; cạnh ng&oacute;n tay c&aacute;i. N&oacute; kh&ocirc;ng phải dạng từ t&iacute;nh nhưng n&oacute; c&oacute; k&iacute;ch thước lớn, khi lăn kh&ocirc;ng hề c&oacute; tiếng động, độ mượt th&igrave; khỏi b&agrave;n v&agrave; n&oacute; c&oacute; độ nặng vừa đủ để tr&aacute;nh bạn lăn qu&aacute; mức. V&igrave; thường khi d&ugrave;ng con lăn ngang trong c&aacute;c t&aacute;c vụ k&eacute;o timeline video hay k&eacute;o excel ta cần độ ch&iacute;nh x&aacute;c hơn l&agrave; tốc độ</li>\r\n</ul>\r\n\r\n<h4>Cảm biến b&aacute; đạo</h4>\r\n\r\n<p>C&oacute; một sự thật th&uacute; vị m&agrave; m&igrave;nh nghĩ, m&igrave;nh n&ecirc;n chia sẻ với bạn. Đ&oacute; l&agrave; m&igrave;nh th&iacute;ch d&ugrave;ng con chuột n&agrave;y tr&ecirc;n mặt k&iacute;nh hơn l&agrave; mặt đế di chuột chuy&ecirc;n dụng. Bởi v&igrave; khi d&ugrave;ng tr&ecirc;n mặt k&iacute;nh th&igrave; n&oacute; cho cảm gi&aacute;c trơn, nhẹ v&agrave; &ldquo;lướt&rdquo; hơn. C&ograve;n độ ch&iacute;nh x&aacute;c th&igrave; khỏi b&agrave;n nha. N&oacute; kh&ocirc;ng kh&aacute;c g&igrave; so với bạn di chuột tr&ecirc;n mặt đế chuy&ecirc;n dụng lu&ocirc;n. N&oacute;i vậy để bạn biết được rằng, cảm biến của Logitech MX Master 3 n&oacute; b&aacute; thế n&agrave;o!</p>\r\n\r\n<h4>Hiệu suất l&agrave;m việc đỉnh cao</h4>\r\n\r\n<p style=\"text-align:center\"><img alt=\"đánh giá Logitech MX Master 3\" height=\"560\" sizes=\"(max-width: 840px) 100vw, 840px\" src=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03415-1024x683.jpg\" srcset=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03415-1024x683.jpg 1024w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03415-300x200.jpg 300w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03415-768x512.jpg 768w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03415-1536x1024.jpg 1536w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03415-2048x1365.jpg 2048w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03415-788x525.jpg 788w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03415.jpg 1200w\" width=\"100%\" /></p>\r\n\r\n<p>Tất cả c&aacute;c yếu tố từ: Thiết kế c&ocirc;ng th&aacute;i học, n&uacute;t bấm tiện dụng, khả năng t&ugrave;y chỉnh n&uacute;t linh hoạt, con lăn dọc từ t&iacute;nh, con lăn ngang mượt m&agrave; cho đến cảm biến si&ecirc;u ch&iacute;nh x&aacute;c đ&atilde; hợp lại với nhau. Để khiến Logitech MX Master 3 trở th&agrave;nh một con chuột kh&ocirc;ng d&acirc;y sở hữu hiệu suất l&agrave;m việc rất đỉnh cao. M&igrave;nh xin khẳng định l&agrave; rất đỉnh cao nha!</p>\r\n\r\n<h4>Ưu điểm kh&aacute;c</h4>\r\n\r\n<p>Ngo&agrave;i c&aacute;c ưu điểm tr&ecirc;n, c&ograve;n nhiều ưu điểm kh&aacute;c m&agrave; m&igrave;nh sẽ chỉ liệt k&ecirc; ra đ&acirc;y chứ kh&ocirc;ng ph&acirc;n t&iacute;ch kỹ. Đơn giản l&agrave; v&igrave; bạn sẽ c&oacute; thể gặp c&aacute;c ưu điểm n&agrave;y ở những con chuột c&oacute; gi&aacute; chỉ bằng 1/3. C&aacute;c ưu điểm đ&oacute; gồm:</p>\r\n\r\n<ul>\r\n	<li>D&ugrave;ng pin sạc, thời lượng pin l&acirc;u. D&ugrave;ng v&agrave;i th&aacute;ng sạc một lần l&agrave; chuyện b&igrave;nh thường</li>\r\n	<li>Cổng sạc USB type C tiện dụng</li>\r\n	<li>Kết nối nhiều thiết bị c&ugrave;ng l&uacute;c</li>\r\n	<li>Độ bền của chuột Logitech th&igrave; khỏi ch&ecirc; rồi!</li>\r\n</ul>\r\n\r\n<p>Từ n&atilde;y đến giờ to&agrave;n thấy n&oacute;i ưu điểm, thế n&oacute; kh&ocirc;ng c&oacute; hạn chế g&igrave; &agrave;? Tất nhi&ecirc;n l&agrave; c&oacute; chứ. C&ograve;n c&oacute; v&agrave;i chứ kh&ocirc;ng phải một.</p>\r\n\r\n<h3>Hạn chế</h3>\r\n\r\n<h4>K&iacute;ch thước lớn, nặng</h4>\r\n\r\n<p style=\"text-align:center\"><img alt=\"review Logitech MX Master 3\" height=\"560\" sizes=\"(max-width: 840px) 100vw, 840px\" src=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03420-1024x683.jpg\" srcset=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03420-1024x683.jpg 1024w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03420-300x200.jpg 300w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03420-768x512.jpg 768w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03420-1536x1024.jpg 1536w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03420-2048x1365.jpg 2048w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03420-788x525.jpg 788w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03420.jpg 1200w\" width=\"100%\" /></p>\r\n\r\n<p>Con chuột n&agrave;y chỉ ph&ugrave; hợp với bạn n&agrave;o c&oacute; b&agrave;n tay to th&ocirc;i nha. Tay nhỏ cầm n&oacute; sẽ hơi cấn đ&oacute;. Th&ecirc;m v&agrave;o đ&oacute; n&oacute; cũng nặng hơn so với đại đa số c&aacute;c con chuột kh&aacute;c. Tuy nhi&ecirc;n, n&oacute;i l&agrave; nặng hơn, lớn hơn nhưng nhờ sự c&ocirc;ng th&aacute;i học trong thiết kế v&agrave; cảm biến b&aacute; đạo n&ecirc;n sử dụng n&oacute; vẫn rất tuyệt nha.</p>\r\n\r\n<p>Chỉ c&oacute; điều việc to hơn sẽ tốn nhiều diện t&iacute;ch trong balo hơn!</p>\r\n\r\n<h4>Kh&ocirc;ng c&oacute; chỗ cất receiver tr&ecirc;n chuột</h4>\r\n\r\n<p>C&aacute;i n&agrave;y cũng kh&aacute; bất tiện nha. Bạn phải cất cẩn thận hoặc cắm lu&ocirc;n n&oacute; cố định v&agrave;o m&aacute;y t&iacute;nh nếu kh&ocirc;ng muốn mất receiver. Dĩ nhi&ecirc;n, nếu mất th&igrave; chỉ tốn tầm 100k để mua c&aacute;i mới th&ocirc;i!</p>\r\n\r\n<h4>N&uacute;t bấm k&ecirc;u</h4>\r\n\r\n<p>Nếu bạn đang cần chuột silent th&igrave; Master 3 kh&ocirc;ng ph&ugrave; hợp lắm đ&acirc;u. N&uacute;t chuột tr&aacute;i/phải của n&oacute; k&ecirc;u kh&aacute; to đ&oacute;.</p>\r\n\r\n<h4>Gi&aacute; cao</h4>\r\n\r\n<p>Trang chủ Logitech để gi&aacute; MX Master 3 khoảng $199. Ở Việt Nam gi&aacute; của n&oacute; khoảng 2 đến 2.3 triệu đồng. N&oacute;i thực l&agrave; kh&ocirc;ng phải ai cũng sẵn s&agrave;ng bỏ tiền ra để mua n&oacute;. Nhưng tin m&igrave;nh đi, c&aacute;i g&igrave; cũng c&oacute; gi&aacute; của n&oacute; &agrave;!</p>\r\n\r\n<h3>C&aacute;c lựa chọn kh&aacute;c</h3>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" height=\"560\" sizes=\"(max-width: 840px) 100vw, 840px\" src=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03423-1024x683.jpg\" srcset=\"https://reviewed.vn/wp-content/uploads/2021/05/DSC03423-1024x683.jpg 1024w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03423-300x200.jpg 300w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03423-768x512.jpg 768w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03423-1536x1024.jpg 1536w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03423-2048x1365.jpg 2048w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03423-788x525.jpg 788w, https://reviewed.vn/wp-content/uploads/2021/05/DSC03423.jpg 1200w\" width=\"100%\" /></p>\r\n\r\n<p>Dưới đ&acirc;y l&agrave; một số lựa chọn thay thế m&agrave; bạn n&ecirc;n c&acirc;n nhắc:</p>\r\n\r\n<ul>\r\n	<li>Nếu bạn bị đau cổ tay, c&aacute;nh tay do d&ugrave;ng chuột m&aacute;y t&iacute;nh. Bạn c&oacute; thể c&acirc;n nhắc lựa chọn Logitech MX Ergo. N&oacute; sở hữu c&aacute;ch sử dụng kh&aacute;c biệt so với chuột truyền thống nhưng lại gi&uacute;p giảm đau mỏi cổ tay rất nhiều. Gi&aacute; th&igrave; tương đương nha! Bạn c&oacute; thể đọc b&agrave;i&nbsp;đ&aacute;nh gi&aacute; chi tiết Logitech MX Ergo&nbsp;của m&igrave;nh để hiểu r&otilde; hơn</li>\r\n	<li>Nếu bạn kh&ocirc;ng cần con lăn dọc từ t&iacute;nh, bạn chỉ cần con lăn ngang v&agrave; bạn muốn tiết kiệm chi ph&iacute;. Lựa chọn MX Master 2s c&oacute; lẽ sẽ hợp l&yacute; hơn.</li>\r\n	<li>Nếu bạn c&oacute; b&agrave;n tay nhỏ nhưng lại th&iacute;ch thiết kế c&ocirc;ng th&aacute;i học v&agrave; t&iacute;nh năng cuộn v&ocirc; hạn c&ugrave;ng c&aacute;c n&uacute;t t&ugrave;y biến th&igrave; c&oacute; thể xem x&eacute;t chọn mua Logitech M720 Triathlon. Tất nhi&ecirc;n M720 c&oacute; gi&aacute; rẻ hơn rất nhiều!</li>\r\n</ul>\r\n\r\n<h3>Tổng kết</h3>\r\n\r\n<p>Tổng kết lại, nếu bạn đang cần một con chuột kh&ocirc;ng d&acirc;y th&iacute;ch hợp cho c&aacute;c c&ocirc;ng việc văn ph&ograve;ng như:</p>\r\n\r\n<ul>\r\n	<li>Xử l&yacute; file Excel với cả ng&agrave;n d&ograve;ng t&iacute;nh</li>\r\n	<li>Xử l&yacute; file Word d&agrave;i cả v&agrave;i trăm trang</li>\r\n	<li>Edit video với timeline d&agrave;i</li>\r\n	<li>Chỉnh sửa ảnh, vẽ 3D</li>\r\n</ul>\r\n\r\n<p>Th&igrave; h&atilde;y xem x&eacute;t lựa chọn chuột kh&ocirc;ng d&acirc;y <a href=\"http://127.0.0.1:8000/sanphamchitiet/1\">Logitech MX Master 3</a>. N&oacute; sẽ đem lại cho bạn một hiệu suất l&agrave;m việc đỉnh cao đồng thời cũng gi&uacute;p bạn hạn chế đau mỏi cổ tay d&ugrave; phải l&agrave;m việc cả ng&agrave;y d&agrave;i. Dĩ nhi&ecirc;n, điều kiện quan trọng l&agrave; bạn phải sẵn s&agrave;ng bỏ ra hơn 2 triệu để sở hữu n&oacute;.</p>', 'Danh-gia-Logitech-MX-Master-3-blog.jpg', 16, 'REVIEW', 5, '2021-07-24 16:22:31', '2021-07-24 16:53:34', 0, NULL);
COMMIT;

-- ----------------------------
-- Table structure for trangthai
-- ----------------------------
DROP TABLE IF EXISTS `trangthai`;
CREATE TABLE `trangthai` (
  `Id` tinyint NOT NULL AUTO_INCREMENT,
  `TrangThai` varchar(150) NOT NULL,
  `MoTa` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb3;

-- ----------------------------
-- Records of trangthai
